INSERT INTO drink_me_bot.goods_i18n (goods_id, lang, name, description) VALUES
  (445, 'de', 'Zimt Sirup', 'Dieser berühmte Gewürzsirup entsteht durch die Pasteurisierung und Infusion von Zuckersirup mit Zimt.'),
  (176, 'de', 'Limettensaft', 'Für die Herstellung des Saftes werden Limetten gepresst, gefiltert und abgefüllt.'),
  (482, 'de', 'Apfelsaft', 'Für die Herstellung des Saftes werden Äpfel gepresst, gefiltert und abgefüllt.'),
  (767, 'de', 'Wachtel Eiweiß', 'Für die Herstellung dieser Cocktail-Zutat mit ihrer sanften, schaumigen Konsistenz, empfehlen wir die "Dry shake”-Methode. Ein Hühnereiweiß entspricht 5 Wachteleiweiß.'),
  (217, 'de', 'Gurke', 'Gurken sind Kürbisgewächse mit zylinderförmigen Früchten, die als kulinarisches Gemüse genutzt werden. Gurken wachsen hauptsächlich in mediterranen Ländern. Sie regulieren den Stoffwechsel und verbessern die Herz- und Nierenfunktion. Eine Gurke wiegt durchschnittlich etwa 150g und kann in 10 Stücke oder Streifen geschnitten werden.'),
  (31, 'de', 'Eiswürfel', 'Für die Herstellung dieser unverzichtbaren Zutat sollte das Augenmerk auf die Reinheit des Wassers und die Geschwindigkeit des Gefrierens gelegt werden. Je langsamer das Wasser gefriert, desto klarer ist das Endprodukt. Ein optimales Resultat hat keine Streifen und schmilzt nur langsam im Glas.'),
  (210, 'de', 'Champagner Schale', 'Ein Glas mit einem schlanken Stiel und einer flachen Schale. Der Legende nach wurde es entworfen, um die Silhouette einer Mätresse des französischen Königs widerzuspiegeln. Es wird benutzt, um Champagner und kleine Cocktails zu servieren. Standardkapazität: 200 - 300 ml.'),
  (68, 'de', 'Cocktailshaker', 'Hat seinen heutiges Aussehen um 1800 bekommen und erreichte in den 1920gern und 1930gern spezielle Beliebtheit, nachdem man Dutzende Stile und Formen ausprobiert hatte. Es gibt eine Unterteilung in Cobbler Shaker, mit einem eingebauten Sieb, French Shaker ohne Sieb und Boston Shaker, die aus zwei gleich grossen Bechern bestehen. Standardvolumen: 500—700ml.'),
  (69, 'de', 'Barsieb', 'Ein Accessoire auf das bei der Arbeit mit Boston oder French Shakern nicht verzichtet werden kann. Wird verwendet um Cocktails von Fruchtsamen, Eisstückchen und anderer ungewünschter Bestandteile zu filtern.'),
  (73, 'de', 'Jigger', 'Gewährleistet akkurate und ideale Portionsgrößen in Cocktails. Die besten Barkeeper haben eine Reihe von Größen auf Lager: 20-40ml, 25-50ml und 30-60ml.'),
  (70, 'de', 'Saftpresse', 'Ein unverzichtbares Instrument um Saft von Zitronen und Limetten zu pressen. Ungeachtet der Tatsache, dass die meisten berühmten Einrichtungen heutzutage fertig zubereiteten Saft verwenden, wird frischgepresster Saft als ein hohes Level an Qualität angesehen.'),
  (239, 'de', 'Entsafter', 'Extrahiert Saft aus jeglichem Gemüse oder Früchten. Im Gegensatz zu einer manuellen Presse, trennt der elektrische Apparat durch eine Schleuder den Saft vom Fruchtfleisch.'),
  (1, 'de', 'Wodka', 'Wodka'),
  (55, 'de', 'Kaffee Likör', 'Ein berühmter aufputschender Likör, hergestellt durch die Filtration von verschiedenen Kaffeebohnen mit neutralem Alkohol. Das Resultat wird nicht filtriert, aber mit gebranntem Zucker vermengt und bis zur gewünschten Stärke mit Wasser verschnitten.'),
  (65, 'de', 'Rocks Glas', 'Ein breites Glas mit einem dicken Boden um starke Spirituosen oder Cocktails in reiner, unverdünnter Form zu Servieren. Standardkapazität: 200-300 ml.'),
  (64, 'de', 'Barlöffel', 'Dieses unverzichtbare Hilfsmittel eines jeden Barkeepers wird zur Zubereitung von Cocktails in einem Misch-Glas verwendet, um mehrere Lagen in einem Shot herzustellen und ebenso als Maßeinheit für 5ml Flüssigkeit oder 5g Trockenprodukt.'),
  (57, 'de', 'Strohhalm', '1888 erfand Marvin Stone, der Besitzer einer Fabrik für Papier-Mundstücke, das beste Accessoire um Drinks aus Gläsern zu trinken. Joseph Friedman machte daraufhin ein Vermögen mit der Entwicklung von flexiblen Strohhalmen. Der letze Schritt erfolgte mit der Herstellung von Strohhalmen aus Plastik.'),
  (799, 'de', 'Botanischer Gin', 'Dies ist ein schottischer Likör, dem die Welt Gin & Tonic mit Gurke verdankt. Vor der Destillation wird der Kornalkohol tagelang mit elf Pflanzentypen unter Zusatz von Rose und Gurke infundiert. Das resultierende Produkt wird mit einem Getränk aus einer zweiten Destille kombiniert, dessen einzigartige Qualität die Verwendung der "Bad" -Methode des Dampfbrennens von Kräutern ist. Der bekannteste solcher Gin, Hendrick''s, umfasst neben Gurken und bulgarischen Rosen eine große Anzahl von Blumen, Wurzeln und Früchten, die ihn zu einem der gefragtesten Getränke in Bars weltweit machen.'),
  (54, 'de', 'Triple sec', 'Ein kultiger Zitruslikör, dreifach trocken, hergestellt durch die Mazeration von Curacao Orangenschalen in Neutralalkohol mit Wasser. Das Ergebnis wird dreifach destilliert bevor es abgefüllt wird, während es seinen hohen Alkoholgehalt bewahrt.'),
  (9, 'de', 'Zitronensaft', 'Für die Herstellung des Saftes werden Zitronen gepresst, gefiltert und abgefüllt.'),
  (734, 'de', 'Zitronen Schale', 'Die oberste Schicht einer Zitronen-Haut, mit einem speziellen scharfen Messer abgeschnitten. Enthält ätherische Öle, die den Geschmack der Zitrone tragen. Die Schale kann von einer geschnittenen oder ganzen Frucht gewonnen werden und geraspelt oder sogar zur Spirale gedreht (Twist genannt) werden.'),
  (66, 'de', 'Sour Glas', 'Diese Gläser wurden entworfen um Sour Cocktails zu servieren - mit einer alkoholischen Basis, Zitronen- oder Limettensaft und einem Süssmittel. Standardkapazität: 90-120 ml.'),
  (71, 'de', 'Sparschäler', 'Ein Barkeeper-Instrument aus der japanischen Schnitzkultur. Wird benutzt um dünne Schichten von Schalen oder Ringe und Twists von Äpfeln zu schneiden.'),
  (143, 'de', 'Mezcal', 'Eine mexikanische Spirituose, hergestellt nach traditioneller Methode, einschliesslich dem Räuchern von Agaven auf heissem vulkanischem Gestein in Gruben im Erdboden. Das Getränk nimmt dadurch ein rauchiges Aroma an. Danach werden die Agavenherzen gemahlen, der Saft gärt und reift für mindestens 4 Monate in Eichenfässern.'),
  (224, 'de', 'Basilikum', 'Würzige Kräuter, die hauptsächlich in den warmen Regionen der alten Welt wachsen. Diese grünen Blätter haben breite Beliebtheit erreicht, dank des “Basil Smash” Cocktails, welcher mittlerweile ein Klassiker ist.'),
  (223, 'de', 'Kardamom', 'Ein Würzmittel aus Sri Lanka, das an krautigen Pflanzen der Ingwer-Familie wächst. Es wird als eines der wirkungsvollsten Gewürze angesehen.'),
  (566, 'de', 'Ingwerwurzel', 'Eine mehrjährige Pflanze aus Asien, die im Mittelalter nach Europa importiert wurde. Ein Rhizom sieht aus wie abgerundete Stücke, verbessert das Immunsystem und hilft gegen Kopfschmerzen. Ein Kreis des Wurzelstock wiegt durchschnittlich etwa 5g.'),
  (83, 'de', 'Crushed Ice', 'Das erste “Shaved Ice” wurde von Barkeepern mit speziellen Messern von einer grossen Eisschicht abgeschnitten. Bald aber gab es Eismacher und Eismaschinen.'),
  (117, 'de', 'Sieb', 'Wird zusammen mit Shakern und Seihern zum doppelten Filtern von Cocktails verwendet, wenn man sie vom Shaker ins Glas giesst. Mit einem feinmaschigeren Netz als beim Seiher, verhindert es, dass auch die kleinsten Fruchtsamen und Eisstückchen in den Drink fallen.'),
  (52, 'de', 'Stößel', 'Ein unverzichtbares Accessoire für tropische Cocktails, mit dem man Beeren und Früchte im Shaker oder direkt im Glas zerkleinern kann.'),
  (373, 'de', 'Wäscheklammer', 'Ein dekoratives Accessoire um eine Garnierung am Glas zu halten.'),
  (113, 'de', 'Absinth', 'Der Absinth ist eine französische Spirituose, die durch Mazeration (Aufweichung) von Kräutern und Gewürzen, einschliesslich Zitronenmelisse, Fenchel und Anis, in Neutralalkohol oder Weinalkohol hergestellt wird. Die Hauptzutat ist Wermut, welcher das stark berauschende Thujon enthält.'),
  (295, 'de', 'Zucker Sirup', 'Zucker Sirup'),
  (152, 'de', 'Himbeere', 'Eine kleine rote Beere, die an ganzjährigen Stauden wächst und hauptsächlich in Russland, Serbien, Polen und den USA vorkommt. Sie enthält Zucker, organische Säuren, Vitamin A, B, C und fettige Öle. Eine Beere wiegt durchschnittlich etwa 5g.'),
  (125, 'de', 'Highland Single Malt Whisky', 'Hierbei handelt es sich um Spirituosen aus den Bergen Schottlands, den Highlands. Der Whisky wird aus 100% Gerstenmalz durch zweifache, selten auch dreifache Destillation hergestellt. Der daraus gewonnene Alkohol reift mindestens 3 Jahre in Eichenfässern.'),
  (47, 'de', 'Campari', 'Campari'),
  (189, 'de', 'Grapefruitsaft', 'Für die Herstellung des Saftes werden Grapefruits gepresst, gefiltert und abgefüllt.'),
  (672, 'de', 'Minze', 'Die am höchsten angesehenen Kräuter für Cocktails umfassen mehr als 30 Sorten. In erster Linie werden Pfefferminze und Süße Minze beim Mixen verwendet. Sie sollten nicht länger als 2 Tage in Papiertüchern im Kühlschrank aufbewahrt werden.'),
  (124, 'de', 'Chartreuse Grün', 'Dieser Kloster Likör wird seit 1764 in den französischen Alpen nach einem geheimen Rezept hergestellt. Etwa 130 Pflanzen und Kräuter werden in neutralem Alkohol mazeriert und mehrere Male destilliert. Das Ergebnis wird mit Zucker ausgeglichen, auf die gewünschte Stärke gebracht und in Eichenfässern gereift.'),
  (427, 'de', 'Holunderblüten Likör', 'Ein französischer Blüten Likör, hergestellt nach einem geheimen Rezept durch die Mazeration von zerkleinerten Holunderblüten. Der gewonnene Alkohol wird filtriert, mit Zucker vermengt und bis zur gewünschten Stärke mit Wasser verschnitten.'),
  (35, 'de', 'Trockener Wermut', 'Ein starker Wermut, der erstmals zu Beginn des 21. Jhdt. auftauchte und durch die Mazeration von alpinem Wermut und einem Dutzend anderer Kräuter und Pflanzen in trockenem Weisswein hergestellt wird. Der daraus gewonnene Alkohol wird filtriert und für mindestens 1 Jahr in Eichenfässern aufbewahrt.'),
  (130, 'de', 'Dry Orange Likör', 'Ein duftender Zitrus Likör, hergestellt durch die Mazeration von verschiedenen Schalen der Laraha Orange in neutralem Alkohol mit Wasser. Der daraus resultierende Alkohol wird filtriert, mit Zucker vermengt und in Eichenfässern aufbewahrt.'),
  (114, 'de', 'Peychaud''s Bitter', 'Ein klassischer Bitter aus New Orleans, erfunden 1830 von dem berühmten Apotheker mit einem geheimen Rezept aus neutralem Alkohol, infundiert mit Anis, Nelken, Vanille, Muskat, Früchten und Gewürzen.'),
  (161, 'de', 'Goblet Glas', 'Ein königliches Glas mit dicken Wänden, die es erlauben während des Trinkens mit den Gläsern anzustossen, ohne sie zu zerbrechen. Standardkapazität: 200 - 300 ml.'),
  (665, 'de', 'Maraschino Likör', 'Ein Beerenlikör aus Kroatien, hergestellt durch die mindestens 1-monatige Mazeration von Maraska-Kirschen, einschliesslich deren Kerne, in neutralem Alkohol mit Wasser. Das Ergebnis wird filtriert, gesüßt, zu seiner gewünschten Stärke gebracht und mindestens 3 Jahre lang in Eichenfässern gereift.'),
  (303, 'de', 'Grapefruit Bitter', 'Ein saisonaler Sommer-Bitter, hergestellt durch die Infusion von Neutralalkohol mit Grapefruit Schalen unter der Zugabe von Hopfen, um die Bitterkeit zu mildern.'),
  (20, 'de', 'Rote Maraschino Kirsche', 'Spezielle Kirschsorten, wie “King Anna”, “Rainier” oder "Golden Diversity", werden in eine Kochsalzlösung gelegt werden und danach in Zuckersirup mit der Zugabe von Lebensmittelfarbe eingeweicht werden.'),
  (96, 'de', 'Cocktailspieß', 'Ein dekoratives Accessoire um Oliven mit Martinis und Cocktailkirschen mit Manhattan-Cocktails zu servieren. Zuerst tauchten sie am Ende des 19. Jhdt. dank des Marketinggenies Charles Forster in Bars auf.'),
  (101, 'de', 'Gereifter Rum', 'Der gereifte Rum ist eine karibische Spirituose, hergestellt durch die vertikale Destillation von Alkohol, welcher durch Gärung von Melasse oder Saft vom Zuckerrohr gewonnen wird. Vor dem Mischen wird er, abhängig von der gewählten Alterungsmethode, zwischen 7 und 20 Jahren in ausgebrannten Bourbon oder Sherry Eichenfässern aufbewahrt.'),
  (116, 'de', 'Dunkler Kakao Likör', 'Dunkler Schokoladen Likör, hergestellt durch die Filtration von Kakaobohnen mit neutralem Alkohol. Das Resultat wird bis zur gewünschten Stärke mit Wasser verschnitten und mit madagassischer Vanille und Karamell vermengt, wodurch die dunkle Farbe des Likörs entsteht.'),
  (67, 'de', 'Misch Glas', 'Ein klassisches Must-Have jeder 5-Sterne-Bar. Verwendet für die Herstellung von starken, “männlichen” Drinks ohne die Zugabe von Säften, Kräutern oder Marmeladen. Das Eis behält seine Form und schmilzt nicht so leicht, so dass die Stärke des Drinks erhalten bleibt. Standardkapazität: 500-900 ml.'),
  (166, 'de', 'Amaro', 'Ein italienischer Vintage Likör, hergestellt durch die Mazeration von Kräutern und Wurzeln, einschliesslich Zitrus Schalen, Wacholder, Fenchel, Zitronenmelisse, Anis und Kardamom, in neutralem Alkohol. Der daraus gewonnene Alkohol wird gefiltert, mit Zucker vermengt und mit Wasser verdünnt, bis er die gewünschte Stärke erreicht.'),
  (171, 'de', 'Eiskugel', 'Der Stolz japanischer Barkeeper - Eis, das zu einem Kunstobjekt erhoben wurde. Heutzutage sind sie Dank spezieller Maschinen etwas häufiger in Bars zu finden. Fertige Eiswürfel werden in einen leicht warmen Schraubstock gegeben und das Metall wird durch Wasser erwärmt, wodurch der Umriss einer Kugel entsteht.'),
  (3, 'de', 'Zitrone', 'Eine tropische Zitrusfrucht, die hauptsächlich in China, Indien und Mexico auf kleinen immergrünen Bäumen wächst. Sie enthält Vitamin C und organische Säuren und wird traditionell im Kampf gegen Erkältungen und Nährstoffdefizite verwendet. Eine Frucht wiegt etwa 160g, liefert 60ml Fruchtsaft und kann in 8 Stücke oder 4 grosse Teile mit jeweils 15ml Saft geteilt werden'),
  (62, 'de', 'Bourbon', 'Hierbei handelt esum eine starke Spirituose amerikanischer Herkunft. sich Der Bourbon muss einen gesetzlich vorgeschriebenen Maisanteil in der Maische von mindestens 51% haben, zudem Gerste und Roggen, erst destilliert, dann gefiltert. Für seinen Geschmack reift er zwischen 2 und 7 Jahren in Eichenfässern. Die Fässer werden mit einer speziellen Technologie innen ausgebrannt.'),
  (111, 'de', 'Creme de Cassis Likör', 'Der Beeren Likör aus Dijon wird durch eine bis zu 2-monatige Mazeration von schwarzen Johannisbeeren in neutralem Alkohol hergestellt. Der Likör wird nicht filtriert und mit Zucker vermengt.'),
  (63, 'de', 'Angostura Bitter', 'Ein Vintage Bitter aus Venzuela, benannt zu Ehren der Stadt Angostura. Hergestellt wird dieser Bitter nach dem geheimen Originalrezept von Dr. Johann Gottlieb Benjamin Siegert (ca. 1800), indem geheime Gewürze und Kräuter in dunklem Rum infundiert werden.'),
  (16, 'de', 'Leichte Sahne', 'Fettarme Sahne wird hauptsächlich aus Kuhmilch hergestellt, indem der Rahm von der Milch getrennt wird. Der Anteil an Fett variiert in verschiedenen Ländern, liegt aber meist bei unter 15%. Im Kühlschrank bis zu 20 Tage haltbar.'),
  (36, 'de', 'Roter Wermut', 'Ein leicht süßlicher Wermut, hergestellt durch die Mazeration von 30 alpinen Kräutern und Gewürzen in Weißwein. Der dadurch gewonnene Alkohol wird gefiltert, auf seine gewünschte Süße und Stärke gebracht, mit Zuckerkulör vermengt und mindestens 1 Jahr lang in Eichenfässern aufbewahrt.'),
  (34, 'de', 'Sprudelwasser', 'Kohlensäurehaltiges Wasser, das ein unentbehrlicher Bestandteil von Fizz und anderen kohlensäurehaltigen Drinks ist. Früher produziert durch das Karbonisieren von Wasser mit Kohlendioxid und mittlerweile zunehmend hergestellt durch die Zugabe von Backpulver zu stillem klarem Wasser.'),
  (732, 'de', 'Orangen Schale', 'Die oberste Schicht einer Orangenschale, mit einem speziellen scharfen Messer abgeschnitten. Enthält ätherische Öle, die den Geschmack der Orange tragen. Die Schale kann von einer geschnittenen oder ganzen Frucht gewonnen werden und geraspelt oder sogar zur Spirale gedreht (Twist genannt) werden.'),
  (258, 'de', 'Champagner', 'Ein Schaumwein, der unter strengen Auflagen in der gleichnamigen Region Frankreichs hergestellt wird. Drei verschiedene Rebsorten, von Hand verlesen, werden gegärt und die daraus resultierenden Weine werden vermengt und mit der Zugabe von Rohrzucker und Hefe abgefüllt. Eine zweite Vergärung findet in der Flasche statt und dauert 9 Monate. Der Rückstand wird daraufhin durch eine Methode, die Remuage (dt. Rütteln) genannt wird, entfernt und nach der Zugabe von Alkohol wird die Flasche mit einem Champagner-Korken verschlossen.'),
  (148, 'de', 'Pfirsich Püree', 'Pfirsich Püree'),
  (535, 'de', 'Pfirsich', 'Eine die Sonne liebende Frucht, die hauptsächlich in China, Italien und Spanien auf Laubbäumen wächst. Sie enthält organische Säuren, Mineralsalze und Pektin. Eine Frucht wiegt etwa 120g, woraus ca. 80g Püree gewonnen werden können.'),
  (59, 'de', 'Kelch Glas', 'Ein High-Society Glas für Cocktails, die auf Champagner oder Sekt basieren. Die lange dünne Form erinnert an eine Tulpe und bewahrt die Schaumweinperlen, so dass der Cocktail länger sprudelnd bleibt. Standardvolumen: 180 - 250 ml.'),
  (179, 'de', 'Limettette Cordial', 'Ein altes Zitrus-Rezept, hergestellt durch die Pasteurisierung von Limettensaft gemischt mit Zuckersirup, Weinstein und Wasser.'),
  (733, 'de', 'Limetten Schale', 'Die oberste Schicht einer Limetten-Haut, mit einem speziellen scharfen Messer abgeschnitten. Enthält ätherische Öle, die den Geschmack der Limette tragen. Die Schale kann von einer geschnittenen oder ganzen Frucht gewonnen werden und geraspelt oder sogar zur Spirale gedreht (Twist genannt) werden.'),
  (72, 'de', 'Cocktail Glas', 'Ach bekannt als Martini Glas. Eines der ersten Gläser in denen Cocktails ohne Eis serviert wurden. Vor dem Servieren muss das Glas gekühlt werden und der lange Stiel verhindert, dass der Cocktail durch das Halten warm wird. Standardkapazität: 90 - 160 ml.'),
  (40, 'de', 'Cognac', 'Es handelt sich hierbei um einen gereiften Alkohol französischer Herkunft aus weissen Trauben: Ugni Blanc, Folle Blanche oder weniger oft auch Colombard Montilla. Er wird durch zweifache Destillation hergestellt und reift in Eichenfässern. Die Altersangabe VS (Very Special) kann bis zu 3 Jahre und V.S.O.P (Very Superior Old Pale) sogar bis zu 5 Jahre an Reife bedeuten.'),
  (14, 'de', 'Gemahlene Muskatnuss', 'Ein indonesisches Gewürz aus Muskatnüssen, die getrocknet und zu einem Pulver zermahlen werden.'),
  (746, 'de', 'Muskatreibe', 'Ein nützliches Accessoire um Muskat oder Kakaopulver zuzubereiten, oder seltener auch Schalen von Zitrusfrüchten.'),
  (8, 'de', 'Orangensaft', 'Für die Herstellung des Saftes werden Orangen gepresst, gefiltert und abgefüllt.'),
  (88, 'de', 'Weißer Rum', 'Rum ist eine karibische Spirituose, hergestellt durch die vertikale Destillation von Alkohol, welcher durch Gärung von Melasse oder Saft vom Zuckerrohr gewonnen wird. Vor dem Mischen wird er, abhängig von der gewählten Alterungsmethode, mindestens 12 Monate lang in ausgebrannten Bourbon oder Sherry Eichenfässern aufbewahrt. Der Rum wird gefiltert um ihn zu entfärben.'),
  (92, 'de', 'Calvados', 'Hierbei handelt es sich um eine französische Spirituose, die zunächst aus Cidre hergestellt wird, welcher durch die 6-monatige bis 1-jährige Gärung von Saft aus normannischen Herbst Äpfeln in stählernen Fässern entsteht. Daraufhin wird das Getränk zweifach destilliert und mindestens 2 Jahre in Eichenfässern gereift.'),
  (77, 'de', 'Grenadine Sirup', 'Populärer roter Fruchtsirup, hergestellt durch die Pasteurisierung von Granatapfelsaft mit dem Saft anderer roter Beeren, Vanille und Rohrzucker.'),
  (86, 'de', 'Brauner Rum', 'Der braune Rum ist eine karibische Spirituose, hergestellt durch die vertikale Destillation von Alkohol, welcher durch Gärung von Melasse oder Saft vom Zuckerrohr gewonnen wird. Vor dem Mischen wird er, abhängig von der gewählten Alterungsmethode, zwischen 2 und 7 Jahren in ausgebrannten Bourbon oder Sherry Eichenfässern aufbewahrt. Um seine Farbe zu bewahren wird er nicht gefiltert.'),
  (365, 'de', 'Overproof Rum', 'Eine karibische Spirituose, hergestellt durch die vertikale Destillation von Alkohol, welcher durch Gärung von Melasse oder Saft vom Zuckerrohr gewonnen wird. Vor dem Mischen wird er für mindestens ein Jahr in ausgebrannten Bourbon oder Sherry Eichenfässern aufbewahrt. Um seine Stärke zu bewahren wird er nicht mit Wasser verschnitten.'),
  (190, 'de', 'Grapefruit', 'Diese beliebte Zitrusfrucht wächst hauptsächlich in China, den USA und Mexico. Sie enthält Vitamin C, Pektin und Lycopin mit Cholesterin senkenden Eigenschaften. Eine Frucht wiegt etwa 600g, kann in 10 Stücke geteilt werden und ergibt ca. 200ml Fruchtsaft.'),
  (186, 'de', 'Tiki Becher', 'Tiki Becher sind Keramikgefäße für Tiki Cocktails.'),
  (662, 'de', 'Irischer Whiskey', 'Diese Spirituose kommt aus Irland und wird aus dem Malz gekeimter Gerste hergestellt, welche im Ofen getrocknet, gemahlen und mit heissem Wasser bedeckt wird. Getrennt vom Korn wird die Flüssigkeit gegärt, dreifach destilliert und zum Reifen für mindestens 3 Jahre in Eichen-, Sherry-, Bourbon- oder Portfässern aufbewahrt.'),
  (128, 'de', 'Schlagsahne', 'Doppelrahm wird hauptsächlich aus Kuhmilch hergestellt, indem der Rahm von der Milch getrennt wird. Der Anteil an Fett variiert von 20 bis zu 40%. Im Kühlschrank bis zu 20 Tage haltbar.'),
  (74, 'de', 'Schüssel', 'Ein Behälter aus Glas oder Metall, um Zutaten mit einem Schneebesen zu vermengen. Eine Mischung in der Tomaten oder Zitrussäfte vorkommen, sollte nur in einer Schüssel aus Glas oder Edelstahl vorgenommen werden um eine Reaktion der Säuren zu vermeiden.'),
  (90, 'de', 'Irish Coffee Glas', 'Ein starkes Glas zum Servieren von Grog, Glühwein und Cocktails mit Kaffee - benannt zu Ehren einer dieser Kaffee-Cocktails. Standardkapazität: 200 - 300 ml.'),
  (78, 'de', 'Schneebesen', 'Unentbehrlich um Sahne für Irish Coffee oder Eiweiss mit Zucker für einen Tom und Jerry zu schlagen. Um Zutaten in einem Krug zu mischen oder zu schlagen, wird eine spezielle Version verwendet, die einen längeren Griff und ein schmale Spitze am Ende hat.'),
  (761, 'de', 'Kaffeemaschine', 'Ein automatisches Gerät um verschiedene Arten von Kaffee zu machen: Latte, Espresso, Americano, Latte Macchiato, Cappuccino, Eiskaffee.'),
  (39, 'de', 'Cachaca', 'Brasilianischer Alkohol, der durch die sorgfältige Filtrierung und Destillation von gegärtem Zuckerrohrsaft hergestellt wird. Bei dieser Methode werden der “Kopf” und der “Schwanz” weggeworfen und nur das “Herz” des Getränks reift für mindestens 1 Jahr in Eichenfässern.'),
  (5, 'de', 'Limette', 'Eine tropische Zitrusfrucht, die das ganze Jahr hindurch in tropischem Klima wächst, hauptsächlich in China, Indien und Mexico. Limetten sind eine hervorragende Quelle für Zellulose, Vitamin C und Calcium und perfekt um die Aromen in Lebensmitteln und Getränken hervorzuheben. Eine Frucht wiegt etwa 80g, liefert 30ml Fruchtsaft und kann in 4 Scheiben mit jeweils 7.5 ml Saft geteilt werden.'),
  (43, 'de', 'Himbeer Sirup', 'Ein beliebter Beerensirup, hergestellt durch die Pasteurisierung von Himbeersaft gemischt mit Zucker und Wasser.'),
  (661, 'de', 'Zitrus Wodka', 'Stark aromatisierte Spirituose, hergestellt durch mehrfache Destillation von Getreide, mehrere Stufen der Reinigung durch Aktivkohle und andere Filterprozesse und später mit destilliertem Wasser verschnitten. Das gewonnene Getränk wird mit Zitrus- und Limetten-Extrakten aufgegossen.'),
  (481, 'de', 'Cranberrysaft', 'Für die Herstellung des Saftes werden Johannisbeeren gepresst, gefiltert und abgefüllt.'),
  (53, 'de', 'Küchenbrenner', 'Das Accessoire eines Kavaliers um das Zitrusöl über dem berühmten Cosmopolitan zu flambieren, prickelnden Zimt über Tiki-Cocktails zu sprühen und einfach um Gästen eine Zigarre anzuzünden.'),
  (82, 'de', 'Tawny Port', 'Gesättigter roter Portwein, hergestellt aus einer Mischung von roten Vintage-Weinen mit der Zugabe von Cognac und der darauf folgenden Reifung nach der Solera Methode in Eichenfässern.'),
  (49, 'de', 'Wachtel Eigelb', 'Dieses Produkt gibt einem Cocktail eine zarte Konsistenz. Ein Hühnereigelb entspricht 5 Wachteleigelb.'),
  (178, 'de', 'Wachteleischere', 'Eine spezielle Schere mit einem Ring zum Halten, die glatt durch das Ei schneidet.'),
  (569, 'de', 'Sellerie', 'Das “Recht auf Ruhm” dieser Pflanze beruht auf dem antiken Griechenland. Sie wächst hauptsächlich in mediterranem Klima. Vor dem Servieren müssen die Fasern entfernt werden, indem ein kleiner Einschnitt am Stiel gemacht wird und der “Faden” abgezogen wird. Ein Stängel wiegt durchschnittlich etwa 15g.'),
  (42, 'de', 'Rote Tabasco Sauce', 'Eine pfeffrige rote Sauce, hergestellt aus ausgewählten reifen Chili Paprikas, die 3 Jahre lang in weissen Eichenfässern mit Salz aus Avery Island lagern. Der dadurch entstandene Brei wird mit Essig gewürzt und weitere 4 Wochen reifen gelassen. Die Sauce ist schärfer als die grüne Version.'),
  (56, 'de', 'Gemahlener schwarzer Pfeffer', 'Ein gemahlenes Gewürz aus Indien, hergestellt aus unreifen Beeren von schwarzem Pfeffer, getrocknet in der Sonne, bis sie schwarz sind. Im Gegensatz zur körnigen Version verfliegt der Duft viel schneller.'),
  (58, 'de', 'Longdrinkglas', 'Ein hohes Glas für Wasser, Säfte oder Club Mischungen, die direkt im Glas zubereitet werden. Standardkapazität: 300-400 ml.'),
  (37, 'de', 'Scotch Whisky', 'Hierbei handelt es sich um eine Spirituose aus Schottland, die aus über Torffeuer gedarrtem Gerstenmalz hergestellt wird. Dies wird gemahlen und mit heissem Wasser bedeckt. Die abgesonderte Flüssigkeit wird gegärt und dreifach destilliert. Der gewonnene Alkohol wird gemischt und mindestens 3 Jahre lang zum Reifen in Eichen-, Sherry, Bourbon- oder Portfässern gelagert.'),
  (46, 'de', 'Kirsch Likör', 'Der berühmte Beeren Likör wird hergestellt, indem Kirschen für mindestens einen Monat in mehreren verschiedenen neutralen Spirituosen mit Wasser mazeriert werden. Das Ergebnis wird gefiltert, gesüßt, mit Cognac verstärkt und mindestens 3 Jahre lang in Eichenfässern gereift.'),
  (89, 'de', 'Goldener Rum', 'Der goldene Rum ist eine karibische Spirituose, hergestellt durch die vertikale Destillation von Alkohol, welcher durch Gärung von Melasse oder Saft vom Zuckerrohr gewonnen wird. Vor dem Mischen wird er, abhängig von der gewählten Alterungsmethode, zwischen 1 und 5 Jahren in ausgebrannten Bourbon oder Sherry Eichenfässern aufbewahrt. Der Rum wird nicht gefiltert und manchmal wird eine Karamel-Färbung hinzugefügt.'),
  (94, 'de', 'Cola', 'Das beliebteste kohlensäurehaltige Getränk, hergestellt nach einem geheimen Rezept, welches auf Koffein, Zucker, Aromen und Farbstoffen basiert.'),
  (60, 'de', 'Weißer Kakao Likör', 'Ein leichter Schokoladenlikör, hergestellt durch die Filtration von Kakaobohnen mit neutralem Alkohol. Das Ergebnis wird gefiltert, verliert seine dunkle Farbe und wird bis zu seiner gewünschten Stärke mit Zucker vermengt bis eine cremige Konsistenz entsteht.'),
  (61, 'de', 'Grüner Minze Likör', 'Ein cremiger Kräuter Likör, hergestellt mit hohem Zuckergehalt durch die Filtration von frischem Pfefferminz Extrakt mit Limetten Destillat in neutralem Alkohol. Das Ergebnis wird auf die gewünschte Süße und Stärke gebracht und dann abgefüllt.'),
  (93, 'de', 'Weißer Tequila', 'Dies ist ein gereifter Alkohol mexikanischer Herkunft, traditionell hergestellt durch die Destillation von blauem Agavensaft. Sieben bis zehn Sommer-Agavenherzen werden in spezielle Öfen gegeben, um deren Stärke in Zucker umzuwandeln; der gewonnene Saft wird gegärt, doppelt destilliert und nach seiner Filtrierung sofort abgefüllt.'),
  (212, 'de', 'Ingwerbier', 'Das ”Trojanische Pferd" unter den Wodkas in Amerika. Diese spezielle Art von Limonade wird durch die Mazeration von getrocknetem, gemahlenen Ingwer in Bierhefe hergestellt.'),
  (99, 'de', 'Mandel Sirup', 'Mandel Sirup'),
  (127, 'de', 'Salz', 'Ein kristallisiertes Würzmittel aus Mineralien, das bis zu 250 Millionen Jahre alt ist.'),
  (84, 'de', 'Margarita Glas', 'In seinem früheren Leben war dies eine Sauciere für Guacamole, nun aber ist es das Haupt-Glas um den berühmtesten Tequila-Cocktail der Welt zu servieren. Standardkapazität: 250-350 ml.'),
  (85, 'de', 'Orangen Bitter', 'Einer der ältesten verfügbaren Zitrusbitter. Für seine Herstellung werden getrocknete Orangenschalen, Gewürze und Kräuterwurzeln in Rum infundiert und vor dem Abfüllen noch Rohrzucker und destilliertes Wasser hinzugefügt.'),
  (75, 'de', 'Maracuja Sirup', 'Ein tropischer Fruchtsirup, hergestellt durch die Pasteurisierung von Maracuja-Fruchtfleisch gemischt mit Rohrzucker und Wasser.'),
  (7, 'de', 'Ananassaft', 'Für die Herstellung des Saftes weird das Fruchtfleisch von Ananas gepresst, gefiltert und abgefüllt.'),
  (76, 'de', 'Hurricane Glas', 'Ein altertümliches Glas, das einer Kerosinlampe gleicht und zum Servieren von tropischen Drinks verwendet wird, benannt nach dem Namenspatron Pat O’Brien. Standardkapazität: 300-400 ml.'),
  (4, 'de', 'Orange', 'Eine orangefarbene Zitrusfrucht, die hauptsächlich in Brasilien, den USA und China auf grossen Bäumen wächst. Sie enthält Vitamin C, Kalium und Calcium und ist bekannt für ihre positive Wirkung auf Herz, Blutgefäße und den Körper allgemein. Eine Frucht wiegt etwa 300g, liefert 80ml Saft und kann in 10 Stücke oder 8 Scheiben geteilt werden.'),
  (375, 'de', 'Collins Glas', 'Ein hohes Glas für Long und Mixed Drinks. Benannt nach dem klassischen Cocktail "Tom Collins". Standardkapazität: 300-400 ml.'),
  (104, 'de', 'Benedictine', 'Dieser berühmte normannische Likör ist mit der Inschrift DOM - DEO Optimo Maximo («Dem gnädigsten und erhabensten Gott») versehen und wird in 4 Stufen aus 27 geheimen Kräutern und Gewürzen hergestellt. Nach deren separater Mazeration und Destillation wird der gewonnene Alkohol getrennt aufbewahrt und dann 11 Monate lang in Eichenfässern vermengt. Danach wird das Ergebnis mit Wasser, Brandy, Honig und gebranntem Zucker gemischt und leitet die finale Phase der Alterung für weitere 3 Monate ein.'),
  (95, 'de', 'Ananas', 'Eine tropische Frucht, die an terrestrischen, stacheligen Pflanzen, hauptsächlich in Brasilien, Thailand und den Philippinen wächst. Sie enthält Mangan und Vitamin C und stimuliert bekannterweise die Verdauung und reduziert Blutviskositaet. Eine Frucht wiegt etwa 1200g und kann in 40 Stücke geteilt werden.'),
  (105, 'de', 'Sling Glas', 'Das wesentliche Glas um Cocktails selbigen Namens zu Servieren, das zur Visitenkarte der Raffles Hotels wurde. Standardvolumen: 200-300 ml.'),
  (79, 'de', 'Stilles Wasser', 'Die wichtigste Quelle für Gesundheit und ein langes Leben. Barkeeper weltweit empfehlen immer Wasser zu trinken, während man Cocktails zu sich nimmt. Deshalb wird in den besten Häusern ein Glas Wasser kostenlos serviert.'),
  (150, 'de', 'Zuckerwürfel', 'Ein süsses Würzmittel aus Europa, gewonnen durch eine komplizierte Reinigung, Veredelung und Kristallisierung von Sirup vom Zuckerrohr oder Zuckerrübensaft. Die Kristalle werden in die gewünschte Form gepresst.'),
  (100, 'de', 'Drambuie', 'Der schottische Likör, der aus dem Gälischen übersetzt so viel wie “glücklich machend” bedeutet, wird seit 1910 nach einem geheimen Rezept hergestellt. Es ist bekannt, dass der Drink aus einer Mischung aus berühmten Single Malts, Heidehonig, Kräutern und Gewürzen hergestellt wird.'),
  (677, 'de', 'Orangenblütenwasser', 'Ein altes Rezept für Wasser, das mit frischen Blüten der Bitterorange infundiert wird.'),
  (118, 'de', 'Ananas Blätter', 'Blätter einer tropischen Frucht, die als Verzierung für exotische Tiki-Cocktails verwendet werden.'),
  (98, 'de', 'Pisco', 'Dieser peruanische Brandy wird aus 8 verschiednen Traubensorten hergestellt, wohingegen in Chile nur maximal 3 Sorten benutzt werden. Der gegärte Saft wird in Edelstahl-Bottichen destilliert und entweder sofort abgefüllt oder noch 2 Jahre zum Reifen in Eichenfässern aufbewahrt.'),
  (103, 'de', 'Rohrzuckerwürfel', 'Ein tropisches, süsses Gewürz, welches durch das Kristallisieren von Zuckerrohr hergestellt wird und danach in kleine Würfel gepresst wird. Je höher der Anteil an Melasse, desto dunkler die Farbe und reicher der Geschmack.'),
  (132, 'de', 'Gereifter Bourbon', 'Gereifter Bourbon'),
  (102, 'de', 'Streuzucker', 'Ein süsses Würzpulver, hergestellt aus gemahlenem, puderigem Zucker, gemischt mit Speisestärke damit er nicht verklumpt. Aufgrund der geringen Körnergrösse löst er sich sofort in Flüssigkeiten auf und spart dadurch Zeit.'),
  (158, 'de', 'Kupferbecher', 'Ein Must-Have, das zum “Trojanischen Pferd” des Wodkas in Amerika geworden ist. Es ist das Glas der Wahl um den "Moscow Mule" Cocktail zu servieren. Standardkapazität: 300-400 ml.'),
  (214, 'de', 'Brombeere', 'Dunkelviolette, mittelgrosse Beeren, die an Büschen in Europa, Nordwestafrika, Zentralasien und Nord- und Südamerika wachsen. Sie enthalten Carotin, Vitamin C, K, B1 und B1 und andere Vitamine. Eine Beere wiegt durchschnittlich etwa 6g .'),
  (115, 'de', 'Kristallzucker', 'Ein süsses Gewürz aus Europa, gewonnen durch eine komplizierte Reinigung, Veredelung und Kristallisierung von Sirup vom Zuckerrohr oder Zuckerrübensaft. Die Grösse des Granulats ist wichtig, je kleiner desto schneller löst es sich auf.'),
  (107, 'de', 'Milch', 'Hergestellt aus Vollmilch von Kühen. Der gewünschte Fettanteil wird durch die Zugabe von Rahm oder Fett zu einer fettfreien Version des Produkts erreicht.'),
  (330, 'de', 'Zimtstange', 'Ein Würzmittel aus Sri Lanka, das seit dem 15. Jhdt. bekannt ist und aus Zweigen und Stämmen des Zimtbaumes hergestellt wird. Es wird gereinigt, geschmirgelt und im Schatten getrocknet bis es sich röhrenartig zusammenrollt.'),
  (108, 'de', 'Becher', 'Ein hoher Becher aus Keramik für Kaffee oder Tee. 1930 wurde es das Utensil der Wahl für den "Tom und Jerry" Cocktail. Standardkapazität: 200-250 ml.'),
  (655, 'de', 'Milchkanne', 'Eine Milchkanne aus Metall. Wird für Schlagsahne und zur Herstellung von heissen Cocktails verwendet.'),
  (120, 'de', 'Gemahlener Zimt', 'Ein gemahlenes Gewürz aus Sri Lanka, das seit dem 15. Jhdt. bekannt ist. Späne und Reste der Zimtbaumrinde werden hierfür getrocknet und gemahlen.'),
  (149, 'de', 'Sternanis', 'Eine tropische, sternförmige Frucht, die auf immergrünen Bäumen hauptsächlich in China wächst. Sie wird in unreifem Zustand gepflückt und in der Sonne getrocknet.'),
  (134, 'de', 'Ahorn Sirup', 'Ein berühmter Weihnachtssirup aus dem Saft des Zuckerahorn, der im Februar und März von Ahornbäumen gesammelt wird. Hergestellt wird er durch die Pasteurisierung dieses Saftes mit Rohrzucker und Wasser.'),
  (123, 'de', 'Rosen Sirup', 'Ein schmackhafter Blütensirup, hergestellt durch die Infusion und Pasteurisierung von Rosenblüten in Zuckersirup.'),
  (201, 'de', 'Rosenblüten', 'Die sich am besten verkaufende Blume der Welt. In einer Knospe befinden sich 25 Blütenblätter.'),
  (1035, 'de', 'Amerikanischer Whisky', 'Amerikanischer Whisky'),
  (288, 'de', 'Pedro Ximenez Sherry', 'Die süßeste Sorte des gereiften spanischen Weins wird aus den gleichnamigen Trauben hergestellt. Der gegärte Saft wird mit Alkohol aus Trauben angereichert und unter Benutzung der Solera Methode zwischen 10 und 30 Jahren oder länger in Eichenfässern reifen gelassen.'),
  (154, 'de', 'Teelöffel', 'Ein Löffel um Tee in einer Tasse umzurühren. Auf einen Löffel passen etwa 5g Trockenprodukt oder 5ml Flüssigkeit.'),
  (211, 'de', 'Eis Rocks', 'Ein klumpiger oder gerader Würfel, wobei ein grösseres Stück Eis langsamer schmilzt und beeindruckender im Glas aussieht.'),
  (450, 'de', 'Ingwer Sirup', 'Ein würziger, asiatischer Sirup, der durch die Pasteurisierung von Ingwer-Extrakten in Zuckersirup entsteht.'),
  (693, 'de', 'Mate Bombilla', 'Ein spezieller Strohhalm um Mate zu servieren. Das obere Ende enthält ein Mundstück, während am unteren Ende ein Sieb ist.'),
  (552, 'de', 'Johannisbeere', 'Kleine rote Beeren, die an laubtragenden Stauden wachsen und hauptsächlich in Nordasien, Zentral- und Nordeuropa vorkommen. Sie enthalten grosse Mengen an Vitamin C, verschiedene Zucker, organische Säuren und Mineralien. Auf einen Barlöffel passen durchschnittlich etwa 5g Beeren.'),
  (332, 'de', 'Oloroso Sherry', 'Ein halbtrockener oder süßer Likörwein aus Spanien, hergestellt durch die Vergärung von Palomino Sherry-Trauben ohne die Bildung eines schützenden Films, dem Flor. Das Ergebnis wird in mehreren Stufen mit Alkohol aus Trauben angereichert und durch die Solera Methode mindestens 2 Jahre lang in Eichenfässern gereift.'),
  (191, 'de', 'Getrocknete Aprikosen', 'Eine helle, getrocknete Frucht, hergestellt aus reifen Aprikosen hauptsächlich in der Türkei, im Iran und Usbekistan. Die Früchte werden zunächst eingekocht oder in Sirup eingeweicht und dann in der Sonne oder einem speziellen Trockner getrocknet. Ein Stück wiegt durchschnittlich etwa 10g.'),
  (683, 'de', 'Tablett', 'Eine Platte aus Metall oder Holz um den Gästen Essen oder Getränke zu servieren.'),
  (121, 'de', 'Vanille Sirup', 'Ein duftender Sirup aus Madagaskar, hergestellt durch die Infusion und Pasteurisierung von Vanilleschoten.'),
  (381, 'de', 'Brauner Tequila', 'Dies ist ein gereifter Alkohol mexikanischer Herkunft, traditionell hergestellt durch Destillation von blauem Agavensaft. Sieben bis zehn Sommer-Agavenherzen werden in spezielle Öfen gegeben, um die Stärke in Zucker umzuwandeln; der gewonnene Saft wird gegärt, doppelt destilliert und mit Karamell gefärbt. Er erhält Geschmack durch verschiedene aromatische Zusätze.'),
  (318, 'de', 'Weißer Wermut', 'Der Süßeste unter den Wermuts, hergestellt durch die Mazeration von alpinen Kräutern und Gewürzen in Weißwein. Der dadurch gewonnene Alkohol wird gefiltert, auf seine gewünschte Stärke und maximale Süße gebracht und mindestens 1 Jahr lang in Eichenfässern aufbewahrt.'),
  (126, 'de', 'Erdbeer Püree', 'Erdbeer Püree'),
  (327, 'de', 'Rohrzucker', 'Ein tropisches, süsses Gewürz, hergestellt durch das Kristallisieren von Zuckerrohr mit einem nachfolgenden mechanischen Prozess. Je höher der Anteil an Melasse, desto dunkler die Farbe und reicher der Geschmack.'),
  (138, 'de', 'Mixer', 'Erfunden im Jahr 1922 von Stephen Poplawski, ist dieses elektrische Instrument unverzichtbar in der Herstellung von Tiki-Cocktails, Smoothies und gefrorenen Drinks.'),
  (196, 'de', 'Kokosnuss Sirup', 'Dieser beliebteste tropische Sirup entsteht durch die Pasteurisierung von Kokosnusswasser mit Rohrzucker.'),
  (197, 'de', 'Ananasschneider', 'Ein Tiki-Accessoire, das innerhalb weniger Sekunden die Schale und den harten Kern einer Ananas entfernt.'),
  (744, 'de', 'Eisschaufel', 'Ein praktisches Werkzeug aus Polycarbonat oder Edelstahl, das es einem erlaubt eine bestimmte Menge Eis zu nehmen. Die Schaufeln variieren in Größe und Volumen, wodurch man eine Schaufel für die gewünschte Menge Eis auswählen kann.'),
  (406, 'de', 'Gelber Bananen Likör', 'Ein tropischer, cremiger Likör, der hergestellt wird indem das Fruchtfleisch gelber Bananen in Neutralalkohol mit Wasser mazeriert wird. Das Ergebnis wird gefiltert, mit Zucker vermengt und um mit jungem Brandy angereichert.'),
  (200, 'de', 'Banane', 'Die älteste tropische Pflanze, die hauptsächlich in China, Indien und Uganda wächst. Ihre Früchte enthalten viel Vitamin B6, Mangan und Ballaststoffe. Eine Frucht wiegt etwa 200g, mit ca. 80g Schale.'),
  (244, 'de', 'Jenever', 'Ein Getränk aus den Niederlanden, der Vater des Gin, hergestellt seit dem 15. Jhdt. durch Destillation von purem Alkohol und dem Zusatz von Wacholderbeeren und anderen Gewürzen.'),
  (133, 'de', 'Honig Sirup', 'Hierbei handelt es sich um den wohl beliebtesten Sirup, hergestellt durch die Pasteurisierung von Honig, der darauf bis zu seiner gewünschten Konsistenz mit Wasser verschnitten wird'),
  (293, 'de', 'Teekanne', 'Die Geschichte dieses alten chinesischen Gefäß reicht zurück zum Ursprung des Tees selbst - ins 14 Jhdt. nach China. Verwendet um Tee, Kräuter und Gewürze in kochendem Wasser zu brauen.'),
  (287, 'de', 'Single Islay Malt Whisky', 'Single Islay Malt Whisky'),
  (284, 'de', 'Rhabarber Likör', 'Ein bitter-süßer Kräuterlikör, ideal zum Dessert, hergestellt durch die Mazeration von Rhabarberstängeln und -blättern in neutralem Alkohol mit Wasser. Das Resultat wird mit Zucker vermengt und auf die gewünschte Stärke gebracht.'),
  (358, 'de', 'Cynar', 'Italienischer Kräuter Likör, hergestellt durch die Mazeration und Destillation von 16 Kräutern und Gewürzen, hauptsächlich Artischocken, in neutralem Alkohol. Der dadurch gewonnene Alkohol wird gefiltert und zu gewünschter Stärke und Süße gebracht.'),
  (735, 'de', 'Grapefruit Schale', 'Die oberste Schicht einer Grapefruit-Haut, mit einem speziellen scharfen Messer abgeschnitten. Enthält ätherische Öle, die den Geschmack der Grapefruit tragen. Die Schale kann von einer geschnittenen oder ganzen Frucht gewonnen werden und geraspelt oder sogar zur Spirale gedreht (Twist genannt) werden.'),
  (704, 'de', 'Zerstäuber', 'Ein attraktives Accessoire um Bitters und aromatische Zusatzstoffe über Cocktails zu sprühen.'),
  (435, 'de', 'Fino Sherry', 'Ein trockener Likörwein aus Spanien, hergestellt durch die Vergärung von Palomino Sherry-Trauben mit der Zugabe besonderer Hefe. Nach einer mindestens 12 Monate langen Reife ist der Wein mit einem speziellen Film bedeckt - dem Flor. Er wird in mehreren Stufen mit Alkohol aus Trauben angereichert und unter dem schützenden Film für mindesten 2 Jahre in Fässern reifen gelassen.'),
  (653, 'de', 'Shot Glas', 'Ein Glas mit vorgegebenen geraden Kanten. Es ist bestimmt für die stärksten Drinks und Cocktails, die in einem Zug getrunken werden sollten. Standardvolumen: 50-100 ml.'),
  (546, 'de', 'Erdbeere', 'Grosse rote Beeren, welche an kleinen Sträuchern, hauptsächlich in den USA, der Türkei, Spanien, Ägypten und Mexico wachsen. Sie enthalten Zucker, Pektin, Tannin, Ascorbinsäure und andere entzündungshemmende Wirkstoffe. Eine Beere wiegt durchschnittlich etwa 20g.'),
  (402, 'de', 'Limoncello', 'Der italienische Nationallikör wird durch die einmonatige Mazeration von Zitronenschalen in neutralem Alkohol hergestellt. Das Ergebnis wird mit Zucker und Wasser vermengt, gegoren und gefiltert.'),
  (410, 'de', 'Litschi Likör', 'Hergestellt aus dem Fruchtfleisch reifer Litschi, die mit Alkohol vermengt und ziehen gelassen werden.'),
  (486, 'de', 'Mangosaft', 'Für die Herstellung des Saftes weird das Fruchtfleisch von Mangos gepresst, gefiltert und abgefüllt.'),
  (529, 'de', 'Maracuja', 'Die subtropische Passionsfrucht stammt von einer Kletterpflanze der Passionsblumengewächse, die hauptsächlich in Neuseeland, Israel und Sri Lanka vorkommt. Sie enthält Vitamin A, Beta-Carotin und Calcium und ist bekannt für ihre straffende Wirkung auf den Körper. Eine Frucht wiegt etwa 90g.'),
  (415, 'de', 'Brombeer Likör', 'Beeren Likör mit reichem Aroma, hergestellt durch die bis zu zweimonatige Mazeration von Brombeeren in neutralem Alkohol mit Wasser. Der Likör wird nicht filtriert und mit Zucker gemischt.'),
  (405, 'de', 'Grüner Apfel Likör', 'Erfrischender Frucht Likör, hergestellt durch die Mazeration von Fruchtfleisch grüner Äpfel in neutralem Alkohol. Die daraus gewonnene Spirituose wird gefiltert, mit Zucker vermengt und bis zur gewünschten Stärke mit Wasser verschnitten.'),
  (528, 'de', 'Apfel', 'Diese beliebte Frucht kommt ursprünglich aus Zentralasien und wächst hauptsächlich in China, den USA und der Türkei auf Laubbäumen. Äpfel enthalten Ascorbinsäure, Vitamin K, Kalium und gelten als Stärker des Immunsystems und als Helfer im Kampf gegen Übergewicht. Ein Apfel wiegt durchschnittlich 200g und kann in 10 Stücke geteilt werden.'),
  (682, 'de', 'Krug', 'Ein Glas mit einem dichten Deckel um Liköre und Cordials zu mischen und aufzubewahren. Es gibt kein Standardvolumen.'),
  (446, 'de', 'Agaven Sirup', 'Ein mexikanischer Sirup, hergestellt aus Agavensaftkonzentrat gemischt mit Zuckersirup.'),
  (432, 'de', 'Trockener Rotwein', 'Die gängigste Weinsorte, hergestellt durch die Mazeration und anschliessende Vergärung von roten und blauen Trauben, die dem Wein seine Farbe geben. Danach wird der Wein gefiltert und mindestens 3 Monate lang in Eichenfässern aufbewahrt.'),
  (613, 'de', 'Nelken', 'Ein indonesisches Gewürz, das aus getrockneten Knospen von tropischem Nelkenpfeffer hergestellt wird.'),
  (705, 'de', 'Absinthbrunnen', 'Ein wichtiges Attribut beim Ritual mit dem der starke französische Drink serviert wird. Der Alkohol wird mit Kräutern und Früchten in das Hauptgefäß gegeben. Nachdem er aufgebraut wurde, wird der Trink Tropfen für Tropfen durch Zucker auf einem Löffel gegossen und endet schliesslich im Glas.'),
  (698, 'de', 'Absinthlöffel', 'Ein wichtiges Attribut beim Ritual mit dem der starke französische Drink serviert wird. Der Alkohol wird mit Kräutern und Früchten in das Hauptgefäß gegeben. Nachdem er aufgebraut wurde, wird der Trink Tropfen für Tropfen durch Zucker auf einem Löffel gegossen und endet schliesslich im Glas.'),
  (494, 'de', 'Energie Drink', 'Energy Drinks sind speziell für den Nutzen bei erhöhter physischer und mentaler Aktivität entstanden.'),
  (394, 'de', 'Irish Cream Likör', 'Irish Cream Likör wird aus dreifach destilliertem irischem Whiskey mit der Zugabe von Rahm und neutralem Alkohol hergestellt. Das Ganze wird mit Kakao, Vanille, Zucker und Karamell angereichert.'),
  (547, 'de', 'Blaubeere', 'Kleine violette Beeren, die an Büschen in Kanada, Nordamerika, der Türkei und Westeuropa wachsen. Sie enthalten eine grosse Menge an Vitamin A, B, C, Mangan und Kalium. Sie sind gut für das Sehvermögen und verbessern die Nachtsichtigkeit. Ein Barlöffel hält etwa 5g Beeren.'),
  (578, 'de', 'Zitronengras', 'Ein Gras mit Zitrusaroma, das aus der karibischen und der asiatischen Küche stammt. Es wächst hauptsächlich auf den Britischen Inseln, den Philippinen und Indonesien.'),
  (490, 'de', 'Sprite', 'Ein süßes, kohlensäurehaltiges Getränk, das mit Soda und der Zugabe von Zucker und Zitronen-Extrakt hergestellt wird.'),
  (666, 'de', 'Sambuca', 'Hierbei handelt es sich um einen starken Likör italienischer Herkunft, der hergestellt wird indem man Weizenspiritus mit Zuckern und Ölen von normalem oder Sternanis und durch Destillation von Beeren, Holunderblüten und verschiedenen Kräutern aromatisiert, so dass es am Ende zu einem nachhaltigen Duft kommt.'),
  (414, 'de', 'Advocaat Likör', 'Niederländischer Weihnachtslikör, der von einem alkoholischen aus Avocado gemachten Getränk aus Brasilien stammt. Dieser Likör wird aus einer Mischung von Eigelb, Zucker, Vanille und Brandy hergestellt.'),
  (531, 'de', 'Granatapfel', 'Eine mediterrane Frucht, die an fruchttragenden Laubhölzern oder kleinen Bäumen, hauptsächlich in Israel und Indien wächst. Sie enthält Kalium und Phosphor und hat bekannterweise eine positive Wirkung auf das Herz-Kreislauf-System. Eine Frucht wiegt durchschnittlich etwa 300g und kann in 10 Stücke geteilt werden.'),
  (684, 'de', 'Rotwein Glas', 'Ein klassisches, leicht gewölbtes Glas. Traditionell ist es etwas höher als ein Weißweinglas. Standardkapazität: 200-300 ml.'),
  (483, 'de', 'Kirschsaft', 'Für die Herstellung des Saftes werden Kirschen gepresst, gefiltert und abgefüllt.'),
  (551, 'de', 'Schwarze Johannisbeere', 'Kleine, schwarze Beeren, die an Büschen in Asien, Zentral- und Nordeuropa wachsen. Sie enthalten eine grosse Menge Vitamin C, verschiedene Zucker, organische Säuren und Mineralien. Eine Barlöffel hält etwa 5g Beeren.'),
  (597, 'de', 'Himbeer Marmelade', 'Marmelade aus roten Beeren, die auf mehrjährigen Zwergsträuchern hauptsächlich in Russland, Serbien, Polen und den USA wachsen. Die reifen Früchte werden mit Zucker gekocht bis eine homogene Masse entsteht. Auf einen Barlöffel passen ca. 5g Marmelade.'),
  (590, 'de', 'Orangen Marmelade', 'Marmelade aus dem Fruchtfleisch von Zitrusfrüchten, die auf hohen Bäumen hauptsächlich in Brasilien, den USA und China wachsen. Die reifen Früchte werden mit Zucker gekocht bis eine homogene Masse entsteht. Auf einen Barlöffel passen ca. 5g Marmelade.'),
  (589, 'de', 'Honig', 'Ein Blumennektar, gesammelt und verarbeitet von Bienen.'),
  (652, 'de', 'Cookie', 'Ein süsser Keks aus verschiedenen Teigsorten und im Ofen gebacken.'),
  (686, 'de', 'Pitcher', 'Ein altes Küchengefäß um Wasser, Limonade und Sangria zu Servieren. Standardvolumen: 500-3000 ml.'),
  (484, 'de', 'Granatapfelsaft', 'Für die Herstellung des Saftes werden Granatapfelkerne gepresst, gefiltert und abgefüllt.'),
  (548, 'de', 'Wassermelone', 'Eine grosse Beerensorte, welche hauptsächlich in China, der Türkei und dem Iran angepflanzt wird. Sie enthält Glukose, Fruktose, Pektin, Calcium, Magnesium und alkalische Stoffe und reguliert den Stoffwechsel. Eine Beere wiegt durchschnittlich etwa 5kg, eine Scheibe 300g und das Verhältnis des Gewichts von Fruchtfleisch zu Schale beträgt 60% - 40%.'),
  (454, 'de', 'Zitronengras Sirup', 'Ein Zitronensirup, hergestellt durch die Pasteurisierung von Zitronengras-Extrakt mit Zuckersirup.'),
  (433, 'de', 'Trockener Weißwein', 'Ein Sommerwein, hergestellt durch die Mazeration und anschliessende Vergärung von weissen Trauben ohne Hülse. Danach wird der Wein gefiltert und mindestens 3 Monate lang in Eichenfässern aufbewahrt.'),
  (532, 'de', 'Kiwi', 'Die Kiwi, auch Chinesische Stachelbeere genannt, ist die essbare Beere einer holzigen Ranke und wächst hauptsächlich in Italien, Neuseeland und Chile. Sie enthält Vitamin C, Ballaststoffe, Folsäure, Calcium und Phosphor und ist bekannt dafür, das menschliche Immunsystem zu stärken. Eine Beere wiegt etwa 120g.'),
  (577, 'de', 'Roter Basilikum', 'Scharfe, aromatische Kräuter, die hauptsächlich in den warmen Regionen der Alten Welt wachsen.'),
  (702, 'de', 'Sahnespender', 'Ein Instrument aus dickem Glas oder Metall um Sahne schnell zu schlagen, so dass sie eine delikate, luftige Konsistenz bekommt. Es kann auch zur Herstellung verschiedner Desserts, komplexer Saucen und Mousses verwendet werden. Standardvolumen: 0.5-1 Liter.'),
  (399, 'de', 'Pfirsich Likör', 'Ein sonniger Fruchtlikör, hergestellt durch die Destillation von gegärtem Pfirsichsaft mit der Zugabe von Cognac. Um das Aroma zu verstärken werden manchmal Pfirsichkerne hinzugefügt.'),
  (396, 'de', 'Aprikosen Likör', 'Berühmter Frucht Likör, hergestellt durch die Destillation von gegärtem Aprikosen Saft mit Spirituosen um das reiche Aroma zu verstärken.'),
  (691, 'de', 'Bowle Schüssel', 'Ein grosses Gefäß aus Glas, Kristall oder Metall zum Servieren von Punsch, das zu Beginn des 17. Jhdt. von Indien nach England gebracht wurde. Standardvolumen: 5 Liter.'),
  (395, 'de', 'Amaretto Likör', 'Ein klassischer italienischer Likör, der durch die Mazeration von Aprikosen Kernen, verschiedenen Kräutern und Früchten in neutralem Alkohol hergestellt wird. Die daraus resultierende Basis wird gefiltert, mit Zucker vermengt und mit Wasser verdünnt bis die gewünschten Stärke erreicht ist.'),
  (556, 'de', 'Kirsche', 'Gelbe oder scharlachrote Beeren, die auf Bäumen, hauptsächlich in warmem und gemäßigtem Klima wachsen, wie der Türkei, Italien, Spanien und Chile. Sie enthalten organische Säuren, Mineralien, Pektin, Folsäure, Vitamin A, C, E und B. Eine Beere wiegt durchschnittlich etwa 5g.'),
  (437, 'de', 'Lagerbier', 'Ein helles Bier, hergestellt aus Wasser, Gerste, Malt-Extrakt, Hopfen und Bierhefe.'),
  (452, 'de', 'Schwarzer Johannisbeer Sirup', 'Ein Beerensirup, der hergestellt wird, indem der Saft von reifen schwarzen Johannisbeeren mit Zucker und Wasser gemischt wird.'),
  (397, 'de', 'Melonen Likör', 'Dieser tropische Likör aus Asien wird hergestellt, indem das Fruchtfleisch von Melonen in neutralem Alkohol mit Wasser mazeriert wird. Das Resultat wird filtriert, zu seiner gewünschten Süße und Stärke gebracht und in Flaschen abgefüllt.'),
  (763, 'de', 'Bitter Lemon', 'Ein kohlensäurehaltiger Zitronendrink, hergestellt durch das Karbonisieren von Wasser mit Zitronenextrakt.'),
  (380, 'de', 'Becherovka', 'Kanonischer tschechischer Likör, hergestellt durch die Mazeration von einer Mischung aus 20 Kräutern und Gewürzen in neutralem Alkohol, der daraufhin mit Wasser und Zucker vermengt wird und zwischen zwei und drei Wochen in Eichenfässern reift.'),
  (502, 'de', 'Earl Grey Tee', 'In seiner klassischem Form wird dieser Schwarztee mit der Zugabe von Bergamottöl hergestellt. Die beste Temperatur für die Zubereitung ist 90-95 °C und er sollte 3-5 min ziehen gelassen werden.'),
  (709, 'de', 'Cocktailschirm', 'Eine fröhliche Papierdekokoration für tropische Cocktails oder um Kindern eine Freude zu machen.'),
  (639, 'de', 'Getrocknete Pflaumen', 'Eine europäische Delikatesse aus dunklen Pflaumen, die in der Sonne oder in einem speziellen Trockner getrocknet werden.'),
  (747, 'de', 'Törtchen', 'Eine Miniatur-Kopie einer Torte, die König Richard II 1390 zubereitete. Das Gebäck besteht aus einer Füllung auf einem Teigboden, der oben offen gelassen und nicht mit Teig bedeckt wird.'),
  (453, 'de', 'Gelber Apfel Sirup', 'Ein gelber, fruchtiger Sirup, hergestellt durch die Pasteurisierung von gelben Äpfeln mit der Zugabe von Rohrzucker.'),
  (576, 'de', 'Rosmarin', 'Mediterrane Kräuter mit einem scharfen Tannengeruch.'),
  (409, 'de', 'Grapefruit Likör', 'Zitrus Likör, hergestellt durch die Mazeration von rosa Grapefruit Schalen in neutralem Alkohol. Das Ergebnis wird gefiltert, mit Zucker vermengt und mit reinem Wasser verschnitten bis die gewünschte Stärke erreicht ist.'),
  (549, 'de', 'Cranberry', 'Kleine, rote Beeren, die an Zwergsträuchern oder Kletterpflanzen wachsen, hauptsächlich in den USA, Chile, Argentinien und den Niederlanden. Sie enthalten organische Säuren, Mineralien, Pektin, Folsäure, Vitamin A, C, E und B. Eine Barlöffel hält etwa 5g Beeren.'),
  (492, 'de', 'Tonic', 'Ein kohlensäurehaltiges Getränk, das in Indien für den Kampf gegen Malaria entwickelt wurde. Es wird aus Sprudelwasser mit Chinin und ein klein wenig Zucker hergestellt.'),
  (562, 'de', 'Rote Trauben', 'Rote Beeren von mittlerer Größe; Trauben sind fruchtige Beeren, die an belaubten Weinranken wachsen. Hauptsächlich sind sie in China, den USA, Italien, Frankreich und Spanien verbreitet. Sie enthalten Zucker, Zellulose, organische Säuren, Vitamin B und andere Spurenelemente und haben einen stärkenden und straffenden Effekt. Eine Beere wiegt durchschnittlich etwa 5g.'),
  (663, 'de', 'Orangen Wodka', 'Stark aromatisierte Spirituose, hergestellt durch mehrfache Destillation von Getreide, mehrere Stufen der Reinigung durch Aktivkohle und andere Filterprozesse und Verschnitt mit destilliertem Wasser. Das gewonnene Getränk wird mit Extrakten von reifen Orangen aufgegossen.'),
  (530, 'de', 'Mandarine', 'Eine Mandarine ist eine orangefarbene Zitrusfrucht und wächst an immergrünen Sträuchern, hauptsächlich in China, Spanien und Brasilien. Sie enthält Vitamin C und Kalium und stärkt bekannterweise das Immunsystem. Eine Frucht wiegt durchschnittlich etwa 100g und liefert 40ml Saft.'),
  (710, 'de', 'Lillet Blanc', 'Ein französischer Aperitifwein, hergestellt durch eine Kombination von Weißweinen aus der Bordeaux Region und Fruchtlikören. Während der Wein reift werden Schalen von süßen, bitteren und sauren Orangen und grünem Chinin mit Brandy infundiert. Dann wird alles vermengt und für 8-12 Monate in Eichenfässern aufbewahrt.'),
  (389, 'de', 'Gewürzter Rum', 'Dies ist eine karibische Spirituose, hergestellt durch die vertikale Destillation von Alkohol, welcher durch Gärung von Melasse oder Saft vom Zuckerrohr gewonnen wird. Vor dem Mischen wird er, abhängig von der gewählten Alterungsmethode, zwischen 2 und 7 Jahren in ausgebrannten Bourbon oder Sherry Eichenfässern aufbewahrt. Der Rum wird mit Zimt, Muskat, Vanille und anderen Gewürzen aufgegossen.'),
  (398, 'de', 'Blue Curacao Likör', 'Neonblauer Likör, hergestellt durch die Mazeration von getrockneten Orangen Schalen in neutralem Alkohol mit Wasser. Das Ergebnis wird gefiltert, mit Zucker vermengt und mit natürlichen Farbstoffen gefärbt.'),
  (550, 'de', 'Grüne Trauben', 'Grüne Beeren von mittlerer Größe, die an belaubten Weinranken wachsen. Hauptsächlich sind sie in China, den USA, Italien, Frankreich und Spanien verbreitet. Sie enthalten Zucker, Zellulose, organische Säuren, Vitamin B und andere Spurenelemente und haben einen straffenden Effekt. Eine Beere wiegt durchschnittlich etwa 5g.'),
  (533, 'de', 'Mango', 'Eine wilde, tropische Frucht, die hauptsächlich in Indien, Pakistan und den Philippinen wächst. Sie enthält Vitamin A, Folsäure und Kalium und kann das Immunsystem und die Sehkraft verbessern. Eine Frucht wiegt etwa 300g und kann in 10 Stücke geteilt werden.'),
  (408, 'de', 'Zimt Likör', 'Dieser deutsche gewürzte Likör wird durch die Mazeration von Zimt in Schnaps hergestellt. Das Resultat wird gefiltert, mit Zucker vermengt und für den letzten Schliff werden Goldblättchen hinzugegeben.'),
  (495, 'de', 'Grüner Eistee', 'Eistee ist sehr beliebt in Asien und dieser wird auf der Basis von Grüntee-Extrakt und anderen Kräutern ohne die Zugabe von künstlichen Aromen und Konservierungsmitteln hergestellt.'),
  (711, 'de', 'Julep Barsieb', 'Ein unverzichtbares Accessoire, wenn man mit einem Misch-Glas arbeitet. Es dient ebenso als unvergleichliche Dekoration für den klassischen Cocktail gleichen Namens. Wird benutzt um Cocktails von zerkleinerten Stücken Eis oder anderen ungewollten Bestandteilen zu befreien.'),
  (670, 'de', 'Espresso', 'Ein starker Kaffee, der zubereitet wird, indem eine kleine Menge kochendes Wasser bei einer Temperatur von 90 °C über gemahlenen Kaffee gegossen wird.'),
  (690, 'de', 'Teetasse', 'Ein traditioneller türkischer Becher für Teetrinker. Standardvolumen: 40-80 ml.'),
  (615, 'de', 'Vanille Kristallzucker', 'Ein klassischer Zucker mit Vanille Aroma.'),
  (181, 'de', 'Kaffeepresse', 'Ein französisches Accessoire zum Kaffe und Tee Brauen, das aus einem Glaskanne mit einem Sieb und einem Stempel besteht.'),
  (448, 'de', 'Erdbeer Sirup', 'Ein Beerensirup, hergestellt durch die Pasteurisierung von Saft aus reifen Erdbeersaft gemischt mit Zucker und Wasser.'),
  (567, 'de', 'Chilischote', 'Eine scharfe, tropische Chili Paprika die an Büschen hauptsächlich in Südamerika wächst. Sie enthält Vitamin A und C, Kalium, Magnesium und Eisen. Eine Paprikaschote wiegt etwa 30g.'),
  (499, 'de', 'Schwarzer Tee', 'Eine Teesorte, die eine Gärung zwischen 2 Wochen und 1 Monat durchmacht. Sie wächst in Gegenden tropischen oder subtropischen Klimas. Für die Zubereitung giessen Sie 100ml kochendes Wasser über einen Löffel Tee und lassen Sie ihn 4-5 min ziehen.'),
  (412, 'de', 'Maracuja Likör', 'Hergestellt vom Fruchtfleisch reifer Passionsfrucht, Orangen und Pampelmuse, welche zusammen in Alkohol gemischt und aufgegossen werden.'),
  (411, 'de', 'Mango Likör', 'Dieser tropische Likör aus Asien wird hergestellt, indem das Fruchtfleisch reifer Mangos in neutralem Alkohol mazeriert wird. Das Resultat wird gefiltert und mit Zucker vermengt.'),
  (514, 'de', 'Vanilleeis', 'Ein gefrorenes Dessert aus Milch, Rahm, Butter und Zucker mit der Zugabe von Vanilleextrakt. Kann bis zu einem Monat im Gefrierfach aufbewahrt werden.'),
  (592, 'de', 'Kirsch Marmelade', 'Marmelade aus gelben oder scharlachroten Beeren, die hauptsächlich in Ländern mit gemäßigtem Klima wie der Türkei, Italien, Spanien und Chile wachsen. Die reifen, entkernten Beeren werden mit Zucker gekocht bis alles homogenisiert ist. Ein Barlöffel hält ca. 5g Marmelade.'),
  (485, 'de', 'Pfirsichsaft', 'Für die Herstellung des Saftes werden Pfirsiche gepresst, gefiltert und abgefüllt.'),
  (387, 'de', 'Kurant Wodka', 'Ein stark aromatisierter Alkohol, hergestellt durch mehrfache Destillation von Getreidekörnern. Der Alkohol wird durch Aktivkohle und andere Filterprozesse gereinigt und später mit destilliertem Wasser verschnitten. Das Ergebnis ist ein Alkohol, aufgegossen mit einem Aroma gereifter schwarzer Johannisbeere'),
  (633, 'de', 'Rosenwasser', 'Ein altes Rezept für parfümiertes Wasser, das mit Rosenblüten infundiert wird.'),
  (713, 'de', 'Himbeer Püree', 'Himbeer Püree'),
  (586, 'de', 'Thymian', 'Ein aromatisches Gewürz, das aus Zwergsträuchern besteht, die hauptsächlich in Eurasien, Nordafrika und Grönland wachsen. Es wird häufig in Provençal-Mischungen verwendet und ist ideal um starke Spirituosen zu würzen.'),
  (407, 'de', 'Kokosnuss Likör', 'Ein tropischer Tiki Likör, hergestellt durch die Mazeration von Kokosnuss-Fruchtfleisch in Rum. Der daraus gewonnene Alkohol wird filtriert, mit Zucker vermengt und bis zur gewünschten Stärke mit Wasser verschnitten.'),
  (430, 'de', 'Rose Wermut', 'Diese relativ neue Kategorie von Wermut wird durch die Mazeration von alpinen Kräutern und Gewürzen in Rosewein hergestellt. Das Ergebnis wir filtriert, auf seine gewünschte Stärke und Süße gebracht und mindestens ein Jahr lang in Eichenfässern aufbewahrt.'),
  (646, 'de', 'Dunkle Schokolade', 'Ein süsses Dessert aus dunklen Kakaobohnen, dem wenig oder gar kein Zucker hinzugefügt wurde.'),
  (447, 'de', 'Karamell Sirup', 'Der berühmte Karamellsirup wird hergestellt, indem flüssiges Karamell mit Vanille und Wasser verarbeitet wird.'),
  (750, 'de', 'Servietten', 'Baumwoll- oder Papier-Servietten. Manchmal als Untersetzer für Drinks verwendet.'),
  (360, 'de', 'Soda Siphon', 'Ein Gerät aus dickem Glas oder Metall um Drinks zu karbonisieren. Standardvolumen: 1-2 Liter.'),
  (500, 'de', 'Bohnenkaffee', 'Geröstete Bohnen der Kaffeepflanze, die aufgrund ihre Koffeingehalts eine stimulierende Wirkung auf den menschlichen Körper haben. Es gibt zwei vorherrschende Sorten der Kaffeepflanze: Arabica und Robusta.'),
  (565, 'de', 'Sake', 'Japanischer Alkohol, hergestellt aus Reis, welcher eingeweicht und gedämpft wird. Dem werden Pilze zur Fermentation hinzugegeben und das Ganze wird etwa 2 Tage lang in einem warmen, feuchten Raum gelagert. Nach der Gärung wird der Sake zwischen 6 und 12 Monaten in versiegelten Behältern aufbewahrt.'),
  (537, 'de', 'Kumquat', 'Eine kleine Zitrusfrucht, die hauptsächlich in China, Korea und Japan auf kleinen fruchttragenden Bäumen wächst. Sie enthält Vitamin C, Eisen und Magnesium und ist hilfreich im Kampf gegen Infektionen. Eine Frucht wiegt durchschnittlich etwa 10g.'),
  (685, 'de', 'Cognac Glas', 'Ein klassisches Glas um Cocktails oder Brandy zu trinken. Standardkapazität: 170 - 400 ml.'),
  (423, 'de', 'Southern Comfort', 'Ein Fruchtlikör aus New Orleans, der 1874 von dem Barkeeper Martin Heron erfunden wurde. Er wird nach einem alten Rezept hergestellt und basiert auf Amerikanischem Whiskey mit der Zugabe von Früchten, Kräuteressenzen, Zucker und Karamell. Er wird bis zur gewünschten Reife in Eichenfässern gelagert.'),
  (703, 'de', 'Pfanne', 'Ein altes Kücheinstrument, das in einer Bar nötig ist um Beeren und Früchte zu flambieren.'),
  (688, 'de', 'Verkostungs Set', 'Besteht aus einem Glastablett, gefüllt mit Eis, wodurch sichergestellt wird, dass die Shots kühl bleiben.'),
  (462, 'de', 'Litschi Sirup', 'Ein asiatischer Fruchtsirup, hergestellt durch die Pasteurisierung von Litschisaft mit Zuckersirup und Wasser.'),
  (504, 'de', 'Kamillen Tee', 'Ein Gebräu aus getrockneten Kamilleblüten. Meist wird kochendes Wasser über die Blüten im Verhältnis 1-2 Teelöffel pro 200ml Wasser gegossen und dann alles ca. 7-10min ziehen gelassen. Nachdem der Tee durch ein Sieb gegossen wird, wird er entweder pur getrunken oder mit etwas Zucker oder Honig.'),
  (673, 'de', 'Sanddorn Marmelade', 'Marmelade aus kleinen gelben Beeren, die an dornigen Laubsträuchern hauptsächlich an der Atlantikküste Europas und in Nordwest-China wachsen. Die reifen Früchte werden mit Zucker gekocht bis eine homogene Masse entsteht. Auf einen Barlöffel passen ca. 5g Marmelade.'),
  (769, 'de', 'Untertasse', 'Ein Geschirr aus Glas, Porzellan oder Metall, das klassischerweise mit einem Becher serviert wird. In der modernen Interpretation erweckt eine Untertasse ein Gefühl von vornehmem und elegantem Service.'),
  (463, 'de', 'Mango Sirup', 'Ein asiatischer Fruchtsirup, hergestellt durch die Pasteurisierung von Mangosaft gemischt mit Rohrzucker und Wasser.'),
  (700, 'de', 'Teeglasuntersatz', 'Ein Glashalter aus Metall mit einem Henkel, der einem erlaubt heisse Getränke zu trinken ohne sich die Hände zu verbrennen.'),
  (695, 'de', 'Gabel', 'Besteck, das aus einem Griff und mehreren Zinken (gewöhnlich zwischen zwei und 4) an einem Ende besteht. Wird sowohl für die Zubereitung von Nahrung, als auch zum Essen, um Teile der Speise zu halten oder zu bewegen, verwendet.'),
  (445, 'es', 'Sirope de canela', 'Famoso sirope especiado elaborado mediante la pasteurización e infusión de sirope de azúcar con canela.'),
  (176, 'es', 'Zumo de lima', 'Para preparar el zumo, las limas son sometidas a una prensa y luego se filtra y se embotella.'),
  (482, 'es', 'Zumo de manzana', 'Para preparar el zumo, las manzanas son sometidas a una prensa y luego se filtra y se embotella.'),
  (767, 'es', 'Clara de huevo de codorniz', 'Para hacer que este ingrediente de cóctel tenga una textura suave y espumosa recomendamos utilizar el método de preparación "sacudida en seco”. Una clara de huevo de gallina es igual a 5 claras de huevo de codorniz.'),
  (217, 'es', 'Pepino', 'El pepino es una enredadera que da frutos cilíndricos que se utilizan como vegetales culinarios. El pepino crece principalmente en los países mediterráneos. Normaliza el metabolismo, mejora el funcionamiento del corazón y de los riñones. Un vegetal pesa una media de 150 g y podría cortarse en 10 rodajas o en tiras.'),
  (31, 'es', 'Cubitos de hielo', 'Para la producción de este ingrediente tan indispensable se debe prestar atención a la pureza del agua y a la velocidad de congelación. Cuanto más despacio se congela el agua el producto final es más limpio. Un cubito ideal no tiene rayas y se funde lentamente en el vaso.'),
  (210, 'es', 'Copa de champán abierta', 'Copa con tallo con un alto y estrecho bol. Según la leyenda fue diseñado para reflejar la silueta de una de las amantes del rey francés. Se utiliza para servir champán y cócteles tipo tini. Capacidad estándar: 200-300 ml.'),
  (68, 'es', 'Coctelera', 'Adquirió su aspecto actual en el siglo 19 y obtuvo especial popularidad en los años 20 y 30, siendo probada en docenas de estilos y formas. Se dividen en cocteleras cobbler que tienen un colador incorporado, las cocteleras francesas sin colador y las cocteleras tipo Boston que están formadas por dos tazas de igual tamaño. Volumen estándar: 500-700ml.'),
  (69, 'es', 'Colador de gusanillo', 'Accesorio que es indispensable cuando se trabaja con cocteleras tipo Boston o francesas. Usado para filtrar en los cócteles pepitas de fruta, trozos de hielo y otros ingredientes no deseados.'),
  (73, 'es', 'Vaso medidor', 'Asegura porciones exactas e ideales en los cócteles. Los mejores camareros siempre tienen en su arsenal una gama con varios tamaños: 20-40ml, 25-50ml y 30-60ml.'),
  (70, 'es', 'Exprimidor de limon', 'Herramienta indispensable para exprimir el zumo de limas y limones. A pesar del hecho de que la mayoría de los establecimientos populares hoy en día utilizan zumo preparado antes, se considera que el zumo recién exprimido es de alta calidad.'),
  (239, 'es', 'Exprimidor', 'Extrae zumo de cualquier fruta o verdura. A diferencia de una prensa manual, un aparato eléctrico separa el zumo de la pulpa utilizando una ruleta.'),
  (1, 'es', 'Vodka', 'Vodka'),
  (55, 'es', 'Licor de café', 'Famoso licor estimulante obtenido del filtrado de granos de café de distintas variedades con un licor neutro. La mezcla resultante no se filtra, se mezcla con azúcar quemada y se diluye con agua hasta obtener la concentración deseada.'),
  (65, 'es', 'Vaso Rocks', 'Vaso ancho de fondo grueso para servir licores fuertes o cócteles puros, sin diluir. Capacidad estándar: 200-300 ml.'),
  (64, 'es', 'Cuchara de cóctel', 'Esta herramienta indispensable para un barman se utiliza para la preparación de cócteles en un vaso mezclador y para poner capas en los chupitos, así como para la medición de partes de líquidos de 5 ml o partes de medidas secas de 5 g.'),
  (57, 'es', 'Pajitas', 'En 1888 Marvin Stone, el dueño de una fábrica de producción de boquillas de papel inventó el mejor accesorio para consumir bebidas en vasos. Joseph Friedman luego hizo una fortuna mediante el desarrollo de las pajitas flexibles. La etapa final llegó con las pajitas hechas de plástico.'),
  (799, 'es', 'Ginebra botanica', 'Este es un licor fuerte escocés, al que el mundo le debe gin tonic con pepino. Antes de la destilación, el alcohol de grano se infunde durante días con once tipos de plantas, con la adición de rosa y pepino. El producto resultante se combina con una bebida de un segundo alambique, cuya calidad única es su uso del método de "baño" de destilación de vapor de hierbas. Además de los pepinos y las rosas búlgaras, la ginebra más famosa, la de Hendrick, incluye una gran cantidad de flores, raíces y frutas, que la convierten en una de las bebidas más solicitadas en bares de todo el mundo.'),
  (54, 'es', 'Triple sec', 'Licor cítrico de culto destilado tres veces obtenido de la maceración de la piel de naranja curaçao en un alcohol neutro con agua. El resultado se destila tres veces antes de ser embotellado manteniendo una alta concentración.'),
  (9, 'es', 'Zumo de limon', 'Para preparar el zumo, los limones son sometidos a una prensa y luego se filtra y se embotella.'),
  (734, 'es', 'Piel de limón', 'Capa superior de la piel del limón cortada con un cuchillo afilado especial. Contiene aceites esenciales que llevan el sabor del limón. La piel se puede obtener a partir de una pieza de fruta cortada, una pieza de fruta entera, rallada o incluso en forma de espiral (llamado twist).'),
  (66, 'es', 'Vaso Sour', 'Los vasos Sour fueron diseñados para contener cócteles Sour - que contienen un licor base, zumo de limón o lima y un edulcorante. Capacidad estándar: 90-120 ml.'),
  (71, 'es', 'Cuchillo pelador', 'Herramienta de barman introducida por la cultura japonesa del tallado. Usado para cortar una fina capa de piel o para cortar anillos o espirales de manzanas.'),
  (143, 'es', 'Mezcal', 'Licor Mexicano, elaborado artesanalmente de agave ahumado en fosas subterráneas con rocas volcánicas bajo altas temperaturas. La bebida está impregnada de su sabor ahumado. Los corazones de agave se muelen, y el zumo se fermenta y envejece en barricas de roble durante al menos 4 meses.'),
  (224, 'es', 'Albahaca verde', 'Hierbas aromáticas que crecen principalmente en las regiones cálidas del Viejo Mundo. Sus hojas verdes han ganado gran popularidad debido al cóctel "Basil smash", que se ha convertido en un clásico.'),
  (223, 'es', 'Cardamomo', 'Condimento de Ceilán, que crece en plantas herbáceas de la familia del jengibre. Es considerada una de las más eficientes en el mundo de las especias.'),
  (566, 'es', 'Raíz de jengibre', 'Planta perenne asiática, importada a Europa en la Edad Media. El rizoma parece piezas redondeadas, es útil para mejorar el sistema inmunitario y para luchar contra los dolores de cabeza. Una rodaja de la raíz pesa 5 g de media.'),
  (83, 'es', 'Hielo picado', 'El primer hielo "raspado" era cortado por los barmans utilizando cuchillos especiales en un gran bloque de hielo. Después aparecieron las máquinas de hielo picado y de cubitos de hielo.'),
  (117, 'es', 'Colador', 'Utilizado junto a cocteleras y coladores de gusanillo para el doble filtrado de cócteles cuando se vierten de la coctelera al vaso. Con una red más fina que los coladores de gusanillo, no permite que incluso las semillas de fruta más pequeñas y los trozos de hielo caigan en la bebida.'),
  (52, 'es', 'Mortero de bar', 'Accesorio indispensable para los cócteles tropicales, aplasta bayas y frutas en la coctelera o directamente en el vaso.'),
  (373, 'es', 'Pinza de colgar', 'Accesorio decorativo usado para sujetar la decoración a la copa.'),
  (113, 'es', 'Absenta', 'Bebida espirituosa francesa obtenida de la maceración de hierbas y especias, entre ellas el bálsamo de limón, hinojo y anís en grano o alcohol del vino. El componente principal, el ajenjo, contiene tujona, un ingrediente altamente tóxico.'),
  (295, 'es', 'Sirope de azúcar', 'Sirope de azúcar'),
  (152, 'es', 'Frambuesa', 'Pequeña baya roja que crece en subarbustos perennes sobre todo en Rusia, Serbia, Polonia y los Estados Unidos. Contiene azúcar, ácidos orgánicos, vitaminas A, B, C y aceites grasos. Una baya pesa 5 g de media.'),
  (125, 'es', 'Whisky Single highland Malt', 'Bebida espirituosa de origen escocés producida en la región montañosa de Escocia, los Highlands. Elaborada con un 100% de cebada malteada, o rara vez, triple destilada. El alcohol resultante se madura durante al menos 3 años en barricas de roble.'),
  (47, 'es', 'Campari', 'Campari'),
  (189, 'es', 'Zumo de pomelo', 'Para preparar el zumo, los pomelos son sometidos a una prensa y luego se filtra y se embotella.'),
  (672, 'es', 'Menta', 'La hierba más ampliamente reconocida en los cócteles, cuenta con más de 30 especies. La hierbabuena y la menta dulce son usadas principalmente en la coctelería. Guardar por no más de dos días en el refrigerador envuelto en una servilleta de papel.'),
  (124, 'es', 'Chartreuse verde', 'Este licor monástico se ha producido en los Alpes franceses usando una receta secreta desde 1764. Cerca de 130 plantas y hierbas se maceran en alcohol neutro y se destilan en varias ocasiones. El resultado se equilibra con azúcar, se mezcla para obtener la concentración deseada y se envejece en barricas de roble.'),
  (427, 'es', 'Licor de flor de saúco', 'Licor floral francés obtenido de la maceración de flores de saúco trituradas utilizando una receta secreta. El licor resultante se filtra, se mezcla con azúcar y se diluye con agua hasta obtener la concentración deseada.'),
  (35, 'es', 'Vermut seco', 'Vermut intenso, que apareció a principios del siglo XIX, obtenido mediante la maceración de ajenjo alpino y una docena de otras hierbas y plantas en vino blanco seco. El resultado se filtra y es envejecido en barricas de roble durante al menos un año.'),
  (130, 'es', 'Licor de naranja seca', 'Licor de cítricos fragante obtenido de la maceración de la piel de naranja de la variedad laraha en alcohol neutro con agua. El licor resultante se filtra, se mezcla con azúcar y se almacena en barricas de roble.'),
  (114, 'es', 'Amargo de Peychaud', 'Un clásico de Nueva Orleans, inventado por el famoso farmacéutico en 1830 elaborado según una receta secreta mediante la infusión de alcoholes neutros y anís, clavo oloroso, vainilla, nuez moscada, frutas y especias.'),
  (161, 'es', 'Copa cáliz', 'Copa real de gruesas paredes que permiten brindar con las copas mientras se bebe sin riesgo de romperlas. Capacidad estándar: 200-300 ml.'),
  (665, 'es', 'Licor de marrasquino', 'Licor de bayas de Croacia elaborado mediante la maceración de bayas marrasquino con los huesos en un licor neutro con agua por lo menos durante un mes. La mezcla resultante es entonces filtrada, endulzada, se lleva a la concentración requerida y se envejece en barricas de roble durante al menos tres años.'),
  (303, 'es', 'Amargo de pomelo', 'Amargos de verano elaborados mediante la infusión de alcoholes neutros con piel de pomelo con la adición de lúpulo para suavizar la amargura.'),
  (20, 'es', 'Cereza marrasquino roja', 'Tipos especiales de cerezas como el "King Anna", "Rainer" o "Golden diversity" se colocan en una solución salina, y luego se sumergen en sirope de azúcar con la adición de colorante alimenticio.'),
  (96, 'es', 'Pincho de cóctel', 'Accesorio decorativo para servir aceitunas en martinis y cerezas de cóctel en el cóctel Manhattan. Apareció por primera vez en los bares a finales del siglo 19 gracias al genio del marketing Charles Forster.'),
  (101, 'es', 'Ron viejo', 'Bebida espirituosa caribeña elaborada mediante la destilación vertical del alcohol obtenido por la fermentación de la melaza o zumo de caña de azúcar. Antes de mezclar se mantiene en barricas de roble quemado de bourbon o jerez durante 7 a 20 años, dependiendo del método elegido de reposo.'),
  (116, 'es', 'Licor de cacao negro', 'Licor de chocolate negro obtenido del filtrado de los granos de cacao con un alcohol neutro. El licor resultante se diluye con agua hasta que se obtiene la concentración deseada y se mezcla con vainilla de Madagascar y caramelo, que le da al licor un color oscuro.'),
  (67, 'es', 'Vaso mezclador', 'Un clásico imprescindible para un bar de cinco estrellas. Utilizado para la preparación de bebidas fuertes para hombres sin zumos añadidos, hierbas ni mermeladas. El hielo mantiene su forma y no se derrite, manteniendo la intensidad de la bebida. Capacidad estándar: 500-900 ml.'),
  (166, 'es', 'Amaro', 'Licor italiano antiguo obtenido de la maceración de hierbas y raíces, incluyendo la piel de cítricos, enebro, hinojo, melisa, anís y cardamomo en alcohol neutro. El licor resultante se filtra, se mezcla con azúcar y se diluye con agua hasta obtener la concentración deseada.'),
  (171, 'es', 'Bola de hielo', 'El orgullo de los barmans japoneses - hielo considerado como una obra de arte. Hoy son más habituales en los bares gracias a máquinas especiales. Los cubitos de hielo preparados son colocados en un tornillo ligeramente caliente y el metal es calentado por agua que corta los contornos de una esfera.'),
  (3, 'es', 'Limón', 'Fruta cítrica tropical que crece en árboles pequeños de hoja perenne, principalmente en China, India y México. Contiene vitamina C y ácidos orgánicos, tradicionalmente usado para luchar contra los resfriados y el déficit nutricional. Una pieza de fruta pesa 160 g y produce 60 ml de zumo, puede ser cortado en 8 rodajas o 4 grandes gajos de 15 ml cada uno.'),
  (62, 'es', 'Bourbon', 'Fuerte bebida espirituosa de origen americano, de acuerdo con la ley, hecha de al menos un 51% de malta de maíz con una adición de cebada y de centeno, destilada y filtrada. Envejecida para su placer en barricas de roble de entre 2 a 7 años. Los barriles son quemados desde el interior utilizando una tecnología especial.'),
  (111, 'es', 'Licor de crema de cassis', 'Licor de bayas Dijon obtenido de la maceración de la grosella negra en un alcohol neutro con agua durante un máximo de dos meses. El licor no se filtra y se mezcla con azúcar.'),
  (63, 'es', 'Amargo de Angostura', 'Amargo venezolano, nombrado así en honor a la ciudad de Angostura. Elaborado según la receta original secreta del Dr. Johann Gottlieb Benjamin Siegert (alrededor del año 1800) mediante la infusión de especias secretas y hierbas en bebidas de ron oscuro.'),
  (16, 'es', 'Crema baja en grasa', 'La crema baja en grasa se elabora principalmente de leche de vaca separando la crema de la leche. El porcentaje de grasa varía en diferentes países usualmente no más de un 15%. Se conserva almacenada en el frigorífico hasta 20 días.'),
  (36, 'es', 'Vermut rojo', 'Vermut con un ligero sabor dulce, obtenido de la maceración de 30 hierbas alpinas y especias en vino blanco. El resultado se filtra, se ajusta a la intensidad y dulzura deseada, se añade colorante de caramelo y se deja añejar en barricas de roble durante al menos un año.'),
  (34, 'es', 'Agua con gas', 'El agua con gas es componente indispensable tanto en los refrescos con burbujas como en otras bebidas carbonatadas. Anteriormente se producía mediante la carbonatación de agua con dióxido de carbono, y ahora se prepara cada vez más mediante la adición de bicarbonato de sodio al agua aún clara.'),
  (732, 'es', 'Piel de naranja', 'Capa superior de la piel de la naranja cortada con un cuchillo afilado especial. Contiene aceites esenciales que llevan el sabor de la naranja. La piel se puede obtener a partir de una pieza de fruta cortada, una pieza de fruta entera, rallada o incluso en forma de espiral (llamado twist).'),
  (258, 'es', 'Champán', 'Vino espumoso producido en la región homónima de Francia bajo estrictas normas. Tres variedades de uva recogidas a mano son fermentadas, y los vinos resultantes son mezclados y embotellados añadiendo azúcar moreno y levadura. Una segunda fermentación ocurre en la botella, tarda al menos 9 meses, y el residuo se elimina usando el removido. Se añade el licor y la botella se cierra con un corcho natural.'),
  (148, 'es', 'Puré de melocotón', 'Puré de melocotón'),
  (535, 'es', 'Melocotón', 'Esta fruta aprecia mucho al sol y crece en árboles de hoja caduca principalmente en China, Italia y España. Contiene ácidos orgánicos, sales minerales y pectina. Una pieza de fruta pesa 120 g de media, de los cuales se puede producir alrededor de 80 gramos de puré.'),
  (59, 'es', 'Copa de flauta', 'Copa de la alta sociedad para cócteles a base de champán o vino espumoso. Su forma larga y estrecha recuerda a un tulipán y retiene las burbujas en el cóctel permitiéndole seguir gaseoso durante más tiempo. Volumen estándar: 180-250ml.'),
  (179, 'es', 'Concentrado de lima', 'Receta antigua elaborada mediante la pasteurización de zumo de limón mezclado con sirope de azúcar, crema tártara y agua.'),
  (733, 'es', 'Piel de lima', 'Capa superior de la piel de la lima cortada con un cuchillo afilado especial. Contiene aceites esenciales que llevan el sabor de la lima. La piel se puede obtener a partir de una pieza de fruta cortada, una pieza de fruta entera, rallada o incluso en forma de espiral (llamado twist).'),
  (72, 'es', 'Copa de cóctel', 'También conocida como copa de martini, fue una de las primeras copas para servir cócteles sin hielo. Antes de servir es necesario enfriar el vidrio, y el largo tallo de la copa evita que el cóctel se caliente al cogerlo. Capacidad estándar: 90-160 ml.'),
  (40, 'es', 'Coñac', 'Alcohol añejado de origen francés que proviene de las uvas blancas: Ugni Blanc, Folle Blanche o con menor frecuencia de la Colombard Montilla. Sujeto a un proceso de doble destilación y añejado en barricas de roble, - VS (Very Special) hasta 3 años; V.S.O.P (Very Superior Old Pable) hasta 5 años.'),
  (14, 'es', 'Nuez moscada en polvo', 'Condimento de Indonesia, creado a partir de nuez moscada, secada y molida hasta obtener polvo.'),
  (746, 'es', 'Rallador de nuez moscada', 'Accesorio útil para la preparación de la nuez moscada o el chocolate en polvo, o más raramente para rallar la piel de cítricos.'),
  (8, 'es', 'Zumo de naranja', 'Para preparar el zumo, las naranjas son sometidas a una prensa y luego se filtra y se embotella.'),
  (88, 'es', 'Ron blanco', 'Bebida caribeña elaborada mediante la destilación vertical del alcohol obtenido por la fermentación de la melaza o zumo de caña de azúcar. Antes de mezclar se mantiene en barricas de roble quemado de bourbon o jerez por lo menos 12 meses, dependiendo del método elegido de añejamiento y se filtra para decolorar la bebida.'),
  (92, 'es', 'Calvados', 'Bebida espirituosa francesa que se elabora fermentando el zumo de las manzanas de otoño en depósitos de acero entre seis meses y un año. La bebida entonces se somete a una doble destilación y se reposa en barricas de roble durante al menos 2 años.'),
  (77, 'es', 'Sirope de granadina', 'Popular sirope de fruta roja elaborado mediante la pasteurización de zumo de granada con otros zumos de bayas rojas, vainilla y azúcar moreno.'),
  (86, 'es', 'Ron oscuro', 'Bebida espirituosa caribeña elaborada mediante la destilación vertical del alcohol obtenido por la fermentación de la melaza o zumo de caña de azúcar. Antes de mezclar se mantiene en barricas de roble quemado de bourbon o jerez de 2 a 7 años, dependiendo del método elegido para el reposo y no filtrado para conservar el color.'),
  (365, 'es', 'Ron con alto contenido', 'Bebida espirituosa caribeña elaborada mediante la destilación vertical del alcohol obtenido por la fermentación de la melaza o zumo de caña de azúcar. Antes de mezclar se mantiene en barricas de roble quemado de bourbon o jerez durante al menos un año. No se diluye con agua para preservar la fuerza.'),
  (190, 'es', 'Pomelo', 'Este popular cítrico crece en racimos sobre todo en China, los EE.UU. y México. Contiene vitamina C, pectina y licopeno con propiedades para reducir el colesterol. Una pieza de fruta fresca pesa 600 g de media, se puede cortar en 10 rodajas o partes y se consigue alrededor de 200 ml de zumo.'),
  (186, 'es', 'Taza Tiki', 'Las tazas Tiki son envases de cerámica para cócteles basados en la temática tiki.'),
  (662, 'es', 'Whisky irlandés', 'Bebida espirituosa de origen irlandés, hecha de malta de cebada germinada, secada al horno, molida y cubierta con agua caliente. Separado del grano, el líquido se fermenta, se destila tres veces y se deja madurar en roble, jerez, bourbon o barricas especiales puerto durante al menos 3 años.'),
  (128, 'es', 'Crema de leche espesa', 'La crema doble se elabora principalmente de leche de vaca separando la crema de la leche. El porcentaje de grasa varía en diferentes países del 20 a 40%. Se conserva almacenada en el frigorífico hasta 20 días.'),
  (74, 'es', 'Bol', 'Recipiente de vidrio o de metal para batir los ingredientes con una batidora. Cualquier mezcla con la adición de zumos de tomate o de cítricos se debe hacer sólo en un bol de vidrio o de acero inoxidable, para evitar la reacción con los ácidos.'),
  (90, 'es', 'Vaso Toddy', 'Vaso resistente para servir ponche caliente, vino caliente y cócteles con café – toma su nombre en honor a un cóctel de café. Volumen estándar: 200-300ml.'),
  (78, 'es', 'Batidora eléctrica', 'Indispensable para batir crema para el café irlandés o para batir claras de huevo con azúcar para un Tom y Jerry. Para mezclar o batir ingredientes en una jarra, se utiliza una versión especial con un mango más largo y una pequeña punta en el extremo.'),
  (761, 'es', 'Cafetera', 'Aparato automático para elaborar diferentes tipos de cafés: latte, espresso, americano, manchado latte, capuchino y café glacé.'),
  (39, 'es', 'Cachaça', 'Licor brasileño elaborado mediante una cuidadosa filtración y con la destilación del zumo de caña fermentado siguiendo una única técnica: la "cabeza" y la ”cola" se descartan, dejando sólo el "corazón" de la bebida para su posterior envejecimiento en barricas de roble por lo menos 1 año.'),
  (5, 'es', 'Lima', 'Fruta cítrica tropical que crece durante todo el año en los climas tropicales, principalmente en China, India y México. Las limas son una excelente fuente de celulosa, vitamina C y calcio, y son buenas para ser utilizadas para acentuar los sabores de los alimentos y bebidas. Una pieza de fruta pesa 80 g de media, y produce 30 ml de jugo. Se puede cortar en 4 gajos, cada uno conteniendo 7,5 ml de zumo.'),
  (43, 'es', 'Sirope de frambuesa', 'Popular sirope de bayas elaborado mediante la pasteurización de zumo de frambuesa mezclado con azúcar y agua.'),
  (661, 'es', 'Vodka citron', 'Bebida espirituosa de fuerte sabor resultado de la destilación de múltiples granos, sujeto a varios procesos de carbono y otros filtros. El licor resultante se mezcla con agua limpia. La bebida resultante se infusiona con extractos cítricos y con lima.'),
  (481, 'es', 'Zumo de arándanos', 'Para preparar el zumo, los arándanos son sometidos a una prensa y luego se filtra y se embotella.'),
  (53, 'es', 'Soplete de cocina', 'Accesorio de caballero para flamear el aceite de los cítricos sobre el famoso Cosmopolitan, espolvorear canela brillante sobre cócteles tiki y simplemente para encender los cigarrillos de los huéspedes.'),
  (82, 'es', 'Vino de Oporto', 'Vino de Oporto rojo saturado elaborado a partir de una mezcla de vinos añejos de color rojo con la adición de coñac y posterior envejecimiento en barricas de roble utilizando el método Solera.'),
  (49, 'es', 'Yema de huevo de codorniz', 'El producto ofrece a los cócteles una delicada textura. Una yema de huevo de gallina es igual a 5 yemas de codorniz.'),
  (178, 'es', 'Cortador de huevos de codorniz', 'Tijeras especiales con un anillo para sujetar y cortar con limpieza a través del huevo.'),
  (569, 'es', 'Apio', 'La "Fama" de la planta se debe a los antiguos griegos. Esta crece principalmente en climas templados. Antes de servir sus fibras deben extraerse haciendo una pequeña incisión en el tallo y tirando de la "hebra". Un tallo pesa 15 g de media.'),
  (42, 'es', 'Salsa Tabasco', 'Salsa roja picante hecha de chiles madurados seleccionados envejecidos durante tres años en barricas de roble blanco con sal de la isla de Avery. La masa resultante se condimenta con vinagre y se deja añejar durante otras cuatro semanas. Es más picante que la versión verde.'),
  (56, 'es', 'Pimienta negra molida', 'Condimento molido de la India elaborado a partir de bayas inmaduras de pimienta negra, secadas al sol para oscurecerlas. A diferencia de la versión granular, la fragancia se evapora mucho más rápido.'),
  (58, 'es', 'Vaso de tubo', 'Vaso alto para el agua, zumo o combinados. La mezcla se hace en el mismo vaso. Capacidad estándar: 300-400 ml.'),
  (37, 'es', 'Whisky escocés', 'Licor escocés de malta de cebada, secado sobre turba en grano. Molido y cubierto con agua caliente. El líquido por separado se fermenta, se destila tres veces, y el alcohol resultante se mezcla y se deja madurar en roble, jerez, bourbon o barricas de puerto durante al menos 3 años.'),
  (46, 'es', 'Licor de cereza', 'Famoso licor de bayas obtenido de la maceración de cerezas en diferentes variedades de licores neutros con agua durante al menos un mes. El resultado se filtra, se endulza, se intensifica con coñac y se envejece en barricas de roble durante al menos 3 años.'),
  (89, 'es', 'Ron dorado', 'Bebida espirituosa caribeña producida mediante la destilación vertical del alcohol obtenido por la fermentación de la melaza o zumo de caña de azúcar. Antes de mezclar se mantiene en barricas de roble quemado de bourbon o jerez durante 7 a 20 años, dependiendo del método elegido de reposo. Sin filtrar, a veces se le añade colorante de caramelo.'),
  (94, 'es', 'Cola', 'Es la bebida altamente carbonatada más popular elaborada según una fórmula secreta en base a cafeína, azúcar, aromatizantes y colorantes.'),
  (60, 'es', 'Licor de cacao blanco', 'Licor de chocolate light obtenido del filtrado de los granos de cacao con un alcohol neutro. El resultado se filtra, eliminando el color oscuro, se ajusta a la concentración deseada y se mezcla con azúcar hasta tener una consistencia cremosa.'),
  (61, 'es', 'Licor de menta verde', 'Licor de hierbas cremoso elaborado con un alto contenido de azúcar mediante el filtrado de extracto de menta fresca con destilados de lima en un alcohol neutro. El licor resultante se ajusta a la dulzura deseada, se mezcla para obtener la concentración deseada y se embotella.'),
  (93, 'es', 'Tequila blanco', 'Bebida de origen mexicano, tradicionalmente producida por la destilación del zumo de agave azul. De siete a diez corazones de agave veraniego se colocan en hornos especiales para convertir el almidón en azúcar, y el zumo resultante se fermenta, con un doble destilado y después de la filtración se embotella inmediatamente.'),
  (212, 'es', 'Cerveza de jengibre', 'El "Caballo de Troya" del vodka en América. Este tipo especial de limonada especiada se elabora mediante la maceración de jengibre seco en polvo en levadura de cerveza.'),
  (99, 'es', 'Sirope de almendra', 'Sirope de almendra'),
  (127, 'es', 'Sal', 'Condimento cristalizado elaborado a partir de minerales. Su edad puede alcanzar hasta los 250 millones de años o más.'),
  (84, 'es', 'Copa Margarita', 'En su vida anterior era una salsera para el guacamole, pero ahora es la copa más importante para servir los cócteles basados en tequila más famosos del mundo. Volumen estándar: 250-350ml.'),
  (85, 'es', 'Amargo de naranja', 'Uno de los amargos cítricos más antiguos disponibles. Elaborado mediante la infusión de piel de naranja seca en ron, especias y raíces de hierba con azúcar de caña y agua destilada justo antes de ser embotellado.'),
  (75, 'es', 'Sirope de maracuyá', 'Sirope de fruta tropical elaborado mediante la pasteurización de zumo de pulpa de maracuyá mezclado con azúcar moreno y agua.'),
  (7, 'es', 'Zumo de piña', 'Para preparar el zumo, la pulpa de la piña se prensa y luego se filtra y se embotella.'),
  (76, 'es', 'Copa tulipán', 'Copa de estilo antiguo que se asemeja a una lámpara de queroseno para servir bebidas tropicales, llamada así en honor al cóctel homónimo de Pat O''Brien. Volumen estándar: 300-400ml.'),
  (4, 'es', 'Naranja', 'Fruta cítrica naranja que crece en árboles grandes, principalmente en Brasil, EE.UU. y China. Contiene vitamina C, potasio y calcio. Conocida por tener un efecto beneficioso en el corazón, en los vasos sanguíneos y en todo el cuerpo. Una pieza de fruta pesa 300 g de media y produce 80 ml de zumo. Se puede cortar en 10 rodajas o separarse en 8 gajos.'),
  (375, 'es', 'Vaso Collins', 'Vaso alto para tragos largos y combinados. Toma su nombre del cóctel clásico "Tom Collins". Capacidad estándar: 300-400 ml.'),
  (104, 'es', 'Bénédictine', 'El famoso licor Normando decorado con la inscripción DOM - DEO Optimo Maximo (“a Dios, el más bueno, el más grandioso”) está hecho de 27 hierbas y especias secretas en cuatro etapas. Después de la maceración y destilación los licores resultantes se mantienen por separado, y luego se mezclan durante 11 meses en barricas de roble. Después se mezcla con agua, brandy, miel y azúcar quemado. Eso nos lleva a la etapa final de 3 meses de envejecimiento.'),
  (95, 'es', 'Piña', 'La piña es una planta tropical que crece en terrenos con plantas espinosas mayormente en Brasil, Tailandia y Filipinas. Contiene manganeso y vitamina C, conocida por estimular la digestión y reducir la viscosidad de la sangre. Una pieza de fruta pesa 1200 g de media y se puede cortar en unas 40 rodajas.'),
  (105, 'es', 'Vaso Sling', 'La quinta esencia de los vasos para servir el cóctel del mismo nombre que se convirtió en la tarjeta de visita del Hotel Raffles. Volumen estándar: 200-300ml.'),
  (79, 'es', 'Agua sin gas', 'La fuente más importante de salud y longevidad. Los camareros de todo el mundo recomiendan siempre beber agua mientras se consume un cóctel, de manera que en los mejores locales un vaso de agua sin gas es gratuito.'),
  (150, 'es', 'Terrones de azúcar (2)', 'Condimento dulce Europeo obtenido de una complicada purificación, el refinado y la cristalización del jarabe de la caña de azúcar o jugo de remolacha azucarera. Estos cristales se presionan para darle la forma deseada.'),
  (100, 'es', 'Drambuie', 'Licor escocés, traducido del gaélico "fulfilling", hecho usando una receta secreta desde 1910. Es sabido que la bebida es una mezcla de whiskies de malta de orígenes famosos, miel de brezo, hierbas y especias.'),
  (677, 'es', 'Agua de azahar', 'Antigua receta de agua infusionada con flores frescas de naranjas amargas.'),
  (118, 'es', 'Hojas de piña', 'Hojas de la fruta tropical que se utilizan como adorno para cócteles tipo tiki exóticos.'),
  (98, 'es', 'Pisco', 'Este aguardiente de uva peruana se produce a partir de un máximo de ocho variedades de uva, mientras que en Chile se utilizan más de tres. El jugo fermentado se destila en depósitos de acero inoxidable y se embotella inmediatamente o se añeja en barricas de roble durante 2 años.'),
  (103, 'es', 'Terrones de azúcar', 'Condimento dulce europeo obtenido mediante una complicada purificación, refinado y cristalización del sirope de azúcar moreno o zumo de remolacha azucarera. Estos cristales son prensados hasta conseguir la forma deseada.'),
  (132, 'es', 'Bourbon viejo', 'Bourbon viejo'),
  (102, 'es', 'Azúcar glass', 'Condimento dulce en polvo obtenido del azúcar en polvo. Debido al tamaño del grano se disuelve instantáneamente en el líquido y ahorra tiempo significativamente.'),
  (158, 'es', 'Taza de cobre', 'Un imprescindible que se ha convertido en el "caballo de Troya" del vodka en América y en el utensilio preferido para servir el cóctel "Moscow Mule". Capacidad estándar: 300-400 ml.'),
  (214, 'es', 'Mora', 'Bayas de color púrpura oscuro de tamaño medio que crecen en arbustos de toda Europa, en el noroeste de África, Asia Central, América del Norte y del Sur. Contiene caroteno, vitamina C, B1, B2, K y otras vitaminas. Una baya pesa 6 g de media.'),
  (115, 'es', 'Azúcar granulado', 'Condimento dulce europeo obtenido de la complicada purificación, refinado y cristalización del sirope de azúcar moreno o del zumo de remolacha azucarera. El tamaño de los gránulos es importante, cuanto más pequeños más rápido se disolverán.'),
  (107, 'es', 'Leche', 'Elaborado con leche de vaca entera. El contenido de grasa deseado se consigue añadiendo crema a una versión del producto sin de grasa.'),
  (330, 'es', 'Canela en rama', 'Condimento de Ceilán, conocido desde el siglo XV, elaborado a partir de la corteza del árbol de la canela, que se limpia, es lijada y secada a la sombra hasta que se retuerce formando un tubo.'),
  (108, 'es', 'Taza', 'Taza alta de cerámica para el café o el té, en 1930 se convirtió en el utensilio preferido para el coctél "Tom y Jerry". Capacidad estándar: 200-250 ml.'),
  (655, 'es', 'Jarra de leche', 'Bote metálico para la leche. Usado para batir crema y preparar cócteles calientes.'),
  (120, 'es', 'Canela en polvo', 'Condimento en polvo de Ceilán, conocido desde el siglo XV, elaborado a partir de virutas y trozos de corteza de canela secados y molidos.'),
  (149, 'es', 'Anís estrellado', 'Fruta tropical con forma de estrella que crece en árboles de hoja perenne, principalmente en China. Se recolectan sin madurar y se secan al sol.'),
  (134, 'es', 'Sirope de arce', 'Famoso sirope navideño elaborado a partir de la savia del azúcar de arce recolectado de los arces en febrero y marzo. Se produce mediante la pasteurización de esta savia con azúcar moreno y agua.'),
  (123, 'es', 'Sirope de rosa', 'Sirope de delicada flor elaborado mediante la pasteurización e infusión de pétalos de rosa en sirope azúcar.'),
  (201, 'es', 'Pétalos de rosa', 'La flor más vendida del mundo. Hay 25 pétalos en un capullo.'),
  (1035, 'es', 'Whisky americano', 'Whisky americano'),
  (288, 'es', 'Jerez Pedro Ximénez', 'El tipo más dulce de los vinos españoles madurados se elabora con las uvas maduras homónimas. El zumo de uva fermentado se enriquece con alcohol de uva y se deja añejar en barricas de roble utilizando el método Solera de 10 a 30 años o más.'),
  (154, 'es', 'Cuchara de té', 'Cuchara para remover el té en una taza. Una cucharada contiene 5 g de media de ingredientes secos o 5 ml de líquido.'),
  (211, 'es', 'Hielo en bloques', 'Cubito en forma de masa o liso, gran trozo de hielo que se derrite más lentamente y parece más impresionante en el vaso.'),
  (450, 'es', 'Sirope de jengibre', 'Sirope asiático especiado elaborado mediante la pasteurización de extractos de jengibre en sirope de azúcar.'),
  (693, 'es', 'Bombilla de mate', 'Pajita especial para servir mate. El extremo superior contiene una boquilla mientras que la parte inferior tiene un colador.'),
  (552, 'es', 'Grosella roja', 'Pequeños frutos rojos que crecen en arbustos de hoja caduca, principalmente en Centroeuropa, el norte de Europa y el norte de Asia. Contiene grandes cantidades de vitamina C, así como varios azúcares, ácidos orgánicos y minerales. Una cucharada de cóctel contiene 5 g de bayas.'),
  (332, 'es', 'Jerez Oloroso', 'Vino fortificado español semiseco o dulce elaborado mediante la fermentación de las uvas Palomino sin formar una película protectora floras. El licor resultante se enriquece por etapas con licor de uva y se añeja en barricas de roble utilizando el método Solera durante al menos dos años.'),
  (191, 'es', 'Albaricoques desecados', 'Fruta desecada brillante producida principalmente en Turquía, Irán y Uzbekistán a partir de albaricoques maduros. Los frutos primero son reducidos o empapados en sirope y después se secan al sol o en un secador especial. Una pieza pesa 10g de media.'),
  (683, 'es', 'Bandeja', 'Plato de madera o metálico para servir comida o bebidas a los invitados.'),
  (121, 'es', 'Sirope de vainilla', 'Sirope fragante de Madagascar elaborado mediante la infusión y la pasteurización de vainas de vainilla en sirope.'),
  (381, 'es', 'Tequila dorado', 'Bebida espirituosa de orígen mexicano, tradicionalmente producida por la destilación del zumo de agave azul. De siete a diez corazones de agave veraniego se colocan en hornos de mampostería especiales para convertir el almidón en azúcar, el zumo resultante se fermenta, se destila dos veces y se colorea con caramelo. Se aromatiza con varios aditivos aromáticos.'),
  (318, 'es', 'Vermut blanco', 'Vermut dulce, obtenido mediante la maceración de hierbas alpinas y especias en vino blanco. El resultado se filtra, se adecúa a la concentración deseada, se lleva a la máxima dulzura y se añeja en barricas de roble durante al menos un año.'),
  (126, 'es', 'Puré de fresa', 'Puré de fresa'),
  (327, 'es', 'Azúcar moreno', 'Condimento dulce tropical elaborado mediante la cristalización de la caña de azúcar con su posterior tratamiento mecánico. Cuanto mayor sea el contenido de la melaza, el color será más oscuro y el sabor más rico.'),
  (138, 'es', 'Licuadora', 'Inventado en 1922 por Stephen Poplawski, este aparato eléctrico es indispensable para hacer cócteles tipo tiki, batidos y bebidas heladas.'),
  (196, 'es', 'Sirope de coco', 'El sirope tropical más popular es elaborado mediante la pasteurización de agua de coco con azúcar moreno.'),
  (197, 'es', 'Cortador de piña', 'Accesorio tiki que en cuestión de segundos elimina la piel y el núcleo duro de una piña.'),
  (744, 'es', 'Cuchara de cubitos de hielo', 'Herramienta adecuada hecha a partir de policarbonato o acero inoxidable que le permite a uno coger una cantidad específica de hielo. Las cucharas difieren en tamaño y volumen lo que le permite a uno seleccionar una herramienta para la cantidad requerida de hielo.'),
  (406, 'es', 'Licor de plátano amarillo', 'Licor de crema tropical obtenido de la maceración de la pulpa de plátanos amarillos en un alcohol neutro con agua. El resultado se filtra, se mezcla con azúcar y se enriquece con brandy joven.'),
  (200, 'es', 'Plátano', 'La planta tropical más antigua crece principalmente en China, India y Uganda. Esta fruta contiene vitamina B6, manganeso y fibra dietética. Una pieza de fruta pesa 200 g de media, pesando la piel 80 g.'),
  (244, 'es', 'Jenever', 'Bebida espirituosa holandesa, el padre de la ginebra, elaborado desde el siglo XV con la destilación de alcohol puro con la adición de bayas de enebro y otras especias.'),
  (133, 'es', 'Sirope de miel', 'El sirope más popular se elabora mediante la pasteurización de miel diluida con agua hasta conseguir la consistencia deseada.'),
  (293, 'es', 'Tetera', 'La historia del antiguo recipiente chino se remonta a dónde y cuándo comenzó el té en sí - en la China del siglo 14. Utilizado para preparar té, hierbas y especias en agua o zumo hirviendo.'),
  (287, 'es', 'Whisky Single Islay Malt', 'Whisky Single Islay Malt'),
  (284, 'es', 'Licor de ruibarbo', 'Licor de hierbas agridulce de postre obtenido de la maceración de los tallos y hojas de ruibarbo en un alcohol neutro con agua. El resultado se mezcla con azúcar y se lleva a la concentración deseada.'),
  (358, 'es', 'Cynar', 'Licor de hierbas italiano obtenido de la maceración y destilación de 16 hierbas y especias, principalmente la alcachofa, en alcohol neutro. El licor resultante se filtra y se lleva a la concentración y dulzura deseada.'),
  (735, 'es', 'Piel de pomelo', 'Capa superior de la piel del pomelo cortada con un cuchillo afilado especial. Contiene aceites esenciales que llevan el sabor del pomelo. La piel se puede obtener a partir de una pieza de fruta cortada, una pieza de fruta entera, rallada o incluso en forma de espiral (llamado twist).'),
  (704, 'es', 'Pulverizador', 'Atractivo accesorio para pulverizar amargos y suplementos aromáticos sobre los cócteles.'),
  (435, 'es', 'Jerez Fino', 'Vino fortificado seco español elaborado mediante la fermentación de uvas Palomino añadiendo una levadura especial. Madurado durante al menos 12 meses, el vino es cubierto por una película especial - flora, y se enriquece con alcohol de uva por etapas. Madura en barricas bajo la película protectora durante al menos 2 años.'),
  (653, 'es', 'Vaso de chupito', 'Vaso pequeño que, por regla general, tiene los bordes rectos. Designado para las bebidas más fuertes o cócteles los cuales deberían ser servidos en uno. Volumen estándar: 50-100ml.'),
  (546, 'es', 'Fresa', 'Baya roja grande que crece en pequeños arbustos principalmente en los EE.UU., Turquía, España, Egipto y México. Contiene azúcar, pectina y tanino, ácido ascórbico y otros ingredientes antiinflamatorios. Una baya pesa 20 g de media.'),
  (402, 'es', 'Limoncello', 'Licor nacional italiano obtenido de la maceración de la piel de limón en un alcohol neutro durante un mes. El alcohol resultante se mezcla con azúcar y agua, se deja fermentar y se filtra.'),
  (410, 'es', 'Licor de lichi', 'Hecho de la pulpa de lichis maduros que se mezclan con alcohol y se dejan infusionar.'),
  (486, 'es', 'Zumo de mango', 'Para preparar el zumo, la pulpa del mango se prensa y luego se filtra y se embotella.'),
  (529, 'es', 'Maracuyá', 'El maracuyá subtropical es una especie de vid de la flor de la pasión que crece principalmente en Nueva Zelanda, Israel y Sri Lanka. Contiene vitamina A, betacaroteno y potasio, y tiene un efecto tonificante en nuestros cuerpos. Una pieza de fruta pesa 90 g de media.'),
  (415, 'es', 'Licor de mora', 'Rico licor de bayas obtenido de la maceración de la mora en alcohol neutro con agua durante un máximo de dos meses. El licor no se filtra y se mezcla con azúcar.'),
  (405, 'es', 'Licor de manzana verde', 'Licor de fruta fresca obtenido de la maceración de la pulpa de manzanas verdes en alcohol neutro. El licor resultante se filtra, se mezcla con azúcar y se diluye con agua hasta obtener la concentración deseada.'),
  (528, 'es', 'Manzana', 'Esta popular fruta es originaria de Asia Central, y crece en los árboles frondosos, principalmente en China, EE.UU. y Turquía. Contiene ácido ascórbico, vitamina K, potasio, y se considera buena para aumentar la inmunidad y combatir la obesidad. Una pieza de fruta pesa 200 g de media y se puede cortar en 10 rodajas.'),
  (682, 'es', 'Tarro de cerámica (2)', 'Frasco con tapa hermética para mezclar y almacenar licores y cordiales. No hay volumen estándar disponible.'),
  (446, 'es', 'Sirope de agave', 'Sirope Mexicano hecho a partir de concentrado de zumo de agave mezclado con sirope de azúcar.'),
  (432, 'es', 'Vino tinto seco', 'Tipo más común de vino obtenido mediante la maceración y posterior fermentación de las uvas rojas y negras, que le dan al vino su color. Luego el vino se filtra y se mantiene en barricas de roble durante al menos 3 meses.'),
  (613, 'es', 'Clavos', 'Especia de Indonesia que consiste en cogollos secos del clavo tropical pimienta de Jamaica.'),
  (705, 'es', 'Fuente de absenta', 'Atributo vital en el ritual de servir la bebida fuerte francesa. El agua junto con hierbas, frutas y a veces con hielo, se vierte en el frasco principal. Una vez elaborada, la bebida se vierte gota a gota a través de azúcar en una cuchara y termina en el vaso con la absenta.'),
  (698, 'es', 'Cuchara de absenta', 'Atributo vital en el ritual para servir la bebida fuerte francesa. El alcohol con hierbas y frutas se vierte en el frasco principal. Una vez elaborada, la bebida se vierte gota a gota a través de azúcar en la cuchara y termina en la copa.'),
  (494, 'es', 'Bebida energética', 'La bebida energética ha sido diseñada específicamente para su consumo durante el aumento de la actividad física y mental.'),
  (394, 'es', 'Licor de crema irlandesa', 'Licor de crema irlandesa hecho de whisky irlandés destilado tres veces, con la adición de crema y alcohol neutro. Enriquecido con cacao, vainilla, azúcar y caramelo.'),
  (547, 'es', 'Arándano azul', 'Pequeño fruto del bosque púrpura que crece en arbustos en Canadá, América del Norte, Turquía y Europa Occidental. Contiene una gran cantidad de vitaminas A, B, C, manganeso y potasio. Es útil para la vista, mejora la visión nocturna. Una cucharada contiene 5 g de bayas.'),
  (578, 'es', 'Hierba limón', 'Hierba con aroma cítrico con orígenes en la cocina caribeña y asiática, crece principalmente en las Islas Británicas, Filipinas e Indonesia.'),
  (490, 'es', 'Sprite', 'Bebida carbonatada dulce elaborada usando soda y añadiendo azúcar y extracto de limón.'),
  (666, 'es', 'Sambuca', 'Licor italiano obtenido mediante la aromatización de alcohol de trigo con azúcar, aceites de anís normal y estrellado, extractos de bayas, flores de saúco y varias hierbas, que producen su fragancia duradera.'),
  (414, 'es', 'Advocaat', 'Licor de Navidad holandés descendiente de la bebida alcohólica brasileña hecha de aguacate. Esta bebida está hecha de una mezcla de yemas de huevo, azúcar, vainilla y brandy.'),
  (531, 'es', 'Granada', 'Fruta Mediterránea que crece en un arbusto frutal de hojas caducas o en arboles pequeños que crecen principalmente en Israel y la India. Contiene potasio y fósforo, conocida por tener un efecto positivo en el sistema cardiovascular. Una pieza de fruta pesa 300 g de media y se puede cortar en 10 rodajas.'),
  (684, 'es', 'Copa de vino tinto', 'Copa clásica, ligeramente curvada. Tradicionalmente más grande que la copa de vino blanco. Capacidad estándar: 200-300 ml.'),
  (483, 'es', 'Zumo de cereza', 'Para preparar el zumo, las cerezas son sometidas a una prensa y luego se filtra y se embotella.'),
  (551, 'es', 'Grosella negra', 'Pequeña baya negra cuyos arbustos crecen en Europa central, en el norte de Europa y en el norte de Asia. Contiene grandes cantidades de vitamina C, varios azúcares, ácidos orgánicos y minerales. Una cucharada de cóctel contiene 5 g de bayas.'),
  (597, 'es', 'Mermelada de frambuesa', 'Mermelada de bayas rojas que crecen en subarbustos perennes sobre todo en Rusia, Serbia, Polonia y los Estados Unidos. Los frutos maduros son hervidos con azúcar hasta homogeneizarse. Una cucharada de cóctel puede contener 5 g de mermelada.'),
  (590, 'es', 'Mermelada de naranja', 'Mermelada de la pulpa de este cítrico que crece en árboles altos principalmente en Brasil, Estados Unidos y China. Los frutos maduros son hervidos con azúcar hasta homogeneizarse. Una cucharada de cóctel puede contener 5 g de mermelada.'),
  (589, 'es', 'Miel', 'Néctar de la flor de recolectado y procesado por las abejas.'),
  (652, 'es', 'Galleta', 'Galleta dulce horneada con diferentes tipos de masa.'),
  (686, 'es', 'Jarra', 'Recipiente de la antigua cocina para servir agua, limonada y sangría. Volumen estándar: 500-3000ml.'),
  (484, 'es', 'Zumo de granada', 'Para preparar el zumo, las semillas de la granada se prensan y luego se filtra y se embotella.'),
  (548, 'es', 'Sandía', 'Bayas de gran tamaño que se plantan principalmente en China, Turquía e Irán. Contiene glucosa, fructosa, pectina, calcio, magnesio y sustancias alcalinas. Normaliza el metabolismo. Una baya pesa un promedio de 5,000 g, una rodaja - 300 g. La relación del peso de la pulpa con la piel es de - 60% al 40%.'),
  (454, 'es', 'Sirope de hierba limón', 'Sirope elaborado mediante la pasteurización de extracto de hierba limón con sirope de azúcar.'),
  (433, 'es', 'Vino blanco seco', 'Vino de verano que se obtiene mediante la maceración y posterior fermentación de uvas blancas sin piel. Luego el vino se filtra y se mantiene en barricas de roble durante al menos 3 meses.'),
  (532, 'es', 'Kiwi', 'El kiwi o grosella espinosa china es la baya comestible de una enredadera leñosa que crece en Italia, Nueva Zelanda y Chile. Contiene vitamina C, fibra, ácido fólico, calcio y fósforo, conocido por mejorar el sistema inmunológico humano. Una baya pesa 120 g de media.'),
  (577, 'es', 'Albahaca roja', 'Hierbas aromáticas que crecen principalmente en las regiones cálidas del Viejo Mundo.'),
  (702, 'es', 'Batidora de crema', 'Dispositivo hecho de vidrio grueso o metal para conseguir rápidamente nata montada de consistencia delicada y cremosa. También se puede utilizar para hacer diversos postres, salsas complejas y mousses. Volumen estándar: 0,5 a 1 litro.'),
  (399, 'es', 'Licor de melocotón', 'Licor de esta fruta que ama el sol elaborado mediante la destilación de zumo de melocotón fermentado con la adición de coñac. Para intensificar el rico sabor a melocotón se pueden añadir los huesos.'),
  (396, 'es', 'Licor de albaricoque', 'Famoso licor de fruta obtenido de la destilación del zumo fermentado de albaricoque con licores fuertes para intensificar el rico sabor.'),
  (691, 'es', 'Bol para ponche', 'Gran recipiente hecho de vidrio, cristal o metal para servir ponche que fue llevado a Inglaterra desde la India a principios del siglo 17. Volumen estándar: 5 litros.'),
  (395, 'es', 'Licor de amaretto', 'Licor italiano clásico obtenido de la maceración de huesos de albaricoque, diferentes hierbas y frutas en alcohol neutro. La base resultante se filtra, se mezcla con azúcar y se diluye con agua hasta obtener la concentración deseada.'),
  (556, 'es', 'Cereza', 'Baya amarilla o escarlata que crece en árboles de climas principalmente cálidos y templados, como Turquía, Italia, España y Chile. Contiene ácidos orgánicos, minerales, pectina, ácido fólico y vitaminas A, C, E y B. Una baya pesa un promedio de 5 g.'),
  (437, 'es', 'Cerveza lager', 'Cerveza ligera hecha de agua, cebada, extracto de malta, lúpulo y levadura de cerveza.'),
  (452, 'es', 'Sirope de grosella negra', 'Sirope de bayas elaborado mediante el procesamiento de zumo de grosellas maduras mezclado con azúcar y agua.'),
  (397, 'es', 'Licor de melón', 'Licor tropical de Asia obtenido de la maceración de la pulpa de melón en licor neutro con agua. El resultado se filtra, se ajusta a la dulzura y concentración deseada y se embotella.'),
  (763, 'es', 'Limón amargo', 'Bebida de limón carbonatada elaborada mediante la carbonatación de agua con extracto de limón.'),
  (380, 'es', 'Becherovka', 'Licor Checo canónico obtenido de la maceración de una mezcla de 20 hierbas y especias en licor neutro, que posteriormente se mezcla con agua y azúcar y se deja envejecer de dos a tres semanas en barricas de roble.'),
  (502, 'es', 'Té Earl Grey', 'En su forma clásica, este es un té negro con la adición de aceite hecho de la cáscara de la fruta de la bergamota. La mejor temperatura para preparar este té es de 90 a 95 ° C y se debería dejar reposar durante 3-5 minutos.'),
  (709, 'es', 'Sombrilla de cóctel', 'Decoración de papel brillante para cócteles tropicales o para entretener a los niños.'),
  (639, 'es', 'Ciruela pasa', 'Manjar europeo producido a partir de ciruelas negras secadas al sol o en un secador especial.'),
  (747, 'es', 'Tartaleta', 'Copia en miniatura de una tarta, nombrada por primera vez en el libro de cocina del rey Ricardo II en 1390. Es un plato al horno que consiste en un relleno sobre una base de hojaldre con la parte superior abierta no cubierta de masa.'),
  (453, 'es', 'Sirope de manzana amarilla', 'Sirope amarillo y afrutado elaborado mediante la pasteurización de zumo de manzanas amarillas con azúcar moreno.'),
  (576, 'es', 'Romero', 'Hierbas mediterráneas con esencia aromática de pino.'),
  (409, 'es', 'Licor de pomelo', 'Licor de cítricos obtenido de la maceración de piel de pomelo rosa en alcohol neutro. El licor resultante se filtra, se mezcla con azúcar y se diluye con agua pura hasta obtener la concentración deseada.'),
  (549, 'es', 'Arándano rojo', 'Pequeña baya roja que crece en arbustos enanos o enredaderas, principalmente en Estados Unidos, Chile, Argentina y los Países Bajos. Contiene ácidos orgánicos, minerales, pectina, ácido fólico y vitaminas A, C, E y B. Una cucharada de cóctel contiene 5 g de bayas.'),
  (492, 'es', 'Tónica', 'Bebida carbonatada inventada en la India para combatir la malaria. Está hecha de agua con gas mezclada con quinina y una pequeña cantidad de azúcar.'),
  (562, 'es', 'Uvas rojas', 'Bayas rojas de tamaño mediano; una uva es una baya de fructificación de enredaderas de hoja vinícola. Proviene de China, los EE.UU., Italia, Francia y España. Contiene azúcar, celulosa, ácidos orgánicos, vitamina B y trazas de otros elementos, tiene un efecto fortalecedor y tonificante. Una baya pesa 5 g de media.');
INSERT INTO drink_me_bot.goods_i18n (goods_id, lang, name, description) VALUES
  (663, 'es', 'Vodka naranja', 'Bebida espirituosa con fuerte sabor debido a la destilación de múltiples granos, sujeta a varias fases de carbono y otros filtros. El resultado se mezcla con agua limpia. La bebida resultante se infusiona con extractos de naranja madura.'),
  (530, 'es', 'Mandarina', 'La mandarina es una fruta cítrica de color naranja que crece en arbustos de hoja perenne, principalmente en China, España y Brasil. Contiene vitamina C y potasio, conocida por mejorar el sistema inmune. Una pieza de fruta pesa unos 100 g de media y produce 40 ml de zumo.'),
  (710, 'es', 'Lillet Blanc', 'Vino de aperitivo francés producido a partir de una combinación de vinos blancos de la región de Burdeos mezclada con licores de frutas. Mientras el vino está madurando, la piel de naranjas dulces, amargas y agrias y la quinina verde se infusiona en licores de brandy. Entonces todo se mezcla y se mantiene en barricas de roble durante 8-12 meses.'),
  (389, 'es', 'Ron con especies o especiado', 'Bebida caribeña elaborada mediante la destilación vertical del alcohol obtenido de la fermentación de la melaza o zumo de caña de azúcar. Antes de mezclar se mantiene en barricas de roble quemado de bourbon o de jerez entre 2 a 7 años, dependiendo del método elegido de añejamiento, con una infusión de canela, nuez moscada, vainilla y otras especias.'),
  (398, 'es', 'Licor de curaçao azul', 'Licor naranja neón obtenido de la maceración de la piel de naranja seca en un alcohol neutro con agua. El resultado se filtra, se mezcla con azúcar y se colorea con tintes naturales.'),
  (550, 'es', 'Uvas verdes', 'Bayas verdes de tamaño medio que crecen en vides de madera de hoja caduca. Proviene de China, los EE.UU., Italia, Francia y España. Contiene azúcar, celulosa, ácidos orgánicos, vitamina B y trazas de otros elementos, tiene efecto fortalecedor y tonificante. Una baya pesa 5 g de media.'),
  (533, 'es', 'Mango', 'Fruta tropical silvestre que crece principalmente en la India, Pakistán y Filipinas. Contiene vitamina A, ácido fólico y potasio y ayuda a mejorar la inmunidad y la vista. Una pieza de fruta pesa 300 g de media y se puede cortar en 10 rodajas.'),
  (408, 'es', 'Licor de canela', 'Licor alemán especiado obtenido de la maceración de la canela en aguardiente. El resultado se filtra, se mezcla con azúcar y se añade la hoja de oro para el sabor.'),
  (495, 'es', 'Té verde helado', 'Popular en Asia, el té helado se elabora sobre la base del extracto de té verde y otras hierbas sin ningún tipo de saborizantes y conservantes artificiales.'),
  (711, 'es', 'Colador Julep', 'Accesorio indispensable cuando se trabaja con un vaso mezclador. También sirve como una decoración sin igual para el cóctel clásico del mismo nombre. Se utiliza para filtrar en cócteles piezas trituradas de hielo y otros ingredientes no deseados.'),
  (670, 'es', 'Café espreso', 'Café fuerte que se prepara vertiendo una pequeña cantidad de agua hirviendo a una temperatura de 90 ° C sobre café molido.'),
  (690, 'es', 'Taza de té', 'Taza tradicional de los bebedores de té turco. Volumen estándar: 40-80ml.'),
  (412, 'es', 'Licor de maracuyá', 'Hecho de la pulpa del maracuyá maduro, naranjas y pomelos, que se mezclan con alcohol y se dejan infusionar.'),
  (615, 'es', 'Azúcar de vainilla', 'Azúcar clásica con sabor a vainilla.'),
  (181, 'es', 'Cafetera francesa', 'Accesorio francés para la elaboración de café y té, formado por un frasco de vidrio con un colador y una prensa.'),
  (448, 'es', 'Sirope de fresa', 'Este sirope de fruta silvestre se produce de la pasteurización de jugo de fresas maduras mezclado con azúcar y agua.'),
  (567, 'es', 'Pimiento chile', 'Pimientos tropicales picantes que crecen en arbustos, principalmente en América del Sur. Contienen vitaminas A y C así como potasio, magnesio, y hierro. Una vaina pesa 30 g de media.'),
  (499, 'es', 'Té negro', 'Tipo de té que ha sido sometido a fermentación durante un periodo de entre dos semanas a un mes. Crece en regiones con clima tropical o subtropical. Para su elaboración, vierte 100 ml de agua hirviendo sobre 1 cucharada de té y déjalo reposar durante 4-5 minutos.'),
  (411, 'es', 'Licor de mango', 'Licor tropical asiático obtenido de la maceración de la pulpa de mangos maduros en alcohol neutro con agua. El alcohol resultante se filtra y se mezcla con azúcar.'),
  (514, 'es', 'Helado de vainilla', 'Este postre congelado se prepara a partir de leche, nata, mantequilla y azúcar con la adición de extracto de vainilla. Se conserva almacenado en el congelador durante no más de un mes.'),
  (592, 'es', 'Mermelada de cereza', 'Mermelada de bayas amarillas o de color escarlata que crecen en árboles de climas principalmente cálidos, como Turquía, Italia, España y Chile. Las cerezas maduras sin hueso son hervidas con azúcar hasta homogeneizarse. Una cucharada de cóctel contiene 5 g de mermelada.'),
  (485, 'es', 'Zumo de melocotón', 'Para preparar el zumo, los melocotones se prensan y luego se filtra y se embotella.'),
  (387, 'es', 'Vodka de grosella', 'Intensa bebida espirituosa con un sabor fuerte producido por la destilación de múltiples granos, sujeto a varios procesos de carbono y otros filtros, el resultado se mezcla con agua limpia. La bebida resultante se infusiona con extractos de grosella negra madura.'),
  (633, 'es', 'Agua de rosas', 'Antigua receta de agua perfumada infusionada con pétalos de rosa.'),
  (713, 'es', 'Puré de frambuesa', 'Puré de frambuesa'),
  (586, 'es', 'Tomillo', 'Especia aromática en forma de arbusto enano, que crece principalmente en Eurasia, el norte de África y Groenlandia. Usado en mezclas provenzales, ideal para aromatizar licores fuertes.'),
  (407, 'es', 'Licor de coco', 'Licor Tiki tropical obtenido de la maceración de la pulpa del coco en el ron. El licor resultante se filtra, se mezcla con azúcar y se diluye con agua hasta obtener la concentración deseada.'),
  (430, 'es', 'Vermut rosado', 'Categoría relativamente joven de vermut elaborada mediante la maceración de hierbas alpinas y especias en un vino rosado. El resultado se filtra, se adecúa a la intensidad y dulzura deseada y se añeja en barricas de roble durante al menos un año.'),
  (646, 'es', 'Chocolate negro', 'Postre de confitería hecho de granos de cacao negro con poca o ninguna azúcar añadida.'),
  (447, 'es', 'Sirope de caramelo', 'Famoso sirope de caramelo elaborado mediante el procesamiento de caramelo líquido con la adición de vainilla y agua.'),
  (750, 'es', 'Servilletas', 'Servilletas de papel o de algodón. A veces usadas como posavasos para las bebidas.'),
  (360, 'es', 'Sifón', 'Dispositivo hecho de vidrio grueso o metal para las bebidas carbonatadas. Volumen estándar: 1-2 litros.'),
  (500, 'es', 'Grano de café', 'Granos tostados de la planta del café. Debido a su contenido de cafeína es conocido por tener un efecto estimulante en el cuerpo humano. Hay dos variedades principales de planta del café: Arábica y Robusta.'),
  (565, 'es', 'Sake', 'Licor japonés hecho de arroz empapado y cocido al vapor. El cultivo preparado se enriquece con los hongos de la fermentación y se mantiene en una habitación caliente y húmeda durante 2 días. Después de la fermentación el sake se mantiene bien guardado en contenedores sellados entre 6 a 12 meses.'),
  (537, 'es', 'Quinoto', 'Pequeña fruta cítrica que crece de pequeños árboles frutales, principalmente en China, Corea y Japón. Contiene vitamina C, hierro y magnesio, ayuda a luchar contra las infecciones. Una pieza de fruta pesa 10 g de media.'),
  (685, 'es', 'Copa de coñac', 'Copa clásica para beber coñac o brandy. Capacidad estándar: 170-400 ml.'),
  (423, 'es', 'Southern Comfort', 'Licor de frutas de Nueva Orleans inventado por el barman Martin Garza en 1874, elaborado siguiendo una antigua receta a base de whisky americano con la adición de fruta y esencias de hierbas, azúcar y caramelo y envejecido en barricas de roble hasta la madurez deseada.'),
  (703, 'es', 'Sartén', 'Antiguo utensilio de cocina necesario en el bar para flamear bayas y frutas.'),
  (688, 'es', 'Set de cata', 'Set de cata. Consiste en una bandeja de cristal llena de hielo, asegurando que los chupitos de prueba se mantengan fríos.'),
  (462, 'es', 'Sirope de lichi', 'Sirope de fruta asiática elaborada mediante la pasteurización de zumo de lichi mezclado con sirope de azúcar y agua.'),
  (504, 'es', 'Manzanilla', 'Brebaje hecho de las flores secas de la planta de la manzanilla. Generalmente, se vierte agua hirviendo sobre las flores en una proporción de 1-2 cucharaditas cada 200 ml de agua, se deja entonces reposar durante 7-10 minutos, se cuela y entonces o bien se bebe como está o se le añade azúcar o miel.'),
  (673, 'es', 'Mermelada de espino amarillo', 'Mermelada de pequeñas bayas amarillas que crecen en arbustos espinosos caducifolios sobre todo en la costa atlántica de Europa y en el noroeste de China. Los frutos maduros son hervidos con azúcar hasta homogeneizarse. Una cucharada de cóctel puede contener 5 g de mermelada.'),
  (769, 'es', 'Platito', 'Plato pequeño metálico, de porcelana o cristal que se sirve típicamente con una taza. En su interpretación moderna, una copa de cóctel con un platito proyecta un servicio más refinado y elegante.'),
  (463, 'es', 'Sirope de mango', 'Sirope de fruta asiática elaborado mediante la pasteurización de zumo de mango mezclado con azúcar moreno y agua.'),
  (700, 'es', 'Portavasos para té', 'Soporte metálico para vasos con un mango que sujeta el cristal permitiéndole a alguien beber una bebida caliente sin quemarse las manos.'),
  (695, 'es', 'Tenedor', 'Cubierto formado por un mango y varios dientes (por lo general entre dos y cuatro) en un extremo. Se utiliza para la preparación de alimentos así como para sostener o mover partes de comida mientras se está comiendo.'),
  (445, 'fr', 'Sirop de cannelle', 'Célèbre sirop épicé produit par pasteurisation et infusion de sirop de sucre avec de la cannelle.'),
  (176, 'fr', 'Jus de citron vert', 'Pour préparer le jus, les citrons verts sont pressés, le jus est ensuite filtré et mis en bouteille.'),
  (482, 'fr', 'Jus de pomme', 'Pour préparer le jus, les pommes sont pressées, le jus est ensuite filtré et mis en bouteille.'),
  (767, 'fr', 'Blanc d''oeuf de caille', 'Pour donner à cet ingrédient de cocktail une texture lisse et mousseuse, nous vous recommandons d''utiliser la méthode " Dry shake", c''est-à-dire, sans mettre de glaçons dans le shaker. Un blanc d''œuf de poule est équivalent à 5 blancs d''œufs de caille.'),
  (217, 'fr', 'Concombre', 'Le concombre est une vigne rampante qui porte des fruits cylindriques qui sont utilisés comme légumes culinaires. Le concombre pousse principalement dans les pays méditerranéens. Il normalise le métabolisme, améliore la fonction cardiaque et rénale. Un concombre pèse 150 g en moyenne, et peut être coupé en 10 tranches ou tronçons.'),
  (31, 'fr', 'Glaçons', 'Pour produire l''ingrédient indispensable, il faut prêter une attention particulière à la pureté de l''eau et à la vitesse de congélation. Plus l''eau est gelée lentement, plus le produit final sera transparent. Le glaçon idéal n''a aucune rayure et fond lentement dans le verre.'),
  (210, 'fr', 'Coupe à champagne', 'Verre à pied dont le contenant a une forme évasée. Selon une légende, la coupe a été conçue pour imiter la silhouette de l''une des maîtresses d''un roi de France. Elle est utilisée pour servir du champagne et des cocktails « tini ». Contenance standard : 20 à 30 cl.'),
  (68, 'fr', 'Shaker', 'Il a obtenu son look dans les années 1800 et a gagné en popularité dans les années 1920 et 1930, après être passé sous des dizaines de styles et de formes différents. Il existe trois types de shakers : le shaker « trois-pièces » qui a un filtre incorporé, le shaker Continental sans filtre et le shaker Boston qui se composent de deux timbales de tailles égales. Contenance standard : 500 à 700 ml.'),
  (69, 'fr', 'Passoire à cocktail', 'Accessoire qui est indispensable quand on travaille avec un shaker Boston ou un shaker Continental. La passoire à cocktail est utilisée pour filter les pépins de fruits, les morceaux de glace et autres ingrédients indésirables.'),
  (73, 'fr', 'Mesure de bar', 'Permet un dosage précis et idéal pour la préparation des cocktails. Les meilleurs barmen ont toujours dans leur arsenal une gamme de tailles : 20-40 ml, 25-50 ml et 30-60 ml.'),
  (70, 'fr', 'Presse-agrumes', 'Outil indispensable pour presser le jus des citrons verts et des citrons. Malgré le fait que la plupart des établissements populaires utilisent aujourd''hui le jus qui a été préparé à l''avance, un jus fraîchement pressé est considéré de qualité supérieur.'),
  (239, 'fr', 'Centrifugeuse', 'Extracteur de jus de tout légume ou fruit. Contrairement à un presse jus manuel, une centrifugeuse sépare le jus de la pulpe grâce à un mouvement de rotation.'),
  (1, 'fr', 'Vodka', 'Vodka'),
  (55, 'fr', 'Liqueur de café', 'Liqueur stimulante célèbre produite par la percolation de grains de café de différentes variétés dans un alcool neutre. Le mélange obtenu n''est pas filtré, est mélangé avec du caramel et dilué avec de l''eau pour obtenir le degré d''alcool désiré.'),
  (65, 'fr', 'Verre Old Fashioned', 'Verre large avec un fond épais pour servir des spiritueux forts ou des cocktails non dilués. Contenance standard : 20 à 30 cl.'),
  (64, 'fr', 'Cuillère à mélange', 'Cet outil indispensable du barman est utilisé pour la préparation de cocktails dans un verre à mélange et pour créer des étages, ainsi que pour mesurer des doses de 5 ml pour les liquides ou de 5 g pour les solides.'),
  (57, 'fr', 'Pailles', 'En 1888, Marvin Stone, le propriétaire d''une usine de production de porte-cigarettes en papier, inventa le meilleur accessoire pour boire des boissons dans des verres. Joseph Friedman a ensuite fait fortune en développant les pailles flexibles. L''étape finale est venue avec des pailles fabriquées avec du plastique.'),
  (799, 'fr', 'Gin botanique', 'Il s''agit d''une liqueur forte écossaise à laquelle le monde entier doit du gin tonic au concombre Avant la distillation, l’alcool de grain est infusé pendant onze jours avec onze types de plantes, auxquels s’ajoutent de la rose et du concombre. Le produit obtenu est associé à une boisson d''un deuxième alambic, dont la qualité unique réside dans son utilisation de la méthode dite du "bain" d''herbes distillées à la vapeur. Outre les concombres et les roses bulgares, le gin Hendrick''s le plus célèbre comprend un grand nombre de fleurs, de racines et de fruits, ce qui en fait l''une des boissons les plus demandées dans les bars du monde entier.'),
  (54, 'fr', 'Liqueur triple sec', 'Liqueur d''agrumes culte élaborée par macération d''écorces séchées d''oranges de Curaçao dans un alcool neutre avec de l''eau. Le liquide obtenu subit une triple distillation avant l''embouteillage, tout en maintenant un degré d''alcool élevé.'),
  (9, 'fr', 'Jus de citron', 'Pour préparer le jus, les citrons sont pressés, le jus est ensuite filtré et mis en bouteille.'),
  (734, 'fr', 'Zeste de citron', 'Couche extérieure de la peau de citron, coupée avec un couteau spécial tranchant. Le zeste contient des huiles essentielles qui portent la saveur de citron. Il peut être obtenu à partir d''un fruit coupé, un fruit entier, râpé ou même vrillé en spirale (twist).'),
  (66, 'fr', 'Verre à sour', 'Les verres à sour ont été conçus pour servir les cocktails sour - contenant une liqueur de base, du jus de citron ou de citron vert, et une substance sucrée. Contenance standard : 9 à 12 cl.'),
  (71, 'fr', 'Zesteur', 'Outil de barman provenant de la culture japonaise de la sculpture. Utilisé pour prélever une mince couche de zeste ou pour couper des anneaux ou des torsades de pommes.'),
  (143, 'fr', 'Mezcal', 'Spiritueux mexicain, élaboré selon des méthodes traditionnelles, y compris de fumer les agaves placées dans des fosses creusées dans le sol et recouvertes de roches volcaniques chaudes. La boisson est infusée avec une saveur fumée. Puis les coeurs d''agaves sont moulus, le jus ainsi obtenu est fermenté et mis à vieillir en fûts de chêne pendant au moins 4 mois.'),
  (224, 'fr', 'Basilic vert', 'Ces plantes épicées poussent principalement dans les régions chaudes de l''Ancien Monde. Les feuilles vertes ont gagné en popularité en raison du cocktail « Smash basilic » qui est déjà devenu un classique.'),
  (223, 'fr', 'Cardamome', 'Assaisonnement de Ceylan qui pousse sur des plantes herbacées de la famille du gingembre. La cardamome est considérée comme l''une des épices les plus efficaces au monde.'),
  (566, 'fr', 'Racine de gingembre', 'Le gingembre est une plante vivace asiatique, importée en Europe au Moyen Age. Le rhizome ressemble à des boules attachées les unes sur les autres. La racine de gingembre aide à améliorer l''immunité et à lutter contre les maux de tête. Une « boule » de la racine pèse 5 g en moyenne.'),
  (83, 'fr', 'Glace pilée', 'Les toutes premières glaces “concassées” étaient réduites en morceaux par des barmen en utilisant des pics à glace sur des gros blocs de glace. Aujourd''hui, des broyeurs permettent de faire de la glace pilée.'),
  (117, 'fr', 'Chinois', 'Utilisé conjointement avec le shaker et la passoire pour un double filtrage des cocktails quand la boisson est versée du shaker dans le verre. Avec des perforations plus petites que celles de la passoire, il ne laisse même pas passer les plus petites graines de fruits et les morceaux de glace dans la boisson.'),
  (52, 'fr', 'Pilon de bar', 'Accessoire indispensable pour les cocktails tropicaux, il permet d''écraser les baies et les fruits dans le shaker ou directement dans le verre.'),
  (373, 'fr', 'Pinces à linge', 'Accessoire décoratif utilisé pour maintenir la garniture sur un verre.'),
  (113, 'fr', 'Absinthe', 'Spiritueux français obtenu par macération de plantes aromatiques et d''épices, y compris la mélisse, le fenouil et l''anis en grains ou alcool de vin. La principale composante est l''absinthe, qui contient de la thuyone, un ingrédient très enivrant.'),
  (295, 'fr', 'Sirop de sucre', 'Sirop de sucre'),
  (152, 'fr', 'Framboise', 'Cette petite baie rouge pousse sur des petits arbustes vivaces cultivés principalement en Russie, en Serbie, en Pologne et aux États-Unis. Elle contient du sucre, des acides organiques, des vitamines A, B et C, et des lipides. Une framboise pèse 5 g en moyenne.'),
  (125, 'fr', 'Single malt whisky des Highlands', 'Spiritueux d''origine écossaise produit dans la région montagneuse de l''Écosse, les Highlands. Fabriqué à partir de 100 % de malt d''orge par double, ou rarement, triple distillation. L''alcool obtenu est mis à vieillir en fûts de chêne pendant au moins 3 ans.'),
  (47, 'fr', 'Campari', 'Campari'),
  (189, 'fr', 'Jus de pamplemousse', 'Pour préparer le jus, les pamplemousses sont pressés, le jus est ensuite filtré et mis en bouteille.'),
  (672, 'fr', 'Menthe', 'La plante la plus largement reconnue dans les cocktails, elle comprend plus de 30 espèces. La menthe poivrée et la menthe douce sont principalement utilisées dans la mixologie. Peut être conservée pendant deux jours au plus au réfrigérateur, enveloppée dans une serviette de papier.'),
  (124, 'fr', 'Chartreuse verte', 'Cette liqueur monastique est produite dans les Alpes françaises depuis 1764 en utilisant une recette secrète. Environ 130 plantes sont macérées dans un alcool neutre, ce qui est ensuite distillé à plusieurs reprises. Le résultat obtenu est équilibré avec du sucre, mélangé pour obtenir le degré d''alcool désiré et mis à vieillir en fûts de chêne.'),
  (427, 'fr', 'Liqueur de fleur de sureau', 'Liqueur florale française élaborée par macération de fleurs de sureau écrasées en utilisant une recette secrète. Le spiritueux obtenu est filtré, mélangé avec du sucre et dilué avec de l''eau pour obtenir le degré d''alcool désiré.'),
  (35, 'fr', 'Vermouth sec', 'Vermouth fort, qui est apparu au début du XIXe siècle, élaboré par macération de génépi et une douzaine d''autres plantes dans un vin blanc sec. Le résultat est filtré et mis à vieillir en fûts de chêne pendant au moins un an.'),
  (130, 'fr', 'Liqueur d''orange', 'Liqueur d''agrumes parfumée élaborée par macération de zestes d''oranges de variété laraha dans un alcool neutre avec de l''eau. Le spiritueux obtenu est filtré, mélangé avec du sucre et conservé dans des fûts de chêne.'),
  (114, 'fr', 'Peychaud''s bitters', 'Amer classique de la Nouvelle-Orléans, inventé par le célèbre apothicaire du même nom en 1830, produit selon une recette secrète par infusion d''alcool neutre avec de l''anis, des clous de girofle, de la vanille, de la muscade, des fruits et des épices.'),
  (161, 'fr', 'Verre à pied', 'Verre royal avec des parois épaisses permettant de trinquer sans risque de les casser. Contenance standard : 20 à 30 cl.'),
  (665, 'fr', 'Liqueur marasquin', 'Sirop de baies produit par pasteurisation du jus de cerises au marasquin mélangé avec du sucre de canne et de l''eau.'),
  (303, 'fr', 'Bitters au pamplemousse', 'Amer estival produit par infusion d''alcool neutre avec des écorces de pamplemousse avec ajout de houblon pour adoucir l''amertume.'),
  (20, 'fr', 'Cerises au marasquin', 'Variétés spéciales de cerise, telles que « King Anna », « Rainer » ou « Golden diversity » qui sont placées dans une solution saline, puis trempées dans un sirop de sucre avec ajout de colorant alimentaire.'),
  (96, 'fr', 'Pique à cocktail', 'Accessoire décoratif pour servir les olives dans les martinis et les cerises dans le cocktail Manhattan. Les piques à cocktail ont fait leur entrée dans les bars à la fin du 19e siècle grâce au génie de marketing Charles Forster.'),
  (101, 'fr', 'Rhum vieux', 'Spiritueux des Caraïbes produit par distillation continue de l''alcool obtenu par fermentation de mélasse ou de jus de canne à sucre. Avant d''être mélangé, il est conservé dans des fûts de chêne brûlés, de bourbon ou de xérès, pendant 7 à 20 ans, selon la méthode de vieillissement choisie.'),
  (116, 'fr', 'Liqueur de chocolat noir', 'Liqueur de chocolat noir produite par la percolation de fèves de cacao dans un alcool neutre. Le spiritueux obtenu est dilué avec de l''eau pour obtenir le degré d''alcool désiré, puis est mélangé avec de la vanille de Madagascar ainsi que du caramel qui donne à la liqueur une couleur foncée.'),
  (67, 'fr', 'Verre à mélange', 'Un must classique pour un bar cinq étoiles. Utilisé pour la préparation de boissons masculines fortes sans ajout de jus de fruits, de plante ou de confiture. La glace conserve sa forme et ne fond pas,gardant ainsi la teneur en alcool de la boisson. Contenance standard : 50 à 90 ml.'),
  (166, 'fr', 'Amaro', 'Liqueur italienne classique obtenue par macération de plantes et de racines, y compris les écorces d''agrumes, le genévrier, le fenouil, la mélisse, l''anis et la cardamome, dans de l''alcool neutre. Le spiritueux obtenu est filtré, mélangé avec du sucre et dilué avec de l''eau pour obtenir le degré d''alcool désiré.'),
  (171, 'fr', 'Glaçon sphérique', 'La fierté des barmen japonais – un glaçon élevé au rang d''objet d''art. Aujourd''hui, ces glaçons sphériques sont plus fréquents dans les bars grâce à des machines spéciales. Des glaçons préparés sont placés dans un étau à peine tiède et le métal est réchauffé par de l''eau, ce qui découpe les contours d''une sphère.'),
  (3, 'fr', 'Citron', 'Cet agrume tropical pousse sur des petits arbres à feuilles persistantes cultivés principalement en Chine, en Inde et au Mexique. Il contient de la vitamine C et des acides organiques, et est traditionnellement utilisé pour lutter contre les rhumes et le déficit nutritionnel. Un fruit pèse 160 g et produit 60 ml de jus, peut être coupé en 8 tranches ou 4 grands segments de 15 ml chacun.'),
  (62, 'fr', 'Bourbon', 'Spiritueux vieilli d''origine américaine, qui doit contenir, selon la loi, au moins 51 % de malt de maïs, avec ajout d''orge et de seigle, d''abord distillé, puis filtré. Mis à vieillir pour votre plaisir en fûts de chêne de 2 à 7 ans. Les barils sont brûlés de l''intérieur grâce à une technique spéciale.'),
  (111, 'fr', 'Crème de cassis', 'Liqueur de baies de Dijon élaborée par macération de cassis dans un alcool neutre avec de l''eau pendant deux mois au plus. La liqueur n''est pas filtrée et est mélangée avec du sucre.'),
  (63, 'fr', 'Amers d''Angostura', 'Amer classique vénézuélien, nommé en l''honneur de la ville d''Angostura. Fabriqué selon la recette originale secrète de Dr. Johann Gottlieb Benjamin Siegert, (vers 1800) par infusion d''épices et de plantes secrètes dans du rhum brun.'),
  (16, 'fr', 'Crème fraîche légère', 'Crème pauvre en matières grasses fabriquée en séparant la crème du lait, principalement de vache. Le pourcentage de matières grasses varie selon les pays, mais ne dépasse normalement pas 15 %. À conserver dans le réfrigérateur pendant 20 jours au plus.'),
  (36, 'fr', 'Vermouth rouge', 'Vermouth légèrement sucré, produit par macération de 30 plantes alpines et épices dans un vin blanc. Le résultat est filtré, ajusté pour obtenir le degré d''alcool et la douceur désirés, et après ajout d''un colorant caramel, mis à vieillir en fûts de chêne pendant au moins un an.'),
  (34, 'fr', 'Eau gazeuse', 'Eau carbonatée, devenue un élément indispensable du Fizz et d''autres boissons gazeuses, auparavant produite en carbonatant de l''eau avec du dioxyde de carbone, mais de nos jours, elle est de plus en plus préparée en ajoutant du bicarbonate de soude à de l''eau plate pure.'),
  (732, 'fr', 'Zeste d''orange', 'Couche extérieure de la peau d''orange, coupée avec un couteau spécial tranchant. Le zeste contient des huiles essentielles qui portent la saveur d''orange. Il peut être obtenu à partir d''un fruit coupé, un fruit entier, râpé ou même vrillé en spirale (twist).'),
  (258, 'fr', 'Champagne', 'Vin mousseux produit dans la région française du même nom, en vertu de strictes réglementations. Récoltées à la main, trois variétés de raisins sont fermentées et les vins obtenus sont mélangés et mis en bouteille avec ajout de sucre de canne et de levure. Une deuxième fermentation se produit dans la bouteille, cela prend au moins 9 mois, le dépôt est éliminé durant l''étape du dégorgement, une liqueur est ajoutée et la bouteille est bouchée avec un bouchon de liège naturel.'),
  (148, 'fr', 'Purée de pêches', 'Purée de pêches'),
  (535, 'fr', 'Pêche', 'Ce fruit aime le soleil et pousse sur des arbres à feuilles caduques cultivés principalement en Chine, en Italie et en Espagne. Il contient des acides organiques, des sels minéraux et de la pectine. Un fruit pèse 120 g en moyenne et produit environ 80 g de purée.'),
  (59, 'fr', 'Flûte', 'Verre de la haute société pour les cocktails à base de champagne ou de vin mousseux. La forme longue et étroite rappelle une tulipe et retient les bulles dans le cocktail lui permettant ainsi de rester pétillant plus longtemps. Contenance standard : 18 à 25 cl.'),
  (179, 'fr', 'Cordial de citron vert', 'Ancienne recette aux agrumes, produite par pasteurisation du jus de citron vert mélangé avec du sirop de sucre, de la crème de tartre et de l''eau.'),
  (733, 'fr', 'Zeste de citron vert', 'Couche extérieure de la peau de citron vert, coupée avec un couteau spécial tranchant. Le zeste contient des huiles essentielles qui portent la saveur de citron vert. Il peut être obtenu à partir d''un fruit coupé, un fruit entier, râpé ou même vrillé en spirale (twist).'),
  (72, 'fr', 'Verre à cocktail', 'Connu également comme verre à martini, l''un des premiers verres pour servir des cocktails sans glace. Avant de servir, il est nécessaire de refroidir le verre, et le long pied du verre empêche le cocktail de se réchauffer quand on le tient. Contenance standard : 9 à16 cl.'),
  (40, 'fr', 'Cognac', 'Spiritueux vieilli d''origine française qui provient de raisins blancs: Ugni blanc, Folle-blanche ou moins souvent Colombard Montilla. Soumis à une double distillation et mis à vieillir en fûts de chêne, - VS (Very Special) jusqu''à 3 ans; V.S.O.P (Very Superior Old Pale) jusqu''à 5 ans.'),
  (14, 'fr', 'Noix de muscade en poudre', 'Assaisonnement indonésien créé à partir de noix de muscade séchée et moulue.'),
  (746, 'fr', 'Râpe à noix de muscade', 'Accessoire utile pour préparer des poudres de noix de muscade ou de chocolat, ou plus rarement des zestes d''agrumes.'),
  (8, 'fr', 'Jus d''orange', 'Pour préparer le jus, les oranges sont pressées, le jus est ensuite filtré et mis en bouteille.'),
  (88, 'fr', 'Rhum blanc', 'Spiritueux des Caraïbes produit par distillation continue de l''alcool obtenu par fermentation de mélasse ou de jus de canne à sucre. Avant d''être mélangé, il est conservé dans des fûts de chêne brûlés, de bourbon ou de xérès, pendant au moins 12 mois, selon la méthode de vieillissement choisie, et est ensuite filtré pour enlever toute couleur.'),
  (92, 'fr', 'Calvados', 'Spiritueux français produit par fermentation du jus de pommes normandes, cueillies en automne, dans des cuves d''acier pendant six mois à un an. Le liquide obtenu est soumis à une double distillation et mis à vieillir en fûts de chêne pendant au moins 2 ans.'),
  (77, 'fr', 'Sirop de grenadine', 'Sirop de fruits rouges populaire produit par pasteurisation du jus de grenade avec d''autres jus de fruits rouges, de la vanille et de la canne à sucre.'),
  (86, 'fr', 'Rhum brun', 'Spiritueux des Caraïbes produit par distillation continue de l''alcool obtenu par fermentation de mélasse ou de jus de canne à sucre. Avant d''être mélangé, il est conservé dans des fûts de chêne brûlés, de bourbon ou de xérès, pendant 2 à 7 ans, selon la méthode de vieillissement choisie, et non filtré pour préserver la couleur.'),
  (365, 'fr', 'Rhum overproof', 'Spiritueux des Caraïbes produit par distillation continue de l''alcool obtenu par fermentation de mélasse ou de jus de canne à sucre. Avant d''être mélangé, il est conservé dans des fûts de chêne brûlés, de bourbon ou de xérès, pendant au moins 1 ans. Non dilué avec de l''eau pour préserver un degré d''alcool élevé.'),
  (190, 'fr', 'Pamplemousse', 'Cet agrume populaire pousse en grappes, principalement en Chine, aux États-Unis et au Mexique. Il contient de la vitamine C, de la pectine et du lycopène, qui aide à baisser le taux de cholestérol. Un fruit pèse 600 g en moyenne, peut être coupé en 10 tranches ou segments et produit environ 200 ml de jus.'),
  (186, 'fr', 'Verre tiki', 'Les verres tiki sont des récipients en céramique pour boire des cocktails à thème tiki.'),
  (662, 'fr', 'Whisky irlandais', 'Spiritueux d''origine irlandaise, fabriqué à partir d''orge malté, qui est séché au four, broyé et recouvert d''eau chaude. Après être séparé du grain, le liquide obtenu est fermenté, distillé trois fois et mis à vieillir en fûts de chêne, de xérès, de bourbon ou de porto pendant au moins 3 ans.'),
  (128, 'fr', 'Crème fraîche', 'Crème épaisse fabriquée en séparant la crème du lait, principalement de vache. Le pourcentage de matières grasses varie selon les pays, entre 20 et 40 %. À conserver dans le réfrigérateur pendant 20 jours au plus.'),
  (74, 'fr', 'Bol', 'Récipient en verre ou en métal pour battre des ingrédients avec un fouet. Tout mélange avec du jus de tomate ou des agrumes devrait être effectué uniquement dans un bol en verre ou en acier inoxydable afin d''éviter une réaction avec les acides.'),
  (90, 'fr', 'Verre à Irish coffee', 'Verre épais pour servir du grog, du vin chaud et des cocktails avec du café - il est nommé en l''honneur d''un tel cocktail au café. Contenance standard : 20 à 30 cl.'),
  (78, 'fr', 'Fouet', 'Indispensable pour fouetter la crème pour un Irish coffee ou pour battre des blancs d’œufs avec du sucre pour un Tom et Jerry. Pour mélanger ou battre des ingrédients dans un bocal, une version spéciale est utilisée, avec un manche plus long et un embout plus petit.'),
  (761, 'fr', 'Machine à café', 'Appareil automatique pour la fabrication de divers types de cafés: expresso, latte, americano, latte macchiato, cappuccino, café glacé.'),
  (39, 'fr', 'Cachaça', 'Spiritueux brésilien produit par filtration minutieuse et distillation du jus de canne fermenté. Suivant une certaine technique, la « tête » et la « queue » sont jetées, ne laissant que le «cœur» de la boisson qui est ensuite mise à vieillir en fûts de chêne pendant au moins 1 an.'),
  (5, 'fr', 'Citron vert', 'Agrume tropical cultivé toute l''année dans les climats tropicaux, principalement en Chine, en Inde et au Mexique. Le citron vert est une excellente source de cellulose, de vitamine C et de calcium, et est parfait pour accentuer les saveurs des aliments et des boissons. Un fruit pèse 80 g en moyenne et produit 30 ml de jus, peut être coupé en 4 segments contenant chacun 7,5 ml de jus.'),
  (43, 'fr', 'Sirop de framboise', 'Sirop de baies populaire produit par pasteurisation du jus de framboise mélangé avec du sucre et de l''eau.'),
  (661, 'fr', 'Vodka aux agrumes', 'Spiritueux fort aromatisé produit par distillations multiples de grains, soumis à plusieurs étapes de filtration utilisant le charbon et d''autres méthodes, puis mélangé avec de l''eau pure. La boisson obtenue est infusée avec des extraits d''agrumes et de citron vert.'),
  (481, 'fr', 'Jus de canneberge', 'Pour préparer le jus, les canneberges sont pressées, le jus est ensuite filtré et mis en bouteille.'),
  (53, 'fr', 'Chalumeau culinaire', 'Accessoire pour flamber l''huile d''agrumes sur le célèbre Cosmopolitan, pour saupoudrer de la cannelle au-dessus de la flamme sur les cocktails tiki ou tout simplement pour allumer les cigares des clients.'),
  (82, 'fr', 'Porto Tawny', 'Porto rouge oxydatif produit à partir d''un mélange de vins rouges millésimés avec ajout de cognac, suivi d''un vieillissement en fûts de chêne en utilisant la méthode Solera.'),
  (49, 'fr', 'Jaune d’œuf de caille', 'Cet ingrédient donne aux cocktails une texture délicate. Un jaune d''œuf de poule est équivalent à 5 jaune d''œufs de caille.'),
  (178, 'fr', 'Ciseaux à oeufs de caille', 'Ciseaux spéciaux avec un anneau pour maintenir et couper l''œuf nettement.'),
  (569, 'fr', 'Céleri', '« La prétention à la gloire » de la plante est due aux anciens Grecs, elle pousse principalement dans les climats tempérés. Avant de servir le céleri, les fibres doivent être enlevées en faisant une petite incision sur la tige et en tirant sur le « fil ». Une tige pèse 15 g en moyenne.'),
  (42, 'fr', 'Tabasco', 'Sauce rouge pimentée fabriquée à partir de piments mûrs sélectionnés, vieillis pendant trois ans en fûts de chêne blanc avec du sel de l''île Petite Anse. La purée ainsi obtenue est ensuite aromatisée avec du vinaigre et mise à vieillir quatre semaines supplémentaires. La sauce est plus épicée que la version verte.'),
  (56, 'fr', 'Poivre noir moulu', 'Condiment indien moulu créé à partir de baies presque mûres de poivre, séchées au soleil jusqu''à ce qu''elles deviennent noires. Contrairement au poivre en grains, le parfum se dissipe beaucoup plus rapidement.'),
  (58, 'fr', 'Verre Highball', 'Grand verre pour l''eau, le jus ou les long drinks. La boisson est préparée directement dans le verre. Contenance standard : 30 à 40 cl.'),
  (37, 'fr', 'Whisky écossais', 'Spiritueux écossais, fabriqué à partir de malt d''orge, séché au feu tourbe, qui est ensuite broyé et recouvert d''eau chaude. Le liquide est alors fermenté, distillé trois fois, et l''alcool obtenu est mélangé et mis à vieillir en fûts de chêne, de xérès, de bourbon ou de porto pendant au moins 3 ans.'),
  (46, 'fr', 'Liqueur de cerise', 'Célèbre liqueur de petits fruits obtenue par macération de cerises dans différentes variétés de spiritueux neutres avec de l''eau pendant au moins un mois. Le résultat est filtré, sucré, son degré d''alcool est augmenté avec du cognac et il est mis à vieillir en fûts de chêne pendant au moins 3 ans.'),
  (89, 'fr', 'Rhum ambré', 'Spiritueux des Caraïbes produit par distillation continue de l''alcool obtenu par fermentation de mélasse ou de jus de canne à sucre. Avant d''être mélangé, il est conservé dans des fûts de chêne brûlés, de bourbon ou de xérès, pendant 1 à 5 ans, selon la méthode de vieillissement choisie. Non filtré et auquel du colorant caramel est parfois ajouté.'),
  (94, 'fr', 'Cola', 'Boisson très carbonatée la plus populaire produite selon une formule secrète à base de caféine, de sucre, d''arômes et de colorants.'),
  (60, 'fr', 'Liqueur de chocolat blanc', 'Liqueur de chocolat incolore produite par la percolation de fèves de cacao dans un alcool neutre. Le résultat est filtré, en supprimant la couleur foncée, ajusté pour obtenir le degré d''alcool souhaité et mélangé avec du sucre jusqu''à une consistance crémeuse.'),
  (61, 'fr', 'Liqueur de menthe verte', 'Liqueur onctueuse à base de plantes, avec une teneur élevée en sucre, produite par la percolation de l''extrait de menthe poivrée fraîche dans un alcool neutre avec des distillats de citron vert. Le spiritueux obtenu est ajusté et mélangé pour obtenir la douceur et le degré d''alcool souhaités et mis en bouteille.'),
  (93, 'fr', 'Tequila blanco', 'Spiritueux d''origine mexicaine, traditionnellement produit par la distillation du jus d''agave bleu. Sept à dix cœurs d''agaves, cueillis en été, sont placés dans des fours spéciaux pour convertir l''amidon en sucre, le jus obtenu est fermenté, distillé deux fois et mis en bouteille immédiatement après filtration.'),
  (212, 'fr', 'Bière de gingembre', 'Le "Cheval de Troie" de la vodka en Amérique. Ce type particulier de limonade épicée est produite par macération de poudre de gingembre séché dans la levure de bière.'),
  (99, 'fr', 'Sirop d''amande', 'Sirop d''amande'),
  (127, 'fr', 'Sel', 'Assaisonnement cristallisé à base de minéraux, dont l''âge peut atteindre jusqu''à 250 millions d''années ou plus.'),
  (84, 'fr', 'Verre à margarita', 'À l''origine, c''était un saucière pour guacamole mais maintenant c''est le verre principal pour servir le plus célèbre cocktail à base de tequila dans le monde. Contenance standard : 25 à 35 cl.'),
  (85, 'fr', 'Orange bitters', 'Un des amers d''agrumes les plus anciens, produit par infusion de rhum avec des écorces séchées d''oranges, des épices et des racines de plantes avec ajout de sucre de canne et d''eau distillée juste avant la mise en bouteille.'),
  (75, 'fr', 'Sirop de fruit de la passion', 'Sirop de fruits tropicaux produit par pasteurisation du jus de pulpe de fruits de la passion mélangé avec du sucre de canne et de l''eau.'),
  (7, 'fr', 'Jus d''ananas', 'Pour préparer le jus, la pulpe des ananas est pressée, le jus est ensuite filtré et mis en bouteille.'),
  (76, 'fr', 'Verre Hurricane', 'Verre à l''ancienne, ressemblant à une lampe à pétrole, pour servir des boissons tropicales, nommé en l''honneur du cocktail du même nom de Pat O''Brien. Contenance standard : 30 à 40 cl.'),
  (4, 'fr', 'Orange', 'Cet agrume orange pousse sur des grands arbres cultivés principalement au Brésil, au États-Unis et en Chine. Il contient de la vitamine C, du potassium et du calcium. L''orange est bien connue pour avoir des effet positifs sur le cœur, les vaisseaux sanguins et le corps dans son ensemble. Un fruit pèse 300 g en moyenne et produit 80 ml de jus. Peut être coupé en 10 tranches ou séparé en 8 segments.'),
  (375, 'fr', 'Verre Collins', 'Grand verre idéal pour les long drinks et les boissons mélangées. Tire son nom du cocktail classique « Tom Collins ». Contenance standard : 30 à 40 cl.'),
  (104, 'fr', 'Bénédictine', 'La célèbre liqueur de Normandie, avec le sigle D.O.M. - Deo Optimo Maximo (« À Dieu, le meilleur, le plus grand »), est composée de 27 plantes et épices secrètes et est fabriquée en quatre étapes Après macération et distillation, les différents spiritueux obtenus sont conservés séparément, puis. mélangés pendant 11 mois en fûts de chêne. Ce liquide est ensuite mélangé avec de l''eau, de l''eau-de-vie, du miel et du caramel pour une dernière étape de vieillissement de 3 mois.'),
  (95, 'fr', 'Ananas', 'Ce fruit tropical pousse sur des plantes basses épineuses cultivées principalement au Brésil, en Thaïlande et aux Philippines. Il contient du manganèse et la vitamine C, bien connue pour stimuler la digestion et réduire la viscosité du sang. Un fruit pèse 1 200 g en moyenne et peut être découpé en plus ou moins 40 tranches.'),
  (105, 'fr', 'Sling', 'Le verre essentiel pour servir le cocktail du même nom qui est devenu la carte de visite de l''Hôtel Raffles. Contenance standard : 20 à 30 cl.'),
  (79, 'fr', 'Eau plate', 'La plus importante source de santé et de longévité. Les barmans du monde entier recommandent toujours de boire de l''eau tout en consommant un cocktail, alors dans les meilleurs établissements, un verre d''eau pure est généralement inclus.'),
  (150, 'fr', 'Morceaux de sucre', 'Assaisonnement européen sucré obtenu par purification, raffinage et cristallisation du sirop de canne à sucre ou du jus de betterave à sucre. Les cristaux de sucre sont ensuite moulés sous la forme voulue.'),
  (100, 'fr', 'Drambuie', 'Liqueur écossaise, dont le nom traduit du gaélique signifie « satisfaisant », produite depuis 1910 en utilisant une recette secrète. Il est connu que cette boisson est un mélange de single malts d''origines bien connues, de miel de bruyère, de plantes et d''épices.'),
  (677, 'fr', 'Eau de fleur d''oranger', 'Eau infusée avec des fleurs fraîches d''oranges amères selon une ancienne recette.'),
  (118, 'fr', 'Feuilles d''ananas', 'Feuilles de fruits tropicaux utilisées comme décoration pour les cocktails tiki exotiques.'),
  (98, 'fr', 'Pisco', 'Cette eau de vie de raisin péruvienne est produite avec jusqu''à huit variétés de raisin, tandis qu''au Chili pas plus de trois sont utilisées. Le jus fermenté est distillé dans des cuves en acier inoxydable et mis en bouteille immédiatement ou mis à vieillir en fûts de chêne pendant 2 ans.'),
  (103, 'fr', 'Morceaux de sucre de canne', 'Assaisonnement sucré tropical produit par cristallisation du jus de canne à sucre, qui est moulé en forme de petit cube. Plus la teneur en mélasse est élevée, plus la couleur est sombre et plus la saveur est riche.'),
  (132, 'fr', 'Bourbon vieux', 'Bourbon vieux'),
  (102, 'fr', 'Sucre extra fin', 'Assaisonnement en poudre sucré obtenu à partir de sucre semoule. En raison de la taille des grains, le sucre extra fin se dissout instantanément dans tout liquide et permet ainsi de gagner beaucoup de temps.'),
  (158, 'fr', 'Tasse en cuivre', 'Un must, devenu le « cheval de Troie » de la vodka en Amérique et ustensile de choix pour servir le cocktail « Mule à la moscovite ». Contenance standard : 30 à 40 cl.'),
  (214, 'fr', 'Mûre', 'Ces baies moyennes violet foncé poussent sur des arbustes dans toute l''Europe, dans le Nord-Ouest de l''Afrique, en Asie centrale, en Amérique du Nord et du Sud. Elles contiennent de la carotène, des vitamines C, B1, B2, K, et autres. Une baie pèse 6 g en moyenne.'),
  (115, 'fr', 'Sucre semoule', 'Assaisonnement européen sucré obtenu par purification, raffinage et cristallisation du sirop de canne à sucre ou du jus de betterave à sucre. La taille des cristaux est pertinente, plus ils sont petits, plus le sucre se dissoudra vite.'),
  (107, 'fr', 'Lait', 'Fabriqué à partir de lait de vache entier. La teneur en matières grasses désirée est obtenue en ajoutant de la crème à une version allégée du produit.'),
  (330, 'fr', 'Bâtons de cannelle', 'Assaisonnement de Ceylan, connu depuis le XVe siècle, fait d''écorces du cannelier, qui sont nettoyées, poncées et séchées à l''ombre jusqu''à ce qu''elles se tordent sur elles-mêmes en formant un bâton.'),
  (108, 'fr', 'Tasse', 'Tasse haute en céramique pour le café ou le thé; en 1930 la tasse, ou mug, est devenue l''ustensile de choix pour le cocktail « Tom et Jerry » . Contenance standard : 20 à 25 cl.'),
  (655, 'fr', 'Pichet à lait', 'Pot à lait métallique. Utilisé pour fouetter la crème et lpréparer des cocktails chauds.'),
  (120, 'fr', 'Cannelle en poudre', 'Assaisonnement de Ceylan moulu, connu depuis le XVe siècle, fabriqué à partir de copeaux et de morceaux d''écorces du cannelier, séchés et broyés.'),
  (149, 'fr', 'Anis étoilé', 'Ce fruit tropical en forme d''étoile pousse sur des arbres à feuilles persistantes cultivés principalement en Chine. L''anis étoilé est récolté encore vert et est séché au soleil.'),
  (134, 'fr', 'Sirop d''érable', 'Célèbre sirop de Noël fabriqué à partir de la sève de l''érable à sucre, recolté sur les érables en Février et Mars. Produit par pasteurisation de cette sève avec du sucre de canne et de l''eau.'),
  (123, 'fr', 'Sirop de rose', 'Sirop de fleurs délicat produit par infusion et pasteurisation de pétales de roses dans un sirop de sucre.'),
  (201, 'fr', 'Pétales de rose', 'La fleur la plus vendue dans le monde. Il y a 25 pétales dans une rose.'),
  (1035, 'fr', 'Whisky américain', 'Whisky américain'),
  (288, 'fr', 'Xérès Pedro Ximenez', 'Le plus doux des vins espagnols âgés fabriqué à partir du cépage du même nom. Le jus de raisin fermenté est fortifié avec de l''alcool de raisin et mis à vieillir en fûts de chêne en utilisant la méthode solera, pendant 10 à 30 ans, ou plus.'),
  (154, 'fr', 'Petite cuillère', 'Cuillère pour touiller le thé dans une tasse. Une cuillerée peut contenir environ 5 g d''ingrédients solides ou 5 ml de liquide.'),
  (211, 'fr', 'Cubes de glace', 'Sans forme précise ou coupé en cube, un gros cube de glace fond plus lentement et a l''air plus impressionnant dans un verre.'),
  (450, 'fr', 'Sirop de gingembre', 'Sirop asiatique épicé produit par pasteurisation d''extraits de gingembre dans du sirop de sucre.'),
  (693, 'fr', 'Bombilla pour maté', 'Paille spéciale pour boire le maté. L''extrémité supérieure comprend un embout buccal alors que la partie inférieure contient un filtre.'),
  (552, 'fr', 'Groseille', 'Ces petites baies rouges poussent sur des arbustes à feuilles caduques cultivés principalement en Europe centrale, au Nord de l''Europe, et en Asie du Nord. Elles contiennent de grandes quantités de vitamine C, ainsi que divers sucres, des acides organiques et minéraux. Une cuillère à mesure contient 5 g de groseilles.'),
  (332, 'fr', 'Xérès oloroso', 'Vin fortifié espagnol demi-sec ou doux produit par fermentation de raisins Palomino sans formation du voile de levure appelé ''''flor''''. Le spiritueux obtenu est fortifié par étapes avec de l''alcool de raisin et mis à vieillir en fûts de chêne en solera pendant au moins deux ans.'),
  (191, 'fr', 'Abricots secs', 'Ce fruit sec coloré est produit principalement en Turquie, en Iran et en Ouzbékistan à partir d''abricots mûrs. Les fruits sont d''abord bouillis ou trempés dans un sirop, puis séchés au soleil ou dans un séchoir spécial. Un abricot sec pèse 10 g en moyenne.'),
  (683, 'fr', 'Plateau', 'Plateau en métal ou en bois pour servir les aliments ou les boissons aux clients.'),
  (121, 'fr', 'Sirop de vanille', 'Sirop parfumé malgache produit par infusion et pasteurisation de gousses de vanille dans du sirop.'),
  (381, 'fr', 'Tequila gold', 'Spiritueux vieilli d''origine mexicaine, traditionnellement produit par la distillation du jus d''agave bleu. Sept à dix cœurs d''agaves, cueillis en été, sont placés dans des fours spéciaux pour convertir l''amidon en sucre, le jus obtenu est fermenté, distillé deux fois et coloré avec du caramel. Aromatisé avec divers additifs aromatiques.'),
  (318, 'fr', 'Vermouth blanc', 'Le vermouth le plus sucré, obtenu par macération de plantes alpines et d''épices dans un vin blanc. Le résultat est filtré, ajusté pour obtenir le degré d''alcool désiré et la douceur maximale, puis mis à vieillir en fûts de chêne pendant au moins un an.'),
  (126, 'fr', 'Purée de fraises', 'Purée de fraises'),
  (327, 'fr', 'Cassonade', 'Assaisonnement sucré tropical produit par cristallisation de la canne à sucre après transformation mécanique. Plus la teneur en mélasse est élevée, plus la couleur est sombre et plus la saveur est riche.'),
  (138, 'fr', 'Mixeur', 'Inventé en 1922 par Stephen Poplawski, cet appareil électrique est indispensable pour faire des cocktails tiki, des smoothies et des boissons glacées.'),
  (196, 'fr', 'Sirop de noix de coco', 'Sirop tropical le plus populaire produit par pasteurisation d''eau de noix de coco avec du sucre de canne.'),
  (197, 'fr', 'Vide-ananas', 'Accessoire tiki qui, en quelques secondes, permet d''enlever la peau et le centre dur d''un ananas.'),
  (744, 'fr', 'Pelle à glace', 'Outil pratique en polycarbonate ou en acier inoxydable qui permet de prendre une quantité spécifique de glace. Les pelles diffèrent en taille et en volume ce qui permet de sélectionner l''outil idéal pour la quantité de glace requise.'),
  (406, 'fr', 'Liqueur de banane jaune', 'Liqueur tropicale crémeuse obtenue par macération de la pulpe de bananes jaunes dans un alcool neutre avec de l''eau. Le résultat est filtré, mélangé avec du sucre et enrichi avec un jeune cognac.'),
  (200, 'fr', 'Banane', 'La plus ancienne plante tropicale cultivée principalement en Chine, en Inde et en Ouganda. Le fruit contient de la vitamine B6, du manganèse et des fibres alimentaires. Un fruit pèse 200 g en moyenne et la peau pèse 80 g.'),
  (244, 'fr', 'Genièvre', 'Spiritueux néerlandais, l’ancêtre du gin, fabriqué à partir du XVe siècle par distillation d''alcool pur avec ajout de baies de genièvre et d''autres épices.'),
  (133, 'fr', 'Sirop de miel', 'Sirop le plus populaire produit par pasteurisation de miel dilué, jusqu''à consistance désirée, avec de l''eau.'),
  (293, 'fr', 'Théière', 'L''histoire de cet ancien récipient chinois remonte, avec le thé, au XIVe siècle en Chine. La théière est utilisée pour faire infuser le thé, les plantes et les épices dans de l''eau bouillante ou du jus.'),
  (287, 'fr', 'Single malt whisky d''Islay', 'Single malt whisky d''Islay'),
  (284, 'fr', 'Liqueur de rhubarbe', 'Liqueur de dessert douce-amère à base de plantes produite par macération de tiges et de feuilles de rhubarbe dans un alcool neutre avec de l''eau. Le liquide obtenu est mélangé avec du sucre et amené au degré d''alcool souhaité.'),
  (358, 'fr', 'Cynar', 'Liqueur italienne à base de plantes obtenue par macération et distillation de 16 plantes et épices, essentiellement l''artichaut, dans un alcool neutre. Le spiritueux obtenu est filtré et ajusté pour obtenir la douceur et le degré d''alcool désirés.'),
  (735, 'fr', 'Zeste de pamplemousse', 'Couche extérieure de la peau de pamplemousse, coupée avec un couteau spécial tranchant. Le zeste contient des huiles essentielles qui portent la saveur de pamplemousse. Il peut être obtenu à partir d''un fruit coupé, un fruit entier, râpé ou même vrillé en spirale (twist).'),
  (704, 'fr', 'Vaporisateur', 'Accessoire attrayant pour la pulvérisation d''amers et d''additifs aromatiques au-dessus d''un cocktail.'),
  (435, 'fr', 'Xérès fino', 'Vin fortifié espagnol sec produit par fermentation de raisins Palomino avec ajout de levure spéciale. Vieilli pendant au moins 12 mois, le vin, fortifié avec de l''alcool de raisin par étapes, développe un voile de levure appelé ''''flor'''',. Mis à vieillir en fût sous voile pendant au moins 2 ans.'),
  (653, 'fr', 'Verre à shooter', 'Petit verre avec, en règle générale, des bords droits. Destiné à être utilisé pour les boissons les plus fortes ou les cocktails qui doivent être bues d''un trait. Contenance standard : 5 à 10 cl.'),
  (546, 'fr', 'Fraise', 'Cette grosse baie rouge pousse sur des petits arbustes cultivés principalement aux États-Unis, en Turquie, en Espagne, en Égypte et au Mexique. Elle contient du sucre, de la pectine, du tanin, de l''acide ascorbique et autres ingrédients anti-inflammatoires. Une fraise pèse 20 g en moyenne.'),
  (402, 'fr', 'Limoncello', 'Liqueur nationale italienne obtenue par macération d''écorces de citron dans un alcool neutre pendant un mois. Le spiritueux obtenu est mélangé avec du sucre et de l''eau, mis de côté pour continuer l''infusion, puis filtré.'),
  (410, 'fr', 'Liqueur de litchi', 'Fabriqué à partir de la pulpe de litchis mûrs, qui est mélangé avec de l''alcool. le tout est mis de côté pour permettre l''infusion.'),
  (486, 'fr', 'Jus de mangue', 'Pour préparer le jus, la pulpe des mangues est pressée, le jus est ensuite filtré et mis en bouteille.'),
  (529, 'fr', 'Fruit de la passion', 'Ce fruit subtropical pousse sur une espèce de vigne de passiflore cultivée principalement en Nouvelle-Zélande, en Israël et au Sri Lanka. il contient de la vitamine A, du bêta-carotène et du potassium, et a un effet tonifiant sur le corps. Un fruit pèse 90 g en moyenne.'),
  (415, 'fr', 'Liqueur de mûre', 'Liqueur de baies intense obtenue par macération de mûres dans un alcool neutre et de l''eau pendant deux mois au plus. Du sucre est ajouté à cette liqueur non filtrée.'),
  (405, 'fr', 'Liqueur de pomme verte', 'Liqueur de fruits frais élaborée par macération de la pulpe de pommes vertes dans un alcool neutre. Le spiritueux obtenu est filtré, mélangé avec du sucre et dilué avec de l''eau pure pour.obtenir le degré d''alcool désiré.'),
  (528, 'fr', 'Pomme', 'Ce fruit populaire, originaire d''Asie centrale, pousse sur des arbres feuillus, cultivés principalement en Chine, aux États-Unis et en Turquie. Il contient de l''acide ascorbique, de la vitamine K, du potassium, et on estime qu''il stimule le système immunitaire et aide à lutter contre l''obésité. Un fruit pèse 200 g en moyenne et peut être découpé en 10 tranches.'),
  (682, 'fr', 'Bocal', 'Bocal avec un couvercle hermétique pour mélanger et conserver des liqueurs et des sirops. Aucune contenance standard disponible.'),
  (446, 'fr', 'Sirop d''agave', 'Sirop mexicain à base de concentré de jus d''agave mélangé avec du sirop de sucre.'),
  (432, 'fr', 'Vin rouge sec', 'Type de vin le plus courant produit par macération et subséquente fermentation de raisins noirs, qui donnent au vin sa couleur. Le vin est ensuite filtré, conservé dans des fûts de chêne pendant au moins 3 mois.'),
  (613, 'fr', 'Clous de girofle', 'Épice indonésienne composée de boutons floraux séchés provenant d''un arbre tropical de la même famille que le piment de la Jamaïque.'),
  (705, 'fr', 'Fontaine à absinthe', 'Accessoire essentiel pour le rituel du service de la boisson forte française. L''eau, des plantes et des fruits sont versés dans la fontaine. Une fois infusé, le liquide coule goutte à goutte au travers d''un sucre posé sur une cuillère et termine sa course dans un verre d''absinthe.'),
  (698, 'fr', 'Cuillère à absinthe', 'Accessoire essentiel pour le rituel du service de la boisson forte française. L''alcool, ainsi que des plantes et des fruits, sont versés dans la fontaine. Une fois infusé, le liquide coule goutte à goutte au travers d''un sucre posé sur une cuillère et termine sa course dans un verre.'),
  (494, 'fr', 'Boisson énergisante', 'Boisson énergisante conçue spécialement pour être utilisée pendant une activité physique ou mentale accrue.'),
  (394, 'fr', 'Liqueur crème de whisky', 'Liqueur irlandaise crémeuse faite à base de whisky irlandais distillé trois fois, avec ajout de crème et d"un alcool neutre. Enrichie avec du cacao, de la vanille, du sucre et du caramel.'),
  (547, 'fr', 'Mirtylle', 'Cette petite baie violette pousse sur des arbustes au Canada, en Amérique du Nord, en Turquie et en Europe occidentale. Elle contient une grande quantité de vitamines A, B, C, du manganèse et du potassium.Bénéfique pour la vue, elle améliore la vision nocturne. Une cuillère à mesure contient 5 g de myrtilles.'),
  (578, 'fr', 'Citronnelle', 'Herbe avec des arômes d''agrumes utilisée à l''origine dans la cuisine des Caraïbes et d''Asie, elle pousse principalement dans les îles britanniques, aux Philippines et en Indonésie.'),
  (490, 'fr', 'Sprite', 'Boisson gazeuse sucrée produite en ajoutant du sucre et des extraits de citron à de l''eau gazeuse.'),
  (666, 'fr', 'Sambuca', 'Liqueur forte d''origine italienne obtenue par aromatisation et coloration d''alcool de blé avec du sucre et des huiles d’anis et d''anis étoilé, des fleurs de sureau et diverses plantes, produisant ainsi son parfum qui fait forte impression.'),
  (414, 'fr', 'Liqueur advocaat', 'Liqueur de Noël néerlandaise tirant ses origines d''une boisson alcoolisée brésilienne faite à partir d''avocats. Cette boisson est faite d''un mélange de jaune d’œuf, de sucre, de vanille et de brandy.'),
  (531, 'fr', 'Grenade', 'Ce fruit méditerranéen pousse sur des arbustes ou petits arbres à feuilles caduques cultivés principalement en Israël et en Inde. Il contient du potassium et du phosphore, et est bien connu pour avoir un effet positif sur le système cardiovasculaire. Un fruit pèse 300 g en moyenne et peut être découpé en 10 tranches.'),
  (684, 'fr', 'Verre à vin rouge', 'Verre classique, légèrement incurvé. Traditionnellement plus haut que verre de vin blanc. Contenance standard : 20 à 30 cl.'),
  (483, 'fr', 'Jus de cerise', 'Pour préparer le jus, les cerises sont pressées, le jus est ensuite filtré et mis en bouteille.'),
  (551, 'fr', 'Cassis', 'Cette petite baie noire pousse sur des buissons en Europe centrale, au Nord de l''Europe, et au Nord de l''Asie. Elle contient de grandes quantités de vitamine C, divers sucres, des acides organiques et minéraux. Une cuillère à mesure contient 5 g de cassis.'),
  (597, 'fr', 'Confiture de framboises', 'Confiture de fruits rouges qui poussent sur des arbustes nains vivaces cultivés principalement en Russie, en Serbie, en Pologne et aux États-Unis. Les fruits mûrs sont bouillis avec du sucre jusqu''à ce que le mélange s''épaississe. Une cuillère à mesure contient 5 g de confiture.'),
  (590, 'fr', 'Confiture de d''oranges', 'Confiture faite avec la pulpe d''agrumes qui poussent sur de grands arbres cultivés principalement au Brésil, aux États-Unis et en Chine. Les fruits mûrs sont bouillis avec du sucre jusqu''à ce que le mélange s''épaississe. Une cuillère à mesure contient 5 g de confiture.'),
  (589, 'fr', 'Miel', 'Nectar des fleurs collecté et transformé par les abeilles.'),
  (652, 'fr', 'Cookie', 'Biscuit sucré cuit au four fait à partir de différents types de pâtes.'),
  (686, 'fr', 'Pichet', 'Ancien récipient de cuisine utilisé pour servir l''eau, la limonade et la sangria. Contenance standard : 50 à 300 cl.'),
  (484, 'fr', 'Jus de grenade', 'Pour préparer le jus, les arilles de grenade sont pressées, le jus est ensuite filtré et mis en bouteille.'),
  (548, 'fr', 'Pastèque', 'Un grand type de baies, cultivé principalement en Chine, en Turquie et en Iran. Il contient du glucose, du fructose, de la pectine, du calcium, du magnésium, de la substance alcaline, et il permet de régler le métabolisme. Une baie pèse 5000 g en moyenne, une tranche pèse 300 g, le ratio entre le poids de la pulpe et le poids de la peau est de 60% - 40%.'),
  (454, 'fr', 'Sirop de citronnelle', 'Sirop rafraîchissant produit par pasteurisation d''extraits de citronnelle avec du sirop de sucre.'),
  (433, 'fr', 'Vin blanc sec', 'Vin estival obtenu par macération et subséquente fermentation de raisins blancs sans peau. Le vin est ensuite filtré, conservé dans des fûts de chêne pendant au moins 3 mois.'),
  (532, 'fr', 'Kiwi', 'Le kiwi ou groseille de Chine est la baie comestible d''une plante grimpante ligneuse qui pousse en Italie, en Nouvelle-Zélande et au Chili. Il contient de la vitamine C, des fibres, de l''acide folique, du calcium et du phosphore, bien connu pour renforcer le système immunitaire. Une baie pèse en moyenne 120 g.'),
  (577, 'fr', 'Basilic rouge', 'Ces plantes aromatiques épicées, poussent principalement dans les régions chaudes de l''Ancien Monde.'),
  (702, 'fr', 'Siphon à chantilly', 'Appareil en verre ou métal épais pour fouetter la crème rapidement avec une consistance délicate et aérée. Il peut également être utilisé pour la fabrication de divers desserts, de sauces et de mousses complexes. Contenance standard : 0,5 à 1 litre.'),
  (399, 'fr', 'Liqueur de pêche', 'Liqueur de fruits produite par distillation de jus de pêche fermenté avec ajout de cognac; pour améliorer la riche saveur les noyaux de pêchs peuvent être ajoutés.'),
  (396, 'fr', 'Liqueur d’abricot', 'Célèbre liqueur de fruits produite par distillation de jus d''abricot fermenté ajoutée à des spiritueux forts pour rehausser l''intense saveur.'),
  (691, 'fr', 'Bol à punch', 'Grand récipient en verre, en cristal ou en métal pour servir le punch qui a été apporté à l''Angleterre depuis l''Inde au début du XVIIe siècle. Conttenance standard : 500 cl.'),
  (395, 'fr', 'Liqueur amaretto', 'Liqueur italienne classique élaborée par macération de noyaux d''abricots, de plantes et de fruits dans de l''alcool neutre. Cette base obtenue est filtrée, mélangée avec du sucre puis diluée avec de l''eau pour obtenir le degré d''alcool désiré.'),
  (556, 'fr', 'Cerise', 'Cette baie jaune ou rouge écarlate pousse sur des arbres cultivés principalement dans les climats chauds et tempérés, comme la Turquie, l''Italie, l''Espagne et le Chili. Elle contient des acides organiques, des minéraux, de la pectine, de l''acide folique, des vitamines A, C, E et B. Une cerise pèse 5 g en moyenne.'),
  (437, 'fr', 'Lager', 'Bière légère faite à partir d''eau, d''orge, d''extrait de malt, de houblon et de levure de bière.'),
  (452, 'fr', 'Sirop de cassis', 'Sirop de cassis produit par transformation de jus cassis mûr mélangé avec du sucre et de l''eau.'),
  (397, 'fr', 'Liqueur de melon', 'Liqueur tropicale asiatique obtenue par macération de la pulpe de melon dans un alcool neutre avec de l''eau. Le résultat est filtré, ajusté pour obtenir la douceur et le degré d''alcool souhaité et mis en bouteille.'),
  (763, 'fr', 'Bitter lemon', 'Boisson gazeuse au citron produite en carbonatant de l''eau contenant des extraits de citron.'),
  (380, 'fr', 'Becherovka', 'Liqueur tchèque canonique obtenue par macération d''un mélange de 20 plantes et épices dans un alcool neutre, le liquide obtenu est ensuite mélangé avec de l''eau et du sucre et est mis à vieillir en fûts de chêne pendant deux à trois semaines.'),
  (502, 'fr', 'Thé Earl Grey', 'Dans sa forme classique, il s''agit d''un thé noir avec ajout d''huile d''écorce de bergamote. La meilleure température pour la préparation de ce thé est de 90 à 95° C et il devrait être laissé à infuser pendant 3 à 5 minutes.'),
  (709, 'fr', 'Parasol à cocktail', 'Décoration colorée en papier pour les cocktails tropicaux ou pour divertir les enfants.'),
  (639, 'fr', 'Pruneau', 'Friandise européenne produite à partir de prunes noires séchées au soleil ou dans un séchoir spécial.'),
  (747, 'fr', 'Tartelette', 'Copie miniature d''une tarte, d''abord mentionnée dans le livre de cuisine du roi Richard II en 1390. Plat cuit au four composé d''une garniture sur une base de pâte, et non couvert avec de la pâte.'),
  (453, 'fr', 'Sirop de pomme jaune', 'Sirop fruité jaune produit par pasteurisation de jus de pommes jaunes avec ajout de sucre de canne.'),
  (576, 'fr', 'Romarin', 'Plantes méditerranéennes avec un parfum épicé de pin.'),
  (409, 'fr', 'Liqueur de pamplemousse', 'Liqueur d''agrumes obtenue par macération d''écorces de pamplemousses roses dans un alcool neutre. Le spiritueux obtenu est filtré, mélangé avec du sucre et dilué avec de l''eau pure pour.obtenir le degré d''alcool désiré.'),
  (549, 'fr', 'Canneberge', 'Cette petite baie rouge pousse sur des arbustes nains ou des vignes rampantes cultivées principalement aux États-Unis, au Chili, en Argentine et aux Pays-Bas. Elle contient des acides organiques, des minéraux, de la pectine, de l''acide folique et les vitamines A, C, E et B. Une cuillère à mesure contient 5 g de canneberges.'),
  (492, 'fr', 'Eau tonique', 'Boisson gazeuse qui a été inventée en Inde pour combattre le paludisme. Fabriquée à partir d''eau gazeuse mélangée avec de la quinine et une petite quantité de sucre.'),
  (562, 'fr', 'Raisin rouge', 'Ces baies rouges de taille moyenne poussent sur les vignes cultivées en Chine, aux États-Unis, en Italie, en France et en Espagne. Elles contiennent du sucre, de la cellulose, des acides organiques, de la vitamine B et d''autres oligo-éléments, et aident à fortifier et à tonifier. Un grain de raisin pèse 5 g en moyenne.'),
  (663, 'fr', 'Vodka à l''orange', 'Spiritueux fort aromatisé produit par distillations multiples de grains, soumis à plusieurs étapes de filtration utilisant le charbon et d''autres méthodes, puis mélangé avec de l''eau pure. La boisson obtenue est infusée avec des extraits d''orange mûre.'),
  (530, 'fr', 'Mandarine', 'Cet agrume de couleur orange pousse sur des arbustes à feuilles persistantes cultivés principalement en Chine, en Espagne et au Brésil. Il contient de la vitamine C et du potassium, bien connu pour renforcer le système immunitaire. Un fruit pèse environ 100 g et produit 40 ml de jus.'),
  (710, 'fr', 'Lillet Blanc', 'Vin apéritif français produit à partir d''un mélange de vins blancs de la région bordelaise et de liqueurs de fruits. Alors que le vin vieillit, des zestes d''oranges sucrées et amères et de la quinine verte sont infusés dans de l''eau-de-vie. Ensuite, tout est mélangé et conservé dans des fûts de chêne pendant 8 à 12 mois.'),
  (389, 'fr', 'Rhum épicé', 'Spiritueux des Caraïbes produit par distillation continue de l''alcool obtenu par fermentation de mélasse ou de jus de canne à sucre. Avant d''être mélangé, il est conservé dans des fûts de chêne brûlés, de bourbon ou de xérès, pendant 2 à 7 ans, selon la méthode de vieillissement choisie. On y ajoute ensuite d''autres épices tels que la cannelle, la muscade et la vanille.'),
  (398, 'fr', 'Liqueur curaçao bleu', 'Liqueur d''orange de couleur bleu brillant obtenue par macération d''écorces d''oranges séchées dans un alcool neutre avec de l''eau. Le résultat est filtré, mélangé avec du sucre et coloré avec des colorants naturels.'),
  (550, 'fr', 'Raisin vert', 'Ces baies vertes de taille moyenne poussent sur les vignes cultivées en Chine, aux États-Unis, en Italie, en France et en Espagne. Elles contiennent du sucre, de la cellulose, des acides organiques, de la vitamine B et d''autres oligo-éléments, et aident à fortifier et à tonifier. Un grain de raisin pèse 5 g en moyenne.'),
  (533, 'fr', 'Mangue', 'Ce fruit tropical sauvage pousse principalement en Inde, au Pakistan et aux Philippines. Il contient de la vitamine A, de l''acide folique et du potassium, il aide à l''amélioration du système immunitaire et de la vue. Un fruit pèse 300 g en moyenne et peut être découpé en 10 tranches.'),
  (408, 'fr', 'Liqueur de cannelle', 'Liqueur allemande aux épices élaborée par macération de cannelle dans du schnaps. Le résultat est filtré, mélangé avec du sucre, et des feuilles d''or sont ajoutées pour donner du punch.'),
  (495, 'fr', 'Thé vert glacé', 'Populaire en Asie, le thé glacé est produit à base d''extraits de thé vert et d''autres plantes sans ajout de arômes artificiels et d''agents de conservation.'),
  (711, 'fr', 'Passoire Julep', 'Accessoire indispensable pour les préparations avec un verre à mélange. Sert également de décoration sans égale pour le cocktail classique du même nom. La passoire Julep est utilisée pour filtrer les morceaux de glace et autres ingrédients indésirables.'),
  (670, 'fr', 'Expresso', 'Café très fort préparé en versant une petite quantité d''eau bouillante à une température de 90 ° C à travers du café moulu.'),
  (690, 'fr', 'Verre à thé', 'Verre traditionnel des buveurs de thé turcs. Contenance standard : 4 à 8 cl.'),
  (412, 'fr', 'Liqueur de fruit de la passion', 'Fabriquée à partir de pulpe de fruits de la passion mûrs, d''oranges et de pamplemousses, qui sont mélangés avec de l''alcool et mis de côté pour permettre l''infusion.'),
  (615, 'fr', 'Sucre vanillé', 'Sucre semoule parfumé à la vanille.'),
  (181, 'fr', 'Cafetière à piston', 'Accessoire français, pour infuser le café et le thé, constitué d''un récipient en verre d''un filtre et d''un piston.'),
  (448, 'fr', 'Sirop de fraise', 'Sirop de baies produit par pasteurisation de jus de fraise mûre mélangé avec du sucre et l''eau.'),
  (567, 'fr', 'Piment', 'Ces poivrons tropicaux épicés poussent sur des arbustes cultivés principalement en Amérique du Sud. Ils contiennent des vitamines A et C ainsi que du potassium, du magnésium et du fer. Un piment pèse 30 g en moyenne.'),
  (499, 'fr', 'Thé noir', 'Type de thé qui a subi une fermentation pendant une période de deux semaines à un mois. Pousse dans les régions à climat tropical ou subtropical. Pour la préparation, verser 10 cl d''eau bouillante sur 1 cuillerée de thé et laisser reposer pendant 4 à 5 minutes.'),
  (411, 'fr', 'Liqueur de mangue', 'Liqueur tropicale asiatique obtenue par macération de la pulpe de mangues mûres dans un alcool neutre avec de l''eau. L''alcool obtenu est filtré et mélangé avec du sucre.'),
  (514, 'fr', 'Crème glacée à la vanille', 'Dessert glacé préparé à partir de lait, de crème, de beurre et de sucre avec ajout d''extraits de vanille. À conserver dans le congélateur pendant un mois au plus.'),
  (592, 'fr', 'Confiture de cerises', 'Confiture de fruits jaunes ou rouges poussant principalement dans les climats tempérés chauds, comme la Turquie, l''Italie, l''Espagne et le Chili. Les fruits mûrs dénoyautés sont bouillis avec du sucre jusqu''à ce que le mélange s''épaississe. Une cuillère à mesure contient 5 g de confiture.'),
  (485, 'fr', 'Jus de pêche', 'Pour préparer le jus, les pêches sont pressées, le jus est ensuite filtré et mis en bouteille.'),
  (387, 'fr', 'Vodka au cassis', 'Spiritueux fort aromatisé produit par distillations multiples de grains, soumis à plusieurs étapes de filtration utilisant le charbon et d''autres méthodes, puis mélangé avec de l''eau pure. La boisson obtenue est infusée avec des extraits de cassis mûr.'),
  (633, 'fr', 'Eau de rose', 'Eau parfumée infusée avec des pétales de roses selon une ancienne recette.'),
  (713, 'fr', 'Purée de framboises', 'Purée de framboises'),
  (586, 'fr', 'Thym', 'Cette plante aromatique pousse sur des d''arbustes nains cultivés principalement en Eurasie, en Afrique du Nord et au Groenland. Le thym est utilisé dans les mélanges de Provence, et est idéal pour aromatiser les spiritueux forts.'),
  (407, 'fr', 'Liqueur de noix de coco', 'Liqueur tropicale Tiki obtenue par macération de la pulpe de noix de coco dans du rhum. Le spiritueux obtenu est filtré, mélangé avec du sucre et dilué avec de l''eau pour obtenir le degré d''alcool désiré.'),
  (430, 'fr', 'Vermouth rosé', 'Cette relativement nouvelle catégorie de vermouth est produite par macération de plantes alpines et d''épices dans un vin rosé. Le résultat est filtré, ajusté pour obtenir le degré d''alcool et la douceur désirés, puis mis à vieillir en fûts de chêne pendant au moins un an.'),
  (646, 'fr', 'Chocolat noir', 'Confiserie faite à partir de fèves de cacao noir avec peu ou pas de sucre ajouté.'),
  (447, 'fr', 'Sirop de caramel', 'Célèbre sirop de caramel produit par transformation de caramel liquide avec ajout de vanille et d''eau.'),
  (750, 'fr', 'Serviettes', 'En coton ou en papier. Les serviettes sont parfois utilisées comme sous-verres pour les boissons.'),
  (360, 'fr', 'Siphon à soda', 'Appareil fait de verre épais ou de métal pour les boissons gazeuse. Contenance standard : 1 à 2 litres.'),
  (500, 'fr', 'Grains de café', 'Grains torréfiés du caféier, qui, en raison de leur teneur en caféine, sont bien connus pour leur effet stimulant sur le corps humain. Il existe deux variétés principales de caféier - Arabica et Robusta.'),
  (565, 'fr', 'Saké', 'Spiritueux japonais à base de riz qui est trempé et cuit à la vapeur. Ainsi préparé, il est enrichi avec des champignons de fermentation et gardé dans une pièce chaude et humide pendant environ 2 jours. Après fermentation, le saké est conservé dans des récipients scellés pendant 6 à 12 mois.'),
  (537, 'fr', 'Kumquat', 'Ce petit agrume pousse sur des petits arbres fruitiers cultivés principalement en Chine, en Corée et au Japon. Il contient de la vitamine C, du fer et du magnésium, et aide à combattre les infections. Un fruit pèse 10 g moyenne.'),
  (685, 'fr', 'Verre à cognac', 'Verre classique pour déguster le cognac ou le brandy. Contenance standard : 17 à 40 cl.'),
  (423, 'fr', 'Southern Comfort', 'Liqueur de fruits de la Nouvelle-Orléans inventée par le barman Martin Heron en 1874, produite, suivant une ancienne recette, à base de whisky américain avec ajout de fruits, d''essences de plantes, de sucre et de caramel et mise à vieillir en fûts de chêne jusqu''à la maturité souhaitée.'),
  (703, 'fr', 'Poêle à frire', 'Ancien ustensile de cuisson nécessaire dans un bar pour flamber des baies et des fruits.'),
  (688, 'fr', 'Plateau de dégustation', 'Un plateau de dégustation consiste en un plateau en verre rempli de glace pour que les shooters de dégustation restent frais.'),
  (462, 'fr', 'Sirop de litchi', 'Sirop de fruits asiatique produit par pasteurisation du jus de litchi mélangé avec du sirop de sucre et de l''eau.'),
  (504, 'fr', 'Tisane de camomille', 'Une infusion faite à partir des fleurs séchées de camomille. En général, l''eau bouillante est versée sur les fleurs selon une proportion de 1 à 2 cuillères à café pour 20 cl d''eau; laisser infuser pendant 7 à 10 minutes, filtrer et boire nature ou avec du sucre ou du miel.'),
  (673, 'fr', 'Confiture de baies d''argousier', 'Confiture de petites baies jaunes qui poussent sur des arbustes épineux à feuilles caduques cultivés principalement sur la côte atlantique de l''Europe et au Nord-Ouest de la Chine. Les fruits mûrs sont bouillis avec du sucre jusqu''à ce que le mélange s''épaississe. Une cuillère à mesure contient 5 g de confiture.'),
  (769, 'fr', 'Soucoupe', 'Petite assiette en verre, en porcelaine ou en métal qui est typiquement servie avec une tasse. L''interprétation moderne d''un verre à cocktail sur une soucoupe est que cela projette l''image d''un service plus raffiné et plus élégant.'),
  (463, 'fr', 'Sirop de mangue', 'Sirop de fruits asiatique produit par pasteurisation du jus de mangue mélangé avec du sucre de canne et de l''eau.'),
  (700, 'fr', 'Porte-verre à thé', 'Porte-verre en métal avec une poignée qui permet de tenir le verre et de boire une boisson chaude sans se brûler les mains.'),
  (695, 'fr', 'Fourchette', 'Couvert de table composé d''un manche et de plusieurs dents (généralement entre deux et quatre) sur une extrémité. La fourchette est utilisée pour la préparation des aliments ainsi que pour manger et saisir ou déplacer les éléments d''un repas.'),
  (445, 'it', 'Sciroppo di cannella', 'Famoso sciroppo speziato, ottenuto dalla pastorizzazione e infusione dello sciroppo di zucchero con la cannella.'),
  (176, 'it', 'Succo di lime', 'Per preparare il succo, i lime sono schiacciati da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (482, 'it', 'Succo di mela', 'Per preparare il succo, le mele sono schiacciate da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (767, 'it', 'Albume d''uovo di quaglia', 'Per conferire a questo ingrediente per cocktail una consistenza leggera e schiumosa, raccomandiamo di usare il metodo di preparazione "Dry shake". Un albume d''uovo di gallina equivale a 5 albumi di uova di quaglia.'),
  (217, 'it', 'Cetriolo', 'Il cetriolo è una pianta rampicante dalla quale nascono frutti cilindrici utilizzati in cucina come ortaggi. Il cetriolo cresce soprattutto nei paesi mediterranei. Normalizza il metabolismo, migliora le funzioni cardiache e renali. Un cetriolo pesa in media 150 g; può essere tagliato in 10 fette o strisce.'),
  (31, 'it', 'Cubetti di ghiaccio', 'Per produrre questo ingrediente indispensabile, si deve prestare attenzione alla purezza dell''acqua e alla velocità di congelamento. Più lentamente si congela l''acqua, più sarà chiaro il prodotto finale. Un prodotto ideale, non presenta impurità e si scioglie lentamente nel bicchiere.'),
  (210, 'it', 'Coppa da Champagne', 'Coppa ampia, allargata e poco profonda; la leggenda racconta che sia stata realizzata sul profilo del seno di una delle amanti di un re francese. Utilizzata per servire champagne e cocktail tini; capacità standard: 20-30 сl.'),
  (68, 'it', 'Shaker', 'L''aspetto attuale risale al XIX secolo. Dopo aver sperimentato una dozzina di stili e forme diverse, questo strumento raggiunse una particolare popolarità negli anni venti e trenta del secolo scorso. Gli shaker si dividono in cobbler shaker, con passino integrato, French shaker senza passino e Boston shaker, composto da due coppe di uguale grandezza. Volume standard: 50-70 cl.'),
  (69, 'it', 'Passino da bar', 'Accessorio indispensabile quando si lavora con gli shaker Boston o French; è utilizzato per filtrare i cocktail trattenendo semi di frutta, pezzetti di ghiaccio e altri ingredienti indesiderati.'),
  (73, 'it', 'Misurino da bar', 'Assicura porzioni accurate e ideali nei cocktail. I migliori baristi hanno nel loro ‘arsenale’ misurini che vanno dai 2-4 cl ai 2.5-5 cl e 3-6 cl.'),
  (70, 'it', 'Spremiagrumi', 'Strumento indispensabile per spremere lime e limoni; nonostante oggi si utilizzi del succo preparato in precedenza, il succo appena spremuto è considerato di qualità superiore.'),
  (239, 'it', 'Centrifuga', 'Estrae il succo da qualsiasi tipo di frutta o verdura. Diversamente da una pressa manuale, questo piccolo elettrodomestico separa il succo dalla polpa utilizzando un filtro.'),
  (1, 'it', 'Vodka', 'Vodka'),
  (55, 'it', 'Liquore al caffè', 'Famoso liquore stimolante, ottenuto da diverse varietà di chicchi di caffè mediante percolazione con un distillato neutro. Il percolato non viene filtrato, è mescolato con zucchero caramellato e diluito con acqua fino al raggiungimento della gradazione desiderata.'),
  (65, 'it', 'Bicchiere rock', 'Bicchiere grande con fondo doppio, per servire distillati o cocktail in forma pura o diluita; capacità standard: 20-30 cl.'),
  (64, 'it', 'Cucchiaio da bar', 'Questo strumento, indispensabile per un barman, è utilizzato per preparare i cocktail nel mixing glass e per creare gli strati negli shot, oltre che per misurare porzioni di liquido da 0.5 cl o porzioni di sostanze asciutte da 5 g.'),
  (57, 'it', 'Cannucce', 'Nel 1888 Marvin Stone, il proprietario di una fabbrica che produceva bocchini di carta, inventò il miglior accessorio per bere i drink dal bicchiere. Joseph Friedman allora ha fatto una fortuna sviluppando le cannucce flessibili. Il passo finale è arrivato quando le cannucce sono state prodotte in plastica.'),
  (799, 'it', 'Gin botanico', 'Questo è un forte liquore scozzese, al quale il mondo deve il gin tonic con il cetriolo. Prima della distillazione, l''alcol del grano viene infuso per giorni con undici tipi di piante, con l''aggiunta di rosa e cetriolo. Il prodotto risultante è combinato con una bevanda di un secondo still, la cui qualità unica è l''uso del metodo "bagno" delle erbe distillate a vapore. Oltre ai cetrioli e alle rose bulgare, il gin più famoso, Hendrick''s, comprende un gran numero di fiori, radici e frutta, che lo rendono uno dei drink più richiesti nei bar di tutto il mondo.'),
  (54, 'it', 'Triple Sec', 'Liquore cult agli agrumi dal gusto particolarmente secco, ottenuto dalla macerazione della scorza delle arance curaçao in alcol neutro e acqua. Il risultato viene distillato tre volte prima di essere imbottigliato, per conservarne l''alta gradazione.'),
  (9, 'it', 'Succo di limone', 'Per preparare il succo, i limoni sono schiacciati da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (734, 'it', 'Scorzetta di limone', 'Lo strato più superficiale del limone, tagliato con uno speciale coltello affilato. Contiene oli essenziali al sapore di limone. La scorzetta può essere ottenuta da un frutto tagliato o intero e utilizzata grattugiata o anche arrotolata a spirale.'),
  (66, 'it', 'Bicchiere da sour', 'I bicchieri da sour sono specifici per servire i cocktail Sour, ossia quelli con una base di liquore, succo di limone o lime, e un dolcificante. Capacità standard: 9-12 cl.'),
  (71, 'it', 'Peeler scorze agrumi', 'Strumento per barista proveniente dalla cultura giapponese dell''intaglio. Utilizzato per tagliare strisce sottili di scorze di agrumi o anelli e spirali di mela.'),
  (143, 'it', 'Mezcal', 'Distillato messicano prodotto utilizzando metodi tradizionali che comprendono la cottura dell''agave in forni interrati con pietre laviche. La bevanda risulta perciò infusa con un sentore di fumo. I cuori di agave vengono quindi macinati; il succo è fatto fermentare e invecchiare in botti di quercia per almeno 4 mesi.'),
  (224, 'it', 'Basilico verde', 'Erba aromatica che cresce principalmente nelle regioni calde del vecchio continente. Le foglie verdi sono diventate popolari grazie al cocktail "Smash al Basilico" che è già un classico.'),
  (223, 'it', 'Cardamomo', 'Pianta erbacea e spezia del Ceylon, della famiglia dello zenzero. È considerata una delle spezie più potenti al mondo.'),
  (566, 'it', 'Radice di zenzero', 'Pianta asiatica, importata in Europa nel Medioevo. Il rizoma appare come un agglomerato di pezzi tondi; è utile per rinforzare il sistema immunitario e combattere il mal di testa. Una fettina della radice pesa in media 5 g.'),
  (83, 'it', 'Ghiaccio tritato', 'Il primo ghiaccio tritato veniva ottenuto dai barman, agendo con coltelli speciali su una grande lastra di ghiaccio. In seguito sono comparse le macchine per il ghiaccio e quelle tritaghiaccio.'),
  (117, 'it', 'Colino', 'Usato insieme a shaker e passino per un doppio filtraggio dei cocktail quando si versano dallo shaker al bicchiere. Con una maglia più stretta del passino da bar, non permette nemmeno al più piccolo seme di frutta o pezzo di ghiaccio di cadere nel drink.'),
  (52, 'it', 'Pestello da bar', 'Accessorio indispensabile per cocktail tropicali: si usa per frantumare bacche e frutti nello shaker o direttamente nel bicchiere.'),
  (373, 'it', 'Mollette', 'Accessorio decorativo utilizzato per fissare le guarnizioni all’orlo del bicchiere.'),
  (113, 'it', 'Assenzio', 'Distillato francese prodotto dalla macerazione di erbe e spezie, inclusi melissa, finocchio e anice in alcol vinico o di cereali. Il componente principale è l''estratto di assenzio che contiene tujone, un ingrediente ad alta tossicità.'),
  (295, 'it', 'Sciroppo di zucchero', 'Sciroppo di zucchero'),
  (152, 'it', 'Lampone', 'Piccola bacca rossa che cresce su arbusti perenni, principalmente in Russia, Serbia, Polonia e Stati Uniti. Contiene zucchero, acidi organici, vitamina A, B, C e grassi. Una bacca pesa mediamente 5 g.'),
  (125, 'it', 'Highland single malt whisky', 'Distillato di origine scozzese, prodotto nelle Highlands, la regione montuosa nel nord della Scozia. Composto al 100% da malto d''orzo sottoposto a distillazione doppia o, raramente, tripla. La bevanda alcolica che ne deriva viene lasciata maturare per almeno 3 anni in botti di quercia.'),
  (47, 'it', 'Campari', 'Campari'),
  (189, 'it', 'Succo di pompelmo', 'Per preparare il succo, i pompelmi sono schiacciati da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (672, 'it', 'Menta', 'L''erba aromatica per cocktail più conosciuta; ne esistono oltre 30 specie ma la menta piperita e la menta dolce sono le più utilizzate. Conservare in frigorifero, arrotolata in un tovagliolo di carta, non oltre due giorni.'),
  (124, 'it', 'Chartreuse verde', 'Questo liquore monastico è prodotto in una località delle Alpi francesi dal 1764 secondo una ricetta segreta. Circa 130 piante ed erbe vengono macerate in alcol neutro e distillate diverse volte. Il risultato viene bilanciato con lo zucchero, mescolato fino alla gradazione desiderata e invecchiato in botti di quercia.'),
  (427, 'it', 'Liquore ai fiori di sambuco', 'Liquore ai fiori francese, ottenuto dalla macerazione dei fiori di sambuco tritati, secondo una ricetta segreta. Il derivato viene filtrato, mescolato allo zucchero e diluito con acqua fino a raggiungere la gradazione desiderata.'),
  (35, 'it', 'Vermouth secco', 'Vermouth forte, ideato all''inizio del XIX secolo e ottenuto dalla macerazione di assenzio alpino insieme ad una dozzina di altre erbe e piante in vino bianco secco. Il risultato viene filtrato e invecchiato in botti di quercia per almeno un anno.'),
  (130, 'it', 'Liquore all''arancia', 'Liquore agli agrumi fragrante, ottenuto dalla macerazione della scorza di arance della varietà Laraha in alcol neutro e acqua. L’alcolico che ne deriva è filtrato, mescolato con zucchero e conservato in botti di quercia.'),
  (114, 'it', 'Bitter Peychaud', 'Classico bitter di New Orleans, ideato dal famoso farmacista nel 1830, è prodotto secondo una ricetta segreta che prevede l''infusione in distillati neutri di anice, chiodi di garofano, vaniglia, noce moscata, frutta e spezie.'),
  (161, 'it', 'Calice grande', 'Bicchiere ‘regale’, con pareti spesse che consentono di far tintinnare i bicchieri durante un brindisi senza il rischio di romperli. Capacità standard: 20-30 cl.'),
  (665, 'it', 'Maraschino', 'Un liquore alle bacche, proveniente dalla Croazia, prodotto dalla macerazione delle bacche di maraschino con tutti i noccioli, in alcol neutro e acqua per almeno un mese. Il mix che ne deriva viene filtrato, zuccherato, portato alla gradazione desiderata e invecchiato in botti di quercia per almeno tre anni.'),
  (303, 'it', 'Bitter al pompelmo', 'Bitter estivo ottenuto dall''infusione di scorza di pompelmo in un distillato neutro, con l''aggiunta di luppolo per attenuare il gusto amaro.'),
  (20, 'it', 'Ciliegie al maraschino', 'Varietà particolari di ciliegie, come "King", "Rainer" o "Golden" immerse in una soluzione salina e poi nello sciroppo di zucchero con aggiunta di coloranti alimentari.'),
  (96, 'it', 'Spiedino da cocktail', 'Accessorio decorativo per servire olive nei Martini e ciliegie da cocktail nel Manhattan. Comparso per la prima volta nei bar alla fine del XIX secolo, grazie al genio del marketing Charles Forster.'),
  (101, 'it', 'Rum invecchiato', 'Superalcolico dei Caraibi, prodotto attraverso la distillazione verticale dell''alcol ottenuto dalla fermentazione della melassa o del succo estratti dalla canna da zucchero. Prima della miscelazione, è tenuto in botti di quercia bruciate, usate per bourbon o sherry, e invecchiato dai 7 ai 20 anni, a seconda del metodo di invecchiamento scelto.'),
  (116, 'it', 'Liquore al cacao scuro', 'Il liquore al cioccolato scuro è ottenuto dalla filtrazione delle fave di cacao in alcol neutro. Il derivato alcolico è diluito con acqua fino al raggiungimento della gradazione desiderata e mescolato con vaniglia del Madagascar e caramello, che conferisce al liquore un colore scuro.'),
  (67, 'it', 'Mixing glass', 'Un must classico per un bar a cinque stelle; utilizzato per la preparazione di cocktail forti e maschili, senza l''aggiunta di succhi, erbe e marmellate. Il ghiaccio mantiene la propria forma e non si scioglie, così da non alterare la gradazione del drink. Capacità standard: 50-90 cl.'),
  (166, 'it', 'Amaro', 'Liquore italiano tradizionale, prodotto dalla macerazione in alcol neutro di erbe e radici, incluse scorze d''agrumi, ginepro, finocchio, melissa, anice e cardamomo. Il derivato alcolico è filtrato, mescolato con zucchero e diluito con acqua fino a raggiungere la gradazione desiderata.'),
  (171, 'it', 'Sfere di ghiaccio', 'L''orgoglio dei barman giapponesi: il ghiaccio elevato a oggetto d''arte. Oggi sono molto comuni nei bar, grazie a delle macchine speciali. I cubetti di ghiaccio sono messi in una morsa leggermente calda, e il metallo viene scaldato dall''acqua che sagoma i contorni della sfera.'),
  (3, 'it', 'Limone', 'Agrume tropicale che cresce su piccoli alberi sempreverdi soprattutto in Cina, India e Messico. Contiene vitamina C e acidi organici; tradizionalmente utilizzato per contrastare raffreddore e deficit nutrizionali. Un frutto pesa 160 g e rende 6 cl di succo; può essere tagliato in 8 fette o 4 grandi spicchi per 1.5 cl di succo ciascuno.'),
  (62, 'it', 'Bourbon', 'Superalcolico invecchiato di origine americana. Secondo la legge, deve contenere almeno il 51% di malto di mais, con l''aggiunta di orzo e segale, e deve essere prima distillato e poi filtrato. Invecchiato in botti di quercia dai 2 ai 7 anni. Le botti vengono bruciate internamente, utilizzando una speciale tecnologia.'),
  (111, 'it', 'Crème de cassis', 'Liquore alle bacche di Digione, ottenuto dalla macerazione del ribes nero in alcol neutro e acqua per un massimo di due mesi. Il liquore non filtrato viene quindi mescolato con zucchero.'),
  (63, 'it', 'Bitter di Angostura', 'Pregiato Bitter venezuelano, chiamato così in onore della città di Angostura. Prodotto con la ricetta segreta originale del Dr. Johann Gottlieb Benjamin Siegert, (1800 circa) mediante l''infusione di spezie ed erbe segrete in distillati di rum scuro.'),
  (16, 'it', 'Mezza panna', 'Panna light, principalmente ottenuta da latte di mucca, separando la panna dal latte. La percentuale di grassi varia a seconda dei paesi, solitamente non supera il 15%. Conservata in frigorifero dura fino a 20 giorni.'),
  (36, 'it', 'Vermouth rosso', 'Vermouth con una punta di dolce, ottenuto dalla macerazione di 30 erbe e spezie alpine in vino bianco. Il risultato viene filtrato, regolato alla gradazione e dolcezza desiderate, colorato con caramello e invecchiato in botti di quercia per almeno un anno.'),
  (34, 'it', 'Club soda', 'Acqua gassata, che costituisce un ingrediente indispensabile del Fizz e di altri drink frizzanti. Una volta era prodotta addizionando l''acqua minerale naturale con anidride carbonica; oggi invece è sempre più frequente l’aggiunta di bicarbonato di sodio.'),
  (732, 'it', 'Scorzetta d''arancia', 'Lo strato più superficiale dell''arancia, tagliato con uno speciale coltello affilato. Contiene oli essenziali al sapore d''arancia. La scorzetta può essere ottenuta da un frutto tagliato o intero e utilizzata grattugiata o anche arrotolata a spirale.'),
  (258, 'it', 'Champagne', 'Vino frizzante la cui produzione nella omonima regione francese è soggetta ad una rigida regolamentazione. Tre varietà di uva vengono raccolte manualmente e lasciate fermentare. I vini che se ne ricavano sono mescolati e imbottigliati, con l''aggiunta di zucchero di canna e lievito. Una seconda fermentazione, che richiede almeno nove mesi, ha luogo in bottiglia. I residui sono rimossi utilizzando il metodo del remuage; dopo l''aggiunta di una miscela di vini di annate precedenti, la bottiglia viene chiusa con un sughero naturale.'),
  (148, 'it', 'Purea di pesca', 'Purea di pesca'),
  (535, 'it', 'Pesca', 'Frutto amante del sole che cresce su albero decidui principalmente in Cina, Italia e Spagna. Contiene acidi organici, sali minerali e pectina. Un frutto, dal peso medio di 120 g, permette di ricavare 80 grammi di polpa.'),
  (59, 'it', 'Flûte', 'Bicchiere elegante per cocktail a base di champagne o vino frizzante. La forma lunga e stretta ricorda un tulipano e trattiene le bollicine nel cocktail che, in tal modo, resta frizzante più a lungo. Capacità standard: 18-25 cl.'),
  (179, 'it', 'Cordial di lime', 'Un''antica ricetta agli agrumi, che prevede la pastorizzazione del succo di lime, mescolato con sciroppo di zucchero, cremor tartaro e acqua.'),
  (733, 'it', 'Scorzetta di lime', 'Lo strato più superficiale del lime, tagliato con uno speciale coltello affilato. Contiene oli essenziali al sapore di lime. La scorzetta può essere ottenuta da un frutto tagliato o intero, utilizzata grattugiata o anche arrotolata a spirale.'),
  (72, 'it', 'Coppa da cocktail', 'Conosciuto anche come bicchiere da Martini, è ideale per servire cocktail senza ghiaccio. Prima di servire è necessario raffreddare il bicchiere; il gambo lungo evita che il cocktail si scaldi quando lo si tiene in mano; capacità standard: 9-16 cl.'),
  (40, 'it', 'Cognac', 'Superalcolico invecchiato di origine francese che deriva da uve bianche: Ugni Blanc, Folle Blanche o, meno frequentemente, Colombard Montilla. Sottoposto a doppia distillazione e invecchiato in botti di quercia: l''invecchiamento VS (Very Special) raggiunge i 3 anni, mentre l''invecchiamento VSOP (Very Superior Old Pale) arriva a 5 anni.'),
  (14, 'it', 'Noce moscata in polvere', 'Condimento indonesiano, ottenuto dalla noce moscata, essiccata e macinata fino a ricavarne una polvere.'),
  (746, 'it', 'Grattugia per noce moscata', 'Accessorio utile per preparare polvere di noce moscata o cioccolato, o, più raramente, grattare la scorza degli agrumi.'),
  (8, 'it', 'Succo d''arancia', 'Per preparare il succo, le arance sono schiacciate da una pressa, il succo ottenuto è quindi filtrato e imbottigliato.'),
  (88, 'it', 'Rum bianco', 'Superalcolico dei Caraibi, prodotto attraverso la distillazione verticale dell''alcol ottenuto dalla fermentazione della melassa o del succo estratti dalla canna da zucchero. Prima della miscelazione, è tenuto in botti di quercia bruciate, usate per bourbon o sherry, e invecchiato almeno 12 mesi, a seconda del metodo di invecchiamento. Viene infine filtrato per far scolorire la bevanda.'),
  (92, 'it', 'Calvados', 'Distillato francese, derivato dal sidro prodotto dalla fermentazione, per 6-12 mesi, del succo di mele autunnali della Normandia in tini d''acciaio. In seguito, la bevanda è sottoposta a doppia distillazione e viene fatta invecchiare in botti di quercia per almeno 2 anni.'),
  (77, 'it', 'Sciroppo di granatina', 'Il popolare sciroppo ai frutti rossi, ottenuto dalla pastorizzazione del succo di melagrana con altri succhi di bacche rosse, vaniglia e zucchero di canna.'),
  (86, 'it', 'Rum scuro', 'Superalcolico dei Caraibi, prodotto mediante la distillazione verticale dell''alcol ottenuto dalla fermentazione della melassa o del succo estratti dalla canna da zucchero. Prima della miscelazione, è tenuto in botti di quercia bruciate, usate per bourbon o sherry, e invecchiato dai 2 ai 7 anni, a seconda del metodo di invecchiamento scelto. Non viene filtrato, e, alle volte, viene aggiunto del caramello come colorante.'),
  (365, 'it', 'Rum overproof', 'Superalcolico dei Caraibi, prodotto attraverso la distillazione verticale dell''alcol ottenuto dalla fermentazione della melassa o del succo estratti dalla canna da zucchero. Prima della miscelazione, è tenuto in botti di quercia bruciate, usate per bourbon o sherry, e invecchiato almeno un anno. Non viene diluito con acqua per conservarne il sapore deciso.'),
  (190, 'it', 'Pompelmo', 'Questo popolare agrume cresce a grappolo soprattutto in Cina, USA e Messico. Contiene vitamina C, pectina e licopene, che ha la proprietà di ridurre il colesterolo. Un frutto pesa mediamente 600 g; può essere tagliato in 10 fette o parti e rende circa 20 cl di succo.'),
  (186, 'it', 'Bicchiere da tiki', 'I bicchieri da tiki, realizzati in ceramica, sono specifici per i cocktail esotici a tema tiki.'),
  (662, 'it', 'Whiskey irlandese', 'Distillato di origine irlandese, prodotto con malto d''orzo germogliato, essiccato in forno, macinato e coperto con acqua calda. Una volta separato dai cereali, il liquido viene fermentato, distillato tre volte e lasciato a maturare in botti di quercia, usate per sherry, bourbon o Porto, per almeno 3 anni.'),
  (128, 'it', 'Panna', 'La doppia panna è principalmente ricavata dal latte di mucca, separando la panna dal latte. La percentuale di grassi varia a seconda dei paesi dal 20 al 40%. In frigo si conserva fino a 20 giorni.'),
  (74, 'it', 'Ciotola', 'Contenitore in vetro o metallo per mescolare gli ingredienti con una frusta. Qualsiasi miscela con l''aggiunta di succo di pomodoro o di agrumi deve essere preparata soltanto in una ciotola di vetro o di acciaio inossidabile, per evitare la reazione agli acidi.'),
  (90, 'it', 'Bicchiere Irish coffee', 'Bicchiere robusto per servire grog caldo, vin brûlé e cocktail al caffè; è chiamato così in onore del celebre cocktail al caffè. Capacità standard: 20-30 cl.'),
  (78, 'it', 'Frusta', 'Indispensabile per montare la panna per l''Irish Coffee o battere gli albumi con lo zucchero per un ‘Tom and Jerry’. Per mescolare o battere gli ingredienti in un vasetto, è utilizzata una versione apposita con un manico più lungo e una punta più piccola.'),
  (761, 'it', 'Macchina da caffè', 'Macchina automatica per preparare diversi tipi di caffè: espresso, americano, caffè freddo, cappuccino e latte macchiato.'),
  (39, 'it', 'Cachaca', 'Superalcolico brasiliano, prodotto dalla filtrazione e distillazione del succo di canna da zucchero fermentato, seguendo una tecnica precisa: "testa" e "coda" vengono scartati, lasciando soltanto il "cuore" della bevanda che continua l''invecchiamento in botti di quercia per almeno un anno.'),
  (5, 'it', 'Lime', 'Agrume esotico che cresce tutto l''anno nei climi tropicali, principalmente in Cina, India e Messico. I lime, fonte eccellente di cellulosa, vitamina C e calcio, sono ottimi per esaltare il sapore di cibi e bevande. Un frutto pesa in media 80 g e rende 3 cl di succo; può essere tagliato in 4 fette, contenenti 7,5 cl di succo ognuna.'),
  (43, 'it', 'Sciroppo di lampone', 'Popolare sciroppo di bacche, ottenuto dalla pastorizzazione del succo di lampone mescolato con zucchero e acqua.'),
  (661, 'it', 'Vodka agli agrumi', 'Superalcolico forte e aromatizzato, prodotto mediante la distillazione multipla di cereali, soggetti a diversi livelli di filtrazione, anche al carbone attivo. Ciò che ne deriva è mescolato con acqua distillata o sorgiva. La bevanda finale viene infusa con estratti di cedro e lime.'),
  (481, 'it', 'Succo di mirtilli rossi', 'Per preparare il succo, i mirtilli rossi sono schiacciati da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (53, 'it', 'Torcia culinaria', 'Accessorio sofisticato per flambare l''olio d''agrumi sul famoso Cosmopolitan, cospargere di cannella brillante i cocktail tiki o semplicemente accendere i sigari degli ospiti.'),
  (82, 'it', 'Porto Tawny', 'Vino Porto rosso intenso, ottenuto da una miscela di vini rossi pregiati con l''aggiunta di cognac e successivamente invecchiato in botti di quercia con il metodo Solera.'),
  (49, 'it', 'Tuorlo d''uovo di quaglia', 'Il prodotto dà ai cocktail una consistenza delicata. Un tuorlo d''uovo di gallina equivale a 5 tuorli d''uovo di quaglia.'),
  (178, 'it', 'Forbici per uova di quaglia', 'Forbici speciali dotate di un anello per tenere fermo l''uovo ed effettuare un taglio netto.'),
  (569, 'it', 'Sedano', 'La "rinomanza” di questa pianta è dovuta agli antichi greci; cresce soprattutto in climi temperati. Prima di servirlo, devono essere rimosse le fibre, facendo una piccola incisione sul gambo e tirando il "filo". Un gambo pesa mediamente 15 g.'),
  (42, 'it', 'Tabasco rosso', 'Salsa rossa pepata, ottenuta da peperoncini maturi e selezionati, invecchiati per tre anni in botti di quercia con sale dell’isola di Avery. Il composto finale viene aromatizzato con aceto e lasciato invecchiare per altre quattro settimane. È più speziato della versione verde.'),
  (56, 'it', 'Pepe nero in polvere', 'Condimento indiano in polvere, ottenuto da bacche non maturate di pepe nero, essiccate al sole fino a diventare nere. Diversamente dalla versione macinata, la fragranza evapora più velocemente.'),
  (58, 'it', 'Bicchiere highball', 'Bicchiere alto per acqua, succo o club mix. Il mix viene costruito direttamente nel bicchiere; capacità standard: 30-40 cl.'),
  (37, 'it', 'Scotch', 'Distillato scozzese ricavato dal malto d''orzo, essiccato con la torba, macinato e ricoperto con acqua calda. Il liquido, una volta separato, viene fermentato e distillato tre volte. L’alcolico ricavato è mescolato e lasciato a maturare in botti di quercia, usate per sherry, bourbon o Porto, per almeno 3 anni.'),
  (46, 'it', 'Liquore alla ciliegia', 'Famoso liquore alle bacche, ottenuto dalla macerazione delle ciliegie in diverse varietà di distillati neutri e acqua per almeno un mese. Il prodotto viene quindi filtrato, zuccherato, rinforzato con aggiunta di cognac e invecchiato in botti di quercia per almeno 3 anni.'),
  (89, 'it', 'Rum dorato', 'Superalcolico dei Caraibi, prodotto mediante la distillazione verticale dell''alcol ottenuto dalla fermentazione della melassa o del succo estratti dalla canna da zucchero. Prima della miscelazione, è tenuto in botti di quercia bruciate, usate per bourbon o sherry, e invecchiato dai 2 ai 7 anni, a seconda del metodo di invecchiamento scelto. Non viene filtrato per conservarne il colore caratteristico.'),
  (94, 'it', 'Cola', 'La bevanda frizzante più popolare, prodotta secondo una formula segreta a base di caffeina, zucchero, aromi e coloranti.'),
  (60, 'it', 'Liquore al cacao bianco', 'Liquore leggero al cioccolato, ottenuto dalle fave di cacao mediante percolazione con alcol neutro. Il percolato viene filtrato per rimuovere il pigmento scuro, regolato alla gradazione desiderata e mescolato con zucchero fino al raggiungimento di una consistenza cremosa.'),
  (61, 'it', 'Liquore alla menta', 'Liquore cremoso alle erbe, con un alto contenuto di zucchero ottenuto dall’estratto fresco di menta piperita mediante percolazione con distillati di lime in alcol neutro. Il prodotto alcolico finale viene dolcificato, mescolato e imbottigliato.'),
  (93, 'it', 'Tequila argento', 'Superalcolico di origine messicana, tradizionalmente prodotto dalla distillazione del succo dell’agave blu. Dai sette ai dieci cuori di agave vengono posizionati in fornaci speciali per convertire l''amido in zucchero; il succo che ne deriva è fatto fermentare, distillato due volte e, dopo la filtrazione, immediatamente imbottigliato.'),
  (212, 'it', 'Birra allo zenzero', 'La birra di zenzero è il “cavallo di Troia” che ha permesso alla vodka di entrare nel mercato e nel gusto degli americani. Questo tipo particolare di limonata speziata è ottenuta dalla macerazione di zenzero macinato ed essiccato nel lievito di birra.'),
  (99, 'it', 'Sciroppo di mandorle', 'Sciroppo di mandorle'),
  (127, 'it', 'Sale', 'Condimento cristallizzato prodotto da minerali, che possono raggiungere i 250 milioni di anni e oltre.'),
  (84, 'it', 'Coppa da margarita', 'Nella sua ‘vita precedente’ era una salsiera per il guacamole, ma ora è il bicchiere più usato per servire il cocktail a base di tequila più famoso al mondo. Capacità standard: 25-35 cl.'),
  (85, 'it', 'Bitter all''arancia', 'Uno dei primi bitter agli agrumi, ottenuto dall''infusione nel rum di scorza d''arancia essiccata, spezie e radici con l''aggiunta, immediatamente prima dell''imbottigliamento, di zucchero di canna e acqua.'),
  (75, 'it', 'Sciroppo di frutto della passione', 'Sciroppo di frutta tropicale, ottenuto dalla pastorizzazione del succo della polpa del frutto della passione mescolato con zucchero di canna e acqua.'),
  (7, 'it', 'Succo d''ananas', 'Per preparare il succo, la polpa dell''ananas viene schiacciata da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (76, 'it', 'Bicchiere Hurricane', 'Bicchiere dallo stile vintage, che ricorda una lampada a cherosene, per servire drink tropicali. Così chiamato in onore del cocktail omonimo inventato da Pat O’Brien. Capacità standard: 30-40 cl.'),
  (4, 'it', 'Arancia', 'Agrume che cresce su grandi alberi principalmente in Brasile, USA e Cina. Contiene vitamina C, potassio e calcio. Conosciuto per i suoi effetti benefici sul cuore, i vasi sanguigni e sull’intero organismo in genere. Un frutto pesa mediamente 300 g e rende 8 cl di succo. Può essere tagliato in 10 fette o separato in 8 sezioni.'),
  (375, 'it', 'Bicchiere da collins', 'Bicchiere alto, per drink lunghi e mescolati; chiamato così dal nome di un cocktail classico, il "Tom Collins"; capacità standard: 30-40 cl.'),
  (104, 'it', 'Bénédictine', 'Famoso liquore prodotto in Normandia e decorato con l’iscrizione D.O.M. (Deo Optimo Maximo: a Dio, il più buono, il più grande). È composto da 27 erbe e spezie segrete e il processo di produzione prevede quattro passaggi. Dopo la macerazione e la distillazione, i distillati ricavati sono tenuti separati e poi mescolati per 11 mesi in botti di quercia. Successivamente vengono aggiunti acqua, brandy, miele e zucchero caramellato. Il passaggio finale prevede 3 mesi di invecchiamento.'),
  (95, 'it', 'Ananas', 'L''ananas è un frutto tropicale che cresce su piante spinose basse, principalmente in Brasile, Tailandia e Filippine. Contiene manganese e vitamina C; è noto per stimolare la digestione e ridurre la viscosità del sangue. Un frutto pesa mediamente 1200 g e può essere tagliato in 40 fette.'),
  (105, 'it', 'Bicchiere sling', 'La quintessenza dei bicchieri per servire cocktail e ‘biglietto da visita’ del Raffles Hotel; capacità standard: 20-30 cl.'),
  (79, 'it', 'Acqua naturale', 'La fonte più importante di salute e longevità. I barman di tutto il mondo raccomandano sempre di bere dell''acqua mentre si consuma un cocktail; è per questo che nei bar più importanti un bicchiere d''acqua naturale viene servito gratuitamente.'),
  (150, 'it', 'Zollette di zucchero', 'Condimento dolce europeo, ottenuto dalla purificazione, rifinitura e cristallizzazione dello sciroppo di zucchero di canna o del succo di barbabietola da zucchero. I cristalli vengono successivamente pressati nella forma desiderata.'),
  (100, 'it', 'Drambuie', 'Liquore scozzese, il cui nome in gaelico significa "appagante", prodotto dal 1910 secondo una ricetta segreta. È noto che la bevanda è una combinazione di single malt pregiato, miele d''edera, erbe e spezie.'),
  (677, 'it', 'Acqua di fiori d''arancio', 'Antica ricetta che prevede l''infusione in acqua di fiori freschi di arancio amaro.'),
  (118, 'it', 'Foglie di ananas', 'Le foglie del frutto tropicale sono utilizzate come ornamento per gli esotici cocktail tiki.'),
  (98, 'it', 'Pisco', 'Questo brandy d''uva peruviano è prodotto utilizzando fino a otto varietà d''uva, mentre in Cile ne sono utilizzate al massimo tre. Il succo fermentato viene distillato in tini di acciaio inossidabile e imbottigliato immediatamente o invecchiato in botti di quercia per 2 anni.'),
  (103, 'it', 'Zollette di zucchero di canna', 'Condimento dolce tropicale, ottenuto dalla cristallizzazione dello zucchero di canna, successivamente pressato in piccoli cubetti. Più è alto il contenuto di melassa, più scuro è il colore e ricco il sapore.'),
  (132, 'it', 'Bourbon invecchiato', 'Bourbon invecchiato'),
  (102, 'it', 'Zucchero semolato', 'Polvere dolce ottenuta dalla polverizzazione dello zucchero in granelli. Per la grandezza dei suoi grani, si dissolve immediatamente nel liquido, con un significativo risparmio di tempo.'),
  (158, 'it', 'Boccale di rame', 'Un must have, è il "Cavallo di Troia" della vodka in America e l''utensile preferito per servire il cocktail "Mulo Moscovita"; capacità standard: 30-40 cl.'),
  (214, 'it', 'Mora', 'Bacca viola di medie dimensioni che cresce su cespugli in tutta Europa, in Africa Nord-Occidentale, Asia Centrale, Nord e Sud America. Contiene carotene, vitamina C, B1 e B2, K e altre. Una bacca pesa mediamente 6 g.'),
  (115, 'it', 'Zucchero granulato', 'Condimento dolce europeo, ottenuto dalla complicata purificazione, rifinitura e cristallizzazione dello sciroppo di zucchero di canna o del succo di barbabietola da zucchero. La grandezza dei grani è importante: più sono piccoli, più velocemente si dissolveranno.'),
  (107, 'it', 'Latte', 'Ottenuto con latte intero di mucca; il contenuto di grassi desiderato è raggiunto aggiungendo panna ad una versione senza grassi del prodotto.'),
  (330, 'it', 'Bastoncini di cannella', 'Condimento del Ceylon, conosciuto dal XV secolo, costituito dalla corteccia dell''albero di cannella, pulita, levigata ed essiccata all''ombra finché non si torce in un tubo.'),
  (108, 'it', 'Tazza', 'Tazza da caffè o da tè; nel 1930 è diventato il contenitore di elezione per il cocktail "Tom and Jerry". Capacità standard: 20-25 cl.'),
  (655, 'it', 'Lattiera', 'Recipiente di metallo per il latte, utilizzato per preparare cocktail caldi e montare la panna.'),
  (120, 'it', 'Cannella in polvere', 'Condimento del Ceylon in polvere, conosciuto dal XV secolo, prodotto da pezzi e trucioli di corteccia di cannella, essiccati e macinati.'),
  (149, 'it', 'Anice stellato', 'Frutto tropicale a forma di stella, che cresce su alberi sempreverdi principalmente in Cina. Raccolto quando non ancora maturo ed essiccato al sole.'),
  (134, 'it', 'Sciroppo d''acero', 'Famoso sciroppo natalizio, ottenuto dalla linfa dello zucchero d''acero, raccolto dagli alberi tra febbraio e marzo. La linfa viene pastorizzata con zucchero di canna e acqua.'),
  (123, 'it', 'Sciroppo di rose', 'Sciroppo di fiori delicato, ottenuto dall''infusione e pastorizzazione dei petali di rose nello sciroppo di zucchero.'),
  (201, 'it', 'Petali di rosa', 'Il fiore più venduto al mondo; ogni bocciolo ha 25 petali.'),
  (1035, 'it', 'Whisky americano', 'Whisky americano'),
  (288, 'it', 'Sherry Pedro Ximenez', 'Il tipo più dolce di vino spagnolo maturo, ottenuto dalle omonime uve. Il succo dell''uva fermentato viene arricchito con alcol d''uva e invecchiato in botti di quercia, con il metodo Solera, per 10-30 anni o più.'),
  (154, 'it', 'Cucchiaino da tè', 'Cucchiaio per mescolare il tè nella tazza; un cucchiaino contiene circa 5 g di ingredienti secchi e 0.5 сl di liquidi.'),
  (211, 'it', 'Ghiaccio in pezzi', 'Blocco o cubo squadrato: un grosso pezzo di ghiaccio si scioglie più lentamente nel bicchiere ed è di maggiore impatto visivo.'),
  (450, 'it', 'Sciroppo di zenzero', 'Sciroppo speziato asiatico, ottenuto dalla pastorizzazione dello sciroppo di zucchero con estratto di zenzero.'),
  (693, 'it', 'Bombilla per mate', 'Cannuccia speciale per servire il mate: l''estremità superiore presenta un bocchino, quella inferiore un filtro.'),
  (552, 'it', 'Ribes rosso', 'Piccole bacche rosse che crescono su arbusti caducei, principalmente in Europa Centro-Settentrionale e Asia Settentrionale. Contiene grandi quantità di vitamina C, vari zuccheri, acidi organici e minerali. Un cucchiaio da bar contiene 5 g di bacche.'),
  (332, 'it', 'Sherry Oloroso', 'Vino liquoroso spagnolo semi-secco o dolce, ottenuto dalla fermentazione delle uve Palomino senza la formazione del velo di lieviti in superficie: il flor. Il vino è arricchito con distillato d''uva e invecchiato in botti di quercia con il metodo Solera per almeno due anni.'),
  (191, 'it', 'Albicocche essiccate', 'Frutto secco prodotto soprattutto in Turchia, Iran e Uzbekistan, utilizzando albicocche mature. I frutti sono prima bolliti o messi in ammollo in uno sciroppo e poi essiccati al sole o in essiccatori speciali. Un pezzo pesa in media 10g.'),
  (683, 'it', 'Vassoio', 'Piatto in metallo o in legno per servire cibo o bevande agli ospiti.'),
  (121, 'it', 'Sciroppo di vaniglia', 'Fragrante sciroppo del Madagascar, ottenuto dall''infusione e pastorizzazione dei baccelli di vaniglia nello sciroppo.'),
  (381, 'it', 'Tequila oro', 'Superalcolico di origine messicana, tradizionalmente prodotto dalla distillazione del succo dell’agave blu. Dai sette ai dieci cuori di agave vengono posizionati in fornaci speciali per convertire l''amido in zucchero; il succo che ne deriva è fatto fermentare, distillato due volte e colorato con del caramello. La tequila oro è aromatizzata con l’aggiunta di vari additivi.'),
  (318, 'it', 'Vermouth bianco', 'Il vermouth più dolce, ottenuto dalla macerazione di erbe e spezie alpine in vino bianco. Il risultato viene filtrato, regolato alla gradazione desiderata e alla massima dolcezza possibile e infine invecchiato in botti di quercia per almeno un anno.'),
  (126, 'it', 'Purea di fragole', 'Purea di fragole'),
  (327, 'it', 'Zucchero di canna granulato', 'Condimento tropicale dolce, ottenuto dalla cristallizzazione dello zucchero di canna e dalla successiva lavorazione meccanica. Più è alto il contenuto di melassa, più il colore è scuro e il sapore ricco.'),
  (138, 'it', 'Frullatore', 'Inventato nel 1922 da Stephen Poplawski, questo piccolo elettrodomestico è indispensabile per fare cocktail tiki, frullati e drink ghiacciati.'),
  (196, 'it', 'Sciroppo di cocco', 'Lo sciroppo tropicale più popolare, ottenuto dalla pastorizzazione dell''acqua di cocco con zucchero di canna.'),
  (197, 'it', 'Affetta ananas', 'Accessorio tiki che in pochi secondi rimuove la buccia e il cuore duro dell''ananas.'),
  (744, 'it', 'Paletta da ghiaccio', 'Utile strumento di policarbonato o acciaio inossidabile che permette di prelevare una quantità specifica di ghiaccio. La disponibilità di palette, di diversa grandezza e volume, consente di scegliere lo strumento in funzione della quantità di ghiaccio desiderata.'),
  (406, 'it', 'Liquore alla banana gialla', 'Liquore cremoso tropicale, ottenuto dalla macerazione della polpa delle banane gialle in alcol neutro e acqua. Il derivato viene filtrato, mescolato con lo zucchero e arricchito con brandy giovane.'),
  (200, 'it', 'Banana', 'La più antica pianta tropicale che cresce soprattutto in Cina, India e Uganda. Il frutto contiene vitamina B6, manganese e fibre. Un frutto pesa mediamente 200 g, di cui solo la buccia 80 g.'),
  (244, 'it', 'Jénéver', 'Superalcolico olandese, il ‘padre’ del gin, prodotto a partire dal XV secolo, distillando alcol puro con l''aggiunta di bacche di ginepro e altre spezie.'),
  (133, 'it', 'Sciroppo di miele', 'Lo sciroppo più famoso, ottenuto dalla pastorizzazione del miele diluito con acqua fino al raggiungimento della consistenza desiderata.'),
  (293, 'it', 'Teiera', 'La storia dell''antico contenitore cinese risale al tempo e al luogo in cui il tè stesso è natoe si è diffuso: la Cina del XV secolo. La teiera è utilizzata per l’infusione di tè, erbe e spezie in acqua bollente o succo.'),
  (287, 'it', 'Single Islay malt whisky', 'Single Islay malt whisky'),
  (284, 'it', 'Liquore al rabarbaro', 'Liquore da dessert agrodolce, alle erbe, ottenuto dalla macerazione dei gambi e delle foglie del rabarbaro in alcol neutro e acqua. Il risultato viene mescolato con zucchero e portato alla gradazione desiderata.'),
  (358, 'it', 'Cynar', 'Liquore alle erbe italiano, ottenuto dalla macerazione in alcol neutro e distillazione di 16 erbe e spezie, soprattutto carciofo. Il distillato viene quindi filtrato e portato alla gradazione e alla dolcezza desiderate.'),
  (735, 'it', 'Scorzetta di pompelmo', 'Lo strato più superficiale del pompelmo, tagliato con uno speciale coltello affilato. Contiene oli essenziali al sapore di pompelmo. La scorzetta può essere ottenuta da un frutto tagliato o intero, utilizzata grattugiata o anche arrotolata a spirale.'),
  (704, 'it', 'Vaporizzatore', 'Accessorio ‘di classe’ per spruzzare sui cocktail bitter e additivi aromatici.'),
  (435, 'it', 'Sherry Fino', 'Vino secco liquoroso spagnolo, ottenuto dalla fermentazione delle uve Palomino con l''aggiunta di lieviti speciali che durante la maturazione risalgono in superficie aggregandosi a formare un velo: il flor. È arricchito con alcol d''uva e maturato in botti sotto il flor per almeno 2 anni.'),
  (653, 'it', 'Bicchiere da shot', 'Piccolo bicchiere che presenta di solito un margine diritto. Pensato per i drink più forti o i cocktail che vanno consumati in un sorso; capacità standard: 5-10 cl.'),
  (546, 'it', 'Fragola', 'Grande bacca rossa che cresce su piccoli cespugli, principalmente negli USA, in Turchia, Spagna, Egitto e Messico. Contiene zucchero, pectina e tannino, acido ascorbico e altre vitamine e sostanze antinfiammatorie. Una bacca pesa mediamente 20 g.'),
  (402, 'it', 'Limoncello', 'Liquore nazionale italiano, ottenuto dalla macerazione delle scorze di limone in alcol neutro per un mese. L''alcolico che ne deriva viene mescolato ad acqua e zucchero, lasciato in infusione, e filtrato.'),
  (410, 'it', 'Liquore al litchi', 'Ottenuto dalla polpa dei litchi maturi, mescolata con alcol e lasciata in infusione.'),
  (486, 'it', 'Succo di mango', 'Per preparare il succo, la polpa del mango viene schiacciata da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (529, 'it', 'Frutto della passione', 'Frutto subtropicale che cresce su piante rampicanti, principalmente in Nuova Zelanda, Israele e Sri Lanka. Contiene vitamina A, beta carotene e potassio; ha effetto tonificante. Un frutto pesa mediamente 90g.'),
  (415, 'it', 'Liquore alla mora', 'Liquore ricco alle bacche, ottenuto dalla macerazione delle more in alcol neutro e acqua per un periodo massimo di due mesi. Il liquore, non sottoposto a filtrazione, viene mescolato con zucchero.'),
  (405, 'it', 'Liquore alla mela verde', 'Liquore di frutta fresca, ottenuto dalla macerazione della polpa di mele verdi in alcol neutro. Il prodotto alcolico viene quindi filtrato, mescolato con zucchero e diluito con acqua fino a raggiungere la gradazione desiderata.'),
  (528, 'it', 'Mela', 'Frutto popolare originario dell''Asia centrale, cresce su alberi frondosi soprattutto in Cina, USA e Turchia. Contiene acido ascorbico, vitamina K, potassio; aiuta a potenziare il sistema immunitario e a combattere l''obesità. Un frutto pesa in media 200 g e può essere tagliato in 10 fette.'),
  (682, 'it', 'Vasetto', 'Vasetto con coperchio per mescolare e conservare liquori e sciroppi. Capacità standard non disponibile.'),
  (446, 'it', 'Sciroppo d''agave', 'Sciroppo messicano derivato dal succo concentrato di agave mescolato con sciroppo di zucchero.'),
  (432, 'it', 'Vino rosso secco', 'Il tipo di vino più comune, ottenuto dalla macerazione e la conseguente fermentazione di uve rosse e nere, che conferiscono al vino il suo colore. Il prodotto viene quindi filtrato e tenuto in botti di quercia per almeno 3 mesi.');
INSERT INTO drink_me_bot.goods_i18n (goods_id, lang, name, description) VALUES
  (613, 'it', 'Chiodi di garofano', 'Spezia indonesiana costutuita da baccelli essiccati del pimento tropicale.'),
  (705, 'it', 'Fontana per assenzio', 'Accessorio necessario nel rituale di servizio del ‘forte’ drink francese. L''acqua, insieme ad erbe, frutta e talvolta ghiaccio, viene versata nel recipiente principale. Dopo l’infusione, il liquido è trasferito goccia a goccia nel bicchiere con l’assenzio, assorbendo lo zucchero contenuto in un apposito cucchiaio.'),
  (698, 'it', 'Cucchiaio da assenzio', 'Accessorio necessario nel rituale di servizio del forte drink francese. L''acqua, insieme ad erbe, frutta e talvolta ghiaccio, viene versata nel recipiente principale. Dopo l’infusione, il liquido è trasferito goccia a goccia nel bicchiere con l’assenzio, assorbendo lo zucchero contenuto in questo speciale cucchiaio perforato, appoggiato sopra il bicchiere.'),
  (494, 'it', 'Energy drink', 'Un Energy Drink è creato specificatamente per l''utilizzo durante un''intensa attività fisica e mentale.'),
  (394, 'it', 'Crema Irlandese', 'La crema irlandese è fatta con whiskey irlandese distillato triplo, con l''aggiunta di crema e alcol neutro e arricchito con cacao, vaniglia, zucchero e caramello.'),
  (547, 'it', 'Mirtillo', 'Piccola bacca viola che cresce su cespugli in Canada, Nord America, Turchia ed Europa Occidentale. Contiene notevoli quantità di vitamina A, B, C, manganese e potassio. È utile per la vista, in particolare migliora la visione notturna. Un cucchiaio da bar contiene 5 g di bacche.'),
  (578, 'it', 'Citronella', 'Erba dall’aroma d’agrumi, il cui uso ha origini nella cucina caraibica e asiatica; cresce principalmente nelle Isole Britanniche, Filippine e Indonesia.'),
  (490, 'it', 'Sprite', 'Bevanda gassata dolce, prodotta utilizzando la soda con aggiunta di zucchero ed estratto di limone.'),
  (666, 'it', 'Sambuca', 'Liquore italiano prodotto aromatizzando alcol di grano con zucchero e oli di anice e anice stellato, con estratti di bacche, fiori di sambuco ed erbe varie: tutto questo contribuisce alla sua persistente fragranza.'),
  (414, 'it', 'Advocaat', 'Liquore natalizio olandese che discende dalla bevanda alcolica brasiliana ricavata dall''avocado. È composto da una miscela di tuorli d''uovo, zucchero, vaniglia e brandy.'),
  (531, 'it', 'Melagrana', 'Frutto mediterraneo che cresce su un cespuglio a foglia caduca o un piccolo albero principalmente in Israele e in India. Contiene potassio e fosforo; è noto per i suoi effetti positivi sul sistema cardiovascolare. Un frutto pesa mediamente 300 g e può essere tagliato in 10 fette.'),
  (684, 'it', 'Bicchiere da vino rosso', 'Bicchiere classico, dal profilo leggermente allargato; tradizionalmente più alto del bicchiere da vino bianco; capacità standard: 20-30 cl.'),
  (483, 'it', 'Succo di ciliegia', 'Per preparare il succo, le ciliegie sono schiacciate da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (551, 'it', 'Ribes nero', 'Piccola bacca nera che cresce su cespugli in Europa Centrale e Settentrionale e in Asia Settentrionale. Contiene grandi quantità di vitamina C, vari zuccheri, acidi organici e minerali. Un cucchiaio da bar contiene 5 g di bacche.'),
  (597, 'it', 'Confettura di lamponi', 'Confettura ottenuta da bacche rosse, che crescono su arbusti nani perenni principalmente in Russia, Serbia, Polonia e Stati Uniti. I frutti maturi vengono fatti bollire con lo zucchero fino ad ottenere una consistenza omogenea. Un cucchiaio da bar può contenere 5 g di confettura.'),
  (590, 'it', 'Marmellata d''arancia', 'Marmellata ottenuta dalla polpa degli agrumi, che crescono su alberi alti principalmente in Brasile, USA e Cina. I frutti maturi vengono fatti bollire con lo zucchero fino ad ottenere una consistenza omogenea. Un cucchiaio da bar può contenere 5 g di marmellata.'),
  (589, 'it', 'Miele', 'Nettare di fiori, raccolto e trasformato dalle api.'),
  (652, 'it', 'Biscotto', 'Biscotto dolce, ottenuto da varie tipologie di impasto e cotto.'),
  (686, 'it', 'Caraffa di vetro', 'Antico contenitore da cucina, per servire acqua, limonata e sangria. Capacità standard: 50-300 cl.'),
  (484, 'it', 'Succo di melagrana', 'Per preparare il succo, i semi della melagrana sono schiacciati da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (548, 'it', 'Anguria', 'Varietà di bacca di grandi dimensioni, coltivata principalmente in Cina, Turchia e Iran. Contiene glucosio, fruttosio, pectina, calcio, magnesio, sostanze alcaline; normalizza il metabolismo. Una bacca pesa mediamente 5 kg, una fetta 300 g; è composta per il 60% da polpa e per il 40% da buccia.'),
  (454, 'it', 'Sciroppo di citronella', 'Sciroppo ottenuto mediante pastorizzazione dello sciroppo di zucchero con estratto di citronella.'),
  (433, 'it', 'Vino bianco secco', 'Vino estivo ottenuto dalla macerazione e la conseguente fermentazione di uve bianche senza buccia. Il vino viene quindi filtrato e tenuto in botti di quercia per almeno 3 mesi.'),
  (532, 'it', 'Kiwi', 'Il kiwi o uva spina cinese è il frutto commestibile di una vite legnosa che cresce in Italia, Nuova Zelanda e Cile. Contiene vitamina C, fibre, acido folico, calcio e fosforo; è noto perché potenzia il sistema immunitario. Una bacca pesa circa 120 g.'),
  (577, 'it', 'Basilico rosso', 'Erba aromatica che cresce principalmente nelle regioni calde del vecchio continente.'),
  (702, 'it', 'Sifone per panna', 'Dispositivo in vetro o in metallo che monta velocemente la panna fino a una consistenza soffice e delicata. Può essere utilizzato anche per la preparazione di vari dessert, salse elaborate e mousse. Volume standard: 50-100 cl.'),
  (399, 'it', 'Liquore alla pesca', 'Liquore del frutto del sole, ottenuto dalla distillazione del succo di pesca fermentato con l''aggiunta di cognac; per potenziarne la ricchezza del sapore; possono essere aggiunti anche i noccioli delle pesche.'),
  (396, 'it', 'Liquore all''albicocca', 'Famoso liquore fruttato, prodotto dalla distillazione del succo di albicocca fermentato con alcol dall’aroma forte, per potenziare la ricchezza del sapore.'),
  (691, 'it', 'Ciotola da punch', 'Grande recipiente in vetro, cristallo o metallo, per servire il punch, portato in Inghilterra dall''India agli inizi del secolo XVII. Capacità standard: 500 cl.'),
  (395, 'it', 'Amaretto', 'Liquore classico italiano ottenuto dalla macerazione di noccioli d''albicocca, erbe e frutti vari in alcol neutro. La base ricavata viene filtrata, addizionata di zucchero e diluita con acqua fino a raggiungere la gradazione desiderata.'),
  (556, 'it', 'Ciliegia', 'Bacca gialla o rossa che cresce sugli alberi; preferisce climi caldi e temperati di Turchia, Italia, Spagna, Cile. Contiene acidi organici, minerali, pectina, acido folico, vitamina A, C, E e B. Una bacca pesa mediamente 5 g.'),
  (437, 'it', 'Birra lager', 'Birra leggera, composta da acqua, orzo, estratto di malto, luppolo e lievito di birra.'),
  (452, 'it', 'Sciroppo di ribes nero', 'Sciroppo alle bacche, ottenuto dal succo delle bacche di ribes nero mature mescolato con acqua e zucchero.'),
  (397, 'it', 'Liquore al melone', 'Liquore tropicale asiatico, ottenuto dalla macerazione della polpa di melone in distillato neutro e acqua. Il risultato viene filtrato, regolato alla dolcezza e gradazione desiderate e imbottigliato.'),
  (763, 'it', 'Bitter lemon', 'Bevanda gassata al limone, prodotta con acqua gassata ed estratto di limone.'),
  (380, 'it', 'Becherovka', 'Liquore tipico ceco, ottenuto dalla macerazione di una miscela di 20 erbe e spezie in un distillato neutro, che, in seguito, viene mescolato con acqua e zucchero, e invecchiato per due o tre settimane in botti di quercia.'),
  (502, 'it', 'Tè Earl Grey', 'Nella sua versione classica, è un tè nero con l''aggiunta di olio ricavato dalla buccia del bergamotto. La temperatura ottimale dell’acqua per ottenere questa bevanda è 90-95 °C; dovrebbe essere lasciato in infusione per 3-5 minuti.'),
  (709, 'it', 'Ombrellino da cocktail', 'Decorazione colorata in carta per cocktail tropicali o per intrattenere i bambini.'),
  (639, 'it', 'Prugne secche', 'Una delizia europea: prugne nere essiccate al sole o in essiccatori speciali.'),
  (747, 'it', 'Tartelletta', 'Copia in miniatura di una torta, riportata per la prima volta nel libro di cucina di Re Riccardo II nel 1390. La ricetta prevede una base di pasta riempita, senza strato di copertura.'),
  (453, 'it', 'Sciroppo di mela gialla', 'Sciroppo giallo e fruttato, ottenuto dalla pastorizzazione del succo di mela gialla con l''aggiunta di zucchero di canna.'),
  (576, 'it', 'Rosmarino', 'Erba mediterranea con un profumo aromatico di pino.'),
  (409, 'it', 'Liquore al pompelmo', 'Liquore agli agrumi, prodotto dalla macerazione della scorza del pompelmo rosa in alcol neutro. Il derivato alcolico viene filtrato, mescolato con lo zucchero e diluito con acqua distillata fino alla gradazione richiesta.'),
  (549, 'it', 'Mirtillo rosso', 'Piccola bacca rossa che cresce su arbusti nani o rampicanti, principalmente negli Stati Uniti, in Cile, Argentina e Paesi Bassi. Contiene acidi organici, minerali, pectina, acido folico e vitamina A, C, E e B. Un cucchiaio da bar contiene 5 g di bacche.'),
  (492, 'it', 'Acqua tonica', 'Bevanda gassata, inventata in India per combattere la malaria. È composta da acqua gassata mescolata con chinino e una piccola quantità di zucchero.'),
  (562, 'it', 'Uva rossa', 'Bacca rossa di medie dimensioni; l’uva è il frutto di viti legnose decidue. Proviene da Stati Uniti, Cina, Italia, Francia e Spagna. Contiene zucchero, cellulosa, acidi organici, vitamina B e altri elementi in tracce; ha proprietà tonificanti e rinforzanti. Una bacca pesa in media 5 g.'),
  (663, 'it', 'Vodka all''arancia', 'Superalcolico forte e aromatizzato, prodotto mediante la distillazione multipla di cereali, soggetti a diversi livelli di filtrazione, anche al carbone attivo. Ciò che ne deriva è mescolato con acqua distillata o sorgiva. La bevanda finale viene infusa con estratto di arancia matura.'),
  (530, 'it', 'Mandarino', 'Il mandarino è un agrume di colore arancione che cresce su arbusti sempreverdi, principalmente in Cina, Spagna e Brasile. Contiene vitamina C e potassio ed è famoso perché potenzia il sistema immunitario. Un frutto pesa circa 100 g e rende 4 cl di succo.'),
  (710, 'it', 'Lillet Blanc', 'Vino francese da aperitivo, ottenuto da una combinazione di vini bianchi della regione di Bordeaux, mescolati con vari liquori alla frutta. Mentre il vino matura, le scorze di arance dolci, amare e acide insieme al chinino verde vengono messe in infusione nel distillato di brandy. In seguito, viene mescolato il tutto e tenuto in botti di quercia per 8-12 mesi.'),
  (389, 'it', 'Rum speziato', 'Superalcolico dei Caraibi, prodotto attraverso la distillazione verticale dell''alcol ottenuto dalla fermentazione della melassa o del succo estratti dalla canna da zucchero. Prima della miscelazione, è tenuto in botti di quercia bruciate, usate per bourbon o sherry, e invecchiato da 2 a 7 anni, a seconda del metodo di invecchiamento. Viene infuso con cannella, noce moscata, vaniglia e altre spezie.'),
  (398, 'it', 'Blue curaçao', 'Liquore fluorescente all''arancia, prodotto dalla macerazione di scorze d''arancia essiccate in alcol neutro e acqua. Il derivato viene filtrato, mescolato con zucchero e colorato con coloranti naturali.'),
  (550, 'it', 'Uva bianca', 'Bacche verdi di medie dimensioni che crescono su viti legnose. Proveniente da Cina, USA, Italia, Francia e Spagna, l’uva bianca contiene zucchero, cellulosa, acidi organici, vitamina B e altri elementi; ha un effetto rinforzante e tonificante. Una bacca pesa mediamente 5 g.'),
  (533, 'it', 'Mango', 'Frutto selvatico tropicale che cresce principalmente in India, Pakistan e Filippine. Contiene vitamina A, acido folico e potassio; aiuta a migliorare il sistema immunitario e la vista. Un frutto pesa mediamente 300 g e può essere tagliato in 10 fette.'),
  (408, 'it', 'Liquore alla cannella', 'Liquore speziato tedesco, prodotto dalla macerazione della cannella nello schnapps. Il derivato viene filtrato e mescolato allo zucchero, poi si aggiunge oro alimentare in foglia per dare vivacità.'),
  (495, 'it', 'Tè verde freddo', 'Popolare in Asia, è a base di tè verde e altre erbe senza alcun aroma e conservante artificiale.'),
  (711, 'it', 'Passino Julep', 'Accessorio indispensabile quando si lavora con il mixing glass. In più, può fungere da originale decorazione per il classico cocktail omonimo. Utilizzato per filtrare i cocktail, trattenendo pezzetti di ghiaccio tritato e altri ingredienti indesiderati.'),
  (670, 'it', 'Caffè espresso', 'Caffè forte, preparato facendo filtrare una piccola quantità di acqua bollente a 90° C attraverso il caffè macinato.'),
  (690, 'it', 'Bicchiere da tè', 'Tazza da tè tradizionale turca; volume standard: 4-8 cl.'),
  (412, 'it', 'Liquore al frutto della passione', 'Ottenuto dalla polpa di frutti della passione maturi, arance e pompelmi, mescolati con alcol e lasciati in infusione.'),
  (615, 'it', 'Zucchero vanigliato granulato', 'Zucchero classico aromatizzato alla vaniglia.'),
  (181, 'it', 'Caffettiera francese', 'Accessorio francese per fare tè e caffè, composto da un contenitore di vetro con un passino e uno stantuffo.'),
  (448, 'it', 'Sciroppo di fragole', 'Sciroppo di bacche, ottenuto dalla pastorizzazione del succo di fragole mature mescolate con acqua e zucchero.'),
  (567, 'it', 'Peperoncino', 'I peperoncini tropicali crescono sui cespugli, soprattutto in Sud America. Contengono vitamina A e C oltre a potassio, magnesio e ferro. Un peperoncino pesa in media 30 g.'),
  (499, 'it', 'Tè nero', 'Un tipo di tè sottoposto a fermentazione per un periodo che va da due settimane a un mese. Cresce in regioni dal clima tropicale e subtropicale. Per ottenere la bevanda, aggiungere ad un cucchiaino di tè 10 cl di acqua bollente; lasciare riposare per 4-5 minuti.'),
  (411, 'it', 'Liquore al mango', 'Liquore tropicale asiatico, prodotto dalla macerazione della polpa dei mango maturi in alcol neutro e acqua. L''alcolico che ne risulta viene filtrato e mescolato con lo zucchero.'),
  (514, 'it', 'Gelato alla vaniglia', 'Dessert surgelato, preparato con latte, panna, burro e zucchero con aggiunta di estratto di vaniglia. Conservato in freezer dura al massimo un mese.'),
  (592, 'it', 'Confettura di ciliegia', 'Confettura di bacche gialle o rosse, coltivate principalmente nei climi temperati di Turchia, Italia, Spagna e Cile. Le ciliegie mature denocciolate vengono fatte bollire con lo zucchero fino ad ottenere una consistenza omogenea. Un cucchiaio da bar può contenere 5 g di confettura.'),
  (485, 'it', 'Succo di pesca', 'Per preparare il succo, le pesche sono schiacciate da una pressa; il succo ottenuto è quindi filtrato e imbottigliato.'),
  (387, 'it', 'Vodka al ribes nero', 'Superalcolico forte e aromatizzato, prodotto mediante la distillazione multipla di cereali, soggetti a diversi livelli di filtrazione, anche al carbone attivo. Ciò che ne deriva è mescolato con acqua distillata o sorgiva. La bevanda finale viene infusa con estratto di ribes nero maturo.'),
  (633, 'it', 'Acqua di rose', 'Antica ricetta di acqua profumata con infuso di petali di rose.'),
  (713, 'it', 'Purea di lampone', 'Purea di lampone'),
  (586, 'it', 'Timo', 'Erba aromatica che si presenta come piccoli arbusti e cresce principalmente in Eurasia, Nord Africa e Groenlandia. Usata nei mix provenzali, è ideale per aromatizzare distillati forti.'),
  (407, 'it', 'Liquore al cocco', 'Liquore Tropical Tiki, ottenuto dalla macerazione della polpa di cocco in varietà di rum. Il derivato alcolico viene filtrato, mescolato con zucchero e diluito con acqua fino a raggiungere la gradazione desiderata.'),
  (430, 'it', 'Vermouth rosé', 'Una categoria relativamente ristretta di vermouth, ottenuto dalla macerazione di erbe e spezie alpine in vino rosé. Il risultato viene filtrato, regolato alla dolcezza e gradazione desiderate e invecchiato in botti di quercia per almeno un anno.'),
  (646, 'it', 'Cioccolato fondente', 'Prodotto confezionato, ottenuto da fave di cacao amaro con poco o senza zucchero aggiunto.'),
  (447, 'it', 'Sciroppo al caramello', 'Popolare sciroppo, ottenuto dal caramello liquido con l''aggiunta di vaniglia e acqua.'),
  (750, 'it', 'Tovaglioli', 'Salviette in cotone o carta, spesso usate come sottobicchieri per i drink.'),
  (360, 'it', 'Sifone per soda', 'Dispositivo in vetro o metallo per drink frizzanti; volume standard: 100-200 cl.'),
  (500, 'it', 'Chicchi di caffè', 'Chicchi tostati dell''albero del caffè; sostanza nota per il suo effetto stimolante grazie al contenuto di caffeina. Esistono due varietà principali di caffè: arabica e robusta.'),
  (565, 'it', 'Sake', 'Liquore giapponese ricavato dal riso messo in ammollo e cotto al vapore. Il preparato è arricchito con saccaromiceti e tenuto in una stanza calda e umida per circa 2 giorni. Al termine della fermentazione, il sake è conservato in recipienti sigillati per 6-12 mesi.'),
  (537, 'it', 'Kumquat', 'Agrume di dimensioni ridotte che cresce su piccoli alberi, soprattutto in Cina, Corea e Giappone. Contiene vitamina C, ferro e magnesio che contribuiscono a combattere le infezioni. Un frutto pesa in media 10g.'),
  (685, 'it', 'Bicchiere da cognac', 'Bicchiere classico da cognac o brandy; capacità standard: 17-40 cl.'),
  (423, 'it', 'Southern Comfort', 'Inventato dal barman Martin Heron nel 1874, è un liquore alla frutta prodotto secondo un''antica ricetta a base di whiskey americano con l''aggiunta di essenze di frutta ed erbe, zucchero e caramello; successivamente invecchiato in botti di quercia fino alla maturità desiderata.'),
  (703, 'it', 'Padella', 'Antico utensile da cucina, necessario nel bar per preparazioni flambé di bacche e frutta.'),
  (688, 'it', 'Set da degustazione', 'Set da degustazione composto da un vassoio di vetro da riempire di ghiaccio, per far sì che gli shot da degustazione restino freschi.'),
  (462, 'it', 'Sciroppo di litchi', 'Sciroppo di frutta asiatica, ottenuto dalla pastorizzazione del succo di litchi mescolato con acqua e zucchero.'),
  (504, 'it', 'Tè alla camomilla', 'Infuso di fiori secchi di camomilla; in genere, acqua bollente viene aggiunta ai fiori in proporzione di 1-2 cucchiaini per 20 cl di acqua; si lascia quindi riposare per 7-10 minuti, si filtra e si beve al naturale o con l''aggiunta di zucchero o miele.'),
  (673, 'it', 'Confettura di olivello spinoso', 'Confettura ottenuta da piccole bacche gialle, che crescono in cespugli decidui soprattutto sulla costa atlantica dell’Europa e della Cina Nord-Occidentale. I frutti maturi vengono fatti bollire con lo zucchero fino ad ottenere una consistenza omogenea. Un cucchiaio da bar può contenere 5 g di confettura.'),
  (769, 'it', 'Piattino', 'Piccolo piatto in vetro, porcellana o metallo, che accompagna di solito una tazza. L’interpretazione moderna considera una coppa da cocktail posata su un piattino espressione di un servizio più ricercato ed elegante.'),
  (463, 'it', 'Sciroppo di mango', 'Sciroppo di frutta asiatica, ottenuto dalla pastorizzazione del succo di mango mescolato con acqua e zucchero di canna.'),
  (700, 'it', 'Porta bicchieri da tè', 'Porta bicchieri in metallo provvisto di un manico che permette di tenere il bicchiere e bere un drink caldo senza scottarsi le mani.'),
  (695, 'it', 'Forchetta', 'Posata composta da un manico e diversi rebbi (solitamente tra i due e i quattro) su un solo lato. Utilizzata per preparare cibi oltre che per mangiare e tenere ferme parti di cibo.'),
  (445, 'ru', 'Сироп корицы', 'Знаменитый пряный сироп производят методом мацерации и пастеризации корицы в сахарном сиропе с последующей стабилизацией.'),
  (176, 'ru', 'Лаймовый сок', 'Для производства сока лаймы пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (482, 'ru', 'Яблочный сок', 'Для производства сока яблоки пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (767, 'ru', 'Белок перепелиного яйца', 'Продукт славится своими гипоаллергенными свойствами. Чтобы придать коктейлю с этим ингредиентом нежную и пенистую текстуру рекомендуется использовать метод приготовления «драй шейк».'),
  (217, 'ru', 'Огурец', 'Стелющаяся плодовая культура, растущая преимущественно в странах Средиземноморья. Нормализует обмен веществ, улучшает работу сердца и почек. Один плод весит в среднем 150 г, разрезается на 10 кружков или полосок.'),
  (31, 'ru', 'Лед в кубиках', 'При производстве этого незаменимого ингредиента основное внимание уделяют чистоте воды и скорости заморозки. Чем медленнее замораживается вода, тем прозрачнее получается продукт. Идеальные образцы не имеют полостей и медленнее тают в бокале.'),
  (210, 'ru', 'Шампанское блюдце', 'Бокал на высокой тонкой шпильке, по легенде повторяющий силуэт фаворитки французского короля. Служит для подачи шампанского и коктейлей категории тини. Стандартный объем: 200–300 мл.'),
  (68, 'ru', 'Шейкер', 'Свой нынешний облик получил в конце 1800-х, а особую популярность приобрел в 1920–1930-е годы, примерив десятки стилей и форм. Разделяют коблер со встроенным стрейнером, французский без стрейнера и бостонский, состоящий из двух равных стаканов. Стандартный объем: 500–700 мл.'),
  (69, 'ru', 'Стрейнер', 'Аксессуар, незаменимый в работе с бостонским или французским шейкером. Служит для фильтрации коктейля от косточек цитрусовых, отколовшихся кусочков льда и других незапланированных ингредиентов.'),
  (73, 'ru', 'Джиггер', 'Гарант мер и идеальных пропорций в коктейле. В арсенале лучших бартендеров всегда представлен в разных версиях: 20–40 мл, 25–50 мл и 30–60 мл.'),
  (70, 'ru', 'Пресс для цитрусовых', 'Незаменимый инструмент, помогающий выжимать сок лаймов или лимонов. Несмотря на то что сегодня в большинстве популярных заведений сок цитрусовых выжимают заранее, свежевыжатый сок считается высшим уровнем качества.'),
  (239, 'ru', 'Соковыжималка', 'Выжимает сок из любых овощей или фруктов. В отличие от ручного пресса, электрический механизм отделяет сок от мякоти с помощью центрифуги.'),
  (1, 'ru', 'Водка', 'Самый популярный крепкий алкоголь производят методом многократной перегонки зернового спирта, прошедшего разные степени очистки угольными и другими фильтрами и смешанного с чистой водой.'),
  (55, 'ru', 'Кофейный ликер', 'Знаменитый стимулирующий ликер производят методом перколяции зерен кофе разных сортов с нейтральным спиртом. Получившуюся основу, не фильтруя, смешивают с жженым сахаром и разбавляют водой до нужной крепости.'),
  (65, 'ru', 'Рокс', 'Широкий стакан с толстым дном для подачи крепких мужских коктейлей или крепкого алкоголя в чистом виде. Стандартный объем: 200–300 мл.'),
  (64, 'ru', 'Коктейльная ложка', 'Незаменимый инструмент бармена служит для приготовления коктейлей в смесительном стакане и укладки слоев в шотах, используется также как мера измерения, вмещающая 5 мл жидких ингредиентов или 5 г сыпучих.'),
  (57, 'ru', 'Трубочки', 'В 1888 году владелец фабрики бумажных мундштуков Марвин Стоун придумал лучший аксессуар для распития напитков из бокала. Джозеф Фридман сколотил состояние, доработав их гибким гофрированным участком. Последним этапом стал переход на пластик.'),
  (799, 'ru', 'Лондонский сухой джин', 'Крепкий алкоголь изготавливается в вертикальных перегонных кубах, зерновой спирт настаивают в течение суток на можжевельнике и десятке других трав и специй, а затем дистиллируют и разливают в бутылки.'),
  (54, 'ru', 'Трипл сек', 'Культовый цитрусовый ликер тройной сухости производят методом мацерации цедры апельсинов курасао в нейтральном спирте с водой. Получившаяся основа перед розливом проходит тройную дистилляцию с сохранением высокой крепости.'),
  (9, 'ru', 'Лимонный сок', 'Для производства сока лимоны пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (734, 'ru', 'Лимонная цедра', 'Верхний слой кожуры лимона, который срезают специальным острым ножом. Содержит эфирные масла, определяющие аромат. Цедра может быть срезана как с части, так и со всего лимона целиком, мелко натерта и даже закручена в спираль, называемую твистом.'),
  (66, 'ru', 'Бокал сауэр', 'Маленький бокал для взбитых напитков одноименной группы, созданных на основе цитрусовых, сахара и крепкого алкоголя. Стандартный объем: 90–120 мл.'),
  (71, 'ru', 'Нож для цедры', 'Вид оружия бармена из японской культуры карвинга. Служит для срезания тонких полосок цедры, вырезания кружков из яблок или создания широких твистов.'),
  (143, 'ru', 'Мескаль', 'Мексиканский крепкий алкоголь производят традиционным методом, включающим копчение агавы без листьев на раскаленных вулканических камнях под слоем земли. Так напиток приобретает копченый аромат. После этого пиньи размалывают, сок сбраживают и выдерживают в дубовых бочках не менее четырех месяцев.'),
  (224, 'ru', 'Зеленый базилик', 'Пряно-ароматная трава, растущая преимущественно в теплых областях Старого Света. Зеленые листья завоевали особую популярность благодаря ставшему уже классическим коктейлю «Базиликовый удар».'),
  (223, 'ru', 'Кардамон', 'Цейлонская приправа, растущая на травянистых растениях семейства имбирных. Считается одной из самых ярких специй в мире.'),
  (566, 'ru', 'Корень имбиря', 'Азиатское многолетнее растение, завезенное в Европу еще в средние века. Корневище имеет вид округлых кусочков, полезных для поднятия иммунитета и снятия головных болей. Один кружок корня весит в среднем 5 г.'),
  (83, 'ru', 'Дробленый лед', 'Первый «бритый» лед бармены срезали специальными ножами с больших ледяных плит. Позже появились дробильные машинки и ледогенераторы.'),
  (117, 'ru', 'Ситечко', 'Используют совместно с шейкером и стрейнером для двойного процеживания коктейля при переливании из шейкера в бокал. Более мелкая, чем у стрейнера, сетка не допускает попадания в напиток даже самых мелких фруктовых косточек и льдинок.'),
  (52, 'ru', 'Мадлер', 'Незаменимый аксессуар для тропических коктейлей – им давят ягоды и фрукты в шейкере или сразу в бокале.'),
  (373, 'ru', 'Прищепки', 'Декоративный аксессуар служит для крепления украшений к бокалу.'),
  (113, 'ru', 'Абсент', 'Крепкий алкоголь производят методом мацерации ароматных трав и специй, в том числе мелиссы, фенхеля и бадьяна, на зерновом или винном спирте. Основной компонент – полынь. Входящий в ее состав туйон отвечает за одурманивающий эффект.'),
  (295, 'ru', 'Сахарный сироп', 'Самый распространенный коктейльный сироп производят из натурального экстракта сахарного тростника, смешанного с водой.'),
  (152, 'ru', 'Малина', 'Небольшая красная ягода, растущая на многолетних полукустарниках преимущественно в России, Сербии, Польше и США. Содержит сахара, органические кислоты, витамины А, B, С, жирные масла. Одна ягода весит в среднем 5 г.'),
  (125, 'ru', 'Односолодовый виски из Хайленда', 'Односолодовый виски, на протяжении двух столетий дистиллируемый на берегу живописной реки Спей. The Macallan Fine Oak отличается уникальной технологией выдержки в трех различных типах дубовых бочек: европейских и американских из-под хереса Олоросо и американских из-под бурбона. В аромате слышны цветочные и фруктовые тона, окутанные шлейфом ванили и марципана. В продолжительном послевкусии отчетливо раскрываются сухофрукты и пряности.'),
  (47, 'ru', 'Красный биттер', 'Красный биттер производят в Италии по секретной рецептуре с 1872 года. Настойка на ароматических травах и кореньях содержит 20 ингредиентов, в том числе три редких: шафран, ангостуру и коломбо.'),
  (189, 'ru', 'Грейпфрутовый сок', 'Для производства сока грейпфруты пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (672, 'ru', 'Мята', 'Самая разрекламированная трава в коктейльном мире насчитывает более 30 видов. В миксологии используют преимущественно перечную и сладкую мяту. Хранится в холодильнике в бумажном полотенце не более двух суток.'),
  (371, 'ru', 'Свизл стик', 'Небольшая палочка из древесины кварарибии с отростками ветвей, формирующих форму своеобразного миксера. Идеально подходит для смешивания коктейлей, поданных с дробленым льдом прямо в бокале.'),
  (124, 'ru', 'Зеленый шартрез', 'Монастырский ликер из Французских Альп производят с 1764 года по секретному рецепту. Около 130 растений и трав подвергают мацерации в нейтральном спирте и несколько раз дистиллируют. Получившуюся основу балансируют сахаром, доводят до нужной крепости и выдерживают в дубовых бочках.'),
  (427, 'ru', 'Ликер из цветков бузины', 'Французский цветочный ликер производят секретным методом мацерации измельченных цветков бузины в нейтральном спирте. Получившуюся основу фильтруют, смешивают с сахаром и разбавляют водой до нужной крепости.'),
  (35, 'ru', 'Сухой вермут', 'Легкий итальянский аперетив, представленный в 1900 году, работа над созданием идеального рецепта которого заняла целых 10 лет. Сухой вермут основан на сложном букете множества экзотических растений, благодаря чему обладает особым вкусом и деликатным ароматом, в котором можно различить нотки малины и лимона на фоне эссенции ириса, с легкими штрихами дерева и хереса. Все это венчает сбалансированное свежее послевкусие с кислинкой. Уникальность этого напитка делает его незаменимым компонентом многих коктейлей.'),
  (130, 'ru', 'Ликер Драй Оранж', 'Ароматный цитрусовый ликер производят методом мацерации цедры апельсинов лараха в нейтральном спирте с водой. Получившуюся основу фильтруют, смешивают с сахаром и выдерживают в дубовых бочках.'),
  (114, 'ru', 'Пишо биттер', 'Новоорлеанский классический биттер, придуманный знаменитым аптекарем в 1830-х годах, производят по секретной рецептуре методом мацерации в нейтральных спиртах аниса, гвоздики, ванили, мускатного ореха, ягод и специй.'),
  (161, 'ru', 'Кубок', 'Королевский бокал с утолщенным стеклом, позволяющийся чокнутся с соседом так, чтобы напитки в бокалах перехлестнулись. Стандартный объем: 200–300 мл.'),
  (665, 'ru', 'Ликер мараскино', 'Ягодный ликер родом из Хорватии производят методом мацерации ягод и косточек вишни сорта мараскино в нейтральном спирте с водой не менее месяца. Получившуюся основу фильтруют, подслащивают, доводят до нужной крепости и выдерживают в дубовых бочках не менее трех лет.'),
  (303, 'ru', 'Грейпфрутовый биттер', 'Летний биттер производят методом мацерации в нейтральных спиртах цедры грейпфрута с добавлением смягчающего горечь растительного хмеля.'),
  (20, 'ru', 'Коктейльная вишня красная', 'Ягоды сортов "королевская Анна", "райнер" или "золотое разнообразие" помещают в соляной раствор, затем вымачивают в сахарном сиропе с добавлением красителя.'),
  (96, 'ru', 'Коктейльная шпажка', 'Декоративный аксессуар для подачи оливок к мартини или коктейльной вишни к коктейлю «Манхэттен». Появился в барах в конце XIX века благодаря маркетинговому гению Чарльзу Форстеру.'),
  (101, 'ru', 'Выдержанный ром', 'Карибский крепкий алкоголь получают методом вертикальной перегонки спирта, полученного путем брожения патоки или сока из сахарного тростника. Перед купажированием выдерживают в обожженных дубовых бочках из-под хереса или бурбона от 7 до 20 лет в зависимости от выбранного метода старения.'),
  (116, 'ru', 'Какао ликер коричневый', 'Темный шоколадный ликер производят методом перколяции какао-бобов с нейтральным спиртом. Получившуюся основу разбавляют водой до нужной крепости и смешивают с мадагаскарской ванилью и карамелью, которая придает ликеру темный цвет.'),
  (67, 'ru', 'Стакан для смешивания', 'Классический стакан с барной стойки пятизвездочного отеля. Служит для приготовления крепких мужских напитков без добавления соков, травок и джемов. Лед не деформируется и не успевает растаять, сохраняя крепость напитков. Стандартный объем: 500–900 мл.'),
  (166, 'ru', 'Амаро', 'Итальянский дижестивный ликер производят методом мацерации трав и кореньев, в том числе можжевельника, фенхеля, мелиссы, бадьяна и кардамона, а также цедры цитрусовых в нейтральном спирте. Получившуюся основу фильтруют, смешивают с сахаром и разбавляют водой до нужной крепости.'),
  (171, 'ru', 'Ледяная сфера', 'Гордость японских барменов – лед, возведенный в ранг предмета искусства. Сегодня все чаще появляется в барах благодаря специальным машинкам. В легко нагреваемые тиски помещают заготовленный ледяной куб, металл разогревают водой и обрезают лед по заранее заготовленному шарообразному контуру.'),
  (3, 'ru', 'Лимон', 'Тропический цитрусовый фрукт, растущий на небольших вечнозеленых деревьях преимущественно в Китае, Индии и Мексике. Содержит витамин С и органические кислоты, незаменим при авитаминозах и простуде. Один плод весит 160 г и дает 60 мл сока, разрезается на 8 кружков или 4 крупные дольки по 15 мл каждая.'),
  (62, 'ru', 'Бурбон', 'Крепкий алкоголь, согласно законам, производится с содержанием не менее 51% кукурузного солода, а также ячменя и ржи, дистиллированных и отфильтрованных. Спирты выдерживаются в дубовых бочках не менее 2 лет.'),
  (111, 'ru', 'Черносмородиновый ликер', 'Дижонский ягодный ликер производят методом мацерации ягод черной смородины в нейтральном спирте с водой сроком до двух месяцев. Первый сок без отжима фильтруют и смешивают с сахаром.'),
  (63, 'ru', 'Ангостура биттер', 'Рецептура, созданная доктором Йоханном Готтлибом Бенджамином Зигертом, хранится в секрете. При изготовлении пряности настаивают на 97%-ном спирте, затем добавляют тростниковый сахар и дистиллированную воду.'),
  (16, 'ru', 'Нежирные сливки', 'Производят преимущественно из коровьего молока методом частичной сепарации – отделения сливок от молока. Процент жирности в разных странах разнится, но не превышает 15%. Хранится в холодильнике не более 20 дней.'),
  (36, 'ru', 'Красный вермут', 'Своим рождением знаменитый вермут обязан союзу вина, спирта, сахара и 35 альпийским травам и пряностям. Созданный в 1863 году самим Луиджи Росси, оригинальный красный вермут являет собой настоящую икону di Italia и является символом итальянского аперитива. Терпкие пряные ноты напитка отлично дополнят тоник и долька апельсина - такой напиток идеально подойдёт к лёгкому ужину с друзьями.'),
  (34, 'ru', 'Содовая', 'Газированную воду, ставшую незаменимым компонентом физзов и других газированных напитков, ранее производили методом газирования углекислым газом, а сегодня все чаще готовят, добавляя пищевую соду к нейтральной чистой воде.'),
  (732, 'ru', 'Апельсиновая цедра', 'Верхний слой кожуры грейпфрута, который срезают специальным острым ножом. Содержит эфирные масла, определяющие аромат. Цедра может быть срезана как с части, так и со всего грейпфрута целиком, мелко натерта и даже закручена в спираль, называемую твистом.'),
  (258, 'ru', 'Просекко', 'Согласно Апелласьону 2009 года, Просекко могут называться лишь вина с виноградников данного региона. Собранный вручную виноград Глера подвергается брожению в вакуумной таре, что позволяет сохранять его вкус намного дольше. Просекко отличается выразительным ароматом с оттенками цветов и цитрусов, обладает притяным вкусом с нежным фруктовым наполнением и тонкой минеральностью в послевкусии. Идеально в гастрономическом сочетании с морепродуктами и твердыми сырами.'),
  (148, 'ru', 'Персиковое пюре', 'Мякоть солнечного фрукта, растущего на лиственных деревьях преимущественно в Китае, Италии и Испании, смешивают с сахаром в равных пропорциях и пастеризуют для сохранения неизменного вкуса зрелых плодов круглый год.'),
  (535, 'ru', 'Персик', 'Солнечный фрукт, растущий на лиственных деревьях преимущественно в Китае, Италии и Испании. Содержит органические кислоты, минеральные соли и пектины. Один плод весит в среднем 120 г, из которых можно получить 80 г пюре.'),
  (59, 'ru', 'Флюте', 'Светский бокал для коктейлей на основе шампанского и игристых вин. Удлиненная узкая форма, напоминающая тюльпан, сохраняет максимум пузырьков в коктейле, позволяя ему долго оставаться искрящимся. Стандартный объем: 180–250 мл.'),
  (179, 'ru', 'Лаймовый кордиал', 'Старинный цитрусовый сироп производят методом пастеризации сока лайма, смешанного с сахарным сиропом, винным камнем и водой.'),
  (733, 'ru', 'Лаймовая цедра', 'Верхний слой кожуры лайма, который срезают специальным острым ножом. Содержит эфирные масла, определяющие аромат. Цедра может быть срезана как с части, так и со всего лайма целиком, мелко натерта и даже закручена в спираль, называемую твистом.'),
  (72, 'ru', 'Коктейльный бокал', 'Или мартини, один из первых в мире бокалов для подачи коктейлей безо льда. Перед подачей бокал обязательно охлаждают, а длинная ножка не дает коктейлю согреться от руки. Стандартный объем: 90–160 мл.'),
  (40, 'ru', 'Коньяк', 'Французский коньяк, созданный из коньячных спиртов, которые прошли двойную дистилляцию в шарантских перегонных кубах и не менее 3-х лет выдерживались в бочках из французского дуба.'),
  (14, 'ru', 'Мускатный орех молотый', 'Индонезийская приправа, созданная из орехов мускатного дерева, высушенных и перемолотых в порошок.'),
  (746, 'ru', 'Терка для муската', 'Полезный аксессуар для получения пудры из мускатного ореха или шоколада, реже – мелко натертой цедры цитрусовых.'),
  (8, 'ru', 'Апельсиновый сок', 'Для производства сока апельсины пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (88, 'ru', 'Белый ром', 'Карибский крепкий алкоголь получают методом вертикальной перегонки спирта, полученного путем брожения патоки или сока из сахарного тростника. Перед купажированием выдерживают не менее 12 месяцев в обожженных дубовых бочках из-под бурбона и фильтруют, чтобы обесцветить напиток'),
  (92, 'ru', 'Кальвадос', 'Производство крепкого французского алкоголя начинают с сидра, который делают методом ферментации сока осенних нормандских яблок с прессованной мякотью в стальных чанах от полугода до года. Затем напиток подвергают двойной дистилляции и выдерживают в дубовых бочках не менее двух лет.'),
  (77, 'ru', 'Гренадин', 'Популярный сироп производят методом пастеризации гранатового сока с добавлением соков других красных ягод, ванили и тростникового сахара.'),
  (86, 'ru', 'Темный ром', 'Карибский крепкий алкоголь получают методом вертикальной перегонки спирта, полученного путем брожения патоки или сока из сахарного тростника. Перед купажированием выдерживают от 2 до 7 лет в обожженных дубовых бочках из-под бурбона и не фильтруют для сохранения цвета.'),
  (365, 'ru', 'Сверхкрепкий ром', 'Карибский сверхкрепкий алкоголь получают методом вертикальной перегонки спирта, полученного путем брожения патоки или сока из сахарного тростника. Перед купажированием выдерживают не менее года в обожженных дубовых бочках из-под бурбона и не разбавляют водой для сохранения крепости.'),
  (190, 'ru', 'Грейпфрут', 'Популярный цитрусовый фрукт, растущий кластерами на деревьях преимущественно в Китае, США и Мексике. Содержит витамин С, пектин и ликопен, снижающий уровень холестерина. Один плод весит в среднем 600 г, разрезается на 10 кружков или долек и дает 200 мл сока.'),
  (186, 'ru', 'Тики-бокал', 'Керамический истукан, изначально символизирующий полинезийских богов, служит для подачи тики-коктейлей.'),
  (662, 'ru', 'Ирландский виски', 'Ирландский крепкий алкоголь производят в ирландском городе Талламор из трех видов спирта: солодового, зернового и смеси соложенного и не соложенного ячменя. Зерна перемалывают и смешивают с водой до кашеобразного состояния. Отделив жидкость от зернового остатка, ее сбраживают и трижды перегоняют. Получившиеся спирты оставляют вызревать в трех типах дубовых бочек из-под бурбона и хереса.'),
  (128, 'ru', 'Жирные сливки', 'Производят преимущественно из коровьего молока методом частичной сепарации – отделения сливок от молока. Процент жирности в разных странах разнится от 20 до 40%. Хранится в холодильнике не более 20 дней.'),
  (74, 'ru', 'Миска', 'Стеклянная или металлическая емкость для взбивания ингредиентов при помощи венчика. Для миксов с добавлением томатного или цитрусового соков используют только стеклянные миски или из нержавеющей стали, не реагирующие на кислоту.'),
  (90, 'ru', 'Бокал для ирландского кофе', 'Крепкий бокал для подачи горячих грогов, глинтвейнов и коктейлей с кофе, в честь одного из которых он и назван. Стандартный объем: 200–300 мл.'),
  (78, 'ru', 'Венчик', 'Незаменим для приготовления пены из сливок для «Ирландского кофе» или взбивания яичного желтка с сахаром для «Том и Джерри». Для смешивания или взбивания ингредиентов в кувшинах используют версию с удлиненной ручкой и маленьким наконечником на конце.'),
  (761, 'ru', 'Кофемашина', 'Автоматическая машина для приготовления кофе разных видов: латте, эспрессо, американо, латте маккиято, капучино и гляссе.'),
  (39, 'ru', 'Кашаса', 'Бразильский крепкий алкоголь производят методом тщательной фильтрации и дистилляции забродившего сока сахарного тростника по единой схеме: «голову» и «хвост» отбрасывают, оставляя лишь «сердце» напитка для дальнейшей выдержки в бочках из дуба не менее года.'),
  (5, 'ru', 'Лайм', 'Тропический цитрусовый фрукт, растущий на низкорослых деревьях преимущественно в Китае, Индии и Мексике. Содержит клетчатку, витамин С и кальций, хорошо раскрывает аромат и вкус других продуктов. Один плод весит в среднем 80 г и дает 30 мл сока, разрезается на 4 дольки по 7,5 мл каждая или 8 кружков.'),
  (43, 'ru', 'Малиновый сироп', 'Популярный ягодный сироп производят методом пастеризации сока ягод малины, смешанного с сахаром и водой.'),
  (661, 'ru', 'Цитрусовая водка', 'Крепкий ароматизированный алкоголь производят методом многократной перегонки зернового спирта, прошедшего разные степени очистки угольными и другими фильтрами и смешанного с чистой водой. Получившийся напиток ароматизируют экстрактами цитрусовых, в том числе и лайма.'),
  (481, 'ru', 'Клюквенный сок', 'Для производства сока ягоды клюквы пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (53, 'ru', 'Горелка', 'Аксессуар джентльмена, позволяющий поджечь эфирные масла над знаменитым «Космополитеном», посыпать искрящейся корицей тики-коктейль или просто дать прикурить гостю сигару.'),
  (82, 'ru', 'Портвейн Тони', 'Насыщенный красный портвейн производят из смеси красных выдержанных вин с добавлением коньячных спиртов и их последующей выдержкой в дубовых бочках методом солера.'),
  (49, 'ru', 'Желток перепелиного яйца', 'Продукт славится своими гипоаллергенными свойствами и придает коктейлям нежную текстуру.'),
  (178, 'ru', 'Ножницы для перепелиных яиц', 'Специальные ножницы с кольцом для фиксации яйца и лезвием, делающим надрез словно циркулем.'),
  (569, 'ru', 'Сельдерей', 'Зонтичное растение, известное еще древним грекам, растет преимущественно в умеренном климате. Волокна перед подачей удаляют, сделав небольшой надрез на стебле и потянув за «нити». Один стебель весит в среднем 15 г.'),
  (42, 'ru', 'Табаско соус красный', 'Красный перечный соус производят из отборных спелых перцев чили, выдержанных в течение трех лет в бочках из лимузенского дуба в соли с Эйвери Айленд. Полученную основу сдабривают уксусом и оставляют еще на четыре недели. На вкус более острый, чем его зеленая версия.'),
  (56, 'ru', 'Черный перец молотый', 'Индийская молотая приправа, полученная из недозревших ягод черного перца, высушенных на солнце до черноты. В отличие от гранулированной версии аромат улетучивается гораздо быстрее.'),
  (58, 'ru', 'Хайбол', 'Высокий бокал для подачи воды, соков или клубных миксов, смешанных методом билд – сразу в стакане. Стандартный объем: 300–400 мл.'),
  (37, 'ru', 'Российский виски', 'Зерновой российский виски производится из смеси ячменя, кукурузы, ржи и пшеницы путем непрерывной дистилляции в медной колонне с отбором необходимых фракций. Получившиеся спирты оставляют вызревать в комбинированных дубовых бочках, в составе которых преобладает кавказский дуб. Именно многозерновой состав и исконно российский вид дуба обеспечивают яркий аромат и мягкий вкус с пикантными нотами специй и характерным оттенком поджаренного тоста бородинского хлеба.'),
  (46, 'ru', 'Вишневый ликер', 'Знаменитый ягодный ликер производят методом мацерации вишни разных сортов в нейтральном спирте с водой не менее месяца. Получившуюся основу фильтруют, подслащивают, закрепляют коньячными спиртами и выдерживают в дубовых бочках не менее трех лет.'),
  (89, 'ru', 'Золотой ром', 'Карибский крепкий алкоголь получают методом вертикальной перегонки спирта, полученного путем брожения патоки или сока из сахарного тростника. Перед купажированием выдерживают от 1 до 5 лет в обожженных дубовых бочках из-под бурбона, не фильтруют, иногда подкрашивают карамелью.'),
  (94, 'ru', 'Кола', 'Самый популярный сильногазированный напиток производят по секретной рецептуре на основе кофеина, сахара, ароматизаторов и красителей.'),
  (60, 'ru', 'Какао ликер светлый', 'Светлый шоколадный ликер производят методом перколяции какао-бобов с нейтральным спиртом. Получившуюся основу фильтруют, избавляясь от темного цвета, доводят до нужной крепости и смешивают с сахаром до кремовой консистенции.'),
  (61, 'ru', 'Мятный ликер зеленый', 'Кремовый травяной ликер производят с большим количеством сахара методом перколяции экстрактов свежей перечной мяты с лаймовыми дистиллятами в нейтральном спирте. Получившуюся основу доводят до нужной сладости и крепости и разливают в бутылки.'),
  (93, 'ru', 'Серебряная текила', 'Мексиканский крепкий алкоголь традиционно производят методом перегонки из сока голубой агавы, выращенной на высокогорье Лос-Альтос. Семилетние пиньи помещают в специальные печи для преобразования крахмала в сахар, затем получившийся сок фильтруют и ферментируют, подвергают двойной дистилляции в медных кубах, несколько дней выдерживают в стальных резервуарах и разливают в бутылки.'),
  (212, 'ru', 'Имбирное пиво', '«Троянский конь» водки в Америке. Этот особый сорт пряного лимонада производят методом мацерации сушеного молотого имбиря в пивной закваске.'),
  (99, 'ru', 'Миндальный сироп', 'Ореховый сироп производят на основе экстракта очищенного миндаля с добавлением апельсиновой воды, тростникового сахара и чистой воды.'),
  (127, 'ru', 'Соль', 'Кристаллическая приправа из минералов, возраст которых может достигать 250 млн лет и более.'),
  (84, 'ru', 'Бокал маргарита', 'В прошлой жизни соусник для гуакамоле сегодня выступает в роли фирменного бокала для подачи самого популярного в мире коктейля на основе текилы. Стандартный объем: 250–350 мл.'),
  (85, 'ru', 'Апельсиновый биттер', 'Старейший цитрусовый биттер производят методом мацерации в ромовых спиртах подсушенной цедры апельсинов, специй и кореньев с добавлением тростникового сахара и дистиллированной воды.'),
  (75, 'ru', 'Сироп маракуйи', 'Тропический фруктовый сироп производят методом пастеризации сока из мякоти маракуйи, смешанного с тростниковым сахаром и водой.'),
  (7, 'ru', 'Ананасовый сок', 'Для производства сока мякоть ананаса пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (76, 'ru', 'Харрикейн', 'Антикварная керосиновая лампа-бокал для подачи тропических напитков, названная в честь одноименного классического коктейля от Пэта О’Брайна. Стандартный объем: 300–400 мл.'),
  (4, 'ru', 'Апельсин', 'Оранжевый цитрусовый фрукт, растущий на высоких деревьях преимущественно в Бразилии, США и Китае. Содержит витамин С, калий и кальций, оказывающие положительное влияние на работу сердца, сосудов и организма в целом. Один плод весит в среднем 300 г и дает 80 мл сока, разрезается на 10 кружков или 8 долек.'),
  (375, 'ru', 'Коллинз', 'Высокий бокал для лонг- и микс-дринков. Назван в честь классического коктейля «Том Коллинз». Стандартный объем: 300–400 мл.'),
  (104, 'ru', 'Бенедиктин', 'Именитый нормандский ликер, украшенный надписью DOM – DEO Optimo Maximo («За величайшего и лучшего бога»), производят из 27 секретных трав и пряностей в четыре этапа. После мацерации и дистилляции получившиеся основы выдерживают 11 месяцев в дубовых бочках – сначала по отдельности, потом вместе. Затем смешивают с водой, коньяком, медом и жженым сахаром и доводят до идеала трехмесячной выдержкой.'),
  (95, 'ru', 'Ананас', 'Большой тропический фрукт, растущий на наземных колючих растениях преимущественно в Бразилии, Таиланде и на Филиппинах. Содержит марганец и витамин С, стимулирующие пищеварение и снижающие вязкость крови. Один плод весит в среднем 1200 г и разрезается примерно на 40 кружков.'),
  (105, 'ru', 'Слинг', 'Канонический бокал для подачи одноименного коктейля, ставшего визитной карточкой отеля «Раффлс». Стандартный объем: 200–300 мл.'),
  (79, 'ru', 'Вода без газа', 'Важнейший источник здоровья и долголетия. Бармены всего мира рекомендуют всегда пить воду во время дегустации коктейлей, поэтому в лучших заведениях бокал чистой воды – комплимент от бара.'),
  (150, 'ru', 'Сахар в кубиках', 'Европейскую сладкую приправу получают методом сложной очистки, переработки и кристаллизации сиропа сахарного тростника или сока сахарной свеклы. Полученные кристаллы прессуют, чтобы добиться необходимой формы.'),
  (100, 'ru', 'Драмбуи', 'Шотландский ликер (в переводе с гаэльского – «приносящий удовлетворение») производят по секретной рецептуре с 1910 года. Известно, что в состав напитка входят купаж односолодовых виски от именитых вискокурен, вересковый мед, травы и пряности.'),
  (677, 'ru', 'Вода из цветков апельсина', 'Древнейшая ароматизированная вода на основе свежих цветков горького апельсина.'),
  (118, 'ru', 'Ананасовые листья', 'Листья тропического фрукта используют как украшение для экзотических тики-коктейлей.'),
  (98, 'ru', 'Писко', 'В производстве перуанского виноградного бренди участвует до восьми сортов винограда, тогда как в Чили допускают не более трех. Забродивший сок дистиллируют в стальных чанах и либо сразу разливают, либо выдерживают в дубовых бочках до двух лет.'),
  (103, 'ru', 'Тростниковый сахар в кубиках', 'Тропическую сладкую приправу производят методом кристаллизации сахарного тростника с его последующей прессовкой в маленькие кубики. Чем выше содержание патоки, тем темнее цвет и насыщеннее вкус.'),
  (132, 'ru', 'Выдержанный бурбон', 'Новый стандарт бурбонов. Выдержанный бурбон производится из зернового микса с добавлением ржи и, в отличие от традиционных бурбонов, выдерживается в бочках повторно. Для второй выдержки используются обожженные бочки из древесины американского дуба. Выдержанный бурбон проводит в бочках не менее 6 лет.'),
  (102, 'ru', 'Сахарная пудра', 'Сладкую порошкообразную приправу получают из перемолотого до состояния пудры сахара. Благодаря своим размерам моментально растворяется в жидкости.'),
  (158, 'ru', 'Медная кружка', 'Фронтовая посуда, ставшая «троянским конем» для водки в Америке и фирменной посудой для подачи классического коктейля «Московский мул». Стандартный объем: 300–400 мл.'),
  (214, 'ru', 'Ежевика', 'Темно-фиолетовая ягода средних размеров, произрастающая на кустарниках по всей Европе, в Северо-Западной Африке, Центральной Азии, Северной и Южной Америке. Содержит каротин, витамины С, В1 и В2, К и другие. Одна ягода весит в среднем 6 г.'),
  (115, 'ru', 'Сахарный песок', 'Европейскую сладкую приправу получают методом сложной очистки, переработки и кристаллизации сиропа сахарного тростника или сока сахарной свеклы. Калибр помола варьируется: чем он мельче, тем сахар быстрее растворяется.'),
  (107, 'ru', 'Молоко', 'Производят из цельного коровьего молока. Нужный процент жирности продукт приобретает после сепарации сливок методом добавления в уже обезжиренную версию нужного количества отделенного жира.'),
  (330, 'ru', 'Корица в палочках', 'Цейлонскую приправу, известную еще в XV веке, производят из коры коричного дерева, которую зачищают, шлифуют и высушивают в тени, пока она не закрутится в трубочки.'),
  (108, 'ru', 'Чашка', 'Высокая керамическая чашка для кофе или чая, ставшая в 1930 году символом классического коктейля «Том и Джерри». Стандартный объем: 200–250 мл.'),
  (655, 'ru', 'Питчер', 'Металлический чайничек. Используют для взбивания сливок и приготовления согревающих коктейлей.'),
  (120, 'ru', 'Молотая корица', 'Цейлонскую молотую приправу, известную с XV века, производят из высушенных и перемолотых стружек и обрезок коры коричного дерева.'),
  (149, 'ru', 'Бадьян', 'Тропические звездчатые плоды, растущие на вечнозеленых деревьях преимущественно в Китае, собирают недозревшими и высушивают на солнце.'),
  (134, 'ru', 'Кленовый сироп', 'Знаменитый рождественский сироп делают из сока сахарного клена, который собирают в феврале-марте по аналогии с березовым соком. Производят методом пастеризации сока, смешанного с тростниковым сахаром и водой.'),
  (123, 'ru', 'Сироп розы', 'Тонкий цветочный сироп производят методом мацерации и пастеризации лепестков розы в сахарном сиропе.'),
  (201, 'ru', 'Лепестки роз', 'Самый продаваемый цветок в мире. В одном бутоне – 25 лепестков.'),
  (1035, 'ru', 'Американский виски', 'Американский виски производится только в Теннесси из спирта с содержанием не менее 51% кукурузного солода, а также ячменя и ржи, дистиллированных и отфильтрованных. Его главное отличие от бурбона в том, что спирт предварительно пропускается через трехметровый слой угля из сахарного клена. Затем американский виски выдерживается в обожженных дубовых бочках от 4 до 6 лет.'),
  (288, 'ru', 'Херес Педро Хименес', 'Самый сладкий вид испанского крепленого вина производят из одноименного максимально созревшего винограда. Виноградный сок, прошедший период ферментации, закрепляют виноградными спиртами и выдерживают в дубовых бочках методом солера очень длительное время – от 10 до 30 лет и более.'),
  (154, 'ru', 'Чайная ложка', 'Ложка для размешивания чая в чашке. В одной ложке помещается в среднем 5 мл жидкости или 5 г сухого ингредиента.'),
  (211, 'ru', 'Ледяной куб', 'Большие кубы вернулись в бар с возвращением моды на классические напитки. При производстве сначала замораживают большие ледяные блоки, которые впоследствии разрезают пилой на ровные кубы. Лёд такой формы медленнее тает в бокале и не разбавляет напиток.'),
  (450, 'ru', 'Имбирный сироп', 'Пряный азиатский сироп производят методом пастеризации экстракта имбиря, смешанного с сахарным сиропом.'),
  (693, 'ru', 'Бомбилья', 'Специальная трубочка для подачи мате. В верхней части оснащена мундштуком, в нижней – ситечком.'),
  (552, 'ru', 'Красная смородина', 'Маленькая красная ягода, произрастающая на древесных кустарниках преимущественно в Центральной и Северной Европе, а также в Северной Азии. Содержит большое количество витамина С, различные сахара, органические кислоты и минералы. В одной барной ложке помещается 5 г ягод.'),
  (332, 'ru', 'Херес Олоросо', 'Полусухое или сладкое испанское крепленое вино производят методом ферментации винограда сорта «паломино» без образования защитной пленки флор. Получившуюся основу поэтапно закрепляют виноградными спиртами и выдерживают в дубовых бочках методом солера не менее двух лет.'),
  (191, 'ru', 'Курага', 'Солнечный сухофрукт производят из спелых абрикосов преимущественно в Турции, Иране и Узбекистане. Фрукты сначала замачивают или вываривают в сиропе, затем высушивают на солнце либо в сушильных аппаратах. Один плод весит в среднем 10 г.'),
  (683, 'ru', 'Поднос', 'Металлический или деревянный лист для подачи еды или напитков.'),
  (121, 'ru', 'Ванильный сироп', 'Мадагаскарский пряный сироп производят методом мацерации и пастеризации стручков ванили в сахарном сиропе.'),
  (381, 'ru', 'Золотая текила', 'Мексиканский крепкий алкоголь традиционно производят методом перегонки из сока голубой агавы, выращенной на высокогорье Лос-Альтос. Семилетние пиньи помещают в специальные печи для преобразования крахмала в сахар, получившийся сок фильтруют и ферментируют, подвергают двойной дистилляции в медных кубах, подкрашивают карамелью и сдабривают ароматическими добавками, а затем выдерживают в дубовых бочках в течение нескольких месяцев.'),
  (318, 'ru', 'Белый вермут', 'Легкий итальянский аперитив, созданный более ста лет назад. Креплёное вино, ароматизируют пряными и лекарственными травами, цветами, семенами и фруктами, среди которых: полынь, мята, корица, мускатный орех, кора хинного дерева. Ванильные тона сладкого белого вермута лучше всего раскрываются в сочетании с тоником и долькой лайма - этот лёгкий свежий коктейль идеально подойдёт к ужину с друзьями.'),
  (126, 'ru', 'Клубничное пюре', 'Мякоть крупных красных ягод, растущих небольших кустарниках преимущественно в США, Турции, Испании, Египте и Мексике смешивают с сахаром в равных пропорциях и пастеризуют для сохранения неизменного вкуса круглый год.'),
  (327, 'ru', 'Тростниковый сахарный песок', 'Тропическую сладкую приправу производят методом кристаллизации сахарного тростника с его последующей механической обработкой. Чем выше содержание патоки, тем темнее цвет и насыщеннее вкус.'),
  (326, 'ru', 'Бутыль', 'Классический сосуд для хранения алкогольных и безалкогольных напитков.'),
  (138, 'ru', 'Блендер', 'Придуманный в 1922 году Стефеном Поплавским электрический инструмент незаменим для приготовления тики-коктейлей, смузи и замороженных напитков.'),
  (196, 'ru', 'Кокосовый сироп', 'Самый популярный тропический сироп производят методом пастеризации кокосовой воды, смешанной с тростниковым сахаром.'),
  (197, 'ru', 'Слайсер для ананаса', 'Тики-аксессуар позволяет в считанные секунды очистить ананас от кожуры и твердой сердцевины.'),
  (744, 'ru', 'Совок для льда', 'Удобный инструмент из поликарбоната или нержавеющей стали, который позволяет набирать определенную порцию льда. Совки различаются размерами и объемами чаши, что позволяет подобрать инструмент под необходимое количество льда.'),
  (406, 'ru', 'Банановый ликер желтый', 'Кремовый тропический ликер производят методом мацерации мякоти желтых бананов в нейтральном спирте с водой. Получившуюся основу фильтруют, смешивают с сахаром и закрепляют молодыми коньячными спиртами.'),
  (200, 'ru', 'Банан', 'Древнейшее тропическое травянистое растение, произрастающее преимущественно в Индии, Китае и Уганде. Фрукт содержит витамин B6, марганец и пищевые волокна. Один плод весит в среднем 200 г, из которых 80 г – кожура.'),
  (244, 'ru', 'Женевер', 'Голландский крепкий алкоголь – прародитель джина. Изготавливают с XV века методом дистилляции чистого спирта с добавлением ягод можжевельника и других специй.'),
  (133, 'ru', 'Медовый сироп', 'Топовый сироп производят методом пастеризации натурального меда, разбавленного до нужной консистенции водой.'),
  (293, 'ru', 'Заварной чайник', 'История античного китайского сосуда началась там же и тогда же, что и история самого чая, – в Китае в XIV веке. Служит для заваривания чая, трав и специй в горячей воде или соке.'),
  (287, 'ru', 'Односолодовый виски с острова Айла', 'Шотландский крепкий алкоголь производят на острове Айла, в северной части страны, методом тройной дистилляции из 100% ячменного солода, высушенного на торфяном дыму, благодаря чему и появляется знаменитый копченый аромат. Полученные спирты созревают не менее 10 лет в дубовых бочках.'),
  (284, 'ru', 'Ревеневый ликер', 'Десертный кисло-сладкий травяной ликер производят методом мацерации стеблей и листьев ревеня в нейтральном спирте с водой. Получившуюся основу смешивают с сахаром и доводят до нужной крепости.'),
  (358, 'ru', 'Чинар', 'Травяной итальянский ликер производят методом дистилляции и мацерации 16 трав и специй во главе с артишоком в нейтральном спирте. Полученную основу фильтруют и доводят до нужной крепости и сладости.'),
  (735, 'ru', 'Грейпфрутовая цедра', 'Верхний слой кожуры грейпфрута, который срезают специальным острым ножом. Содержит эфирные масла, определяющие аромат. Цедра может быть срезана как с части, так и со всего грейпфрута целиком, мелко натерта и даже закручена в спираль, называемую твистом.'),
  (704, 'ru', 'Спрейер', 'Красивый аксессуар для распыления над коктейлем биттеров и ароматических добавок.'),
  (435, 'ru', 'Херес Фино', 'Испанское сухое крепленое вино производят методом ферментации винограда «паломино» с добавлением специальных хересных дрожжей. Созревавшее не менее 12 месяцев вино, покрытое специальной пленкой флор, закрепляют поэтапно виноградными спиртами, после чего оно дозревает в бочках под защитной пленкой не менее двух лет.'),
  (653, 'ru', 'Стопка', 'Небольшой стакан или рюмка, как правило, с прямыми стенками. Предназначен для самых крепких напитков или коктейлей, которые выпиваются залпом. Стандартный объем: 50–100 мл.'),
  (546, 'ru', 'Клубника', 'Крупная красная ягода, растущая на небольших кустарниках преимущественно в США, Турции, Испании, Египте и Мексике. Содержит сахара, пектиновые и дубильные вещества, аскорбиновую и другие кислоты, обладает противовоспалительным действием. Одна ягода весит в среднем 20 г.'),
  (402, 'ru', 'Лимончелло', 'Национальный итальянский ликер производят методом мацерации лимонной цедры в нейтральном спирте на протяжении месяца. В получившуюся основу добавляют сахар и воду, дают настояться, затем фильтруют.'),
  (410, 'ru', 'Ликер личи', 'Производят из мякоти спелых личи, которые смешивают с алкоголем и дают настояться.'),
  (486, 'ru', 'Сок манго', 'Для производства сока плоды манго пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (529, 'ru', 'Маракуйя', 'Субтропический фрукт страсти, растущий на вечнозеленых лианах преимущественно в Новой Зеландии, Израиле и на Шри-Ланке. Содержит витамин А, бета-каротин и калий, обладает тонизирующим эффектом. Один плод весит в среднем 90 г.'),
  (415, 'ru', 'Ежевичный ликер', 'Насыщенный ягодный ликер производят методом мацерации ягод лесной ежевики в нейтральном спирте с водой сроком до двух месяцев. Первый сок без отжима фильтруют и смешивают с сахаром.'),
  (405, 'ru', 'Яблочный ликер зеленый', 'Свежий фруктовый ликер производят методом мацерации мякоти зеленых яблок в нейтральном спирте. Получившуюся основу фильтруют, смешивают с сахаром и разбавляют водой до нужной крепости.'),
  (528, 'ru', 'Яблоко', 'Популярный фрукт родом из Центральной Азии, растущий на лиственных деревьях преимущественно в Китае, США и Турции. Содержит аскорбиновую кислоту, витамин К, калий, полезен для иммунитета и борьбы с лишним весом. Один плод весит в среднем 200 г и разрезается на 10 долек.'),
  (682, 'ru', 'Банка с крышкой', 'Большой сосуд с плотно прилегающей крышкой служит для создания и хранения настоек и наливок. Стандартных объемов не существует.'),
  (446, 'ru', 'Сироп агавы', 'Мексиканский сироп производят из концентрированного сока агавы, прошедшего стабилизацию с добавлением сахарного сиропа.'),
  (432, 'ru', 'Красное вино сухое', 'Самый распространенный вид вина производят методом мацерации и дальнейшей ферментации черного и красного сортов винограда, кожица которого и придает вину цвет. Затем вино сцеживают или фильтруют, после чего выдерживают в дубовых бочках не менее трех месяцев.'),
  (613, 'ru', 'Гвоздика', 'Индонезийская пряность представляет собой высушенные нераскрывшиеся бутоны тропического гвоздичного дерева.'),
  (705, 'ru', 'Фонтан для абсента', 'Неотъемлемый атрибут ритуальной подачи французского крепкого напитка. В основную колбу заливают воду с добавлением трав, фруктов, а иногда и льда. Настоявшись, напиток капля за каплей проходит через сахар на ложке и попадает в бокал с абсентом.'),
  (698, 'ru', 'Ложка для абсента', 'Неотъемлемый атрибут ритуальной подачи французского крепкого напитка. В основную колбу заливают алкоголь с добавлением трав и фруктов. Настоявшись, напиток капля за каплей проходит через сахар на ложке и попадает в бокал.'),
  (494, 'ru', 'Энергетик', 'Энергетический напиток был специально разработан для употребления во время повышенной физической и умственной нагрузки.'),
  (394, 'ru', 'Айриш крим', 'Ирландский сливочный ликер производят из ирландского виски тройной дистилляции, сливок и нейтрального спирта.'),
  (547, 'ru', 'Черника', 'Маленькая фиолетовая ягода, произрастающая на кустарниках в Канаде, Северной Америке, Турции и Западной Европе. Содержит большой запас витаминов А, В, С, марганец и калий. Полезна для глаз, улучшает сумеречное зрение. В одной барной ложке помещается 5 г ягод.'),
  (578, 'ru', 'Лимонная трава', 'Трава с цитрусовым ароматом из карибской и азиатской кухни, растет преимущественно на Британских островах, Филиппинах и в Индонезии.'),
  (490, 'ru', 'Спрайт', 'Сладкий газированный напиток производят на основе содовой с добавлением сахара и лимонного экстракта.'),
  (666, 'ru', 'Самбука классическая', 'Итальянский крепкий алкоголь производят путем ароматизации пшеничного спирта с сахаром маслами обыкновенного и звездчатого аниса, выжимками из ягод, цветов бузины и разных трав, оттеняющих его стойкий аромат.'),
  (414, 'ru', 'Яичный ликер', 'Голландский рождественский ликер, произошедший от бразильского алкогольного напитка из авокадо, изготавливают из смеси яичных желтков, сахара, ванили и коньяка.'),
  (531, 'ru', 'Гранат', 'Средиземноморский фрукт, растущий на небольших лиственных кустарниках преимущественно в Израиле и Индии. Содержит калий и фосфор, положительно влияющие на сердечно-сосудистую систему. Один плод весит в среднем 300 г и разрезается на 10 долек.'),
  (684, 'ru', 'Бокал для вина', 'Классический немного закругленный бокал традиционно больше, чем бокал для белого вина. Стандартный объем: 200–300 мл.'),
  (483, 'ru', 'Вишневый сок', 'Для производства сока ягоды вишни пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (551, 'ru', 'Черная смородина', 'Маленькая черная ягода, произрастающая на древесных кустарниках в Центральной и Северной Европе, а также в Северной Азии. Содержит большое количество витамина С, различные сахара, органические кислоты и минералы. В одной барной ложке помещается 5 г ягод.'),
  (597, 'ru', 'Малиновый джем', 'Джем из красных ягод, растущих на многолетних полукустарниках преимущественно в России, Сербии, Польше и США. Зрелые ягоды уваривают с сахаром до однородного состояния. В одной барной ложке помещается 5 г джема.'),
  (590, 'ru', 'Апельсиновый джем', 'Джем из мякоти цитрусовых фруктов, растущих на высоких деревьях преимущественно в Бразилии, США и Китае. Зрелые плоды уваривают с сахаром до однородного состояния. В одной барной ложке помещается 5 г джема.'),
  (589, 'ru', 'Мед', 'Цветочный нектар, собранный и трансформированный пчелами.'),
  (652, 'ru', 'Печенье', 'Небольшое кондитерское изделие, выпекают из разного теста.'),
  (686, 'ru', 'Кувшин', 'Археологический кухонный сосуд для подачи воды, лимонадов и сангрий. Стандартный объем: 500–3000 мл.'),
  (484, 'ru', 'Гранатовый сок', 'Для производства сока зерна граната пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (548, 'ru', 'Арбуз', 'Особый вид крупной ягоды, которую высаживают рассадой преимущественно в Китае, Турции и Иране. Содержит глюкозу и фруктозу, пектины, кальций, магний, щелочные вещества, нормализует обмен веществ. Одна ягода весит в среднем 5000 г, кружок – 300 г, соотношение веса мякоти и корки – 60% к 40.'),
  (454, 'ru', 'Сироп лимонника', 'Лимонный сироп производят методом пастеризации экстракта лимонника, смешанного с сахарным сиропом.'),
  (770, 'ru', 'Коктейльная креманка', 'В прошлой жизни десертный бокал для подачи мороженого сегодня выступает в роли фирменного бокала для милкшейкеов, лимонадов и коктейлей. Стандартный объем: 250–350 мл.'),
  (433, 'ru', 'Белое вино сухое', 'Летнее вино создают путем мацерации и дальнейшей ферментации очищенного от кожицы винограда белых сортов. Затем вино сцеживают или фильтруют, после чего выдерживают в дубовых бочках не менее трех месяцев.'),
  (532, 'ru', 'Киви', 'Китайский крыжовник растет на крупных древовидных лианах преимущественно в Италии, Новой Зеландии и Чили. Содержит витамины С, клетчатку, фолиевую кислоту, кальций и фосфор, усиливающие иммунную систему человека. Одна ягода весит в среднем 120 г.'),
  (577, 'ru', 'Красный базилик', 'Пряно-ароматная трава, растущая преимущественно в теплых областях Старого Света.'),
  (702, 'ru', 'Сифон для сливок', 'Прибор из толстого стекла или металла для быстрого взбивания сливок в нежную воздушную пену. Можно также использовать для приготовления разнообразных десертов, сложных соусов, муссов. Стандартный объем: 0,5–1 л.'),
  (399, 'ru', 'Персиковый ликер', 'Солнечный фруктовый ликер производят методом дистилляции ферментированного персикового сока с добавлением коньячных спиртов для усиления насыщенного аромата добавленных косточек.'),
  (396, 'ru', 'Абрикосовый ликер', 'Знаменитый фруктовый ликер производят методом дистилляции ферментированного абрикосового сока с добавлением коньячных спиртов для усиления аромата.'),
  (691, 'ru', 'Чаша для пунша', 'Объемный сосуд из стекла, хрусталя или металла для подачи пуншей был привезен из Индии в Англию в начале XVII века. Стандартный объем: 5 л.'),
  (395, 'ru', 'Ликер амаретто', 'Классический итальянский ликер производят методом мацерации косточек абрикоса, различных трав и фруктов в нейтральном спирте. Получившуюся основу фильтруют, смешивают с сахаром и разбавляют водой до нужной крепости.'),
  (556, 'ru', 'Вишня', 'Желтая или алая ягода, растущая на деревьях главным образом в странах с теплым и умеренным климатом, таких как Турция, Италия, Испания, Чили. Содержит органические кислоты, микроэлементы, пектиновые вещества, фолиевую кислоту, витамины А, С, Е, B, PP. Одна ягода весит в среднем 5 г.'),
  (437, 'ru', 'Светлое пиво', 'Легкий сорт пива производят из воды, ячменя, экстракта солода, хмеля и пивных дрожжей.'),
  (452, 'ru', 'Черносмородиновый сироп', 'Ягодный сироп производят методом пастеризации сока спелых ягод черной смородины, смешанного с сахаром и водой.'),
  (397, 'ru', 'Дынный ликер', 'Азиатский тропический ликер производят методом мацерации дынной мякоти в нейтральном спирте с водой. Получившуюся основу фильтруют, доводят до нужной сладости и крепости и разливают в бутылки.'),
  (763, 'ru', 'Биттер лемон', 'Газированный лимонный напиток производят методом газации с добавлением лимонного экстракта.'),
  (380, 'ru', 'Бехеровка', 'Канонический чешский ликер производят путем мацерации бленда из 20 трав и специй в нейтральном спирте, который впоследствии перемешивают с водой и сахаром и выдерживают от двух до трех недель в дубовых бочках.'),
  (502, 'ru', 'Чай эрл грей', 'В классическом виде представляет собой черный чай с добавлением масла, полученного из кожуры плодов бергамота. Оптимальная температура для заваривания – 90–95 °С, время выдержки настоя – 3–5 минут.'),
  (709, 'ru', 'Зонтик', 'Яркое бумажное украшение для детского или тропического коктейля.'),
  (639, 'ru', 'Чернослив', 'Европейский сушеный деликатес производят из черных слив, высушенных на солнце или в специальных машинах.'),
  (747, 'ru', 'Тарталетка', 'Миниатюрная копия открытого пирога, впервые появилась в кулинарной книге поваров короля Ричарда II в 1390 году. Готовят из слоеного или песочного теста и наполняют разными начинками.'),
  (453, 'ru', 'Яблочный сироп желтый', 'Фруктовый желтый сироп производят методом пастеризации сока яблок желтых сортов с добавлением тростникового сахара.'),
  (576, 'ru', 'Розмарин', 'Средиземноморская трава с пряным ароматом сосны.'),
  (409, 'ru', 'Грейпфрутовый ликер', 'Цитрусовый ликер с горчинкой производят методом мацерации цедры розовых грейпфрутов в нейтральном спирте. Получившуюся основу фильтруют, смешивают с сахаром и разбавляют чистой водой до нужной крепости.'),
  (549, 'ru', 'Клюква', 'Маленькая красная ягода, растущая на стелющихся по земле кустарниках преимущественно в США, Чили, Аргентине и Нидерландах. Содержит органические кислоты, микроэлементы, пектиновые вещества, фолиевую кислоту и витамины А, С, Е, B, PP. В одной барной ложке помещается 5 г ягод.'),
  (492, 'ru', 'Тоник', 'Газированный напиток с хинином был изобретен в Индии для борьбы с малярией. Производят из газированной воды, смешанной с хинином и небольшим количеством сахара.'),
  (562, 'ru', 'Красный виноград', 'Красная ягода средних размеров, произрастающая на лиственных древесных лианах преимущественно в Китае, США, Италии, Франции и Испании. Содержит сахара, клетчатку, органические кислоты, витамин B и другие микроэлементы, оказывающие укрепляющее и тонизирующее действие. Одна ягода весит в среднем 5 г.'),
  (663, 'ru', 'Грейпфрутовая водка', 'Крепкий ароматизированный алкоголь производят методом многократной перегонки зернового спирта, прошедшего разные степени очистки угольными и другими фильтрами и смешанного с чистой водой. Получившийся напиток ароматизируют экстрактами зрелых грейпфрутов.'),
  (530, 'ru', 'Мандарин', 'Тропический цитрусовый фрукт, растущий на вечнозеленых кустарниках преимущественно в Китае, Испании и Бразилии. Содержит витамин С и калий, способствующие укреплению иммунитета. Один плод весит в среднем 100 г и дает 40 мл сока.'),
  (710, 'ru', 'Лилле Блан', 'Французский винный аперитив производят из сочетания белых вин региона Бордо с фруктовыми ликерами. Пока вино зреет, цедру сладких, горьких и кислых зеленых апельсинов и хинин настаивают на коньячных спиртах. Затем все смешивают и выдерживают в дубовых бочках 8–12 месяцев.'),
  (389, 'ru', 'Пряный ром', 'Карибский пряный алкоголь получают методом вертикальной перегонки спирта, полученного путем брожения патоки или сока из сахарного тростника. Перед купажированием выдерживают от 2 до 7 лет в обожженных дубовых бочках из-под хереса или бурбона с добавлением корицы, муската, ванили и других пряностей'),
  (398, 'ru', 'Ликер Блю Кюрасао', 'Неоновый апельсиновый ликер производят методом мацерации высушенной апельсиновой цедры в нейтральном спирте с водой. Получившуюся основу фильтруют, смешивают с сахаром и окрашивают натуральными красителями.'),
  (550, 'ru', 'Зеленый виноград', 'Зеленая ягода средних размеров, произрастающая на лиственных древесных лианах преимущественно в Китае, США, Италии, Франции и Испании. Содержит сахара, клетчатку, органические кислоты, витамин B и другие микроэлементы, оказывающие укрепляющее и тонизирующее действие. Одна ягода весит в среднем 5 г.'),
  (533, 'ru', 'Манго', 'Дикий тропический фрукт, растущий на деревьях преимущественно в Индии, Пакистане и на Филиппинах. Содержит витамин А, калий и фолиевую кислоту, улучшающие иммунитет и зрение. Один плод весит в среднем 300 г и разрезается на 10 долек.'),
  (408, 'ru', 'Ликер корицы', 'Немецкий пряный ликер производят методом мацерации корицы в шнапсе. Получившуюся основу фильтруют, смешивают с сахаром и для эффектности добавляют пищевое сусальное золото.'),
  (495, 'ru', 'Холодный зеленый чай', 'Популярный в Азии холодный чай производят на основе экстракта зеленого чая, а также экстрактов других трав без добавления искусственных ароматизаторов и консервантов.'),
  (711, 'ru', 'Джулеп стрейнер', 'Незаменимый в работе со смесительным стаканом аксессуар. Служит также бесподобным украшением одноименного классического коктейля. Используют для фильтрации коктейля от отколовшихся кусочков льда и других незапланированных ингредиентов.'),
  (670, 'ru', 'Кофе эспрессо', 'Крепкий напиток готовят, пропуская небольшое количество горячей (около 90 °C) воды через молотый кофе.'),
  (690, 'ru', 'Стаканчик для чая', 'Традиционный турецкий стаканчик для чаепития. Стандартный объем: 40–80 мл.'),
  (412, 'ru', 'Ликер маракуйи', 'Производят из мякоти спелых плодов маракуйи, апельсинов и грейпфрута, которые смешивают с алкоголем и дают настояться.'),
  (615, 'ru', 'Ванильный сахарный песок', 'Классический сахарный песок, ароматизированный ванилином.'),
  (181, 'ru', 'Френч-пресс', 'Французский аксессуар для заваривания кофе и чая, состоящий из стеклянной колбы и пресса с ситечком.'),
  (448, 'ru', 'Клубничный сироп', 'Ягодный сироп производят методом пастеризации сока спелой клубники, смешанного с сахаром и водой.'),
  (567, 'ru', 'Перец чили', 'Острый тропический перец, растущий на кустах преимущественно в странах Южной Америки. Содержит витамины А и С, а также калий, магний, железо. Один стручок весит в среднем 30 г.'),
  (499, 'ru', 'Черный чай', 'Вид чая, подвергающийся ферментации от двух недель до месяца. Растет в районах с тропическим или субтропическим климатом. Для заваривания 1 ложку сухого чая надо залить 100 мл кипятка и дать настояться 4–5 минут.'),
  (411, 'ru', 'Ликер манго', 'Азиатский тропический ликер производят методом мацерации мякоти спелых манго в нейтральном спирте с водой. Получившуюся основу фильтруют и смешивают с сахаром.'),
  (514, 'ru', 'Ванильное мороженое', 'Замороженный десерт готовят из молока, сливок, масла и сахара с добавлением экстракта ванили. Хранится в морозилке не более месяца.'),
  (592, 'ru', 'Вишневый джем', 'Джем из желтых или алых ягод, растущих на деревьях преимущественно в странах с теплым умеренным климатом, таких как Турция, Италия, Испания и Чили. Из зрелых ягод удаляют косточку и уваривают с сахаром до однородного состояния. В одной барной ложке помещается 5 г джема.'),
  (485, 'ru', 'Персиковый сок', 'Для производства сока персики пускают под пресс, затем фильтруют и разливают сок по бутылкам.'),
  (387, 'ru', 'Черносмородиновая водка', 'Крепкий ароматизированный алкоголь производят методом многократной перегонки зернового спирта, прошедшего разные степени очистки угольными и другими фильтрами и смешанного с чистой водой. Получившийся напиток ароматизируют экстрактами спелой черной смородины.'),
  (633, 'ru', 'Розовая вода', 'Античная ароматизированная вода на основе лепестков розы.'),
  (713, 'ru', 'Малиновое пюре', 'Мякоть маленьких красных ягод, растущих на многолетних полукустарниках преимущественно в России, Сербии, Польше и США смешивают с сахаром в равных пропорциях и пастеризуют для сохранения неизменного вкуса круглый год.'),
  (586, 'ru', 'Тимьян', 'Ароматическая пряность из веточек низкорослых кустарников, растущих преимущественно в Евразии, Северной Африке и Гренландии. Входит в состав прованской смеси, идеально подходит для ароматизации крепких спиртов.'),
  (407, 'ru', 'Кокосовый ликер', 'Тропический тики-ликер производят методом мацерации мякоти кокосов в ромовых спиртах. Получившуюся основу фильтруют, смешивают с сахаром и разбавляют водой до нужной крепости.'),
  (430, 'ru', 'Розовый вермут', 'Самый молодой вермут из уникального сочетания красного и белого вина. Креплёное вино, ароматизированное лекарственными травами, цветами, семенами и фруктами, среди которых: полынь, мята, корица, мускатный орех, кора хинного дерева, удачно сбалансированные и выраженные в характерном горько-пряном вкусе. Идеальный аромат превосходно раскрывается при сервировке на льду.'),
  (646, 'ru', 'Черный шоколад', 'Кондитерский десерт, приготовленный из темных какао-бобов с минимальным добавлением сахара.'),
  (447, 'ru', 'Карамельный сироп', 'Знаменитый сироп для кофе производят методом пастеризации жидкой карамели с добавлением ванили и воды.'),
  (750, 'ru', 'Салфетки', 'Хлопковый или бумажный барный платок. Иногда выступает в роли костера для напитков.'),
  (360, 'ru', 'Сифон', 'Прибор из толстого стекла или металла для газации напитков углекислым газом. Стандартный объем: 1–2 л.'),
  (500, 'ru', 'Кофе в зернах', 'Жареные зерна кофейного дерева из-за содержания кофеина оказывают стимулирующее действие на организм. Различают две основные разновидности кофейного дерева – арабику и робусту.'),
  (565, 'ru', 'Саке', 'Японский алкоголь производят из шлифованного риса, замоченного и обработанного паром. В подготовленную культуру добавляют для брожения грибки и выдерживают в теплом и влажном помещении около двух суток. После брожения саке выдерживают в герметичных резервуарах от 6 до 12 месяцев.'),
  (537, 'ru', 'Кумкват', 'Небольшой цитрусовый фрукт, растущий на небольших сплюснутых побегах преимущественно в Китае, Корее и Японии. Содержит витамин С, железо и магний, незаменим в борьбе с инфекциями. Один плод весит в среднем 10 г.'),
  (685, 'ru', 'Коньячный бокал', 'Классический бокал для коньяка или бренди. Стандартный объем: 170–400 мл.'),
  (423, 'ru', 'Южный комфорт', 'Новоорлеанский фруктовый ликер, придуманный барменом Мартином Хероном в 1874 году, производят по старинной рецептуре на основе американского виски с добавлением фруктовых и травяных эссенций, сахара и карамели и выдерживают в дубовых бочках до нужной зрелости.'),
  (703, 'ru', 'Сковорода', 'Древнейшая кухонная утварь, необходимая в баре для фламбирования ягод и фруктов.'),
  (688, 'ru', 'Сет', 'Гастрономический сет для дегустаций. Состоит из стеклянного подноса, наполненного льдом, который сохраняет нужную температуру маленьких пробников.'),
  (462, 'ru', 'Сироп личи', 'Азиатский фруктовый сироп производят методом пастеризации сока ягод личи, смешанного с сахарным сиропом и водой.'),
  (504, 'ru', 'Ромашковый чай', 'Настой из высушенных цветов лечебной ромашки. В основном цветы просто заливают кипятком из расчета 1–2 чайные ложки на 200 мл воды, настаивают 7–10 минут, процеживают и пьют либо в чистом виде, либо с добавлением сахара или меда.'),
  (673, 'ru', 'Облепиховый джем', 'Джем из маленьких желтых ягод, растущих на лиственных колючих кустарниках преимущественно на атлантическом побережье Европы и в Северо-Западном Китае. Зрелые ягоды уваривают с сахаром до однородного состояния. В одной барной ложке помещается 5 г джема.'),
  (689, 'ru', 'Саке сет', 'Сет для ритуальной подачи японского крепкого алкоголя. Стандартный объем токкури: 250–300 мл, чашечки: 50–60 мл.'),
  (769, 'ru', 'Блюдце', 'Стеклянный, фарфоровый или металлический предмет посуды, который традиционно подают в паре с чашкой. В современной интерпретации на блюдце подают бокал с коктейлем, благодаря чему подача становится более изысканной и элегантной.'),
  (463, 'ru', 'Сироп манго', 'Азиатский фруктовый сироп производят методом пастеризации сока манго, смешанного с тростниковым сахаром и водой.'),
  (700, 'ru', 'Подстаканник', 'Металлическая подставка с ручкой, охватывающая стакан и позволяющая пить горячие напитки, не обжигая рук.'),
  (695, 'ru', 'Вилка', 'Столовый прибор, состоящий из рукояти и нескольких узких зубцов (обычно от двух до четырех) на одном конце. Используется для приготовления пищи, а также для удержания или переноски отдельных частей блюда во время еды.'),
  (837, 'ru', 'Бочка', 'Небольшая дубовая бочка для выдерживания напитков в баре.'),
  (861, 'ru', 'Коническая колба', 'Лабораторная колба конической формы с плоским дном и вытянутым горлышком.'),
  (865, 'ru', 'Консервная банка', 'Классический сосуд из тонкого метала для хранения напитков и пищевых продуктов. Стандартного объёма не существует.'),
  (950, 'ru', 'Термометр', 'Приспособление для измерения температуры жидкостей, окружающей среды, тела и т.д.'),
  (981, 'ru', 'Сифон для кофе', 'Вакуумное устройство для варки кофе.'),
  (445, 'ua', 'Сироп кориці', 'Знаменитий пряний сироп виготовляють методом пастеризації і мацерації кориці в цукровому сиропі з його подальшою стабілізацією.'),
  (176, 'ua', 'Лаймовий сік', 'Для виробництва соку лайми пускають під прес, потім фільтрують і розливають сік у пляшки.'),
  (482, 'ua', 'Яблучний сік', 'При виробництві соку, яблука пускають під прес, фільтрують і розливають у пляшки.'),
  (767, 'ua', 'Білок перепелиного яйця', 'Щоб надати коктейлю з цим інгредієнтом ніжну і пінисту текстуру, рекомендується використовувати метод приготування «драй шейк».'),
  (217, 'ua', 'Огірок', 'Середземноморська плодова культура, що росте, переважно, в середземноморських країнах. Нормалізує обмін речовин, покращує роботу серця та нирок. Один плід важить в середньому 150 г, розрізається на 10 кілець або смужок.'),
  (31, 'ua', 'Лід в кубиках', 'При виробництві абсолютно незамінного інгредієнту основну увагу надають чистоті води і швидкості заморожування. Чим повільніше заморожується вода, тим прозорішим виходить продукт. Ідеальні зразки не мають порожнин і повільніше тануть у келиху.'),
  (210, 'ua', 'Шампанське блюдце', 'Келих на високій тонкій шпильці, за легендою, повторює силует фаворитки французького короля. Служить для подачі шампанського і коктейлів категорії “тіні”. Стандартний об''єм: 200-300 мл'),
  (68, 'ua', 'Шейкер', 'Свій нинішній вигляд отримав в кінці 1800-х, а особливої популярності набув у 1920-1930-ті роки, змінивши десятки стилів та форм. Розділяють коблер з вбудованим стрейнером, французький, без стрейнера, та бостонський, що складається з двох рівних склянок. Стандартний об’єм: 500-700 мл.'),
  (69, 'ua', 'Стрейнер', 'Аксесуар незамінний в роботі з бостонським або французьким шейкером. Служить для фільтрації коктейлю від кісточок цитрусових, шматочків льоду, що відкололися, та інших незапланованих інгредієнтів.'),
  (73, 'ua', 'Джигер', 'Гарант мір та ідеальних пропорцій в коктейлі. В арсеналі кращих барменів завжди представлений в різних версіях: 20-40 мл, 25-50 мл і 30-60 мл.'),
  (70, 'ua', 'Прес для цитрусових', 'Незамінний інструмент, що допомагає вичавлювати сік лайму або лимонів. Незважаючи на те, що сьогодні в більшості популярних закладів сік цитрусових вичавлюють заздалегідь, свіжовичавлений сік вважається вищим рівнем якості.'),
  (239, 'ua', 'Соковижималка', 'Вичавлює сік з будь-яких овочів та фруктів. На відміну від ручного преса, електричний механізм відділяє сік від м''якоті за допомогою центрифуги.'),
  (1, 'ua', 'Горілка', 'Горілка'),
  (55, 'ua', 'Кавовий лікер', 'Знаменитий стимулюючий лікер виготовляють методом перколювання зерен кави різних сортів з нейтральним спиртом. Основу, що утворюється, не фільтрують, змішують з паленим цукром і розбавляють водою до потрібної міцності.'),
  (65, 'ua', 'Рокс', 'Широка склянка з товстим дном для подачі міцних чоловічих коктейлів або міцного алкоголю в чистому вигляді. Стандартний об’єм: 200-300 мл.'),
  (64, 'ua', 'Коктейльна ложка', 'Незамінний інструмент бармена, який служить для приготування коктейлів в склянці змішувача та викладання шарів у шотах, використовується також як Одиниця виміру, що вміщує 5 мл рідких інгредієнтів або 5 г сипких.'),
  (57, 'ua', 'Трубочки', 'У 1888 році власник фабрики паперових мундштуків, Марвін Стоун, придумав найкращий аксесуар для розпивання напоїв з келиха. Джозеф Фрідман розбагатів, додавши до трубочок гнучку гофровану область. Останнім етапом став їх перехід на пластик.'),
  (799, 'ua', 'Лондонський сухий джин', 'Английский міцний алкогольний напій виготовляється у вертикальних перегінних кубах. Зерновий спирт настоюють протягом доби на ялівці і десятці інших трав та спецій, а потім дистилюють близько 7 годин і розливають у пляшки.'),
  (54, 'ua', 'Трипл сек', 'Культовий цитрусовий лікер потрійної сухості виробляють методом мацерації цедри апельсинів Курасао в нейтральному спирті з водою. Отримана основа перед розливом проходить потрійну дистиляцію зі збереженням високої міцності.'),
  (9, 'ua', 'Лимонний сік', 'Для виробництва соку лимони пускають під прес, потім фільтрують і розливають сік у пляшки.'),
  (734, 'ua', 'Лимонна цедра', 'Верхній шар шкірки лимона, який зрізують спеціальним гострим ножем. Містить ефірні олії, які й надають аромат. Цедра може бути зрізана як з частини, так і з цілого лимона, дрібно натерта і, навіть, закручена в спіраль, яка називається твістом.'),
  (66, 'ua', 'Келих сауер', 'Маленький келих для збитих напоїв однойменної групи, створених на основі цитрусових, цукру та міцного алкоголю. Стандартний об’єм: 90-120 мл.'),
  (71, 'ua', 'Ніж для цедри', 'Вид обладнання бармена з японського мистецтва карвінгу. Служить для зрізання тонких смужок цедри, вирізання яблук або створення широких твістів.'),
  (143, 'ua', 'Мескаль', 'Мексиканський міцний алкогольний напій, виробляється традиційним методом, що включає копчення агави без листя на розпеченому вулканічному камінні під шаром землі. Так напій здобуває копчений аромат. Після чого піньї розмелюють, сік зброджують і витримують у дубових бочках не менше 4 місяців.'),
  (224, 'ua', 'Зелений базилік', 'Пряно-ароматне листя трави, що росте, переважно, в теплих областях Старого Світу. Зелене листя стало особливо популярним завдяки коктейлю «Базиліковий смеш», що вже став класичним.'),
  (223, 'ua', 'Кардамон', 'Цейлонська приправа, що росте на трав''янистих рослинах сімейства імбирних, вважається однією з найяскравіших спецій у світі.'),
  (566, 'ua', 'Корінь імбиру', 'Азійська багаторічна рослина, завезена в Європу ще в часи Середньовіччя. Кореневище має вигляд круглястих шматочків, корисних для підняття імунітету і зняття головного болю. Один шматок кореня важить в середньому 5 г.'),
  (83, 'ua', 'Лід подрібнений', 'Перший «голений» лід бармени зрізували спеціальними ножами з великих крижаних плит. Потім з''явилися подрібнювальні машини та льодогенератори.'),
  (117, 'ua', 'Ситечко', 'Використовують разом із шейкером і стрейнером для подвійного проціджування коктейлю при переливанні з шейкера в келих. Менша ніж у стрейнера сітка не допускає потрапляння в напій навіть найдрібніших фруктових кісточок і крижинок.'),
  (52, 'ua', 'Мадлер', 'Незамінний аксесуар для тропічних коктейлів. Ним чавлять ягоди та фрукти в шейкері або відразу в келиху.'),
  (373, 'ua', 'Прищіпки', 'Декоративний аксесуар служить для кріплення прикрас до келиха.'),
  (113, 'ua', 'Абсент', 'Французький міцний алкогольний напій виготовляють методом мацерації ароматних трав і спецій, у тому числі меліси, фенхелю і бодяну, на зерновому або винному спирті. Основний компонент – полин, який містить туйон, що відповідає за одурманюючий ефект.'),
  (295, 'ua', 'Цукровий сироп', 'Цукровий сироп'),
  (152, 'ua', 'Малина', 'Невелика червона ягода, що росте на багаторічних напівчагарниках, переважно, в Росії, Сербії, Польщі та США. Містить цукор, органічні кислоти, вітаміни А, B, С, жирні олії. Одна ягода важить в середньому 5 г.'),
  (125, 'ua', 'Односолодовий віскі Хайленд', 'Шотландський міцний алкогольний напій виробляють у високогірному регіоні Шотландії – Хайленд, зі 100% ячмінного солоду методом двократної, рідше трикратної дистиляції. Отримані спирти витримують не менше 3 років в дубових бочках.'),
  (47, 'ua', 'Мартіні біттер', 'Італійський біттер виробляють c 1872 року шляхом мацерації бленда з більш ніж 20 трав і спецій, в основі яких - шафран, ангостура і Коломбо, в нейтральних спиртах. Отриману основу витримують в дубових пьемонтских бочках, доводять до потрібної фортеці і бутилюють.'),
  (189, 'ua', 'Грейпфрутовий сік', 'При виробництві соку грейпфрути пускають під прес, потім фільтрують і розливають у пляшки.'),
  (672, 'ua', 'М''ята', 'Найрозрекламованіша трава в коктейльному світі налічує понад 30 видів. У міксології, переважно, використовується перцева та солодка. Зберігається в холодильнику в паперовому рушнику не більше 2 діб.'),
  (371, 'ua', 'Свізл стік', 'Невелика паличка з деревини кварарібії з відростками гілок, які утворюють форму своєрідного міксера. Ідеально підходить для змішування коктейлів, поданих з подрібненим льодом, прямо в келиху.'),
  (124, 'ua', 'Зелений шартрез', 'Монастирський лікер з Французьких Альп виробляють за секретним рецептом з 1764 року. Близько 130 рослин і трав піддають мацерації в нейтральному спирті і кілька разів дистилюють. Отриману основу балансують цукром, доводять до потрібної міцності і витримують у дубових бочках.'),
  (427, 'ua', 'Лікер з квіток бузини', 'Французький квітковий лікер виготовляють секретним методом мацерації подрібнених квіток бузини в нейтральному спирті. Основу, що утворюється, фільтрують, змішують з цукром та розбавляють водою до потрібної міцності.'),
  (35, 'ua', 'Сухий вермут', 'Легкий італійський аперитив презентували у 1900 році. Створення ідеального рецепта цього напою зайняло цілих 10 років. В основі MARTINI EXTRA DRY — складний букет екзотичних рослин, завдяки чому цей вермут демонструє особливі смакові та ароматні якості. В них можна розпізнати нотки малини й лимона на фоні есенції ірису, з легкими штрихами дерева й хересу. Все це вінчає збалансований свіжий післясмак із кислинкою. Унікальність цього напою робить його незамінним компонентом багатьох коктейлів.'),
  (130, 'ua', 'Лікер драй оранж', 'Ароматний цитрусовий лікер виготовляють методом мацерації цедри апельсинів лараха в нейтральному спирті з водою. Основу, що утворюється, фільтрують, змішують з цукром і витримують в дубових бочках.'),
  (114, 'ua', 'Пишо бітер', 'Новоорлеанський класичний бітер, придуманий знаменитим аптекарем у 1830-х роках, виробляють за секретною рецептурою методом мацерації в нейтральних спиртах анісу, гвоздики, ванілі, мускатного горіха, ягід та спецій.'),
  (161, 'ua', 'Кубок', 'Королівський келих з потовщеним склом, що дозволяє цокатися з сусідом так, щоб напої в келихах перехлеснулися. Стандартний об''єм: 200-300 мл'),
  (665, 'ua', 'Лікер мараскино', 'Ягідний лікер родом з Хорватії виробляють методом мацерації ягід і кісточок мараскинової вишні в нейтральному спирті з водою не менше місяця. Отриману основу фільтрують, підсолоджують, доводять до потрібної міцності і витримують в дубових бочках не менше трьох років.'),
  (303, 'ua', 'Грейпфрутовий бітер', 'Сезонний літній бітер виготовляють методом мацерації цедри грейпфрута в нейтральних спиртах з додаванням рослинного хмелю для пом''якшення гіркоти.'),
  (20, 'ua', 'Червона коктейльна вишня', 'Особливі сорти ягід, "Королівська Анна", "Райнер" або "Золота різноманітність", поміщають в соляний розчин, а потім вимочують в цукровому сиропі з додаванням барвника.'),
  (96, 'ua', 'Коктейльна шпажка', 'Декоративний аксесуар для подачі оливок до мартіні або коктейльної вишні до коктейлю «Манхеттен». З''явився у барах в кінці XIX століття завдяки маркетинговому генієві Чарльзу Форстеру.'),
  (101, 'ua', 'Витриманий ром', 'Карибський міцний алкогольний напій виготовляють методом вертикальної перегонки спирту, отриманого шляхом бродіння патоки або соку цукрової тростини. Перед купажуванням витримують в обпалених дубових бочках з-під хересу або бурбону від 2 до 7 років, залежно від вибраного методу старіння.'),
  (116, 'ua', 'Коричневий какао лікер', 'Темний шоколадний лікер роблять методом перколювання какао бобів з нейтральним спиртом. Основу, що утворюється, розбавляють водою до потрібної міцності і змішують з мадагаскарською ваніллю та карамеллю, які надають лікеру темний колір.'),
  (67, 'ua', 'Склянка для змішування', 'Класична склянка з барної стійки п''ятизіркового готелю. Служить для приготування міцних чоловічих напоїв без додавання соків, трав і джемів. Лід не деформується і не встигає розтанути, зберігаючи міцність напоїв. Стандартний об’єм: 500-900 мл.'),
  (166, 'ua', 'Амаро', 'Італійський лікер-дигестив виготовляють методом мацерації трав і коріння, в тому числі і цедри цитрусових, ялівцю, фенхелю, меліси, бодяну та кардамону, в нейтральному спирті. Основу, що утворюється, фільтрують, змішують з цукром і розбавляють водою до потрібної міцності.'),
  (171, 'ua', 'Крижана сфера', 'Гордість японських барменів – лід, поставлений в ранг предметів мистецтва. Сьогодні частіше з''являється в барах завдяки машинам. У злегка нагріті лещата поміщають заготовлений крижаний куб, метал розігрівається водою і обрізає заздалегідь заготовлену по контору кулю.'),
  (3, 'ua', 'Лимон', 'Тропічний цитрусовий фрукт, що росте на невеликих вічнозелених деревах, переважно, в Китаї, Індії та Мексиці. Містить вітамін С і органічні кислоти, незамінний при авітамінозі та застуді. Один плід важить 160 г і дає 60 мл соку, розрізається на 8 кілець або 4 великі частинки.'),
  (62, 'ua', 'Бурбон', 'Американський міцний алкогольний напій, згідно із законами, виготовляється з вмістом не менше 51% курудзяного солоду, а також дистильованих і фільтрованих ячменю й жита. Витримані спирти чекають свого часу в дубових бочках, обпалених з середини за спеціальною технологією, від 2 до 7 років.'),
  (111, 'ua', 'Чорносмородиновий лікер', 'Діжонський ягідний лікер роблять методом мацерації ягід чорної смородини в нейтральному спирті та воді до двох місяців. Перший сік без віджимання фільтрують і змішують з цукром.'),
  (63, 'ua', 'Ангостура бітер', 'Венесуельський старовинний бітер, названий в честь однойменного міста, виготовляють за рецептом Йохана Готтліба Бенджаміна Зігерта (1800-ті роки) методом мацерації секретного набору трав та спецій в темних ромових спиртах.'),
  (16, 'ua', 'Нежирні вершки', 'Виробляють переважно з коров''ячого молока методом часткової сепарації - відділення вершків від молока. Відсоток жирності в різних країнах різниться, але не перевищує 15%. Зберігається в холодильнику не більше 20 днів.'),
  (36, 'ua', 'Червоний вермут', 'Своїм народженням популярний вермут зобов''язаний союзу вина, спирту, цукру та 35 альпійським травам і прянощам. Створений у 1863 році Луїджі Россі, оригінальний MARTINI— справжня ікона di Italia, визнаний символ італійського аперитиву. Терпкі пряні ноти MARTINI Rosso відмінно доповнить тонік і шматочок апельсина — такий напій ідеально підійде для легкої вечері з друзями.'),
  (34, 'ua', 'Содова', 'Газована вода, що стала незамінним компонентом фізів та інших газованих напоїв, раніше робилася методом газування вуглекислим газом. Сьогодні все частіше готується шляхом додавання харчової соди до чистої води.'),
  (732, 'ua', 'Апельсинова цедра', 'Верхній шар шкірки апельсина, який зрізують спеціальним гострим ножем. Містить ефірні олії, які і визначають аромат. Цедра може бути зрізана як з частини, так і з усього апельсина , дрібно натерта і, навіть, закручена в спіраль, яка називається твістом.'),
  (258, 'ua', 'Просекко', 'Згідно з Апелласьйоном 2009 року, назву Просекко можуть носити лише вина з виноградників даного регіону. Зібраний вручну виноград Глера піддається бродінню у вакуумній тарі, що дозволяє зберігати його смак набагато довше. Iгристе вино відрізняється виразним ароматом із відтінками весняних білих квітів, зеленого яблука та цитрусових плодів, має приємний смак із ніжним фруктовим наповненням і тонкою мінеральністю в післясмаку. Ідеальне в гастрономічному поєднанні з морепродуктами та твердими сирами.'),
  (148, 'ua', 'Персикове пюре', 'Персикове пюре'),
  (535, 'ua', 'Персик', 'Сонячний фрукт, що росте на листяних деревах, переважно, в Китаї, Італії та Іспанії. Містить органічні кислоти, мінеральні солі та пектини. Один плід важить в середньому 120 г, з яких можна отримати 80 г пюре.'),
  (59, 'ua', 'Флюте', 'Світський келих для коктейлів на основі шампанського та ігристих вин. Подовжена вузька форма, що нагадує тюльпан, зберігає максимум бульбашок в коктейлі, дозволяючи йому довго залишатися іскристим. Стандартний об''єм: 180-250 мл'),
  (179, 'ua', 'Лаймовий сироп', 'Старовинний цитрусовий сироп виробляють методом пастеризації з соку лайма, змішаного з цукровим сиропом, винним каменем і водою.'),
  (733, 'ua', 'Лаймова цедра', 'Верхній шар шкірки лайма, який зрізують спеціальним гострим ножем. Містить ефірні олії, які і надають аромат. Цедра може бути зрізана як з частини, так і з цілого лайма, дрібно натерта і, навіть, закручена в спіраль, яка називається твістом.'),
  (72, 'ua', 'Коктейльний келих', 'Мартіні, один з перших у світі келихів для подачі коктейлів без льоду. Перед подачею келих обов''язково охолоджують, а довга ніжка не дає коктейлю нагрітися від руки. Стандартний об''єм: 90-160 мл.'),
  (40, 'ua', 'Коньяк', 'Французький міцний алкогольний напій народжується з білого винограду сорту «уні блан», рідше «фоль бланш» або «коломбарабо монтіль».Пройшовши процес подвійної дистиляції, витримується в дубових бочках – V.S. (Very Special) до 3 років; V.S.O.P (Very Superior Old Pale) до 5 років.'),
  (14, 'ua', 'Мелений мускатний горіх', 'Індонезійська приправа, приготована з висушених і перемелених в порошок горіхів мускатного дерева.'),
  (746, 'ua', 'Тертушка для мускату', 'Корисний аксесуар для виготовлення пудри з мускатного горіха або шоколаду, рідше – дрібно натертої цедри цитрусових.'),
  (8, 'ua', 'Апельсиновий сік', 'При виробництві соку апельсини пускають під прес, потім фільтрують і розливають у пляшки.'),
  (88, 'ua', 'Білий ром', 'Карибський міцний алкогольний напій виробляють методом вертикальної перегонки спирту, отриманого шляхом бродіння патоки або соку цукрової тростини. Перед купажуванням витримують не менше 12 місяців в обпалених дубових бочках з-під бурбона та фільтрують, щоб знебарвити напій.'),
  (92, 'ua', 'Кальвадос', 'Виробництво французького міцного алкогольного напою розпочинається з сидру, який роблять методом ферментації соку осінніх нормандських яблук з додаванням спресованої м''якоті в сталевих чанах від півроку до року. Потім напій піддають подвійній дистиляції і витримують в дубових бочках не менше 2 років.'),
  (77, 'ua', 'Гренадін', 'Популярний сироп з червоних ягід виробляють методом пастеризації гранатового соку з додаванням соків інших червоних ягід, ванілі та тростинного цукру.'),
  (86, 'ua', 'Темний ром', 'Карибський міцний алкогольний напій виготовляють методом вертикальної перегонки спирту, отриманого шляхом бродіння патоки або соку цукрової тростини. Перед купажуванням витримують в обпалених дубових бочках з під бурбона від 2 до 7 років і не фільтрують для збереження кольору.'),
  (365, 'ua', 'Надміцний ром', 'Карибський надміцний алкогольний напій виробляють методом вертикальної перегонки спирту, отриманого шляхом бродіння патоки або соку цукрової тростини. Перед купажуванням витримують не менше року в обпалених дубових бочках з-під бурбона і не розбавляють водою для збереження міцності.'),
  (190, 'ua', 'Грейпфрут', 'Популярний цитрусовий фрукт, що росте, переважно, в Китаї, США та Мексиці. Містить вітамін С, пектин і лікопен, що знижує рівень холестерину. Один плід важить в середньому 600 г, розрізається на 10 шматочків або часточок і дає 200 мл соку.'),
  (186, 'ua', 'Тікі-келих', 'Керамічні боввани, що первісно символізують полінезійських богів, служать для подачі тікі-коктейлів.'),
  (662, 'ua', 'Ірландський віскі', 'Ірландський міцний алкогольний напій виробляють з пророслого ячмінного солоду. Підсушені в печі зерна перемелюють і заливають гарячою водою. Відокремлену від зернового залишку рідину зброджують, тричі переганяють і залишають визрівати в дубових бочках з-під хересу, бурбона або портвейну не менше 3 років.'),
  (128, 'ua', 'Жирні вершки', 'Виробляють переважно з коров''ячого молока методом часткової сепарації - відділення вершків від молока. Відсоток жирності в різних країнах варіюється від 20 до 40%. Зберігається в холодильнику не більше 20 днів.'),
  (74, 'ua', 'Миска', 'Скляна або металева місткість для збивання інгредієнтів за допомогою вінчика. Для міксів з додаванням томатного або цитрусового соків використовують тільки скляні миски або з нержавіючої сталі, що не реагують на кислоту.'),
  (90, 'ua', 'Келих для ірландської кави', 'Міцний келих для подачі гарячих грогів, глінтвейнів і коктейлів з кавою, на честь одного з яких він і названий. Стандартний об’єм: 200-300 мл.'),
  (78, 'ua', 'Вінчик', 'Незамінний для приготування піни з вершків для «Ірландської кави» або збивання яєчного жовтка з цукром для «Том і Джеррі». Для змішування або збивання інгредієнтів в глечиках використовують версію з подовженою ручкою і маленьким наконечником на кінці.'),
  (761, 'ua', 'Кавомашина', 'Автоматична машина для приготування кави різних видів: лате, еспресо, американо, лате макіато, капучино, глясе.'),
  (39, 'ua', 'Кашаса', 'Бразильський міцний алкогольний напій виготовляють методом ретельної фільтрації і дистиляції соку цукрової тростини, що забродив, за єдиною схемою – "голову" і "хвіст" відкидають, залишаючи лише "серце" напою для подальшої витримки у бочках з дуба не менше року.'),
  (5, 'ua', 'Лайм', 'Тропічний цитрусовий фрукт, що росте, переважно, в Китаї, Індії та Мексиці. Містить клітковину, вітамін С і кальцій, добре розкриває аромат і смак інших продуктів. Один плід важить в середньому 80 г і дає 30 мл соку, розрізається на 4 шматочки або 8 кілець.'),
  (43, 'ua', 'Малиновий сироп', 'Популярний ягідний сироп виробляють методом пастеризації соку з ягід малини, змішаного з цукром та водою.'),
  (661, 'ua', 'Цитрусова горілка', 'Міцний ароматизований алкогольний напій виготовляють методом багатократної перегонки зернового спирту, змішаного з чистою водою , що пройшов різні ступені очищення вугільними та іншими фільтрами. Напій, що утворюється, ароматизують екстрактами цитрусових, у тому числі лайма.'),
  (481, 'ua', 'Сік журавлини', 'Для виробництва соку ягоди журавлини пускають під прес, а потім фільтрують і розливають у пляшки.'),
  (53, 'ua', 'Пальник', 'Аксесуар джентльмена, що дозволяє підпалити ефірні олії над знаменитим «Космополітеном», посипати іскристою корицею тікі-коктейль або просто дати прикурити гостю сигару.'),
  (82, 'ua', 'Портвейн Тоні', 'Насичений червоний портвейн виробляють із суміші червоних витриманих вин з додаванням коньячних спиртів та їх наступною витримкою в дубових бочках за методом "солера".'),
  (49, 'ua', 'Жовток перепелиного яйця', 'Продукт надає коктейлям ніжну текстуру.'),
  (178, 'ua', 'Ножиці для перепелиних яєць', 'Спеціальні ножиці з кільцем для фіксації яйця і лезом, яке здійснює надріз немов циркулем.'),
  (569, 'ua', 'Селера', 'Зонтична рослина, відома ще стародавнім грекам, росте, переважно, в помірному кліматі. Волокна перед подачею видаляють, зробивши невеликий надріз на стеблі і потягнувши за «нитки». Одне стебло важить в середньому 15 г.'),
  (42, 'ua', 'Червоний соус табаско', 'Червоний перцевий соус роблять із добірних стиглих перців чилі, витриманих протягом трьох років в бочках з лімузенського дуба в солі з Ейвері Айленд. Отриману основу присмачують оцтом та залишають ще на чотири тижні. На смак гостріший, ніж його зелена версія.'),
  (56, 'ua', 'Мелений чорний перець', 'Індійська мелена приправа, створена з недозрілих ягід чорного перцю, висушених на сонці до чорноти. На відміну від гранульованої версії аромат випаровується набагато швидше.'),
  (58, 'ua', 'Хайбол', 'Високий келих для подачі води, соків або клубних міксів, змішаних методом білд відразу в склянці. Стандартний об`єм: 300-400 мл.'),
  (37, 'ua', 'Шотландське віскі', 'Шотландський міцний алкогольний напій виробляють з ячмінного солоду. Висушені над торфом зерна перемелюють і заливають гарячою водою. Відокремлену від зернового залишку рідину зброджують, тричі переганяють, а отримані спирти змішують і залишають визрівати в дубових бочках.'),
  (46, 'ua', 'Вишневий лікер', 'Знаменитий ягідний лікер виготовляють методом мацерації вишні різних сортів в нейтральному спирті з водою не менше місяця. Основу, що утворюється, фільтрують, підсолоджують, закріплюють коньячними спиртами і витримують в дубових бочках не менше 3 років.'),
  (89, 'ua', 'Золотий ром', 'Карибський міцний алкогольний напій отримують методом вертикальної перегонки спирту, отриманого шляхом бродіння патоки або соку цукрової тростини. Перед купажуванням витримують від 1 до 5 років в обпалених дубових бочках з-під бурбона, не фільтрують, а іноді навіть підфарбовують карамеллю.'),
  (94, 'ua', 'Кола', 'Найпопулярніший сильногазований напій виробляється за секретною рецептурою на основі кофеїну, цукру, незліченного числа ароматизаторів і барвників.'),
  (60, 'ua', 'Світлий какао-лікер', 'Світлий шоколадний лікер виробляють методом перколяції какао-бобів з нейтральним спиртом. Отриману основу фільтрують, позбавляючись від темного кольору, і змішують з цукром до кремової густини.'),
  (61, 'ua', 'Зелений м’ятний лікер', 'Трав’яний кремовий лікер виробляють з великим вмістом цукру методом перколяції екстрактів свіжої перцевої м''яти з лаймовими дистилятами в нейтральному спирті. Отриману основу доводять до потрібної солодкості та міцності та розливають у пляшки.'),
  (93, 'ua', 'Срібна текіла', 'Мексиканський міцний алкогольний напій традиційно виробляють методом перегонки з соку блакитної агави. Сімдесятилітні піньї поміщають в спеціальні печі для перетворення крохмалю в цукор, потім сік, що вийшов, ферментують, піддають подвійній дистиляції та розливають у пляшки відразу після фільтрації.'),
  (212, 'ua', 'Імбирне пиво', '«Троянський кінь» горілки в Америці або особливий сорт пряного лимонаду виготовляють шляхом мацерації меленого сушеного імбиру в пивній заквасці.'),
  (99, 'ua', 'Мигдальний сироп', 'Мигдальний сироп'),
  (127, 'ua', 'Сіль', 'Кристалічна приправа з мінералів, вік яких може доходити до більш ніж 250 млн років.'),
  (84, 'ua', 'Келих Маргарита', 'У минулому житті соусник для гуакамоле виступає сьогодні в ролі фірмового келиха для подачі найпопулярнішого в світі коктейлю на основі текіли. Стандартний об’єм: 250-350 мл.'),
  (85, 'ua', 'Апельсиновий бітер', 'Найстаріший цитрусовий бітер виробляють методом мацерації підсушеної цедри апельсинів, спецій і коріння в ромових спиртах з додаванням тростинного цукру та дистильованої води перед бутелюванням.'),
  (75, 'ua', 'Сироп маракуйї', 'Тропічний фруктовий сироп виробляють методом пастеризації соку з м''якоті маракуйї, змішаного з тростинним цукром і водою.'),
  (7, 'ua', 'Ананасовий сік', 'При виробництві соку м''якіть ананаса пускають під прес, потім фільтрують і розливають у пляшки.'),
  (76, 'ua', 'Харрікейн', 'Антикварна гасова лампа-келих для подачі тропічних напоїв, названа на честь однойменного класичного коктейлю від Пета О''Брайна. Стандартний об’єм: 300-400 мл.'),
  (4, 'ua', 'Апельсин', 'Жовтогарячий цитрусовий фрукт, що росте, переважно, в Бразилії, США та Китаї. Містить вітамін С, калій і кальцій, які позитивно впливають на роботу серця, судин та організму в цілому. Один плід важить в середньому 300 г і дає 80 мл соку, розрізається на 10 кілець або 8 часточок.'),
  (375, 'ua', 'Колінз', 'Високий келих для лонг- та мікс-дрінків. Названий на честь класичного коктейлю «Том Колінз». Стандартний об’єм: 300-400 мл.'),
  (104, 'ua', 'Бенедиктин', 'Відомий нормандський лікер, прикрашений написом «DOM – DEO Optimo Maximo» (лат. За найбільшого і кращого бога), який виготовляють з 27 секретних трав та прянощів в чотири етапи. Після мацерації і дистиляції, отримані основи витримують, спочатку окремо, а потім разом, 11 місяців в дубових бочках. Потім змішують з водою, коньяком, медом і паленим цукром та доводять до ідеалу завершальним етапом 3-х місячної витримки.'),
  (95, 'ua', 'Ананас', 'Великий тропічний фрукт, що росте на наземних колючих рослинах, переважно, в Бразилії, Тайланді і Філіппінах. Містить марганець і вітамін С, що стимулюють травлення та знижують в''язкість крові. Один плід важить в середньому 1200 г і розрізається, приблизно, на 40 частин.'),
  (105, 'ua', 'Слінг', 'Канонічний келих для подачі однойменного коктейлю, який став візитною карткою готелю «Раффлс». Стандартний об’єм: 200-300 мл.'),
  (79, 'ua', 'Вода без газу', 'Найважливіше джерело здоров''я та довголіття. Бармени всього світу рекомендують завжди пити воду під час дегустації коктейлів, тому в кращих барах світу келих чистої води до коктейлю завжди є компліментом від бару.'),
  (150, 'ua', 'Цукор в кубиках', 'Європейська солодка приправа виготовляється методом складного очищення, переробки та кристалізації сиропу цукрового очерету або соку цукрового буряка. Отримані кристали спресовують у необхідну форму.'),
  (100, 'ua', 'Драмбуї', 'Шотландський лікер, в перекладі з гельської означає «той, що приносить задоволення», виготовляється за секретною рецептурою з 1910 року. Відомо, що до складу напою входить купаж односолодових віскі від іменитих віскікурень, вересовий мед, трави та прянощі.'),
  (677, 'ua', 'Вода з квіток апельсина', 'Найдавніша ароматизована вода на основі свіжих квіток гіркого апельсина.'),
  (118, 'ua', 'Ананасове листя', 'Листя тропічного фрукта використовують як прикрасу для екзотичних тікі-коктейлів.'),
  (98, 'ua', 'Піско', 'У виробництві перуанського виноградного бренді бере участь до восьми сортів винограду, тоді як в Чилі допускають не більше трьох. Заброджений сік дистилюють у сталевих чанах і відразу розливають або витримують у дубових бочках до 2 років.'),
  (103, 'ua', 'Тростинний цукор в кубиках', 'Тропічна солодка приправа виробляється методом кристалізації цукрового очерету з його подальшим пресуванням в маленькі кубики. Чим вищий вміст патоки, тим темніший колір і насиченіший смак.');
INSERT INTO drink_me_bot.goods_i18n (goods_id, lang, name, description) VALUES
  (132, 'ua', 'Витриманий бурбон', 'Витриманий бурбон'),
  (102, 'ua', 'Цукрова пудра', 'Солодку порошкоподібну приправу отримують з перемеленого до стану пудри цукру. Завдяки своїм розмірам вона вмить розчиняється в рідині.'),
  (158, 'ua', 'Мідний кухоль', 'Фронтовий посуд, що став «троянським конем» для горілки в Америці і фірмовим посудом для подачі класичного коктейлю «Московський мул». Стандартний об''єм: 300-400 мл'),
  (214, 'ua', 'Ожина', 'Темно-фіолетова ягода середніх розмірів, що росте в Європі, Північно-західній Африці, Центральній Азії, Північній та Південній Америці. Містить каротин, вітаміни С, В1 і В2, К та інші. Одна ягода важить в середньому 6 г.'),
  (115, 'ua', 'Цукровий пісок', 'Європейська солодка приправа виготовляється методом доладного очищення, переробки та кристалізації сиропу цукрової тростини або соку цукрового буряка. Калібр помолу варіюється: чим дрібніший, тим швидше розчиняється.'),
  (107, 'ua', 'Молоко', 'Виробляють з цільного коров''ячого молока. Потрібний відсоток жирності продукт набуває після сепарації вершків шляхом додавання в уже знежирену версію потрібної кількості відокремленого жиру.'),
  (330, 'ua', 'Кориця в паличках', 'Цейлонську приправу, відому ще в XV столітті, роблять з кори дерева кориці, яку зачищають, шліфують і висушують в тіні, доки вона не скрутиться в трубочки.'),
  (108, 'ua', 'Чашка', 'Висока керамічна чашка для кави або чаю, що стала в 1930 році символом класичного коктейлю «Том і Джері». Стандартний об''єм: 200-250 мл'),
  (655, 'ua', 'Пітчер', 'Металевий чайник. Використовують для збивання вершків і приготування зігріваючих коктейлів.'),
  (120, 'ua', 'Мелена кориця', 'Цейлонська мелена приправа, відома ще в XV столітті, виготовляється з висушених і змелених стружок та обрізок кори дерева кориці.'),
  (149, 'ua', 'Бодян', 'Тропічні зіркові плоди, що ростуть на вічнозелених деревах, переважно, в Китаї. Збирають недозрілими і висушують на сонці.'),
  (134, 'ua', 'Кленовий сироп', 'Славнозвісний різдвяний сироп роблять із соку цукрового клена, який збирають з дерев у лютому-березні аналогічно з березовим соком. Виробляють методом пастеризації соку з тростинним цукром та водою.'),
  (123, 'ua', 'Сироп троянди', 'Ніжний квітковий сироп виробляють методом мацерації та пастеризації пелюсток троянди в цукровому сиропі.'),
  (201, 'ua', 'Пелюстки троянд', 'Найбільш продавана квітка у світі. В одному бутоні 25 пелюсток.'),
  (1035, 'ua', 'Американський віскі', 'Американський віскі'),
  (288, 'ua', 'Херес Педро Хіменес', 'Найсолодший вид іспанського кріпленого вина виробляють з однойменного максимально дозрілого винограду. Виноградний сік, що пройшов період ферментації, закріплюють виноградними спиртами і витримують в дубових бочках методом "солера" впродовж тривалих термінів, від 10 до 30 років, а то й більше.'),
  (154, 'ua', 'Чайна ложка', 'Ложка для розмішування чаю в чашці. В одній ложці вміститься в середньому 5 г сухого інгредієнта або 5 мл рідини.'),
  (211, 'ua', 'Крижаний куб', 'Колотий або рівної кубічної форми. Великі шматки льоду повільніше тануть та солідніше виглядають у келиху.'),
  (450, 'ua', 'Імбирний сироп', 'Пряний азійський сироп роблять методом пастеризації екстрактів імбиру в цукровому сиропі.'),
  (693, 'ua', 'Бомбілья', 'Спеціальна трубочка для подання мате. Верхня частина оснащена мундштуком, а нижня – ситечком.'),
  (552, 'ua', 'Червона смородина', 'Маленька червона ягода, що росте на деревних чагарниках, переважно, в Центральній та Північній Європі, а також у Північній Азії. Містить велику кількість вітаміну С, різні цукри, органічні кислоти та мінерали. В одній барній ложці вміститься 5 г ягід.'),
  (332, 'ua', 'Херес Олоросо', 'Напівсухе або солодке іспанське кріплене вино виробляють методом ферментації винограду сорту Паломіна без утворення захисної плівки флор. Отриману основу закріплюють поетапно виноградними спиртами і витримують у дубових бочках методом "солера" не менше двох років.'),
  (191, 'ua', 'Курага', 'Сонячний сухофрукт, виготовляють, переважно, в Туреччині, Ірані та Узбекистані. Роблять їх зі стиглих абрикосів. Фрукти спочатку виварюють або замочують в сиропі, а потім висушують на сонці чи в сушарних апаратах. Одна штучка в середньому важить 10 г.'),
  (683, 'ua', 'Таця', 'Металевий або дерев''яний лист для подачі їжі або напоїв гостю.'),
  (121, 'ua', 'Ванільний сироп', 'Мадагаскарський пряний сироп виробляють методом мацерації та пастеризації стручків ванілі в цукровому сиропі.'),
  (381, 'ua', 'Золота текіла', 'Мексиканський міцний алкогольний напій традиційно виробляють методом перегонки із соку блакитної агави. Сімдесятилітні піньї поміщають в спеціальні печі для перетворення крохмалю в цукор. Отриманий сік ферментують, піддають подвійній дистиляції, підфарбовують карамеллю та присмачують ароматичними добавками.'),
  (318, 'ua', 'Білий вермут', 'Легкий італійський аперитив, створений у 1910 році. Кріплене вино ароматизують пряними і лікарськими травами, квітами, насінням і фруктами, серед яких полин, м''ята, кориця, мускатний горіх, кора хінного дерева. Ванільні нотки солодкого Martini Bianco найкраще розкриваються в поєднанні з тоніком і шматочком лайма – цей легкий освіжаючий коктейль ідеально підійде для вечері з друзями.'),
  (126, 'ua', 'Полуничне пюре', 'Полуничне пюре'),
  (327, 'ua', 'Тростинний цукровий пісок', 'Тропічна солодка приправа виготовляється методом кристалізації цукрової тростини з її подальшою механічною обробкою. Чим вищий вміст патоки, тим темніший колір і насиченіший смак.'),
  (326, 'ua', 'Бутель', 'Класична посудина для зберігання алкогольних та безалкогольних напоїв.'),
  (138, 'ua', 'Блендер', 'Винайдений у 1922 році Стівеном Поплавскі електричний інструмент залишається незамінним для приготування тікі-коктейлів, смузі та холодних напоїв.'),
  (196, 'ua', 'Кокосовий сироп', 'Найпопулярніший тропічний сироп виготовляють методом пастеризації кокосової води з тростинним цукром.'),
  (197, 'ua', 'Слайсер для ананасу', 'Тікі-аксесуар дозволяє в лічені секунди очистити ананас від шкірки та твердої серцевини.'),
  (744, 'ua', 'Совок для льоду', 'Зручний інструмент з полікарбонату або нержавіючої сталі, який дозволяє набирати певну порцію льоду. Совки розрізняються розмірами і об’ємами чаші, що дозволяє підібрати інструмент під необхідну кількість льоду.'),
  (406, 'ua', 'Жовтий банановий лікер', 'Тропічний кремовий лікер виготовляють методом мацерації м''якоті жовтих бананів в нейтральному спирті з водою. Основу, що вийшла, фільтрують та змішують з цукром і закріплюють молодими коньячними спиртами.'),
  (200, 'ua', 'Банан', 'Стародавня тропічна трав''яниста рослина, що росте, переважно, в Індії, Китаї та Уганді. Фрукт містить вітамін B6, марганець та харчові волокна. Один плід важить в середньому 200 г, з яких 80 г – шкірка.'),
  (244, 'ua', 'Дженевер', 'Голландський міцний алкогольний напій, прабатько джина, виготовляється з XV століття методом дистиляції чистого спирту з додаванням ягід ялівцю та інших спецій.'),
  (133, 'ua', 'Медовий сироп', 'Топовий за популярністю сироп виробляють методом пастеризації натурального меду, розведеного до потрібної консистенції водою.'),
  (293, 'ua', 'Заварний чайник', 'Історія античної китайської посудини почалася там же і тоді ж, що й історія самого чаю – в Китаї у XIV столітті. Служить для заварювання чаю, трав і спецій в гарячій воді або соці.'),
  (287, 'ua', 'Односолодове віскі з острова Айла', 'Односолодове віскі з острова Айла'),
  (284, 'ua', 'Ревеневий лікер', 'Десертний кисло-солодкий трав''яний лікер виробляють методом мацерації стеблин і листя ревеню в нейтральному спирті з водою. Отриману основу змішують з цукром і доводять до потрібної міцності.'),
  (358, 'ua', 'Чинар', 'Трав''яний італійський лікер виготовляють методом дистиляції та мацерації 16 трав і спецій, з артишоком як основним компонентом, в нейтральному спирті. Отриману основу фільтрують і доводять до потрібної міцності та солодкості.'),
  (735, 'ua', 'Грейпфрутова цедра', 'Верхній шар шкірки грейпфрута, який зрізують спеціальним гострим ножем, містить ефірні олії, які і визначають аромат. Цедра може бути зрізана як і з частини, так і з усього грейпфрута, дрібно натерта і навіть закручена в спіраль, яка називається твістом.'),
  (704, 'ua', 'Спреєр', 'Гарний аксесуар для розпилення бітерів та ароматичних добавок над коктейлем.'),
  (435, 'ua', 'Херес Фіно', 'Іспанське сухе кріплене вино роблять методом ферментації винограду паломіно з додаванням спеціальних хересних дріжджів. Витримане не менше 12 місяців вино, покрите спеціальною плівкою – флор, зміцнюється поетапно виноградними спиртами і дозріває в бочках під захисною плівкою не менше 2 років.'),
  (653, 'ua', 'Чарка', 'Невелика склянка, як правило, з прямими стінками. Призначена для найміцніших напоїв або коктейлів, які випивають залпом. Стандартний об’єм: 50-100 мл.'),
  (546, 'ua', 'Полуниця', 'Велика червона ягода, що росте на невеликих чагарниках, переважно, в США, Туреччині, Іспанії, Єгипті та Мексиці. Містить цукор, пектинові та дубильні речовини, аскорбінову, а також інші кислоти; має протизапальну дію. Одна ягода важить в середньому 20 мг'),
  (402, 'ua', 'Лімончело', 'Італійський національний лікер виробляють методом мацерації лимонної цедри в нейтральному спирті протягом місяця. В отриману основу додають цукор і воду, настоюють і фільтрують.'),
  (410, 'ua', 'Лікер лічі', 'Виробляють з м''якоті стиглих лічі, які змішують з алкоголем і дають настоятися.'),
  (486, 'ua', 'Манговий сік', 'При виробництві соку плоди манго пускають під прес, потім фільтрують і розливають у пляшки.'),
  (529, 'ua', 'Маракуя', 'Субтропічний фрукт пристрасті, що росте на вічнозелених ліанах, переважно, в Новій Зеландії, Ізраїлі та на Шрі-Ланці. Містить вітамін А, бета-каротин і калій, має тонізуючий ефект. Один плід важить в середньому 90 г.'),
  (415, 'ua', 'Ожиновий лікер', 'Насичений ягідний лікер виготовляють методом мацерації лісової ожини в нейтральному спирті з водою до двох місяців. Перший сік без віджиму фільтрують та змішують з цукром.'),
  (405, 'ua', 'Зелений яблучний лікер', 'Свіжий фруктовий лікер виробляють методом мацерації м''якоті зелених яблук в нейтральному спирті. Отриману основу фільтрують, змішують з цукром і розбавляють водою до потрібної міцності.'),
  (528, 'ua', 'Яблуко', 'Популярний фрукт родом з Центральної Азії, що росте на листяних деревах, переважно, в Китаї, США та Туреччині. Містить аскорбінову кислоту, вітамін К, калій, корисний для імунітету та боротьби із зайвою вагою. Один плід важить в середньому 200 г і розрізається на 10 частинок.'),
  (682, 'ua', 'Банка з кришкою', 'Велика ємність з кришкою, що щільно прилягає, служить для приготування і зберігання настоянок і наливок. Стандартних об’ємів не існує.'),
  (446, 'ua', 'Сироп агави', 'Мексиканський сироп виготовляють з концентрованого соку агави, що пройшов стабілізацію з додаванням цукрового сиропу.'),
  (432, 'ua', 'Сухе червоне вино', 'Найпоширеніший вид вина отримують методом мацерації і подальшої ферментації чорного і червоного сортів винограду, шкірка якого і надає колір вину. Потім вино зціджують або фільтрують, після чого витримують в дубових бочках не менше 3 місяців.'),
  (613, 'ua', 'Гвоздика', 'Висушені нерозкриті бутони тропічного дерева гвоздики — популярні Індонезійські прянощі.'),
  (705, 'ua', 'Фонтан для абсенту', 'Невід''ємний атрибут традиційної подачі французького міцного напою. В основний відділ заливають воду з додаванням трав, фруктів, а іноді і льоду. Настояний напій крапля за краплею проходить через цукор на ложці і потрапляє в келих з абсентом.'),
  (698, 'ua', 'Ложка для абсенту', 'Невід''ємний атрибут традиційної подачі французького міцного напою. В основний відділ заливають воду з додаванням трав, фруктів, а іноді і льоду. Настояний напій крапля за краплею проходить через цукор на ложці і потрапляє в келих з абсентом.'),
  (494, 'ua', 'Енергетик', 'Енергетичний напій був спеціально розроблений для вживання в періоди підвищеного фізичного та розумового навантаження.'),
  (394, 'ua', 'Айріш крім', 'Ірландський вершковий лікер виробляють з ірландського віскі потрійної дистиляції, вершків і нейтрального спирту. До основи додають какао, ваніль, цукор і карамель.'),
  (547, 'ua', 'Чорниця', 'Маленька фіолетова ягода, що росте в Канаді, Північній Америці, Туреччині та Західній Європі. Містить великий запас вітамінів А, В, С, марганецю і калію. Корисна для зіру. В одній барній ложці поміщається 5 г ягід.'),
  (578, 'ua', 'Лимонна трава', 'Трава з цитрусовим ароматом походить з карибської та азійської кухні і зростає, переважно, на Британських островах, Філіппінах та в Індонезії.'),
  (490, 'ua', 'Спрайт', 'Солодкий газований напій виробляють на основі содової з додаванням цукру та лимонного екстракту.'),
  (666, 'ua', 'Самбука', 'Італійський міцний алкогольний напій виробляють шляхом ароматизації пшеничного спирту з цукром, маслами звичайного та зіркового анісу і вичавками з ягід, квітів бузини і різних трав, що відтіняють його стійкий аромат.'),
  (414, 'ua', 'Яєчний лікер', 'Голландський різдвяний лікер, який походить від бразильського алкогольного напою з авокадо, виготовляється з суміші яєчних жовтків, цукру, ванілі та коньяку.'),
  (531, 'ua', 'Гранат', 'Середземноморський фрукт, що росте на невеликих листяних чагарниках, переважно, в Ізраїлі та Індії. Містить калій та фосфор, які позитивно впливають на серцево-судинну систему. Один плід важить в середньому 300 г і розрізається на 10 частин.'),
  (684, 'ua', 'Келих для вина', 'Класичний, трохи заокруглений, келих традиційно більший ніж келих для білого вина. Стандартний об’єм: 200-300 мл.'),
  (483, 'ua', 'Вишневий сік', 'При виробництві соку ягоди вишні пускають під прес, потім фільтрують і розливають у пляшки.'),
  (551, 'ua', 'Чорна смородина', 'Маленька чорна ягода, що росте в Центральній та Північній Європі, а також Північній Азії. Містить велику кількість вітаміну С, різні цукри, органічні кислоти та мінерали. В одній барній ложці поміщається 5 гр ягід.'),
  (597, 'ua', 'Малиновий джем', 'Джем з червоних ягід, що ростуть на багаторічних напівчагарниках, переважно, в Росії, Сербії, Польщі та США. Зрілі ягоди варять з цукром до однорідного стану. В одній барній ложці вміститься 5 г джему.'),
  (590, 'ua', 'Апельсиновий джем', 'Джем з м''якоті цитрусових фруктів, що ростуть, переважно, в Бразилії, США та Китаї. Зрілі плоди варять з цукром до однорідного стану. В одній барній ложці вміститься 5 г джему.'),
  (589, 'ua', 'Мед', 'Квітковий нектар, зібраний і трансформований бджолами.'),
  (652, 'ua', 'Печиво', 'Невеликий кондитерський виріб, який випікають в печі з різного тіста.'),
  (686, 'ua', 'Глечик', 'Старовинний кухонний посуд для подачі води, лимонадів та сангрії. Стандартний об’єм: 500-3000 мл.'),
  (484, 'ua', 'Гранатовий сік', 'При виробництві соку зерна граната пускають під прес, потім фільтрують і розливають у пляшки.'),
  (548, 'ua', 'Кавун', 'Особливий вид великої ягоди, яку висаджують розсадою, переважно, в Китаї, Туреччині та Ірані. Містить глюкозу та фруктозу, пектини, кальцій, магній, лужні речовини; нормалізує обмін речовин. Одна ягода важить в середньому 5000 г, кільце – 300 г, співвідношення ваги м''якоті і шкірки – 60% до 40%.'),
  (454, 'ua', 'Сироп лимоннику', 'Лимонний сироп виробляють методом пастеризації екстрактів лимоннику з цукровим сиропом.'),
  (770, 'ua', 'Коктейльна креманка', 'У минулому житті десертний келих для подачі морозива виступає сьогодні в ролі фірмового келиха для мілкшейків, лимонадів та коктейлів. Стандартний об’єм: 250-350 мл.'),
  (433, 'ua', 'Біле вино сухе', 'Літнє вино виготовляється шляхом мацерації і подальшої ферментації очищеного від шкірки винограду білих сортів. Потім вино зціджують або фільтрують, після чого витримують в дубових бочках не менше 3 місяців.'),
  (532, 'ua', 'Ківі', 'Китайський аґрус, зростає на великих ліанах, переважно, в Італії, Новій Зеландії та Чилі. Містить вітамін С, клітковину, фолієву кислоту, кальцій і фосфор, які підсилюють імунну систему людини. Одна ягода важить в середньому 120 г.'),
  (577, 'ua', 'Червоний базилік', 'Пряне, ароматне листя трави, що росте переважно в теплих частинах Старого Світу.'),
  (702, 'ua', 'Сифон для вершків', 'Прилад з товстого скла або металу для швидкого збивання вершків в ніжну повітряну піну. Можна також використовувати для приготування різноманітних десертів, складних соусів, мусів. Стандартний об''єм: 0,5-1 л.'),
  (399, 'ua', 'Персиковий лікер', 'Сонячний фруктовий лікер виробляють методом дистиляції ферментованого персикового соку з додаванням коньячних спиртів для посилення насиченого аромату доданих кісточок.'),
  (396, 'ua', 'Абрикосовий лікер', 'Знаменитий фруктовий лікер виготовляють методом дистиляції ферментованого абрикосового соку з додаванням коньячних спиртів для посилення насиченого аромату.'),
  (691, 'ua', 'Чаша для пуншу', 'Об''ємна посудина зі скла, кришталю або металу для подачі пуншу була привезена з Індії в Англію на початку XVII століття. Стандартний об’єм: 5 л.'),
  (395, 'ua', 'Лікер амарето', 'Класичний італійський лікер виготовляють методом мацерації кісточок абрикосу, різних трав та фруктів в нейтральному спирті. Основу, що утворюється, фільтрують, змішують з цукром, та розбавляють водою до потрібної консистенції.'),
  (556, 'ua', 'Вишня', 'Жовта або яскраво-червона ягода, що росте в країнах з теплим і помірним кліматом, таких як Туреччина, Італія, Іспанія, Чилі. Містить органічні кислоти, мікроелементи, пектинові речовини, фолієву кислоту, вітаміни А, С, Е, B, PP. Одна ягода важить в середньому 5 г.'),
  (437, 'ua', 'Пиво світле', 'Легкий сорт пива виробляють з води, ячменя, екстракту солоду, хмелю і пивних дріжджів.'),
  (452, 'ua', 'Чорносмородиновий сироп', 'Ягідний сироп готують методом пастеризації соку стиглих ягід чорної смородини, змішаного з цукром і водою.'),
  (397, 'ua', 'Динний лікер', 'Азійський тропічний лікер виробляють методом мацерації м''якоті дині в нейтральному спирті з водою. Отриману основу фільтрують, доводять до потрібної солодкості та міцності і розливають.'),
  (763, 'ua', 'Бітер лемон', 'Газований лимонний напій виготовляють методом газування з додаванням лимонних екстрактів.'),
  (380, 'ua', 'Бехерівка', 'Канонічний чеський лікер виготовляється шляхом мацерації міксу 20 трав і спецій в нейтральному спирті, який згодом перемішують з водою та цукром і витримують від двох до трьох тижнів в дубових бочках.'),
  (502, 'ua', 'Чай ерл грей', 'У класичному вигляді – це чорний чай з додаванням олії, отриманої зі шкірки плодів бергамота. Оптимальна температура для заварювання чаю – 90-95°С, час витримки настою – 3-5 хвилин.'),
  (709, 'ua', 'Парасолька', 'Яскрава паперова прикраса для дитячого або тропічного коктейлю.'),
  (639, 'ua', 'Чорнослив', 'Європейський сушений делікатес виробляють зі слив, висушених на сонці або в спеціальних машинах.'),
  (747, 'ua', 'Тарталетка', 'Мініатюрна копія відкритого пирога, що вперше з''явилася в кулінарній книзі кухарів короля Річарда II у 1390 році. Готується з листкового або пісочного тіста з різними начинками.'),
  (453, 'ua', 'Яблучний сироп жовтий', 'Жовтий фруктовий сироп виробляють методом пастеризації соку жовтих сортів яблук з додаванням тростинного цукру.'),
  (576, 'ua', 'Розмарин', 'Середземноморська трава з пряним ароматом сосни.'),
  (409, 'ua', 'Грейпфрутовий лікер', 'Цитрусовий лікер з гірчинкою виробляють методом мацерації цедри рожевих грейпфрутів в нейтральному спирті. Отриману основу фільтрують, змішують з цукром і розбавляють чистою водою до потрібної міцності.'),
  (549, 'ua', 'Журавлина', 'Маленька червона ягода, що росте на кущах, переважно, в США, Чилі, Аргентині та Нідерландах. Містить органічні кислоти, мікроелементи, пектинові речовини, фолієву кислоту та вітаміни А, С, Е, B, PP. В одній барній ложці вміщається 5 г ягід.'),
  (492, 'ua', 'Тонік', 'Газований напій з хініном був винайдений в Індії для боротьби з малярією. Виготовляється із газованої води, змішаної з хініном та невеликою кількістю цукру.'),
  (562, 'ua', 'Червоний виноград', 'Червона ягода середніх розмірів, що росте на ліанах, переважно, в Китаї, США, Італії, Франції та Іспанії. Містить цукор, клітковину, органічні кислоти, вітамін B та інші мікроелементи, які мають зміцнюючу та тонізуючу дію. Одна ягода важить в середньому 5 г.'),
  (663, 'ua', 'Апельсинова горілка', 'Міцний ароматизований алкогольний напій виробляють методом багаторазової перегонки зернового спирту, що пройшов різні ступені очищення вугільними та іншими фільтрами, та змішаного з чистою водою. Напій ароматизують екстрактами стиглих апельсинів.'),
  (530, 'ua', 'Мандарин', 'Тропічний цитрусовий фрукт, що росте на вічнозелених чагарниках, переважно, в Китаї, Іспанії та Бразилії. Містить вітамін С та калій, які сприяють зміцненню імунітету. Один плід важить в середньому 100 г і дає 40 мл соку.'),
  (710, 'ua', 'Лілле Блан', 'Французький винний аперитив отримують через поєднання білих вин регіону Бордо з фруктовими лікерами. Поки вино дозріває, цедру солодких, гірких та кислих зелених апельсинів і хінін настоюють на коньячних спиртах. Потім усе змішують і витримують у дубових бочках 8-12 місяців.'),
  (389, 'ua', 'Пряний ром', 'Карибський пряний алкогольний напій отримують методом вертикальної перегонки спирту, утвореного шляхом бродіння патоки або соку цукрової тростини. Перед купажуванням витримують від 2 до 7 років в обпалених дубових бочках з-під хересу або бурбона з додаванням кориці, мускату, ванілі та інших прянощів.'),
  (398, 'ua', 'Лікер Блю Курасао', 'Неоновий апельсиновий лікер виготовляють методом мацерації висушеної апельсинової цедри в нейтральному спирті з водою. Основу, що вийшла, фільтрують, змішують з цукром і забарвлюють натуральними барвниками.'),
  (550, 'ua', 'Зелений виноград', 'Зелена ягода середніх розмірів, що росте на листяних ліанах, переважно, в Китаї, США, Італії, Франції та Іспанії. Містить цукор, клітковину, органічні кислоти, вітамін B та інші мікроелементи, які надають зміцнюючі та тонізуючі властивості. Одна ягода важить в середньому 5 г.'),
  (533, 'ua', 'Манго', 'Дикий тропічний фрукт, що росте, переважно, в Індії, Пакистані та на Філіппінах. Містить вітамін А, калій і фолієву кислоту, що покращують імунітет та зір. Один плід важить в середньому 300 г і розрізається на 10 часточок.'),
  (408, 'ua', 'Лікер кориці', 'Німецький пряний лікер виготовляють методом мацерації кориці в шнапсі. Основу, що утворюється, фільтрують, змішують з цукром і для ефектності додають харчове сусальне золото.'),
  (495, 'ua', 'Холодний зелений чай', 'Популярний в Азії холодний чай виробляють на основі екстракту зеленого чаю, а також екстрактів інших трав без додавання штучних ароматизаторів та консервантів.'),
  (711, 'ua', 'Джулеп стрейнер', 'Незамінний в роботі зі змішувальною склянкою аксесуар. Слугує також незрівнянною прикрасою однойменного класичного коктейлю. Використовують для фільтрації коктейлю від шматочків льоду, що відкололися та інших незапланованих інгредієнтів.'),
  (670, 'ua', 'Кава еспресо', 'Міцну каву готують шляхом пропускання через мелену каву невеликої кількості гарячої води при температурі близько 90 °C.'),
  (690, 'ua', 'Скляночка для чаю', 'Традиційний турецька скляночка для чаювання. Стандартний об’єм: 40-80 мл.'),
  (412, 'ua', 'Лікер маракуйї', 'Виробляють з м''якоті стиглих плодів маракуйї, апельсинів та грейпфрута, які змішують з алкоголем і дають настоятися.'),
  (615, 'ua', 'Ванільний цукровий пісок', 'Класичний цукровий пісок, ароматизований ваніліном.'),
  (181, 'ua', 'Френч-прес', 'Французький аксесуар для заварювання кави та чаю, що складається зі скляної колби і пресу з ситечком.'),
  (448, 'ua', 'Полуничний сироп', 'Ягідний сироп виробляють методом пастеризації соку стиглої полуниці, змішаного з цукром та водою.'),
  (567, 'ua', 'Перець чилі', 'Гострий тропічний перець, що росте гіллястими стеблами, переважно, в Південній Америці. Багатий на вітаміни А і С, калій, магній і залізо. Один стручок важить в середньому 30 г.'),
  (499, 'ua', 'Чорний чай', 'Вид чаю, що піддається ферментації в період від 2 тижнів до місяця. Росте в районах із тропічним або субтропічним кліматом. Для заварювання 1 ложку сухого чаю потрібно залити 100 мл окропу і дати настоятися 4-5 хвилин.'),
  (411, 'ua', 'Лікер манго', 'Азійський тропічний лікер виробляють методом мацерації м''якоті стиглих манго в нейтральному спирті з водою. Отриману основу фільтрують та змішують з цукром.'),
  (514, 'ua', 'Ванільне морозиво', 'Холодний десерт готують з молока, вершків, масла і цукру з додаванням екстракту ванілі. Зберігається в морозилці не більше місяця.'),
  (592, 'ua', 'Вишневий джем', 'Джем з жовтих або яскраво-червоних ягід, що ростуть на деревах, переважно, в країнах з теплим помірним кліматом, таких як Туреччина, Італія, Іспанія та Чилі. Зі зрілих ягід видаляють кісточку та варять до однорідного стану з цукром. В одній барній ложці вміститься 5 г джему.'),
  (485, 'ua', 'Персиковий сік', 'При виробництві соку персики пускають під прес, потім фільтрують і розливають у пляшки.'),
  (387, 'ua', 'Чорносмородинова горілка', 'Міцний ароматизований алкогольний напій виготовляють методом багатократної перегонки зернового спирту, що пройшов різні ступені очищення вугільними та іншими фільтрами, і змішаного з чистою водою. Напій, що вийшов, ароматизують екстрактами стиглої чорної смородини.'),
  (633, 'ua', 'Рожева вода', 'Антична ароматизована вода на основі пелюсток троянди.'),
  (713, 'ua', 'Малинове пюре', 'Малинове пюре'),
  (586, 'ua', 'Чебрець', 'Ароматна пряність з гілочок низькорослих чагарників, що ростуть, переважно, в Євразії, Північній Африці та Гренландії. Входить до складу прованської суміші, ідеально підходить для ароматизації міцних спиртів.'),
  (407, 'ua', 'Кокосовий лікер', 'Тропічний лікер виготовляють методом мацерації м''якоті кокосів в ромових спиртах. Основу, що утворюється, фільтрують, змішують з цукром і розбавляють водою до потрібної міцності.'),
  (430, 'ua', 'Рожевий вермут', 'Наймолодший вермут з унікального поєднання червоного та білого вина. Кріплене вино, ароматизоване лікарськими травами, квітами, насінням і фруктами, серед яких полин, м''ята, кориця, мускатний горіх, кора хінного дерева, вдало збалансовані в характерному гірко-пряному смаку. Ідеальний аромат чудово розкривається при сервіруванні на льоду.'),
  (646, 'ua', 'Чорний шоколад', 'Кондитерський десерт, приготовлений з темних какао бобів з мінімальним додаванням цукру.'),
  (447, 'ua', 'Карамельний сироп', 'Знаменитий сироп для кави готують методом пастеризації рідкої карамелі з додаванням ванілі та води.'),
  (750, 'ua', 'Серветки', 'Бавовняна або паперова барна хустинка. Іноді виступає в ролі костеру для напоїв.'),
  (360, 'ua', 'Сифон', 'Прилад з товстого скла або металу для газування напоїв вуглекислим газом. Стандартний об’єм: 1-2 л.'),
  (500, 'ua', 'Кава в зернах', 'Смажені зерна кавового дерева через вміст кофеїну мають стимулюючу дію на організм. Розрізняють два основні різновиди кавового дерева – арабіка та робуста.'),
  (565, 'ua', 'Саке', 'Японський міцний алкогольний напій виробляється з шліфованого рису, замоченого та обробленого парою. У підготовлену культуру додають для бродіння грибки, витримують в теплому та вологому приміщенні близько 2 діб. Після бродіння саке витримують в герметичних резервуарах від 6 до 12 місяців.'),
  (537, 'ua', 'Кумкват', 'Невеликий цитрусовий фрукт, що росте, переважно, в Китаї, Кореї та Японії. Містить вітамін С, залізо і магній, що є незамінним у боротьбі з інфекціями. Один плід важить в середньому 10 г.'),
  (685, 'ua', 'Коньячний келих', 'Класичний келих для коньяку або бренді. Стандартний об''єм: 170-400 мл'),
  (423, 'ua', 'Південний комфорт', 'Новоорлеанський фруктовий лікер, придуманий барменом Мартіном Хероном у 1874 році, виробляють за старовинною рецептурою на основі американського віскі з додаванням фруктових та трав''яних есенцій, цукру, карамелі і витриманого в дубових бочках до потрібної міцності.'),
  (703, 'ua', 'Пательня', 'Стародавнє кухонне начиння необхідне у барі для фламбування ягід та фруктів.'),
  (688, 'ua', 'Сет', 'Гастрономічний набір для дегустацій. Складається зі скляного підноса, наповненого льодом, який зберігає потрібну температуру маленьких пробників.'),
  (462, 'ua', 'Сироп лічі', 'Азійський фруктовий сироп виробляють методом пастеризації соку з ягід лічі, змішаного з цукровим сиропом і водою.'),
  (504, 'ua', 'Ромашковий чай', 'Настій з висушених квітів лікувальної ромашки. Переважно квіти просто заливають окропом із розрахунком 1-2 чайних ложки на 200 мл води, настоюють 7-10 хвилин, проціджують і п''ють в чистому вигляді або з додаванням цукру чи меду.'),
  (673, 'ua', 'Обліпиховий джем', 'Джем з маленьких жовтих ягід, що ростуть на листяних колючих чагарниках, переважно, атлантичного узбережжях Європи та в північно-західному Китаї. Стиглі ягоди варять з цукром до однорідного стану. В одній барній ложці вміститься 5 г джему.'),
  (689, 'ua', 'Саке сет', 'Набір для традиційної подачі японського міцного алкоголю. Стандартний об’єм токкурі: 250-300 мл, об’єм чашечки: 50-60 мл.'),
  (769, 'ua', 'Блюдце', 'Скляний, фарфоровий або металевий предмет посуду, який класично подається в парі з чашкою. У сучасній інтерпретації на блюдце подається келих з коктейлем, завдяки чому подача стає більш вишуканою та елегантною.'),
  (463, 'ua', 'Сироп манго', 'Азійський фруктовий сироп виробляють методом пастеризації соку манго, змішаного з тростинним цукром і водою.'),
  (700, 'ua', 'Підсклянник', 'Металева підставка з ручкою, що охоплює склянку і дозволяє пити гарячі напої, не обпікаючи рук.'),
  (695, 'ua', 'Виделка', 'Столовий прилад, що складається з ручки і декількох вузьких зубців (зазвичай від двох до чотирьох) на одному кінці. Використовується для приготування, а також під час прийому їжі для утримання або перенесення окремих частин страви.'),
  (950, 'ua', 'Термометр', 'Пристосування для вимірювання температури рідин, навколишнього середовища, тіла і т.д.'),
  (981, 'ua', 'Сифон для кави', 'Вакуумний пристрій для варіння кави.'),
  (445, 'uk', 'Cinnamon syrup', 'The famous spicy syrup produced by pasteurizing and infusing sugar syrup with cinnamon.'),
  (176, 'uk', 'Lime juice', 'For preparing the juice, limes are put under a press and then filtered and bottled.'),
  (482, 'uk', 'Apple juice', 'For preparing the juice, apples are put under a press and then filtered and bottled.'),
  (767, 'uk', 'Quail egg white', 'To make this cocktail ingredient with a gentle and foamy texture we recommend to use the "Dry shake" method of preparation. One chicken egg white equals 5 quail egg whites.'),
  (217, 'uk', 'Cucumber', 'Cucumber is a creeping vine that bears cylindrical fruits that are used as culinary vegetables. Cucumber grows mainly in the Mediterranean countries. Normalizes metabolism, improves heart and kidney function. One vegetable weights an average 150 g, could be cut into 10 slices or strips.'),
  (31, 'uk', 'Ice cubes', 'For producing the indispensable ingredient attention should be paid to the purity of the water and the speed of the freezing. The slower the water is frozen the clearer the final product. An ideal specimen has no stripes and melts slowly in the glass.'),
  (210, 'uk', 'Champagne saucer', 'A glass with a tall stem and wide bowl. According to legend designed to mirror the silhouette of one of the French King mistresses. Used to serve champagne and tini cocktails. Standard capacity: 200-300 ml.'),
  (68, 'uk', 'Shaker', 'It gained its current look in the 1800s and obtained special popularity in the 1920s and 1930s, having tried out dozens of styles and forms. They are divided into cobbler shakers which have a built-in strainer, French shakers without a strainer and Boston shakers which consist of two equal sized cups. Standard volume: 500—700ml'),
  (69, 'uk', 'Strainer', 'An accessory which is indispensable when working with Boston or French shakers. Used for filtering cocktails of fruit pips, pieces of ice and other undesired ingredients.'),
  (73, 'uk', 'Jigger', 'Ensures accurate and ideal portions in cocktails. The best bartenders always have in their arsenal a range of sizes: 20-40ml, 25-50ml and 30-60ml.'),
  (70, 'uk', 'Squeezer', 'An indispensable tool for squeezing juice from limes and lemons. Despite the fact that most popular establishments nowadays use juice which was prepared earlier, freshly squeezed juice is considered a high level of quality.'),
  (239, 'uk', 'Juicer', 'Extracts juice from any vegetable or fruit. As opposed to a hand press, an electric appliance separates the juice from the pulp using a spinner.'),
  (1, 'uk', 'Vodka', 'Vodka'),
  (55, 'uk', 'Coffee liqueur', 'Famous stimulating liqueur produced by the percolation of coffee beans of different varieties with a neutral spirit. The resulting mix is not filtered, mixed with burnt sugar and diluted with water to the desired strength.'),
  (65, 'uk', 'Rocks glass', 'Wide glass with a thick bottom to serve strong spirits or cocktails in a pure, undiluted form. Standard capacity: 200-300 ml.'),
  (64, 'uk', 'Bar spoon', 'This indispensable tool of a barmen is used for preparing cocktails in a mixing glass and for making layers in shots, as well as for measuring 5ml portions of liquids or 5g portions of dry measures.'),
  (57, 'uk', 'Drinking straws', 'In 1888 Marvin Stone, the owner of a factory producing paper mouthpieces invented the best accessory for drinking drinks from glasses. Joseph Friedman then made a fortune by developing flexible drinking straws. The final stage came with straws being made out of plastic.'),
  (799, 'uk', 'London dry gin', 'Spirit of English origin. Produced in vertical pot stills, alcohol is infused for days with juniper and ten other herbs and spices, and then distilled for about 7 hours and bottled.'),
  (54, 'uk', 'Triple sec', 'Cult citrus liqueur of triple dryness produced by maceration of curacao orange peel in a neutral alcohol with water. The result is triple distilled before bottling while maintaining high strength.'),
  (9, 'uk', 'Lemon juice', 'For preparing the juice, lemons are put under a press and then filtered and bottled.'),
  (734, 'uk', 'Lemon zest', 'The top layer of lemon skin, cut with a special sharp knife. It contains essential oils that carry lemon flavour. Zest can be obtained from a cut fruit, a whole fruit, grated or even twisted into a spiral (called the twist).'),
  (66, 'uk', 'Sour glass', 'Sour glasses were designed to contain Sour cocktails — containing a base liquor, lemon or lime juice, and a sweetener. Standard capacity: 90-120 ml.'),
  (71, 'uk', 'Zest knife', 'Bartender''s tool that came from the Japanese culture of carving. Used to cut off a thin layer of zest or cut rings or twists from apples.'),
  (143, 'uk', 'Mezcal', 'Mexican liquor, made using traditional methods, including smoking agave in underground pits on hot volcanic rocks. The drink is infused with smoky flavor. Then agave hearts are milled, juice is fermented and aged in oak barrels for at least 4 months.'),
  (224, 'uk', 'Green basil', 'Spicy herbs, growing mainly in the warm regions of the Old World. Green leaves have gained widespread popularity due to the cocktail "Basil smash” which has already become a classic.'),
  (223, 'uk', 'Cardamom', 'Ceylon seasoning, growing on herbaceous plants of the ginger family. It is considered one of the most efficient in the world of spices.'),
  (566, 'uk', 'Ginger root', 'Asian perennial, imported to Europe in the Middle Ages. Rhizome looks like rounded pieces, useful for improving immunity and fighting headaches. One slice of the root weighs an average of 5 g.'),
  (83, 'uk', 'Crushed ice', 'The first “shaved” ice was cut by barmen using special knives from a large sheet of ice. Then crushed ice makers and ice machines appeared.'),
  (117, 'uk', 'Sieve', 'Used together with shakers and strainers for double filtering of cocktails when pouring them from the shaker into the glass. With a finer net than on strainers, it does not allow even the smallest fruit seeds and bits of ice to fall into the drink.'),
  (52, 'uk', 'Muddler', 'An indispensable accessory for tropical cocktails, it crushes berries and fruits in the shaker or directly in the glass.'),
  (373, 'uk', 'Clothes peg', 'A decorative accessory used to hold garnish to the glass.'),
  (113, 'uk', 'Absinthe', 'French spirit produced by maceration of herbs and spices, including lemon balm, fennel and anise in grain or wine alcohol. The main component - wormwood, which contains Thujone, a highly intoxicating ingredient.'),
  (295, 'uk', 'Sugar syrup', 'Sugar syrup'),
  (152, 'uk', 'Raspberry', 'A small red berry that grows on perennial subshrubs mostly in Russia, Serbia, Poland and the United States. It contains sugar, organic acids, vitamins A, B, C, fatty oils. One berry weighs an average of 5 g.'),
  (125, 'uk', 'Single Highland malt whisky', 'Spirits of Scottish origin produced in the mountainous region of Scotland, the Highlands. Made from 100% barley malt by double, or rarely, triple distillation. The resulting alcohol is matured for at least 3 years in oak barrels.'),
  (47, 'uk', 'Red bitter', 'The world-renowned Italian bitters produced using a secret recipe starting 1860. A set of aromatic herbs and citrus fruit, it contains 40 to 70 ingredients, including bitter orange, sweet flag, gentiana and perhaps rhubarb.'),
  (189, 'uk', 'Grapefruit juice', 'For preparing the juice, grapefruits are put under a press and then filtered and bottled.'),
  (672, 'uk', 'Mint', 'The most widely recognized herb in cocktails, has more than 30 species. Peppermint and sweet mint are primarily used in the mixology. Store for no longer than two days in refrigerator wrapped in paper towel.'),
  (371, 'uk', 'Swizzle stick', 'A small stick made out of wood with a head in the form of a mixer. It is ideal for mixing cocktails served with crushed ice directly in the glass.'),
  (124, 'uk', 'Green chartreuse', 'This monastic liqueur has been produced in the French Alps using a secret recipe since 1764. About 130 plants and herbs are macerated in neutral alcohol and distilled several times. The result is balanced with sugar, mixed to the desired strength and aged in oak barrels.'),
  (427, 'uk', 'Elderflower liqueur', 'French floral liqueur produced by maceration of crushed elderberry flowers using a secret recipe. The resulting spirit is filtered, mixed with sugar and diluted with water to the desired strength.'),
  (35, 'uk', 'Dry vermouth', 'Strong vermouth, which appeared at the beginning of the XIX century, produced by maceration of alpine wormwood and a dozen other herbs and plants in the dry white wine. The result is filtered and aged in oak barrels for at least a year.'),
  (130, 'uk', 'Dry orange liqueur', 'Fragrant citrus liqueur produced by maceration of orange zest of laraha variety in neutral alcohol with water. The resulting spirit is filtered, mixed with sugar and kept in oak barrels.'),
  (114, 'uk', 'Peychaud''s bitters', 'New Orleans classic bitters, invented by the famous apothecary in 1830, was made based on a secret recipe by infusing neutral spirits with anise, cloves, vanilla, nutmeg, fruit and spices.'),
  (161, 'uk', 'Goblet glass', 'Royal glass with a thick walls permitting clinking glasses during a drink without the risk of breaking them. Standard capacity: 200-300 ml.'),
  (665, 'uk', 'Maraschino liqueur', 'A berry liqueur from Croatia made by macerating maraschino cherries with the pits in a neutral spirit with water for at least a month. The resulting mix is then filtered, sweetened, brought to the required strength and aged in oak barrels for at least three years.'),
  (303, 'uk', 'Grapefruit bitters', 'Seasonal summer bitters produced by infusing neutral spirits with grapefruit peel with the addition of hops to soften the bitterness.'),
  (20, 'uk', 'Red maraschino cherry', 'Special grades of cherry, such as "King Anna", "Rainer" or "Golden diversity" are placed in a saline solution, and then soaked in sugar syrup with the addition of food colouring.'),
  (96, 'uk', 'Cocktail skewer', 'A decorative accessory for serving olives in martinis and cocktail cherries in Manhattan cocktail. First appeared in bars at the end of the 19th century thanks to the marketing genius Charles Forster.'),
  (101, 'uk', 'Aged rum', 'Spirits of a Caribbean produced via vertical distillation of the alcohol obtained by fermentation of molasses or juice from sugar cane. Before blending kept in burnt oak barrels of bourbon or sherry from 7 to 20 years, depending on the chosen method of aging.'),
  (116, 'uk', 'Dark cacao liqueur', 'Dark chocolate liqueur produced by the percolation of cocoa beans with a neutral alcohol. The resulting spirit is diluted with water to the desired strength and mixed with Madagascan vanilla and caramel, which gives the liqueur a dark colour.'),
  (67, 'uk', 'Mixing glass', 'A classic must have for a five star bar. Used for preparation of strong male drinks without added juices, herbs and jams. Ice keeps its form and does not melt, maintaining strength of the drink. Standard capacity: 500-900 ml.'),
  (166, 'uk', 'Amaro', 'Vintage Italian liqueur produced by maceration of herbs and roots, including citrus peel, juniper, fennel, lemon balm, anise and cardamom in neutral alcohol. The resulting spirit is filtered, mixed with sugar and diluted with water to the desired strength.'),
  (171, 'uk', 'Ice ball', 'The pride of Japanese barmen – ice elevated into the ranks of an object of art. Today they are more common in bars thanks to special machines. Prepared ice cubes are placed in a slightly warm vice and the metal is warmed up by water which cuts out the contours of a sphere.'),
  (3, 'uk', 'Lemon', 'A tropical citrus fruit that grows on small evergreen trees mainly in China, India and Mexico. Contains vitamin C and organic acids, traditionally used to fight colds and nutritional deficit. One fruit weighs 160 g and yields 60 ml juice, can be cut into 8 slices or 4 large segments of 15 ml each.'),
  (62, 'uk', 'Bourbon', 'Strong spirit of American origin, according to the law, made of at least 51% corn malt with addition of barley and rye, distilled and filtered. Aged for your pleasure in oak barrels from 2 to 7 years. The barrels are burnt from the inside using a special technology.'),
  (111, 'uk', 'Creme de cassis liqueur', 'Dijon berry liqueur produced by maceration of black currant in a neutral alcohol with water for up to two months. The liqueur is not filtered and mixed with sugar.'),
  (63, 'uk', 'Angostura bitters', 'Venezuelan vintage bitter, named in honour of the Angostura city. Made with the original secret recipe by Dr. Johann Gottlieb Benjamin Siegert, (circa 1800) via infusion of secret spices and herbs in dark rum spirits.'),
  (16, 'uk', 'Light cream', 'Light cream is mainly made from cow''s milk by separating cream from milk. The percentage of fat varies in different countries usually not more than 15%. Stored in the refrigerator for up to 20 days.'),
  (36, 'uk', 'Red vermouth', 'Vermouth with slight sweetness, produced by maceration of 30 alpine herbs and spices in white wine. The result is filtered, adjusted to the desired strength and sweetness, caramel colouring added and aged in oak barrels for at least a year.'),
  (34, 'uk', 'Club soda', 'Carbonated water, which become an indispensable component of Fizz and other carbonated drinks, previously produced by carbonating water with carbon dioxide, and now increasingly prepared by adding baking soda to still clean water.'),
  (732, 'uk', 'Orange zest', 'The top layer of orange skin, cut with a special sharp knife. It contains essential oils that carry orange flavour. Zest can be obtained from a cut fruit, a whole fruit, grated or even twisted into a spiral (called the twist).'),
  (258, 'uk', 'Prosecco', 'Sparkling wine produced in namesake region of France under strict regulations. Collected by hand three varieties grapes are fermented, and resulting wines are blended and bottled with the addition of cane sugar and yeast. A secondary fermentation happens in the bottle, it takes at least 9 months, the residual is removed using reimage, liquor is added and the bottle is closed with a natural cork.'),
  (148, 'uk', 'Peach puree', 'Peach puree'),
  (535, 'uk', 'Peach', 'Sun loving fruit growing on a deciduous tree mainly in China, Italy and Spain. Contains organic acids, mineral salts and pectin. One fruit weighs an average of 120 g, from which you can produce around 80 grams of mash.'),
  (59, 'uk', 'Flute glass', 'A high-society glass for cocktails based on champagne or sparkling wine. The long narrow form is reminiscent of a tulip and retains the bubbles in the cocktail allowing it to remain fizzy for longer. Standard volume: 180-250ml'),
  (179, 'uk', 'Lime cordial', 'Ancient citrus recipe, produced by pasteurizing lime juice mixed with sugar syrup, cream of tartar and water.'),
  (733, 'uk', 'Lime zest', 'The top layer of lime skin, cut with a special sharp knife. It contains essential oils that carry lime flavour. Zest can be obtained from a cut fruit, a whole fruit, grated or even twisted into a spiral (called the twist).'),
  (72, 'uk', 'Cocktail glass', 'Also known as martini glass, one of the first glasses to serve cocktails without ice. Before serving it is necessary to cool the glass, and the long stem glass prevents cocktail from getting warm due to holding. Standard capacity: 90-160 ml.'),
  (40, 'uk', 'Cognac', 'Aged alcohol of a French origin comes from white grapes: Ugni Blanc, Folle Blanche or less often Colombard Montilla. Subject to a double distillation process and aged in oak barrels, - VS (Very Special) up to 3 years; V.S.O.P (Very Superior Old Pale) up to 5 years.'),
  (14, 'uk', 'Ground nutmeg', 'Indonesian seasoning, created from nutmeg, dried and milled to a powder.'),
  (746, 'uk', 'Nutmeg grater', 'A useful accessory for preparing nutmeg or chocolate powder, or more rarely zest from citrus fruits.'),
  (8, 'uk', 'Orange juice', 'For preparing the juice, oranges are put under a press and then filtered and bottled.'),
  (88, 'uk', 'White rum', 'Spirits of a Caribbean produced via vertical distillation of the alcohol obtained by fermentation of molasses or juice from sugar cane. Before blending kept in burnt oak barrels of bourbon or sherry for at least 12 months, depending on the chosen method of aging and filtered to discolour the drink.'),
  (92, 'uk', 'Calvados', 'French spirit that starts with cider made by fermenting the juice of Norman autumn apples in steel vats from six months to a year. Then the beverage is subjected to double distillation and aged in oak barrels for at least 2 years.'),
  (77, 'uk', 'Grenadine syrup', 'The popular red fruit syrup produced by pasteurizing pomegranate juice with other juices of red berries, vanilla and sugar cane.'),
  (86, 'uk', 'Dark rum', 'Spirits of a Caribbean produced via vertical distillation of the alcohol obtained by fermentation of molasses or juice from sugar cane. Before blending kept in burnt oak barrels of bourbon or sherry from 2 to 7 years, depending on the chosen method of aging and not filtered to preserve colour.'),
  (365, 'uk', 'Overproof rum', 'Spirits of a Caribbean produced via vertical distillation of the alcohol obtained by fermentation of molasses or juice from sugar cane. Before blending kept in burnt oak barrels of bourbon or sherry for at least a year. Not diluted with water to preserve the strength.'),
  (190, 'uk', 'Grapefruit', 'This popular citrus fruit grows in clusters mainly in China, the US and Mexico. Contains vitamin C, pectin and lycopene with cholesterol lowering properties. One fruit weighs 600 g on average, can be cut into 10 slices or parts and makes around 200 ml of juice.'),
  (186, 'uk', 'Tiki mug', 'Tiki mugs are ceramic drinkware for tiki themed cocktails.'),
  (662, 'uk', 'Irish whiskey', 'Spirits of Irish origin, made from sprouted barley malt, which is dried in the oven, milled and covered with hot water. Separated from the grain liquid is fermented, distilled three times and left to mature in oak, sherry, bourbon or port casks for at least 3 years.'),
  (128, 'uk', 'Heavy cream', 'Double cream is mainly made from cow''s milk by separating cream from milk. The percentage of fat varies in different countries from 20 to 40%. Stored in the refrigerator for up to 20 days.'),
  (74, 'uk', 'Bowl', 'Glass or metal container for whisking ingredients with a whisk. Any mix with the addition of tomato or citrus juices should be done only in a glass bowl or stainless steel, to avoid reaction with the acids.'),
  (90, 'uk', 'Irish coffee glass', 'A strong glass for serving hot grog, mulled wine and cocktails with coffee – it is named in honour of one such coffee cocktail. Standard volume: 200-300 ml.'),
  (78, 'uk', 'Whisk', 'Indispensable for whipping cream for Irish Coffee or beating egg whites with sugar for a Tom and Jerry. For mixing or beating ingredients in a jar, a special version is used with a longer handle and a small tip at the end.'),
  (761, 'uk', 'Coffee machine', 'An automatic appliance for making various types of coffees: latte, espresso, americano, latte macchiato, cappuccino, glacé coffee.'),
  (39, 'uk', 'Cachaca', 'Brazilian liquor produced by careful filtration and distillation of fermented sugarcane juice following one technique - the "head" and "tail" are discarded, leaving only the "heart" of the drink for further aging in oak barrels for at least 1 year.'),
  (5, 'uk', 'Lime', 'Tropical citrus fruit grown year-round in tropical climates mainly in China, India and Mexico. Limes are an excellent source of cellulose, vitamin C and calcium, and good to be used to accent the flavours of foods and beverages. One fruit weighs an average of 80 g, and yields 30 ml of juice, can be cut into 4 slices, each contains 7.5 ml of juice.'),
  (43, 'uk', 'Raspberry syrup', 'Popular berry syrup produced by pasteurizing of raspberry juice mixed with sugar and water.'),
  (661, 'uk', 'Citrus vodka', 'Strong flavored spirit produced by multiple distillation of grains, subject to several stages of carbon and other filtering, result is mixed with clean water. The resultant drink infused with extracts of lime.'),
  (481, 'uk', 'Cranberry juice', 'For preparing the juice, cranberries are put under a press and then filtered and bottled.'),
  (53, 'uk', 'Culinary torch', 'A gentleman’s accessory for flaming the citrus oil over the famous Cosmopolitan, sprinkling sparkling cinnamon over tiki cocktails and simply lighting cigars of guests.'),
  (82, 'uk', 'Tawny port', 'Saturated red port wine produced from a mixture of red vintage wines with the addition of cognac and subsequent aging in oak barrels using Solera method.'),
  (49, 'uk', 'Quail egg yolk', 'The product gives cocktails a delicate texture. One chicken egg yolk equals 5 quail yolks.'),
  (178, 'uk', 'Quail egg cutter', 'Special scissors with a ring for holding and clearly cutting through the egg.'),
  (569, 'uk', 'Celery', 'The plant’s "claim to fame" is due to the ancient Greeks, grows mainly in temperate climates. Before serving fibers must be removed by making a small incision on the stem and pulling the "thread." One stalk weighs an average 15 g.'),
  (42, 'uk', 'Red Tabasco sauce', 'A peppery red sauce made from selected, ripe chili peppers aged for three years in white oak barrels with salt from the Avery Island. The resulting mash is then flavored with vinegar and left to age for a further four weeks. It is more spicy than the green version.'),
  (56, 'uk', 'Ground black pepper', 'Indian Ground condiment created from non-ripened berries of black pepper, dried in the sun to blackness. Unlike granular version, fragrance evaporates much faster.'),
  (58, 'uk', 'Highball glass', 'Tall glass for water, juice or club mixes. Mixed built right in the glass. Standard capacity: 300-400 ml.'),
  (37, 'uk', 'Scotch whisky', 'A Scottish liquor made from barley malt dried over peat grain. It is ground and covered with hot water, then the separated liquid is fermented, distilled three times. The resulting alcohol is mixed and left to mature in oak casks.'),
  (46, 'uk', 'Cherry liqueur', 'The famous berry liqueur produced by maceration of cherries in different varieties of neutral spirits with water for at least a month. The result is filtered, sweetened, strengthened with cognac and aged in oak barrels for at least 3 years.'),
  (89, 'uk', 'Gold rum', 'Spirits of a Caribbean produced via vertical distillation of the alcohol obtained by fermentation of molasses or juice from sugar cane. Before blending kept in burnt oak barrels of bourbon or sherry from 1 to 5 years, depending on the chosen method of aging. Not filtered, and sometimes caramel colouring is added.'),
  (94, 'uk', 'Cola', 'The most popular highly carbonated drink produced by the secret formula based on caffeine, sugar, flavorings and colorings.'),
  (60, 'uk', 'White cacao liqueur', 'Light chocolate liqueur produced by the percolation of cocoa beans with a neutral alcohol. The result is filtered, removing the dark colour, adjusted to the desired strength and mixed with sugar until creamy consistency.'),
  (61, 'uk', 'Green mint liqueur', 'Creamy herbal liqueur produced with a high sugar content by the percolation of fresh peppermint extract with lime distillates in a neutral alcohol. The resulting spirit is adjusted to the desired sweetness, mixed to strength and bottled.'),
  (93, 'uk', 'Silver tequila', 'Spirits of Mexican origin, traditionally produced by the distillation of the blue agave juice. Seven to ten summer agave hearts are placed in special furnaces to convert starch into sugar, resulting juice is fermented, double distilled and after filtration immediately bottled.'),
  (212, 'uk', 'Ginger beer', '"Trojan horse" of vodka in America. This special kind of spicy lemonade is produced by maceration of dried ground ginger in beer yeast.'),
  (99, 'uk', 'Almond syrup', 'Almond syrup'),
  (127, 'uk', 'Salt', 'A crystallised seasoning made from minerals, the age of which can reach up to 250 million years or more.'),
  (84, 'uk', 'Margarita glass', 'In its former life it was a sauce-boat for guacamole but now it is the main glass for serving the most famous tequila-based cocktail in the world. Standard volume: 250-350 ml.'),
  (85, 'uk', 'Orange bitters', 'One of the oldest citrus bitters available. Produced by infusing in rum dried orange zest, spices and herb roots with the addition of cane sugar and distilled water just before bottling.'),
  (75, 'uk', 'Passion fruit syrup', 'Tropical fruit syrup produced by pasteurizing the pulp juice of passion fruit mixed with cane sugar and water.'),
  (7, 'uk', 'Pineapple juice', 'For preparing the juice, pineapple pulp is put under a press and then filtered and bottled.'),
  (76, 'uk', 'Hurricane glass', 'An old-fashioned glass resembling a kerosene lamp for serving tropical drinks, named in honor of the cocktail of the same name of Pat O’Brien. Standard volume: 300-400 ml.'),
  (4, 'uk', 'Orange', 'Orange citrus fruit growing on large trees mainly in Brazil, USA and China. Contains vitamin C, potassium and calcium. Known to have a beneficial effect on the heart, blood vessels and the body as a whole. One fruit weighs on average 300 g and yields 80 ml of juice. Can be cut into slices 10 or separated into 8 lobes.'),
  (375, 'uk', 'Collins glass', 'Tall glass for long and mixed drinks. Named after the classic cocktail "Tom Collins". Standard capacity: 300-400 ml.'),
  (104, 'uk', 'Benedictine', 'The famous Norman liquor decorated with inscription of DOM - DEO Optimo Maximo («to God, most good, most great ") is made from 27 secret herbs and spices in four stages. After maceration and distillation the resulted spirits are kept separately, and then mixed for 11 months in oak barrels. Then mixed with water, brandy, honey and burnt sugar. That brings us to the final stage of 3-month aging.'),
  (95, 'uk', 'Pineapple', 'The pineapple is a tropical plant grown on the ground spiny plants mostly in Brazil, Thailand and the Philippines. Contains manganese and vitamin C, known to stimulate digestion and reduce blood viscosity. One fruit weighs on average 1200 g and can be cut into around 40 slices.'),
  (105, 'uk', 'Sling glass', 'The quintessential glass for serving the cocktail of the same name which became the calling card of the Raffles Hotel. Standard volume: 200-300 ml.'),
  (79, 'uk', 'Still water', 'The most important source of health and longevity. Bartenders around the world recommend always to drink water while consuming a cocktail, so in the best institutions a glass of clean water is complimentary.'),
  (150, 'uk', 'Sugar cubes', 'European sweet seasoning obtained by complicated purification, refining and crystallization of syrup of sugar cane or sugar beet juice. These crystals are pressed to the desired shape.'),
  (100, 'uk', 'Drambuie', 'Scottish liqueur, translated from the Gaelic "fulfilling", made using a secret recipe since 1910. It is known that the drink is a blend of single malts of famous origins, heather honey, herbs and spices.'),
  (677, 'uk', 'Orange flower water', 'Ancient recipe of water infused with fresh flowers of bitter oranges.'),
  (118, 'uk', 'Pineapple leaves', 'Leaves of tropical fruit that are used as an ornament for exotic tiki cocktails.'),
  (98, 'uk', 'Pisco', 'This Peruvian grape brandy is produced from up to eight varieties of grape, whereas in Chile no more than three are used. Fermented juice is distilled in stainless steel vats and bottled either immediately or aged in oak barrels for 2 years.'),
  (103, 'uk', 'Cane sugar cubes', 'Tropical sweet seasoning produced by the crystallization of sugar cane with its subsequent pressing into small cubes. The higher the content of molasses, the darker colour and richer flavour.'),
  (132, 'uk', 'Aged bourbon', 'Aged bourbon'),
  (102, 'uk', 'Caster sugar', 'Sweet seasoning powder obtained from ground, powdery sugar. Due to the grain size instantly dissolves in liquid and significantly saves time.'),
  (158, 'uk', 'Copper mug', 'A must have, become the "Trojan horse" of vodka in America and utensil of choice to serve the "Moscow Mule" cocktail. Standard capacity: 300-400 ml.'),
  (214, 'uk', 'Blackberry', 'Dark purple medium sized berries, grows on bushes throughout Europe, in North-West Africa, Central Asia, North and South America. Contains carotene, vitamin C, B1 and B2, K, and other vitamins. One berry weighs an average of 6 g.'),
  (115, 'uk', 'Granulated sugar', 'European sweet seasoning obtained by complicated purification, refining and crystallization of syrup of sugar cane or sugar beet juice. Size of granules is important, the smaller, the more quickly it will dissolved.'),
  (107, 'uk', 'Milk', 'Made from full cream cow''s milk. The desired fat content is achieved by adding cream into a fat free version of product.'),
  (330, 'uk', 'Cinnamon sticks', 'Ceylon seasoning, known since the XV century, made from bark of the cinnamon tree, which is cleaned, sanded and dried in the shade until they twist into a tube.'),
  (108, 'uk', 'Cup', 'High ceramic cup for coffee or tea, in 1930 became utensil of choice for the "Tom and Jerry" cocktail. Standard capacity: 200-250 ml.'),
  (655, 'uk', 'Milk pitcher', 'A metallic milk pot. Used for whipping cream and preparing hot cocktails.'),
  (120, 'uk', 'Ground cinnamon', 'Ceylon Ground seasoning, known since the XV century, made from shavings and scraps of cinnamon bark, dried and milled.'),
  (149, 'uk', 'Star anise', 'Tropical star shaped fruit growing on evergreen trees mainly in China. Gathered while not ripe, and dried in the sun.'),
  (134, 'uk', 'Maple syrup', 'Famous Christmas syrup made from the sap of the sugar maple, collected from the maple trees in February and March. Produced by pasteurizing this sap with cane sugar and water.'),
  (123, 'uk', 'Rose syrup', 'Delicate flower syrup produced by infusing and pasteurizing rose petals in sugar syrup.'),
  (201, 'uk', 'Rose petals', 'Best selling flower in the world. There are 25 petals in one bud.'),
  (1035, 'uk', 'American whiskey', 'American whiskey'),
  (288, 'uk', 'Pedro Ximenez sherry', 'The sweetest kind of matured Spanish wines is made from the namesake ripe grapes. Fermented grape juice is enriched with grape alcohol and aged in oak barrels using Solera method for 10 to 30 years or more.'),
  (154, 'uk', 'Teaspoon', 'Spoon for stirring tea in a cup. One spoonful holds on average 5g of dry ingredients or 5ml of liquid.'),
  (211, 'uk', 'Rocks ice', 'A lump or a straight cube, a large piece of ice melts more slowly and looks more impressive in the glass.'),
  (450, 'uk', 'Ginger syrup', 'Spicy Asian syrup produced by pasteurizing extracts of ginger in sugar syrup.'),
  (693, 'uk', 'Mate bombilla', 'A special straw for serving mate. The upper end contains a mouthpiece while the lower part has a strainer.'),
  (552, 'uk', 'Redcurrant', 'Little red berries growing on deciduous shrubs mainly in Central, Northern Europe, and North Asia. It contains large amounts of vitamin C, as well as various sugars, organic acids and minerals. One bar spoon contains 5 g of berries.'),
  (332, 'uk', 'Oloroso sherry', 'Semi-dry or sweet Spanish fortified wine produced by fermenting grapes of Palomino without forming a protective film floras. The resulting spirit is enriched in stages with grape spirit and aged in oak barrels using Solera method for at least two years.'),
  (191, 'uk', 'Dried apricots', 'A bright dried fruit produced primarily in Turkey, Iran and Uzbekistan from ripe apricots. The fruits are first boiled down or soaked in syrup and then dried in the sun or a special dryer. One piece on average weighs 10g.'),
  (683, 'uk', 'Tray', 'A metal or wooden plate for serving food or drinks to guests.'),
  (121, 'uk', 'Vanilla syrup', 'Madagascan fragrant syrup produced by infusing and pasteurizing vanilla pods in syrup.'),
  (381, 'uk', 'Gold tequila', 'Spirits of Mexican origin, traditionally produced by the distillation of the blue agave juice. Seven to ten summer agave hearts are placed in special furnaces to convert starch into sugar, resulting juice is fermented, double distilled and coloured with caramel. Flavored with various aromatic additives.'),
  (318, 'uk', 'White vermouth', 'The sweetest vermouth, produced by maceration of alpine herbs and spices in white wine. The result is filtered, adjusted to the desired strength and maximum sweetness and aged in oak barrels for at least a year.'),
  (126, 'uk', 'Strawberry puree', 'Strawberry puree'),
  (327, 'uk', 'Granulated cane sugar', 'Tropical sweet seasoning produced by the crystallization of sugar cane with his subsequent mechanical processing. The higher the content of molasses, the darker the colour and richer flavour.'),
  (326, 'uk', 'Bottle', 'Classic vessel used for storage of alcoholic beverages and soft drinks.'),
  (138, 'uk', 'Blender', 'Invented in 1922 by Stephen Poplawski, this electric appliance is indispensable for making tiki cocktails, smoothies and frozen drinks.'),
  (196, 'uk', 'Coconut syrup', 'The most popular tropical syrup produced by pasteurizing coconut water with cane sugar.'),
  (197, 'uk', 'Pineapple slicer', 'A tiki accessory which in a matter of seconds removes the skin and the hard core from a pineapple.'),
  (744, 'uk', 'Scoop', 'A convenient tool made from polycarbonate or stainless steel which allows one to take a specific amount of ice. The scoops differ in size and volume which allows one to select a tool for the required amount of ice.'),
  (406, 'uk', 'Yellow banana liqueur', 'Tropical Creamy liqueur produced by maceration of the pulp of yellow bananas in a neutral alcohol with water. The result is filtered, mixed with sugar and enriched with young brandy.'),
  (200, 'uk', 'Banana', 'What can be considered the oldest tropical plant growing mainly in China, India and Uganda. Fruit contains vitamin B6, manganese and dietary fibre. One fruit weighs on average 200 g, with the peel being 80 g.'),
  (244, 'uk', 'Jenever', 'Dutch spirits, the father of gin, made starting XV century by distilling of pure alcohol with the addition of juniper berries and other spices.'),
  (133, 'uk', 'Honey syrup', 'Most popular syrup produced by pasteurizing honey diluted to a desired consistency with water.'),
  (293, 'uk', 'Teapot', 'The history of the ancient Chinese receptacle goes back to where and when tea itself began - in 14th century china. Used to brew tea, herbs and spices in boiling water or juice.'),
  (287, 'uk', 'Single Islay malt whisky', 'Single Islay malt whisky'),
  (284, 'uk', 'Rhubarb liqueur', 'Dessert bitter sweet herbal liqueur produced by maceration of the stems and leaves of rhubarb in a neutral alcohol with water. The result is mixed with sugar and brought to the desired strength.'),
  (358, 'uk', 'Cynar', 'Herbal Italian liqueur produced by maceration and distillation of 16 herbs and spices, mainly the artichoke, in neutral alcohol. The resulting spirit is filtered and brought to the desired strength and sweetness.'),
  (735, 'uk', 'Grapefruit zest', 'The top layer of grapefruit skin, cut with a special sharp knife. It contains essential oils that carry grapefruit flavor. Zest can be obtained from a cut fruit, a whole fruit, grated or even twisted into a spiral (called the twist).'),
  (704, 'uk', 'Sprayer', 'An attractive accessory for spraying bitters and aromatic additives over cocktails.'),
  (435, 'uk', 'Fino sherry', 'Spanish dry fortified wine produced by fermenting grapes of Palomino with the addition of special yeast. Matured for at least 12 months, the wine covered by a special film - flora, enriched with grape alcohol in stages. Matures in barrels under the protective film for at least 2 years.'),
  (653, 'uk', 'Shot glass', 'A small glass with, as a rule, straight edges. Designated for the strongest drinks or cocktails which should be downed in one. Standard volume: 50-100 ml.'),
  (546, 'uk', 'Strawberry', 'Large red berry that grows on small shrubs mostly in the US, Turkey, Spain, Egypt and Mexico. It contains sugar, pectin and tannin, ascorbic acid and others, anti-inflammatory ingredients. One berry weighs an average of 20 g.'),
  (402, 'uk', 'Limoncello', 'Italian National liqueur produced by maceration of lemon peel in a neutral alcohol for a month. The resulting alcohol mixed with sugar and water, let to brew, and filtered.'),
  (410, 'uk', 'Lychee liqueur', 'Made from the pulp of ripe lychees, which are mixed with alcohol and allowed to infuse.'),
  (486, 'uk', 'Mango juice', 'For preparing the juice, mango pulp is put under a press and then filtered and bottled.'),
  (529, 'uk', ' INSERT INTO drink_me_bot.goods_i18n (goods_id, lang, name, description) VALUES
  (72, 'us', 'Cocktail glass', '''Also known as a martini glass, this was one of the first glasses in which cocktails were served without ice. Before serving, the glass must be chilled, and the long stem prevents the cocktail from warming up in the hand. Standard capacity: 3-5 oz.'''),
  (40, 'us', 'Cognac', '''This aged alcohol of French origin comes from white grapes: Ugni Blanc, Folle Blanche or less often Colombard Montilla. It is subjected to a double distillation process and aged in oak barrels according to the following scheme: VS (Very Special) – up to 3 years; V.S.O.P (Very Superior Old Pale) – up to 5 years.'''),
  (14, 'us', 'Ground nutmeg', 'An Indonesian seasoning created from nutmeg that is dried and milled into a powder.'),
  (746, 'us', 'Nutmeg grater', 'A useful accessory for preparing nutmeg or chocolate powder, or even zest from citrus fruits.'),
  (8, 'us', 'Orange juice', '"To prepare the juice, oranges are put under a press, then the resulting mass is filtered and bottled. \r\n"'),
  (88, 'us', 'White rum', 'A Caribbean spirit, produced via vertical distillation of alcohol from fermentation of molasses or sugar cane juice. Before blending, it is kept in burnt oak barrels from bourbon or sherry for 2 to 7 years, depending on the method of aging, and filtered to remove the dark color.'),
  (92, 'us', 'Calvados', 'A French spirit, which uses Norman autumn apple cider as a base. The juice is fermented in steel vats for six months to a year, then subjected to double distillation and aged in oak barrels for at least 2 years.'),
  (77, 'us', 'Grenadine syrup', 'The popular red fruit syrup is produced by pasteurizing pomegranate juice with other red berry juices, vanilla and sugar cane.'),
  (86, 'us', 'Dark rum', 'A Caribbean spirit, produced via vertical distillation of alcohol from fermentation of molasses or sugar cane juice. Before blending, it is kept in burnt oak barrels from bourbon or sherry for 2 to 7 years, depending on the method of aging, but in order to preserve color, it is not filtered.'),
  (365, 'us', 'Overproof rum', 'A spirit of Caribbean produced via vertical distillation of the alcohol obtained from fermented molasses or sugar cane juice. Before blending, it is kept in burnt oak barrels used for bourbon or sherry for at least a year. Not diluted with water, in order to preserve its strength.'),
  (190, 'us', 'Grapefruit', 'This immensely-popular citrus fruit grows in clusters mainly in China, the US and Mexico. Contains vitamin C, pectin and lycopene with cholesterol- lowering properties. One fruit weighs 20 oz on average, can be cut into 10 slices or parts and makes about 7 oz of juice.'),
  (186, 'us', 'Tiki mug', 'Tiki mugs are ceramic drinkware for tiki-themed cocktails.'),
  (662, 'us', 'Irish whiskey', 'A spirit of Irish origin, made from sprouted barley malt, which is dried in the oven, milled and covered with hot water. Once separated from the grain, the liquid is fermented, distilled three times and left to mature in oak, sherry, bourbon or port casks for at least 3 years.'),
  (128, 'us', 'Heavy cream', 'Double cream is made primarily from cow''s milk by partial separation of the cream from the milk. The percentage of fat varies in different countries from 20 to 40%. Can be stored in the refrigerator for up to 20 days.'),
  (74, 'us', 'Bowl', 'A glass or metal container for whisking ingredients. Any mix with the addition of tomato or citrus juices should be made either in a glass bowl or stainless steel in order to avoid a reaction with the acids.'),
  (90, 'us', 'Irish coffee glass', '"A strong glass for serving hot grog, mulled wine and cocktails with coffee – in fact, it is named in honor of one such drink. Standard volume: 7-10 oz."'),
  (78, 'us', 'Whisk', '"Indispensable for whipping cream for Irish Coffee or beating egg whites with sugar for a Tom and Jerry. For mixing or beating ingredients in a jar, a special version with a longer handle and a small tip at the end is used."'),
  (761, 'us', 'Coffee machine', 'An automatic appliance for making various types of coffees: latte, espresso, americano, latte macchiato, cappuccino, and glacé coffee.'),
  (39, 'us', 'Cachaca', 'A Brazilian liquor, produced by careful filtration and distillation of fermented sugarcane juice according to a special technique: the "head" and "tail" are discarded, leaving only the "heart" of the drink for further aging in oak barrels for at least 1 year.'),
  (5, 'us', 'Lime', 'A tropical citrus fruit grown year-round in tropical climates, mainly in China, India and Mexico. Limes are an excellent source of vitamin C, and are often used to accent the flavors of foods and beverages. One fruit weighs an average of 3 oz, and yields 1 oz of juice. It can be cut into 4 slices, each of which contains 0.25 oz of juice.'),
  (43, 'us', 'Raspberry syrup', 'A popular berry syrup produced by pasteurizing a mixture of raspberry juice, sugar and water.'),
  (661, 'us', 'Citrus vodka', 'A strong, flavored spirit produced via multiple distillation of grains, which is then subjected to several stages of carbon and other filtering. The result is mixed with clean water, then infused with extracts of lime.'),
  (481, 'us', 'Cranberry juice', 'To prepare the juice, cranberries are put through a press, then filtered and bottled.'),
  (53, 'us', 'Culinary torch', 'A gentleman’s accessory for lighting the citrus oil on top of the famous Cosmopolitan, sprinkling sparkling cinnamon over tiki cocktails, or simply lighting guests'' cigars.'),
  (82, 'us', 'Tawny port', 'A rich red port wine, produced from a mixture of red vintage wines with the addition of cognac and aged in oak barrels using the Solera method.'),
  (49, 'us', 'Quail egg yolk', 'This product gives cocktails a delicate texture. One chicken egg yolk equals 5 quail egg yolks.'),
  (178, 'us', 'Quail egg cutter', 'Special scissors with a ring to hold the egg and a blade to make a compass-style cut.'),
  (569, 'us', 'Celery', 'The plant’s "claim to fame" comes from the ancient Greeks. It grows mainly in temperate climates. Before serving, fibers must be removed by making a small incision on the stem and pulling the "thread." One stalk weighs on average 0.5 oz.'),
  (42, 'us', 'Red Tabasco sauce', '''A peppery red sauce made from selected ripe chili peppers, aged for three years in white oak barrels with salt from Avery Island. The resulting mash is then flavored with vinegar and left to age for another four weeks. It is spicier than the green version. '''),
  (56, 'us', 'Ground black pepper', 'A ground condiment of Indian origin, created from unripened black peppercorns sun-dried to blackness. Unlike the granulated version, the fragrance evaporates much faster.'),
  (58, 'us', 'Highball glass', '''A tall glass for water, juice or club mixes. Mixes are built right in the glass. Standard capacity: 10-13 oz.'''),
  (37, 'us', 'Scotch whisky', 'A Scottish liquor made from barley malt dried over peat grain. It is ground and covered with hot water, then the separated liquid is fermented, distilled three times. The resulting alcohol is mixed and left to mature in oak casks.'),
  (46, 'us', 'Cherry liqueur', 'A famous berry liqueur produced by macerating cherries in different varieties of neutral spirits with water for at least a month. The result is filtered, sweetened, strengthened with cognac and aged in oak barrels for at least 3 years.'),
  (89, 'us', 'Gold rum', 'A Caribbean spirit, produced via vertical distillation of alcohol from fermentation of molasses or sugar cane juice. Before blending, it is kept in burnt oak barrels from bourbon or sherry for 2 to 7 years, depending on the method of aging. It is not filtered, and caramel coloring is sometimes added.'),
  (94, 'us', 'Cola', 'The most popular highly-carbonated drink, made according to a secret formula of caffeine, sugar, flavorings and colorings.'),
  (60, 'us', 'White cacao liqueur', 'A light chocolate liqueur produced by percolating cocoa beans with grain alcohol. The result is filtered, removing the dark color, then adjusted to the desired strength and mixed with sugar until it reaches creamy consistency.'),
  (61, 'us', 'Green mint liqueur', 'A creamy herbal liqueur with a high sugar content, produced by percolating fresh peppermint extract with lime distillates in grain alcohol. The resulting spirit is adjusted to the desired sweetness, mixed to strength and bottled.'),
  (93, 'us', 'Silver tequila', 'A spirit of Mexican origin, traditionally produced by distilling blue agave juice. Seven to ten summer agave hearts are placed in special furnaces to convert starch into sugar. The resulting juice is fermented, double-distilled and immediately bottled after filtration.'),
  (212, 'us', 'Ginger beer', 'Vodka''s "Trojan horse" in America. This special spicy lemonade is produced by macerating of dried ground ginger in beer yeast.'),
  (99, 'us', 'Almond syrup', 'Almond syrup'),
  (127, 'us', 'Salt', 'A crystallised seasoning made from minerals, which can themselves date back 250 million years or more.'),
  (84, 'us', 'Margarita glass', '''In a past life, it was a simple container for guacamole, but now it is the signature glass for serving the most famous tequila-based cocktail in the world. Standard volume: 8-12 oz.'''),
  (85, 'us', 'Orange bitters', 'One of the oldest citrus bitters available. Produced by infusing dried orange zest, spices and herb roots in rum, with the addition of cane sugar and distilled water just before bottling.'),
  (75, 'us', 'Passionfruit syrup', 'A tropical fruit syrup produced by pasteurizing the juice of passionfruit pulp mixed with cane sugar and water.'),
  (7, 'us', 'Pineapple juice', '"To prepare the juice, pineapple pulp is put in a press and then filtered and bottled."'),
  (76, 'us', 'Hurricane glass', '''An old-fashioned glass resembling a kerosene lamp, used for serving tropical drinks, named in honor of Pat O''Brien''s cocktail of the same name. Standard volume: 10-15 oz.'''),
  (4, 'us', 'Orange', 'Orange citrus fruit grows on large trees, mainly in Brazil, the United States and China. Contains vitamin C, potassium and calcium. Known to have a beneficial effect on the heart, blood vessels and the body as a whole. One fruit weighs on average 10 oz and yields 3 oz of juice. Can be cut into 10 slices or separated into 8 lobes.'),
  (375, 'us', 'Collins glass', 'A tall glass for long and mixed drinks. Named after the classic "Tom Collins" cocktail. Standard capacity: 10-13 oz.'''),
  (104, 'us', 'Benedictine', 'This famous Norman liquor, decorated with the inscription "DOM" (Deo Optimo Maximo – "to God, most good, most great"), is made from 27 secret herbs and spices in four stages. After maceration and distillation, the resulting infusions are first kept separately, then mixed and aged for 11 months in oak barrels. Afterwards, they are mixed with water, brandy, honey and burnt sugar in the final stage of the 3 month aging process.'),
  (95, 'us', 'Pineapple', 'A large tropical fruit that grows on tall, spiky trees, primarily in Brazil, Thailand and the Philippines. Contains manganese and vitamin C, known to stimulate digestion and reduce blood viscosity. One fruit weighs on average 40 oz and can be cut into around 40 slices.'),
  (105, 'us', 'Sling glass', '''The quintessential glass for serving the eponymous cocktail, which would become the calling card of the Raffles Hotel. Standard volume: 7-10 oz.'''),
  (79, 'us', 'Still water', 'An ever-important source of health and longevity. Bartenders around the world recommend drinking water while consuming cocktails – and in the very best institutions, a glass of clean water is complimentary.'),
  (150, 'us', 'Sugar cubes', 'A European sweet seasoning obtained through complex purification, refining and crystallization of the syrup from sugar cane or sugar beet juice. These crystals are then pressed to the desired shape.'),
  (100, 'us', 'Drambuie', 'A Scottish liqueur, whose name means "fulfilling" in Gaelic, made using a secret recipe since 1910. The drink is known to contain a blend of single malts of famous origins, along with heather honey, herbs and spices.'),
  (677, 'us', 'Orange flower water', 'An ancient recipe of water infused with fresh bitter orange flowers.'),
  (118, 'us', 'Pineapple leaves', 'The leaves of the tropical fruit, used as an ornament for exotic tiki cocktails.'),
  (98, 'us', 'Pisco', 'This Peruvian grape brandy is produced from up to eight varieties of grape, whereas in Chile no more than three are used. The fermented juice is distilled in stainless steel vats, and either bottled immediately or aged in oak barrels for 2 years.'),
  (103, 'us', 'Cane sugar cubes', 'A sweet tropical seasoning produced by crystallizing sugar cane, then pressing it into small cubes. The higher the molasses content, the darker the color and the richer the flavor.'),
  (132, 'us', 'Aged bourbon', 'Aged bourbon'),
  (102, 'us', 'Caster sugar', '"A sweet seasoning powder obtained from ground and powdered sugar. Due to the grain size, it instantly dissolves in liquid, significantly saving time."'),
  (158, 'us', 'Copper mug', 'A must have. It has become the "Trojan horse" for vodka in America and vessel of choice for the "Moscow Mule." Standard capacity: 10-13 oz.'),
  (214, 'us', 'Blackberry', 'Dark purple medium-sized berries that grow on bushes throughout Europe, in Northwest Africa, Central Asia, and North and South America. Contains carotene, vitamin C, B1 and B2, K, and other vitamins. One berry weighs an average of 0.15 oz.'),
  (115, 'us', 'Granulated sugar', 'A sweet European seasoning obtained through a complex method of purifying, processing, and crystallizing the syrup of sugar cane or sugar beet juice. The size of the granules is important: the smaller they are, the more quickly they dissolve.'),
  (107, 'us', 'Milk', 'Made from full cream cow''s milk. The desired fat content is achieved by adding cream into a fat-free version of product.'),
  (330, 'us', 'Cinnamon sticks', 'A Ceylon seasoning, known since the 15th century, made from the bark of the cinnamon tree. It is cleaned, sanded and dried in the shade before being twisted into a tube.'),
  (108, 'us', 'Cup', '''A tall ceramic cup for coffee or tea. In 1930, it became utensil of choice for the "Tom and Jerry." Standard volume: 6-7 oz.'''),
  (655, 'us', 'Milk pitcher', 'A metallic milk pot. Used for whipping cream and preparing hot cocktails.'),
  (120, 'us', 'Ground cinnamon', 'A ground Ceylon seasoning, used since the 15th century, made from dried and milled shavings and scraps of cinnamon bark.'),
  (149, 'us', 'Star anise', 'A tropical, star-shaped fruit that grows on evergreen trees mainly in China. Gathered while still not ripe and dried in the sun.'),
  (134, 'us', 'Maple syrup', 'A famous Christmastime syrup made from sugar maple sap, collected from maple trees in February and March. Produced by pasteurizing the sap along with cane sugar and water.'),
  (123, 'us', 'Rose syrup', 'A delicate flower syrup produced by infusing and pasteurizing rose petals in sugar syrup.'),
  (201, 'us', 'Rose petals', 'The best-selling flower in the world. There are 25 petals in one bud.'),
  (1035, 'us', 'American whiskey', 'American whiskey'),
  (288, 'us', 'Pedro Ximenez sherry', 'The sweetest type of fortified Spanish wine is made from ripe grapes of the same name. Fermented grape juice is enriched with grape alcohol and aged in oak barrels using the Solera method for 10 to 30 years or more.'),
  (154, 'us', 'Teaspoon', 'A spoon used to stir tea in a cup. One spoonful holds on average 0.15 oz of dry or liquid ingredients.'),
  (211, 'us', 'Rocks ice', 'Large ice cubes returned to bars along with the trend towards classic drinks. They are produced by first freezing large ice blocks, which are then sawed into even cubes. This kind of ice melts slowly in the glass and doesn''t dilute the drink.'),
  (450, 'us', 'Ginger syrup', 'A spicy Asian syrup produced by pasteurizing ginger extracts in sugar syrup.'),
  (693, 'us', 'Mate bombilla', 'A special straw for serving mate. The upper end contains a mouthpiece while the lower part has a strainer.'),
  (552, 'us', 'Redcurrant', 'Little red berries that grow on deciduous shrubs mainly in Central and Northern Europe, and North Asia. It contains large amounts of vitamin C, as well as various sugars, organic acids and minerals. One bar spoon contains 0.15 oz of berries.'),
  (332, 'us', 'Oloroso sherry', 'A semi-dry or sweet Spanish fortified wine produced by fermenting Palomino grapes without forming the protective flor film. The resulting spirit is fortified in stages using grape spirit and aged in oak barrels using the Solera method for at least two years.'),
  (191, 'us', 'Dried apricots', 'A bright dried fruit produced primarily in Turkey, Iran and Uzbekistan from ripe apricots. The fruits are first boiled down or soaked in syrup, then dried in the sun or a special dryer. One piece on average weighs 3 oz.'),
  (683, 'us', 'Tray', 'A metal or wooden plate for serving food or drinks to guests.'),
  (121, 'us', 'Vanilla syrup', 'A fragrant Madagascan syrup produced by infusing and pasteurizing vanilla pods in sugar syrup.'),
  (381, 'us', 'Gold tequila', 'A spirit of Mexican origin, traditionally produced by distilling blue agave juice. Seven to ten summer agave hearts are placed in special furnaces to convert starch into sugar, and the resulting juice is fermented, double distilled and colored with caramel. Flavored with various aromatic additives.'),
  (318, 'us', 'White vermouth', 'The sweetest vermouth, produced by macerating alpine herbs and spices in white wine. The result is filtered, adjusted to the desired strength and maximum sweetness and aged in oak barrels for at least a year.'),
  (126, 'us', 'Strawberry puree', 'Strawberry puree'),
  (327, 'us', 'Granulated cane sugar', 'A sweet tropical seasoning produced by crystallizing sugar cane followed by mechanical processing. The higher the molasses content, the darker the color and the richer the flavor.'),
  (326, 'us', 'Bottle', 'A classic vessel used for storing alcoholic beverages and soft drinks.'),
  (138, 'us', 'Blender', 'Invented in 1922 by Stephen Poplawski, this electric appliance is indispensable for making tiki cocktails, smoothies and frozen drinks."'),
  (196, 'us', 'Coconut syrup', 'The most popular tropical syrup, produced by pasteurizing coconut water with cane sugar.'),
  (197, 'us', 'Pineapple slicer', 'A tiki accessory, which removes the skin and the hard core from a pineapple in a matter of seconds.'),
  (744, 'us', 'Scoop', 'A convenient tool made from polycarbonate or stainless steel which measures a specific amount of ice. Scoops differ in size and volume, allowing bartenders to select a tool for the required amount of ice.'),
  (406, 'us', 'Yellow banana liqueur', 'A creamy tropical liqueur produced by macerating yellow banana pulp in neutral spirits with water. The result is filtered, mixed with sugar and enriched with young brandy.'),
  (200, 'us', 'Banana', 'An ancient tropical grassy plant, primarily cultivated in India, China, and Uganda. The fruit contains vitamin B6, manganese and dietary fiber. One fruit weighs on average 7 oz, with the peel being 3 oz.'),
  (244, 'us', 'Genever', 'A dutch spirit, widely considered to be the father of gin, was made beginning in the 15th century by distilling pure alcohol with the addition of juniper berries and other spices.'),
  (133, 'us', 'Honey syrup', 'A highly-popular syrup, produced by pasteurizing honey, which is diluted to the desired consistency with water.'),
  (293, 'us', 'Teapot (2)', 'The history of this ancient Chinese vessel goes back to where and when tea itself began - 14th century China. Used to brew tea, herbs and spices in boiling water or juice.'),
  (287, 'us', 'Islay single malt whisky', 'Islay single malt whisky'),
  (284, 'us', 'Rhubarb liqueur', 'A bittersweet herbal dessert liqueur produced by macerating the stems and leaves of rhubarb in neutral spirits with water. The result is mixed with sugar and brought to the desired strength.'),
  (358, 'us', 'Cynar', 'An herbal Italian liqueur produced by macerating and distilling 16 herbs and spices, mainly artichoke, in neutral alcohol. The resulting spirit is filtered and brought to the desired strength and sweetness.'),
  (735, 'us', 'Grapefruit zest', 'The top layer of grapefruit skin, cut with a special sharp knife. It contains essential oils rich in grapefruit flavor. Zest can be obtained from a cut or whole fruit, then grated or even twisted into a spiral (called the twist).'),
  (704, 'us', 'Sprayer', 'An attractive accessory for spraying bitters and aromatic additives over cocktails.'),
  (435, 'us', 'Fino sherry', 'A Spanish dry fortified wine produced by fermenting Palomino grapes with a special added yeast. As it ages for at least 12 months, the wine is covered by a special film called flora, and enriched with grape alcohol in stages. Aged in barrels under this protective film for at least 2 years.'),
  (653, 'us', 'Shot glass', 'A small glass, usually with straight edges. Designated for the strongest drinks or cocktails, which should be downed in one gulp. Standard volume 1.5-3 oz.'),
  (546, 'us', 'Strawberry', 'A large red berry that grows on small shrubs mostly in the US, Turkey, Spain, Egypt and Mexico. It contains sugar, pectin and tannin, ascorbic acid, and anti-inflammatory ingredients. One berry weighs an average of 0.75 oz.'),
  (402, 'us', 'Limoncello', 'One of Italy''s national liqueurs, produced by macerating lemon peel in neutral spirits for a month. The resulting alcohol is mixed with sugar and water, left to infuse, and filtered.'),
  (410, 'us', 'Lychee liqueur', 'Made from the pulp of ripe lychees, which are mixed with alcohol and allowed to infuse.'),
  (486, 'us', 'Mango juice', 'To prepare the juice, mango pulp is put through a press, and then filtered and bottled.'),
  (529, 'us', 'Passion fruit', 'The subtropical passionfruit is a vine species of passionflower grown mainly in New Zealand, Israel and Sri Lanka. Contains vitamin A, beta-carotene and potassium, and has a toning effect on the body1. One fruit weighs on average 3.5 oz.'),
  (415, 'us', 'Blackberry liqueur', 'A rich berry liqueur produced by macerating blackberries in neutral spirits with water for up to two months. The liqueur is not filtered and mixed with sugar.'),
  (405, 'us', 'Green apple liqueur', 'A fresh fruit liqueur produced by macerating the flesh of green apples in neutral spirits. The resulting spirit is filtered, mixed with sugar and diluted with water to the desired strength.'),
  (528, 'us', 'Apple', 'This popular fruit is native to Central Asia, and grows on leafy trees mainly in China, USA and Turkey. Contains ascorbic acid, vitamin K, potassium, considered to boost immunity and combat obesity. One fruit weighs on average 7 oz and can be cut into 10 slices.'),
  (682, 'us', 'Jar', 'A jar with a tight lid to mix and store liqueurs and cordials. No standard volume available.'),
  (446, 'us', 'Agave syrup', 'A Mexican syrup made from agave juice concentrate, mixed with sugar syrup.'),
  (432, 'us', 'Dry red wine', 'The most common type of wine, produced by macerating and subsequently fermenting red and black grapes, which are responsible for the wine''s color. Then the wine is filtered and aged in oak barrels for at least 3 months.'),
  (613, 'us', 'Cloves', 'An Indonesian spice consisting of dried tropical allspice and clove buds.'),
  (705, 'us', 'Absinthe fountain', 'A vital component of the serving ritual for the strong French drink. The alcohol is poured into the main flask along with herbs and fruit. Once it steeps, the drink is poured drop by drop through sugar on the spoon and falls in the glass.'),
  (698, 'us', 'Absinthe spoon', 'A vital component of the serving ritual for the strong French drink. The alcohol is poured into the main flask along with herbs and fruit. Once it steeps, the drink is poured drop by drop through sugar on the spoon and falls in the glass.'),
  (494, 'us', 'Energy drink', 'Energy drinks are specifically designed for use during increased physical and mental activity.'),
  (394, 'us', 'Irish cream liqueur', 'An Irish cream liqueur, made from triple-distilled Irish whiskey with added cream and neutral spirits. Enriched with cocoa, vanilla, sugar and caramel.'),
  (547, 'us', 'Blueberry', 'A little purple berry that grows on bushes in Canada, North America, Turkey and Western Europe. It contains a large amount of vitamins A, B, C, manganese and potassium. It is useful for eyesight and improves night vision. One bar spoon contains 0.15 oz of berries.'),
  (578, 'us', 'Lemongrass', 'A grass with a citrus aroma, used primarily in Caribbean and Asian cuisine. It grows mainly in the British Isles, the Philippines and Indonesia.'),
  (490, 'us', 'Sprite', 'A sweet carbonated drink produced from soda water with added sugar and lemon extract.'),
  (666, 'us', 'Sambuca', 'An Italian liquor produced by flavoring wheat alcohol with sugar, oils of both ordinary and star anise, and extracts from berries, elderberry flowers and various herbs, all of which produce its lasting fragrance.'),
  (414, 'us', 'Advocaat liqueur', 'A Dutch Christmas liqueur that is in turn descended from a Brazilian alcoholic beverage made from avocado. This drink is made from a mixture of egg yolks, sugar, vanilla and brandy.'),
  (531, 'us', 'Pomegranate', 'A Mediterranean fruit that grows on a fruit-bearing deciduous shrub or small tree, primarily in Israel and India. Contains potassium and phosphorus, and known to have a positive effect on the cardiovascular system. One fruit weighs on average 10 oz and can be cut into 10 slices.'),
  (684, 'us', 'Red wine glass', 'A classic, slightly curved glass. Traditionally taller than a white wine glass. Standard capacity: 6-10 oz.'),
  (483, 'us', 'Cherry juice', 'To prepare the juice, cherries are put through a press, then filtered and bottled.'),
  (551, 'us', 'Blackcurrant', 'A little black berry with bushes that grow in Central and Northern Europe, and North Asia. It contains large amounts of vitamin C, various sugars, organic acids and minerals. One bar spoon contains 0.15 oz of berries.'),
  (597, 'us', 'Raspberry jam', 'A jam from red berries that grow on perennial dwarf shrubs mainly in Russia, Serbia, Poland and the United States. Ripe fruit is boiled with sugar until homogenized. A bar spoon can hold 0.15 oz of jam.'),
  (590, 'us', 'Orange jam', 'A jam from the pulp of citrus fruits that grow on tall trees mainly in Brazil, USA and China. Ripe fruit is boiled with sugar until it reaches a homogeneous state. A bar spoon can hold 0.15 oz of jam.'),
  (589, 'us', 'Honey (2)', 'Flower nectar collected and processed by bees.'),
  (652, 'us', 'Cookie', 'A sweet biscuit, baked in an oven from different types of dough.'),
  (686, 'us', 'Pitcher', 'An ancient kitchen vessel for serving water, lemonade and sangria. Standard volume: 15-100 oz.'),
  (484, 'us', 'Pomegranate juice', 'To prepare the juice, pomegranate seeds are put through a press, and then filtered and bottled. '''),
  (548, 'us', 'Watermelon', 'A large type of berry grown mainly in China, Turkey and Iran. Contains glucose, fructose, pectin, calcium, magnesium, and alkaline substances, and normalizes the metabolism. One berry weighs an average of 150 oz, and a single slice - 10 oz, and the pulp to weight ratio is 60% to 40%.'),
  (454, 'us', 'Lemongrass syrup', 'A lemony syrup produced by pasteurizing lemongrass extracts with sugar syrup.'),
  (770, 'us', 'Milkshake sundae glass', 'Previously used to serve ice cream, but now used to serve milkshakes, milkshake sundaes, soft drinks and cocktails. Standard capacity: 8-11 oz.'),
  (433, 'us', 'Dry white wine', 'A summery wine produced by macerating and subsequently fermenting skinless white grapes. The wine is then filtered and aged in oak barrels for at least 3 months.'),
  (532, 'us', 'Kiwi', 'The kiwifruit or Chinese gooseberry is the edible berry of a woody vine that grows in Italy, New Zealand and Chile. Contains vitamin C, fibre, folic acid, calcium and phosphorus, known to enhance the immune system. One berry weighs on average 4 oz.'),
  (577, 'us', 'Red basil', 'A fragrant, aromatic herb, which grows mainly in the warm regions of the Old World.'),
  (702, 'us', 'Cream whipper', 'A device made out of thick glass or metal for quickly whipping cream into a delicate and airy consistency. It can also be used for making various desserts, complex sauces and mousses. Standard volume: 15-30 oz.'),
  (399, 'us', 'Peach liqueur', 'A sunny fruit liqueur produced by distilling fermented peach juice with added cognac. In order to enhance the rich flavor, peach pits may be added.'),
  (396, 'us', 'Apricot liqueur', 'A famous fruit liqueur produced by distilling fermented apricot juice with strong spirits to enhance the rich flavour.'),
  (691, 'us', 'Punch bowl', 'A large vessel made out or glass, crystal or metal for serving punch, which was brought to England from India in the beginning of the 17th century. Standard volume: 150 oz.'),
  (395, 'us', 'Amaretto liqueur', 'A classic Italian liqueur produced by macerating apricot pits with different herbs and fruit in neutral alcohol. The resulting distillate is filtered, mixed with sugar and diluted with water to the desired strength.'),
  (556, 'us', 'Cherry', 'A yellow or scarlet berry that grows on trees mainly in warm and temperate climates, such as Turkey, Italy, Spain, Chile. Contains organic acids, minerals, pectin, folic acid, vitamins A, C, E, B. One berry weighs an average of 0.15 oz.'),
  (437, 'us', 'Lager beer', 'A light beer made from water, barley, malt extract, hops and brewer''s yeast.'),
  (452, 'us', 'Blackcurrant syrup', 'A berry syrup produced by pasteurizing ripe black currant juice mixed with sugar and water.'),
  (397, 'us', 'Melon liqueur', 'A tropical Asian liqueur produced by macerating melon pulp in neutral spirit with water. The result is filtered, adjusted to the desired sweetness and strength and bottled.'),
  (763, 'us', 'Bitter lemon', 'A carbonated lemon drink produced by carbonating water with lemon extract.'),
  (380, 'us', 'Becherovka', 'A canonical Czech liquor, produced by macerating a blend of 20 herbs and spices in neutral spirit, which is subsequently mixed with water and sugar and aged for two to three weeks in oak casks.'),
  (502, 'us', 'Earl Grey tea', 'In its classic form, this is a black tea with the addition of oil from the rind of the bergamot fruit. The best temperature for brewing this tea is 195-205 °F, and it should be left to steep for 3-5 minutes.'),
  (709, 'us', 'Cocktail umbrella', 'Bright paper decoration for tropical cocktails or to entertain children.'),
  (639, 'us', 'Prune', 'A European delicacy produced from black plums dried in the sun or in a special dryer.'),
  (747, 'us', 'Tartlet', 'A miniature copy of a tart first mentioned in King Richard II''s cookbook from 1390. A baked dish consisting of a filling over a pastry base, with an open top not covered with pastry.'),
  (453, 'us', 'Yellow apple syrup', 'A yellow, fruity syrup produced by pasteurizing yellow apple juice with added cane sugar.'),
  (576, 'us', 'Rosemary', 'Mediterranean herbs with a piquant pine scent.'),
  (409, 'us', 'Grapefruit liqueur', 'Citrus liqueur produced by macerating pink grapefuit peel in neutral alcohol. The resulting spirit is filtered, mixed with sugar and diluted with pure water to a required strength.'),
  (549, 'us', 'Cranberry', 'A small red berry that grows on dwarf shrubs or trailing vines mainly in the United States, Chile, Argentina and the Netherlands. Contains organic acids, minerals, pectin, folic acid, and vitamins A, C, E, B. One bar spoon contains 0.15 oz of berries.'),
  (492, 'us', 'Tonic', 'A carbonated drink invented in India to combat malaria. It is made from carbonated water mixed with quinine and a small amount of sugar.'),
  (562, 'us', 'Red grapes', 'Red berries of medium size; grapes is fruiting berries from deciduous woody vines. Comes from China, the US, Italy, France and Spain. Contains sugar, cellulose, organic acids, vitamin B and other trace elements, and has a strengthening and toning effect. One berry weighs an average of 0.15 oz.'),
  (663, 'us', 'Orange vodka', 'A strong flavored spirit produced by multiple distillation of grains, which are then subject to several stages of carbon and other filtering. The result is mixed with clean water, and infused with extracts of ripe orange.'),
  (530, 'us', 'Tangerine', 'Tangerines are an orange-coloured citrus fruit that grows on evergreen shrubs mainly in China, Spain and Brazil. Contains vitamin C and potassium, known to enhance immunity. One fruit weighs around 3.5 oz and yields 1.35 oz juice.'),
  (710, 'us', 'Lillet Blanc', 'A French aperitif wine produced from a combination of the white wines from Bordeaux mixed with fruit liqueurs. While the wine matures, the peel of both sweet, bitter and sour oranges and green quinine are steeped in brandy spirits. Then everything is mixed together and kept in oak barrels for 8-12 months.'),
  (389, 'us', 'Spiced rum', 'A Caribbean spirit, produced via vertical distillation of alcohol from fermentation of molasses or sugar cane juice. Before blending, it is kept in burnt oak barrels from bourbon or sherry for 2 to 7 years, depending on the method of aging, and infused with cinnamon, nutmeg, vanilla and other spices.'),
  (398, 'us', 'Blue curacao liqueur', 'A neon-blue orange liqueur produced by macerating dried orange peel in neutral spirits with water. The result is filtered, mixed with sugar and colored with natural dyes.'),
  (550, 'us', 'Green grapes', 'Green berries of medium size. Grapes are fruiting berries from deciduous woody vines. Comes from China, the US, Italy, France and Spain. Contains sugar, cellulose, organic acids, vitamin B and other trace elements, and has a strengthening and toning effect. One berry weighs an average of 0.15 oz.'),
  (533, 'us', 'Mango', 'A wild tropical fruit that grows primarily in India, Pakistan and the Philippines. Contains vitamin A, folic acid and potassium, and assists in improving immunity and sight. One fruit weighs on average 10 oz and can be cut into 10 slices.'),
  (408, 'us', 'Cinnamon liqueur', 'A German spiced liqueur produced by macerating cinnamon in schnapps. The result is filtered and mixed with sugar, and for an extra zing, gold leaf is added.'),
  (495, 'us', 'Green iced tea', 'Popular in Asia, iced tea is produced using green tea extract and other herbs without any artificial flavors or preservatives.'),
  (711, 'us', 'Julep strainer', 'An indispensable accessory when working with a mixing glass. Also serves as an unmatched decoration for the classic cocktail of the same name. Used for filtering crushed pieces of ice and other undesired ingredients out of cocktails.'),
  (670, 'us', 'Espresso coffee', 'A strong coffee which is prepared by pouring a small quantity of boiling water at a temperature of 195 °F through ground coffee.'),
  (690, 'us', 'Tea cup', 'A traditional Turkish tea drinkers cup. Standard volume: 1-2 oz.'),
  (412, 'us', 'Passion fruit liqueur', 'Made from the pulp of ripe passionfruit, orange and grapefruit, which are mixed with alcohol and allowed to infuse.'),
  (615, 'us', 'Vanilla granulated sugar', 'Classic sugar, flavored with vanilla.'),
  (181, 'us', 'French press', 'A French device for coffee and tea brewing, consisting of a glass flask with a strainer and a press.'),
  (448, 'us', 'Strawberry syrup', 'A berry syrup produced by pasteurizing juice from ripe strawberries mixed with sugar and water.'),
  (567, 'us', 'Chili pepper', 'Hot tropical peppers that grow on bushes, mainly in South America. Contains vitamins A and C as well as potassium, magnesium and iron. One pod weighs on average 1 oz.'),
  (499, 'us', 'Black tea', 'A type of tea which has been fermented from two weeks to one month. Grows in regions with a tropical or subtropical climate. To brew, pour 3.5 oz of boiling water over 1 spoonful of tea and leave for 4-5 minutes.'),
  (411, 'us', 'Mango liqueur', 'An Asian tropical liqueur produced by macerating ripe mango pulp in neutral alcohol with water. The resulting alcohol is filtered and mixed with sugar.'),
  (514, 'us', 'Vanilla ice cream', 'The frozen dessert is prepared from milk, cream, butter and sugar with the addition of vanilla extract. Stored in the freezer for no more than a month.'),
  (592, 'us', 'Cherry jam', 'The jam of yellow or scarlet berries, which grow mainly in warm, temperate climates, such as Turkey, Italy, Spain and Chile. Ripe pitted cherries are boiled with sugar until homogenized. A bar spoon holds 5 g of jam.'),
  (485, 'us', 'Peach juice', 'To prepare the juice, peaches are put through a press, and then filtered and bottled.'),
  (387, 'us', 'Blackcurrant vodka', 'A strong flavored spirit produced by multiple distillation of grains. The distillate is then subject to several stages of carbon and other filtration, and the final product is mixed with clean water. The resulting drink is infused with extracts of ripe black currant.'),
  (633, 'us', 'Rosewater', 'An antique recipe of scented water infused with rose petals.'),
  (713, 'us', 'Raspberry puree', 'Raspberry puree'),
  (586, 'us', 'Thyme', 'An aromatic spice from dwarf shrubs, which grows mainly in Eurasia, North Africa and Greenland. Used in Provençal mixes, and ideal for flavoring strong spirits.'),
  (407, 'us', 'Coconut liqueur', 'A tropical tiki liqueur produced by macerating coconut pulp in rum. The resulting distillate is filtered, mixed with sugar and diluted with water to the desired strength.'),
  (430, 'us', 'Rose vermouth', 'This youngest of vermouths is made from a unique combination of red and white wines. A fortified wine with the addition of herbs, flowers, seeds and fruits, including wormwood, mint, cinnamon, nutmeg, and quinine, all cleverly balanced and present in its characteristic bitter, spiced taste. Its ideal aroma opens up brilliantly when served on ice.'),
  (646, 'us', 'Dark chocolate', 'A confectionery dessert made of dark cocoa beans with little to no sugar added.'),
  (447, 'us', 'Caramel syrup', 'The famous caramel syrup is produced by adding vanilla and water to liquid caramel.'),
  (750, 'us', 'Napkins', 'Cotton or paper serviettes. Sometimes used as coasters for drinks.'),
  (360, 'us', 'Soda syphon', 'A device made out of thick glass or metal used to carbonate drinks. Standard volume: 30-35 oz.'''),
  (500, 'us', 'Whole bean coffee', 'Roasted beans from the coffee tree which are known for their stimulating effect due to their caffeine content. There are two main varieties of coffee tree: Arabica and Robusta.'),
  (565, 'us', 'Sake', 'A Japanese liquor made from soaked and steamed rice. The prepared culture is enriched with fermentation fungi and kept in a warm, humid room for about 2 days. After fermentation, sake is kept in sealed containers from 6 to 12 months.'),
  (537, 'us', 'Kumquat', 'A small citrus fruit that grows on small fruit-bearing trees mainly in China, Korea and Japan. Contains vitamin C, iron and magnesium, and helps the body fight infections. One fruit weighs an average 0.35 oz.'),
  (685, 'us', 'Cognac glass', 'A classic glass for drinking cognac or brandy. Standard capacity: 5-13 oz.'),
  (423, 'us', 'Southern Сomfort', 'A New Orleans fruit liqueur invented by bartender Martin Heron in 1874. Produced according to a historical recipe, using a base of American whiskey with the addition of fruit, herbal essences, sugar and caramel, which is then aged in oak barrels until reaching the desired maturity.'),
  (703, 'us', 'Frying pan', 'An ancient cooking utensil necessary in the bar for flambéeing berries and fruit.'),
  (688, 'us', 'Tasting set', 'A tasting set. It consists of a glass tray filled with ice, ensuring the tasting shots are kept cool.'),
  (462, 'us', 'Lychee syrup', 'An Asian fruit syrup produced by pasteurizing lychee juice mixed with sugar syrup and water.'),
  (504, 'us', 'Chamomile tea', 'A brew made from the dried flowers of the chamomile plant. Generally, boiling water is poured over the flowers at a ratio of 1-2 teaspoons to 7 oz of water. It is then left to steep for 7-10 minutes, then strained and either drank as is or with the addition of sugar or honey.'),
  (673, 'us', 'Sea buckthorn jam', 'Jam made from small yellow berries which grow in deciduous thorny shrubs, mostly on the Atlantic coast of Europe and in northwest China. The ripe fruit is boiled with sugar until homogenized. A bar spoon can hold 0.15 oz of jam.'),
  (689, 'us', 'Sake set', 'A set for the ritual serving of the strong Japanese alcohol. Average volume of the tokkuri flask: 8-10 oz; average volume of the cup: 1.5-2 oz.'),
  (769, 'us', 'Saucer', 'A small glass, porcelain or metal dish that is traditionally served along with a cup. In modern interpretations, a cocktail glass with a saucer offers a more refined and elegant presentation.'),
  (463, 'us', 'Mango syrup', 'Asian fruit syrup produced by pasteurizing mango juice mixed with cane sugar and water.'),
  (700, 'us', 'Tea glass holder', 'A metal glass holder with a handle to hold the glass, allowing one to consume a hot drink without burning one’s hands.'),
  (695, 'us', 'Fork', 'Cutlery that consists of a handle and several prongs, usually between two and four, on one end. Used for preparing food as well as while eating for holding or moving parts of the meal.'),
  (950, 'us', 'Thermometer', 'A device for measuring the temperature of liquids, the environment, the body, etc.'),
  (981, 'us', 'Vacuum coffee maker', 'Coffee brewer that uses vapor pressure to make the drink.');
