INSERT INTO drink_me_bot.cocktail_step (cocktail_id, lang, step_no, text) VALUES
  (1, 'de', 1, 'Pressen Sie 35 ml Gurkensaft und gießen Sie ihn in einen Shaker'),
  (1, 'de', 2, 'Fügen Sie 25 ml Wachtel Eiweiß, 15 ml Limettensaft, 35 ml Apfelsaft und 20 ml Zimt Sirup hinzu'),
  (1, 'de', 3, 'Schütteln Sie alles gut durch'),
  (1, 'de', 4, 'Füllen Sie den Shaker mit Eiswürfeln und schütteln Sie ihn erneut'),
  (1, 'de', 5, 'Seihen Sie das Ganze in eine gekühlte Champagner Schale ab'),
  (1, 'de', 6, 'Garnieren Sie den Drink am Ende mit einer Gurkenscheibe'),
  (2, 'de', 1, 'Füllen Sie ein Rocks Glas bis obenhin mit Eiswürfeln'),
  (2, 'de', 2, 'Gießen Sie 25 ml Kaffee Likör und 50 ml Wodka dazu und rühren Sie vorsichtig um'),
  (4, 'de', 1, 'Gießen Sie 20 ml Zitronensaft, 20 ml Triple Sec Likör und 40 ml Gin in einen Cocktailshaker'),
  (4, 'de', 2, 'Füllen Sie den Cocktailshaker mit Eiswürfeln und schütteln Sie ihn'),
  (4, 'de', 3, 'Seihen Sie das Ganze in ein gekühltes Sour Glas ab'),
